P.entries["quest:2932"] = {n="Grim Message",s="Nimboya vrea ca Troll Witherbark sa fie pedepsiti pentru ca l-au tradat pe Thrall, desi candva au fost aliati ai Horde. Sulita lui Nimboya trebuie sa poarte cranii Witherbark si sa fie infipta intr-un sat Witherbark din Hinterlands.",h="Nimboya vrea ca Troll Witherbark sa fie pedepsiti pentru ca l-au tradat pe Thrall, desi candva au fost aliati...",kw={"grim message","Hinterlands","hiri'watha","nimboya","tarren mill","thrall","witherbark","zun'watha"},sec={{t="Un avertisment scris cu sange",b="Odinioara, troll Witherbark au luptat alaturi de Horde, pana cand l-au tradat pe Thrall. Nimboya iti inmaneaza o sulita si te trimite departe spre nord, in Hinterlands, la nord-est de Tarren Mill, satul aflat sub stapanirea Forsaken. Vaneaza acolo troll Witherbark si strange-le craniile, apoi infige sulita in pamant in Hiri'watha sau Zun'watha, doua dintre satele lor mai mici, ca sa afle cat ii costa faptele. Dupa aceea, Nimboya te asteapta in Stranglethorn."}},faq={{q="De ce vrea Nimboya sa-i pedepseasca pe Troll Witherbark?",a="Nimboya spune ca erau aliati ai Horde care s-au intors impotriva lui Thrall si ca o asemenea tradare nu poate ramane nepedepsita.",al={"de ce sa ataci witherbark","tradarea lui witherbark","motivul mesajului Grim Message"}},{q="Unde te trimite Nimboya sa infigi stiuca?",a="Fie Hiri'watha, fie Zun'watha, sate mai mici ale Witherbark din Hinterlands.",al={"unde sa infigi stiuca","locatia stiucii lui nimboya","locatia lui Grim Message"}},{q="Unde se afla Hinterlands fata de Tarren Mill?",a="Se afla la nord-est de Tarren Mill, satul stapanit de Forsaken, si mult la nord de Nimboya, in Stranglethorn.",al={"locatia hinterlands","unde se afla hinterlands"}},{q="Cine ofera Grim Message?",a="Nimboya, din Stranglethorn, iti da lancea si asteapta acolo vesti.",al={"cel care ofera Grim Message","cine este nimboya"}}},fp="12,213,18.440.0,54.111.0,46.78.0,43.115.0,23.72.0"}
P.entries["quest:2933"] = {n="Venom Bottles",s="Sticle cu o otrava verde respingatoare umplu un sat Witherbark din Hinterlands. Sunt atat de multe, incat par sa indice ca Witherbarks pun mare pret pe ea, iar un apotecar din Tarren Mill, aflat in apropiere, ar putea dori o mostra.",h="Sticle cu o otrava verde respingatoare umplu un sat Witherbark din Hinterlands.",kw={"apothecary lydon","arahnid","hinterlands","tarren mill","venin Troll","sticla de venin","witherbark"},sec={{t="O descoperire toxica",b="Sticlele din satul Witherbark contin o otrava hidoasa, verde. Sunt atat de multe, incat Witherbarks trebuie sa o considere foarte importanta. O mostra ar putea fi dusa la un apotecar din Tarren Mill, care ar putea dori sa o examineze."},{t="Verdictul lui Lydon",b="Apothecary Lydon, ale carui experimente au esuat toate in acea zi, ia sticla si declara ca lichidul contine venin extras de la o creatura arahnida. Lydon intreaba de unde provine."}},faq={{q="Unde se gasesc sticlele cu venin?",a="Se afla intr-un sat Witherbark din Hinterlands, in numar mare.",al={"locatia sticlei cu venin","unde gasesti sticle cu venin","veninul Witherbark"}},{q="Cine este interesat de sticlele cu venin?",a="Sfatul este sa duci o mostra la un apotecar din Tarren Mill, iar Apothecary Lydon este cel pe care trebuie sa-l cauti.",al={"cine vrea veninul","unde predau sticla cu venin","farmacistul din Tarren Mill"}},{q="Ce se afla in sticle?",a="O otrava verde, scarboasa, pe care Witherbarks par sa o pretuiasca mult, judecand dupa numarul de sticle pe care le pastreaza.",al={"ce este veninul","ce se afla in sticle"}}},fp="13,193,17.218.0,15.177.1,34.70.0,39.107.0,23.98.0"}
P.entries["quest:2934"] = {n="Undamaged Venom Sac",s="Apothecary Lydon din Tarren Mill vrea o mostra proaspata din veninul livrat deja si te trimite dupa paianjenii de la care se obtine, in Hinterlands. Timpul conteaza, fiindca mostra trebuie sa ajunga proaspata.",h="Apothecary Lydon din Tarren Mill vrea o mostra proaspata din veninul livrat deja si te trimite dupa...",kw={"apothecary lydon","hinterlands","shadra'alor","venin de paianjen","tarren mill","saculet cu venin"},sec={{t="O mostra proaspata",b="Dupa Venom Bottles, Apothecary Lydon cere ceva mai proaspat. Paianjenii de la care s-a obtinut veninul trebuie sa traiasca in Hinterlands, iar de la ei se doreste un sac de venin nedeteriorat. Multi misuna in apropierea orasului troll Shadra'Alor. Nu e timp de pierdut, fiindca sacul trebuie sa fie proaspat cand ajunge. Lydon abia asteapta sa faca experimente cu el si a comandat cateva animalute mici si tare dragalase pe care sa le foloseasca drept cobai."}},faq={{q="Cine cere sacul de venin intact?",a="Apothecary Lydon din Tarren Mill il cere si il asteapta acolo.",al={"cine da undamaged venom sac","cine incepe undamaged venom sac","cel care ofera misiunea undamaged venom sac"}},{q="Unde pot fi gasiti paianjenii?",a="In Hinterlands, unde multi paianjeni se gasesc in apropierea orasului troll Shadra'Alor.",al={"locatia paianjenilor","unde sunt paianjenii","unde gasesti sacul cu venin intact"}},{q="De ce spune Apothecary Lydon sa nu zabovesti?",a="Prospetimea este esentiala, asa ca Lydon vrea ca sacul sa fie livrat fara intarziere.",al={"de ce este limitat in timp","de ce se strica sacul","cronometrul sacului de venin intact"}},{q="Ce a fost inainte de acest pas?",a="Urmeaza dupa Venom Bottles, in care o mostra de venin dintr-un sat Witherbark a fost adusa lui Lydon.",al={"misiune anterioara","ce misiune preceda undamaged venom sac","cerinta prealabila pentru undamaged venom sac"}}},fp="19,192,14.409.0,37.67.0,31.84.0,43.71.0,27.100.0"}
P.entries["quest:2935"] = {n="Consult Master Gadrin",s="Apothecary Lydon a descoperit ca veninul gardienilor cuibului era mai slab decat mostra adusa initial, ceea ce indica un alt tip de paianjen. Lydon te trimite la Master Gadrin din Sen'jin Village, in Durotar, care s-ar putea sa stie mai multe.",h="Apothecary Lydon a descoperit ca veninul gardienilor cuibului era mai slab decat mostra adusa initial, ceea...",kw={"apothecary lydon","consult master gadrin","durotar","hinterlands","master gadrin","sen'jin village","venin","witherbark"},sec={{t="In cautarea potentei",b="Apothecary Lydon a descoperit ca veninul luat de la broodguards e mai slab decat mostra pe care ai adus-o prima data, deci trebuie sa provina de la un alt paianjen. Lydon vrea o mostra proaspata din soiul mai puternic. Ca sa afli de unde provine, intreaba un troll care cunoaste bine tinuturile Witherbark: Master Gadrin, din Sen'jin Village, in Durotar. Cu putin noroc, Gadrin va sti sa-ti spuna sursa veninului."}},faq={{q="De ce te trimite Apothecary Lydon la Master Gadrin?",a="Veninul pazitorilor cuibului era mai slab decat prima mostra, ceea ce indica un alt paianjen. Gadrin este un troll care cunoaste bine Witherbark si poate ca va putea identifica sursa acelui venin.",al={"de ce sa-l consulti pe gadrin","de ce sa mergi la senjin","lydon gadrin"}},{q="Unde se afla Master Gadrin?",a="Master Gadrin se afla in Sen'jin Village, in Durotar.",al={"unde este gadrin","locatia lui Master Gadrin","gaseste-l pe Master Gadrin"}},{q="Ce a precedat aceasta calatorie?",a="Inainte de asta, i-ai adus lui Apothecary Lydon un sac de venin intact din Hinterlands.",al={"cerinta","ce a fost inaintea acestuia","misiunea anterioara"}}},fp="21,224,20.370.0,52.194.0,31.48.0,30.85.0"}
P.entries["quest:2937"] = {n="Summoning Shadra"}
P.entries["quest:2938"] = {n="Venom to the Undercity",s="Apothecary Lydon e incantat de veninul luat de la zeita-paianjen Witherbark si vrea sa trimiti o mostra superiorului sau, Faranell, la Apothecarium din Undercity. Iti incredinteaza un colet pentru calatorie.",h="Apothecary Lydon e incantat de veninul luat de la zeita-paianjen Witherbark si vrea sa trimiti o mostra...",kw={"apothecarium","apothecary lydon","pachetul lui Faranell","master apothecary faranell","shadra","venom to the undercity"},sec={{t="O descoperire puternica",b="Lydon a ucis aproape doua duzini de iepuri cu o singura doza de venin. Unii erau mici, asa ca rezistenta lor era cu siguranta scazuta, dar nu se poate nega ca otrava este puternica. Lydon este sigur ca Faranell va dori sa o testeze personal si iti da un pachet pe care sa-l duci la Apothecarium din Undercity."}},faq={{q="Cine trimite coletul catre Undercity?",a="Apothecary Lydon il trimite dupa ce testeaza veninul luat de la zeul paianjen al celor din Witherbark.",al={"cine da Venom to the Undercity","cel care ofera misiunea Venom to the Undercity","cine incepe Venom to the Undercity"}},{q="Cine ar trebui sa primeasca veninul in Undercity?",a="Master Apothecary Faranell, superiorul lui Lydon, in Apothecarium of the Undercity.",al={"cine primeste coletul","unde ajunge veninul in Undercity","cine este Faranell"}},{q="Cat de puternic era veninul in timpul testarii?",a="O singura doza a fost de ajuns sa ucida aproape doua duzini de iepuri, desi unii erau foarte tineri si mici.",al={"cat de puternica este otrava lui shadra","testele lui Lydon cu iepuri"}},{q="Ce precede aceasta livrare?",a="Urmeaza Summoning Shadra, in care veninul a fost luat de la zeita paianjen.",al={"misiunea precedenta pentru Venom to the Undercity","conditie prealabila pentru Venom to the Undercity"}}},fp="22,223,13.316.0,43.90.0,54.83.0,40.96.0,32.78.0"}
P.entries["quest:2939"] = {n="In Search of Knowledge",s="Troyas Moonbreeze a gasit printre ruinele din Feralas ceea ce pare a fi un toiag obisnuit, dar nu poate scapa de senzatia ca ascunde mai mult. Te trimite sa vorbesti cu colegul sau, Daryn Lightwind, in Rut'theran Village.",h="Troyas Moonbreeze a gasit printre ruinele din Feralas ceea ce pare a fi un toiag obisnuit, dar nu poate scapa...",kw={"angelas","darnassus","daryn lightwind","feralas","ruine","rut'theran village","toiag","troyas moonbreeze"},sec={{t="Un toiag obisnuit",b="Troyas Moonbreeze spune ca ruinele din Feralas sunt periculoase, dar au multe de dezvaluit despre ce s-a petrecut acolo. Cu cateva zile in urma, in timp ce cauta prin daramaturile din sud, a dat peste un toiag care pare obisnuit, dar nu poate scapa de sentimentul ca ascunde ceva mai mult. El si Angelas au rasfoit cu atentie cartile lor, fara sa gaseasca vreo mentionare a lui."},{t="Un coleg in Darnassus",b="Troyas are o colega in Darnassus care ar putea sa spuna ce este toiagul. Iti cere sa mergi sa vorbesti cu ea, Daryn Lightwind, in Rut'theran Village."},{t="Raspunsul lui Daryn",b="Daryn bombane ca Troyas o bate la cap cu tot felul de idei nebunesti despre o descoperire importanta. In opinia ei, ogres sau harpies care traiesc acum in ruinele acelea probabil au luat de mult tot ce era cu adevarat valoros. Poti sa cauti prin zona, adauga ea, desi se indoieste ca vreo carte de acolo iti va fi de folos."}},faq={{q="Cine te trimite la Daryn Lightwind?",a="Troyas Moonbreeze, care vrea sa afle ce este cu adevarat toiagul gasit de el printre ruinele din Feralas.",al={"cine da In Search of Knowledge","cel care ofera misiunea"}},{q="Ce a gasit Troyas?",a="Un toiag ce pare obisnuit, gasit in daramaturile de la sud de locul unde lucreaza Troyas. El simte ca ascunde ceva mai mult.",al={"ce a gasit troyas","toiagul din feralas"}},{q="Unde se afla Daryn Lightwind?",a="In Rut'theran Village. Troyas o descrie drept o colega din Darnassus.",al={"locatia lui daryn lightwind","unde este daryn"}},{q="De ce te trimite Troyas la Daryn?",a="El si Angelas n-au gasit nimic despre toiag in cartile lor, iar Daryn ar putea sa le spuna ce este.",al={"de ce sa-l vizitezi pe daryn lightwind","de ce darnassus"}}},fp="22,223,17.329.0,24.152.0,13.305.1,33.92.0,21.124.0,25.72.0,34.112.0"}
P.entries["quest:294"] = {n="Ormer's Revenge",s="Ormer's Revenge da startul campaniei de razbunare a lui Ormer Ironbraid, un explorator ramas izolat sus, deasupra sitului arheologic Whelgar Excavation Site din Wetlands. Dupa ce au dezgropat oase fosilizate stravechi, membrii echipei pitice de excavare au atras fara sa vrea haite de rapitori pestriti, infometati, care le-au masacrat tovarasii si i-au prins pe supravietuitori pe o stanca abrupta.",h="Ormer's Revenge da startul campaniei de razbunare a lui Ormer Ironbraid, un explorator ramas izolat sus...",kw={"mottled raptor","mottled screecher","ormer ironbraid","ormer's revenge","prospector whelgar","wetlands","whelgar excavation site"},ang={["class:Hunter"]="Raptorii pestriti si agresivi care bantuie pantele din afara sitului le ofera vanatorilor iscusiti ocazia de a studia comportamentul periculos al urmaririi reptilelor in teren mlastinos.",["race:Dwarf"]="Sa-ti vezi fratii pitici ucisi in timpul unei expeditii arheologice a Explorers' League transforma curatarea carierei infestate de rapitori intr-un act de onoare ancestrala si razbunare dreapta."},sec={{t="Orori dezgropate",b="Whelgar Excavation Site trebuia sa fie un triumf al arheologiei piticilor, scotand la lumina ramasite preistorice uriase ingropate sub noroiul din Wetlands. In schimb, dezgroparea oaselor colosale a atras atentia rapitorilor bastinasi ai mlastinii. Atrase de tulburare, haite de pradatori patati au napadit situl de excavare, luandu-i prin surprindere pe sapatori si rupandu-le randurile."},{t="O rezistenta amara",b="Doar o mana de pitici au supravietuit macelului initial. Ormer Ironbraid, Merrin Rockweaver si Prospector Whelgar au reusit sa se catere pe o stanca deasupra gropii, dar sunt in continuare blocati de haitele agresive de dedesubt. Cuprins de o durere cruda si o furie clocotitoare, Ormer refuza sa se ascunda pur si simplu. Simtindu-se dator sa-i apere pe Prospector si Merrin, care tremura de frica, el cheama calatorii capabili sa rareasca grupurile de Mottled Raptors si Mottled Screechers din imprejurimi, incepand astfel razbunarea."}},faq={{q="Ce s-a intamplat cu excavatorii de aici?",a="Cand arheologii pitici au descoperit oasele uriase din bazin, zarva si mirosul au atras haitele locale de raptoare din mlastina. Rapitoarele au napadit tabara, macelarind cea mai mare parte a echipajului si prinzandu-i pe cei trei supravietuitori in varful unei stanci inalte.",al={"de ce sunt raptoare aici","masacrul de la sapaturile lui Whelgar","ce i-a ucis pe dwarfi"}},{q="Cine este Ormer Ironbraid?",a="Ormer este unul dintre excavatorii pitici supravietuitori, blocati la Whelgar's Excavation Site. Desi considera ca onoarea il obliga sa ramana si sa-i protejeze pe Prospector Whelgar, tulburat, si pe Merrin Rockweaver, dorinta lui principala este sa se razbune cu sange pe rapitorii care i-au macelarit camarazii.",al={"cine este Ormer","trecutul lui Ormer Ironbraid"}},{q="De unde vin acesti rapitori?",a="Mottled Raptors si Mottled Screechers sunt pradatori nativi din Wetlands, care se ascund pe pantele noroioase si in mlastinile de la vest de promontoriul excavatiei, precum si de-a lungul cararilor ce duc spre pesterile sitului arheologic.",al={"unde sunt rapitorii pestriti","locatiile rapitorilor din wetlands"}},{q="De ce nu vaneaza Ormer rapitorii chiar el?",a="Desi abia asteapta sa verse personal sange de raptor, Ormer trebuie sa-i pazeasca pe Prospector Whelgar si Merrin Rockweaver, ingroziti, pentru ca refugiul lor pe stanca sa nu fie napadit.",al={"de ce nu se lupta Ormer","de ce este Ormer blocat"}},{q="Se sfarseste ranchiuna lui Ormer daca starpesti acesti rapitori?",a="Nu. Sa dobori raptorii obisnuiti Mottled si Screecher este doar primul pas din planul lui Ormer de a-si razbuna prietenii cazuti; loviturile impotriva hoardei de raptori vor fi si mai grele.",al={"este acesta sfarsitul pentru Ormer's Revenge","ce urmeaza pentru Ormer"}},{q="De ce au atras rapitorii atentia descoperirii oaselor?",a="Raptorii din Wetlands sunt extrem de teritoriali si scormonesc dupa hrana cu multa agresivitate. Exploziile si excavatiile printre ramasitele stravechi ale uriasilor au tulburat echilibrul firesc al bazinului, atragand pradatori curiosi si infometati chiar in mijlocul taberei de sapaturi.",al={"de ce au atras oasele rapitorii","oase de dinozaur si rapitori"}}},fx={["87324e21"]={q="De ce vrea Ormer Ironbraid sa fie omorati rapitorii?",a="Cand echipa dwarf a dezgropat oase stravechi la situl arheologic, rapitorii infometati au navalit asupra locului si i-au macelarit pe colegii lui Ormer. Ormer, Merrin Rockweaver si Prospector Whelgar au supravietuit cu greu atacului si au ramas blocati pe creste. Mistuit de durere si furie, Ormer vrea sa-si razbune fratii cazuti si sa inceapa sa alunge fiarele feroce de langa sapatura.",al={"motivul lui Ormer Ironbraid","de ce sa ucizi raptoarele pestrite","de ce cauta razbunare Ormer"}},["79eca2c5"]={q="Ce sunt rapitorii patati si tipatorii dupa care esti trimis?",a="Esti trimis impotriva rapitoarelor Mottled si a tipatoarelor Mottled care pandesc chiar la vest de povarnisul sapaturilor. Aceste reptile agresive, originare din Wetlands, au napadit situl imediat ce sapatorii au scos la iveala oase stravechi uriase, masacrandu-i si revendicand terenurile din jur drept loc de hranire.",al={"cu cine te lupti","tinte: tipatori patati","rapitori patati din Wetlands"}}},fp="15,339,17.382.0,14.475.0,37.255.0,23.280.0,33.216.0,43.186.0,46.188.0,49.240.0"}
P.entries["quest:2940"] = {n="Feralas: A History",s="Gasesti o carte care pare sa nu fi fost deschisa de o vesnicie si care ar putea fi exact ce ii trebuie lui Troyas. Ii apartine lui Daryn Lightwind, asa ca trebuie sa-i ceri voie s-o imprumuti.",h="Gasesti o carte care pare sa nu fi fost deschisa de o vesnicie si care ar putea fi exact ce ii trebuie lui...",kw={"carte","daryn lightwind","feralas","istorie","in search of knowledge","lore","troyas"},sec={{t="O carte neglijata",b="Copertele cartii sunt foarte uzate, iar paginile i s-au ingalbenit. Dupa ce o cercetezi, banuiesti ca ar putea fi ceea ce cauta Troyas. O ridici, apoi te razgandesti: nu ar trebui sa o imprumuti fara sa ceri voie. Este a lui Daryn Lightwind, asa ca ar trebui sa o intrebi mai intai."},{t="Raspunsul lui Daryn",b="Daryn Lightwind se opreste o clipa sa se gandeasca. Te va lasa sa imprumuti Feralas: A History, dar numai dupa ce-i faci un serviciu."}},faq={{q="Ce este cartea Feralas: A History?",a="O carte cu coperti uzate si pagini ingalbenite, care pare sa nu fi fost deschisa de veacuri. S-ar putea sa fie chiar ceea ce cauta Troyas.",al={"ce este cartea","Feralas, o carte de istorie","cartea lui troyas"}},{q="Cui apartine cartea?",a="Daryn Lightwind. Ar trebui sa-i ceri permisiunea inainte sa-l imprumuti.",al={"feralas, o istorie","cine are cartea","cine este Daryn Lightwind"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa In Search of Knowledge, in care Troyas Moonbreeze te-a trimis sa vorbesti cu Daryn Lightwind despre toiagul lui.",al={"misiunea anterioara","care a fost ultima misiune","lantul de misiuni anterior"}}},fp="18,180,16.257.0,14.141.1,36.142.0,18.56.0,23.114.0"}
P.entries["quest:2941"] = {n="The Borrower",s="Daryn Lightwind e fascinata de snapjawii de pe plaja din Hinterlands, mai ales de unul urias pe nume Gammerita. Cercetarile o obliga sa ramana pe loc, asa ca iti da o scrisoare pe care sa o duci la Curgle Cranklehop din Tanaris.",h="Daryn Lightwind e fascinata de snapjawii de pe plaja din Hinterlands, mai ales de unul urias pe nume...",kw={"curgle cranklehop","daryn lightwind","gammerita","snapjaw","instantaneu","super snapper fx","tanaris","the borrower"},sec={{t="Un portret al lui Gammerita",b="Daryn Lightwind spune ca a studiat multe domenii, iar cea mai recenta fascinatie a sa sunt snapjaw-ii care traiesc de-a lungul plajei din Hinterlands. O creatura pe care isi doreste in mod deosebit s-o vada este un snapjaw urias numit Gammerita. S-ar duce chiar ea, dar cercetarile o tin aici, asa ca o imagine cu Gammerita ar fi cea mai buna alternativa."},{t="Scrisoarea catre Tanaris",b="Daryn iti da o scrisoare pentru Curgle Cranklehop din Tanaris. Curgle a inventat pentru Daryn un aparat care poate face o fotografie, iar Daryn crede ca Curgle o numeste instantaneu."},{t="Reactia lui Curgle",b="Curgle te ia drept unul dintre stagiarii lui Daryn si vorbeste laudativ despre Daryn, un istoric priceput. Apoi Curgle pleaca sa aduca Super Snapper FX, convins ca o sa-ti placa."}},faq={{q="Cine te trimite la Tanaris?",a="Daryn Lightwind, care iti da o scrisoare de dus. Cercetarile o impiedica sa plece ea insasi.",al={"cel care da misiunea","cine da Borrower","daryn lightwind"}},{q="Cine este Curgle Cranklehop?",a="Cineva din Tanaris care a creat pentru Daryn un dispozitiv ce poate captura o imagine; Daryn crede ca se numeste instantaneu.",al={"cine este curgle","locatia lui Curgle Cranklehop","curgle tanaris"}},{q="De ce vrea Daryn o imagine cu Gammerita?",a="Daryn este fascinat de snapjaw de-a lungul plajei din Hinterlands si vrea sa o vada mai ales pe Gammerita. Cercetarile il impiedica pe Daryn sa plece, asa ca o imagine e urmatorul lucru cel mai bun.",al={"gammerita snapjaw","de ce gammerita","snapjaw urias"}},{q="Ce este Gammerita?",a="Un snapjaw urias de pe plaja din Hinterlands.",al={"cine este Gammerita","Gammerita"}}},fp="12,229,22.320.0,21.171.0,17.176.1,25.92.0,25.125.0,43.176.0,18.48.0"}
P.entries["quest:2942"] = {n="The Morrow Stone",s="De indata ce iei artefactul din Equinex Monolith, puterea din Stave of Equinex incepe sa se stinga. Trebuie sa duci Sparkling Stone si toiagul inapoi la Troyas Moonbreeze, la Feathermoon Stronghold.",h="De indata ce iei artefactul din Equinex Monolith, puterea din Stave of Equinex incepe sa se stinga.",kw={"equinex monolith","feathermoon stronghold","feralas","morrow stone","piatra sclipitoare","stave of equinex","troyas moonbreeze"},sec={{t="Inapoi la Feathermoon Stronghold",b="Pe masura ce artefactul se desprinde de monolit, energia toiagului incepe sa se stinga. Troyas Moonbreeze de la Feathermoon Stronghold abia asteapta sa afle ce ai descoperit, asa ca du-i atat Sparkling Stone, cat si toiagul."},{t="Descoperirile lui Troyas",b="Troyas a citit de cand ai plecat si numeste piatra Morrow Stone. Inca nu-i cunoaste rostul, dar orice lucru ascuns in monolit asa cum era acesta trebuie sa aiba o insemnatate uriasa. Isi va continua cercetarile si spera sa-i fii alaturi."}},faq={{q="Unde incepe asta?",a="La Equinex Monolith, dupa ce artefactul a fost luat de acolo.",al={"unde iau aceasta misiune","unde incep Morrow Stone","de unde incepe Equinex Monolith"}},{q="Cui trebuie sa-i duc piatra?",a="Troyas Moonbreeze, in Feathermoon Stronghold. Adu si Stave of Equinex.",al={"cine preda morrow stone","unde se afla troyas moonbreeze","cine primeste piatra stralucitoare"}},{q="Ce se intampla cu Stave of Equinex?",a="Energia sa incepe sa se stinga in clipa in care artefactul este luat din monolit.",al={"energia lui Stave of Equinex","ce se intampla cu toiagul","de ce si-a pierdut puterea toiagul"}},{q="Ce urmeaza inaintea acestui lucru?",a="Urmeaza dupa The Stave of Equinex, in care ai incarcat toiagul langa monolit.",al={"misiunea precedenta","ce misiune vine inaintea Morrow Stone","misiunea prealabila"}}},fp="16,213,30.204.0,17.267.1,22.66.0,28.77.0,37.77.0,23.86.0"}
P.entries["quest:2943"] = {n="Return to Troyas",s="Daryn Lightwind iti da cartea ei, Feralas: A History, si iti cere sa ai grija de ea. Trebuie s-o duci lui Troyas Moonbreeze, la Feathermoon Stronghold, care cu siguranta iti asteapta nerabdator intoarcerea.",h="Daryn Lightwind iti da cartea ei, Feralas: A History, si iti cere sa ai grija de ea.",kw={"darnassus","daryn lightwind","feathermoon stronghold","feralas","feralas: a history","troyas moonbreeze"},sec={{t="O carte imprumutata",b="Dupa ce ai recuperat Super Snapper FX, Daryn Lightwind iti da cartea ei si te roaga sa ai grija de ea. Te indeamna sa te grabesti, fiind sigura ca Troyas asteapta cu nerabdare sa te intorci. Cartea trebuie dusa la Troyas Moonbreeze, in Feathermoon Stronghold."},{t="Troyas citeste",b="Troyas se bucura ca ai adus cartea. O cerceteaza, ii rasfoieste paginile si exclama ca, dupa parerea lui, a gasit-o."}},faq={{q="Ce livrez?",a="Cartea lui Daryn Lightwind, Feralas: A History.",al={"ce carte este aceasta","ce sa-i aduc lui troyas","o carte de istorie despre feralas"}},{q="Unde se afla Troyas Moonbreeze?",a="La Feathermoon Stronghold.",al={"locatia lui troyas","unde este troyas moonbreeze","unde trebuie sa merg"}},{q="Cine iti da cartea?",a="Daryn Lightwind, care iti cere sa te ocupi de asta.",al={"cine da misiunea","cel care ofera misiunea","daryn lightwind"}},{q="Ce a fost inainte de asta?",a="Urmeaza The Super Snapper FX.",al={"misiunea anterioara","ce tocmai am facut","lantul de dinaintea acesteia"}}},fp="16,182,15.245.0,12.116.1,21.43.0,27.26.0,23.49.0,22.32.0"}
P.entries["quest:2944"] = {n="The Super Snapper FX",s="Curgle Cranklehop a pregatit un aparat foto nou, Super Snapper FX, si ti-l da sa-l incerci. Subiectul este Gammerita, o creatura din Hinterlands. Cu fotografia ei in mana, duci aparatul si poza la Daryn Lightwind, in Rut'theran Village. Aceasta misiune urmeaza dupa The Borrower.",h="Curgle Cranklehop a pregatit un aparat foto nou, Super Snapper FX, si ti-l da sa-l incerci.",kw={"curgle cranklehop","daryn lightwind","gammerita","rut'theran village","instantaneu","super snapper fx","the hinterlands"},sec={{t="Un dispozitiv de testat",b="Dupa The Borrower, Curgle Cranklehop iti prezinta Super Snapper FX, o noua inventie a sa. E simplu de folosit: indreapta-l spre ceea ce vrei sa fotografiezi si apasa butonul. Curgle ti-l da sa-l incerci."},{t="Subiectul",b="Subiectul este Gammerita, o creatura din Hinterlands despre care i-ai vorbit lui Curgle. Curgle iti ureaza noroc in gasirea ei si se asteapta ca Daryn Lightwind sa fie incantat de instantaneu. Dupa ce il obtii, du fotografia si aparatul la Daryn in Rut'theran Village."}},faq={{q="Cine ofera Super Snapper FX?",a="Curgle Cranklehop iti da dispozitivul, o inventie noua, ca sa-l incerci.",al={"cine ofera Super Snapper","cine da misiunea lui Curgle","de unde poti obtine Super Snapper FX"}},{q="Ce fotografiez cu Super Snapper FX?",a="Gammerita, o creatura din Hinterlands. Curgle iti ureaza noroc in cautarea ei.",al={"locatia lui gammerita","unde este gammerita","fotografia lui gammerita"}},{q="Cine primeste instantaneul?",a="Daryn Lightwind din Rut'theran Village. Ii aduci atat fotografia, cat si dispozitivul.",al={"unde predau Super Snapper FX","unde ajunge fotografia","cine este Daryn Lightwind"}},{q="Ce urmeaza in lantul de misiuni?",a="Lantul continua cu Return to Troyas.",al={"urmatoarea misiune dupa super snapper","ce urmeaza dupa super snapper fx"}}},fp="20,293,16.215.0,11.271.0,31.76.0,47.79.0,26.86.0,29.40.0"}
