P.entries["quest:3022"] = {n="Handle With Care",s="Curgle Cranklehop iti da o lada cu oua si iti cere sa o duci la druidul Erelas Ambersky, care poate fi gasit in Rut'theran, un satuc din Teldrassil.",h="Curgle Cranklehop iti da o lada cu oua si iti cere sa o duci la druidul Erelas Ambersky, care poate fi gasit...",kw={"curgle cranklehop","erelas ambersky","oua de hippogryph","rut'theran village","tanaris","teldrassil"},sec={{t="O lada cu oua",b="Curgle Cranklehop iti da o lada cu oua impachetata cu grija. Sunt oua de hippogrif, iar destinatarul lor este un druid pe nume Erelas Ambersky."},{t="Druidul din Rut'theran",b="Erelas Ambersky este un druid care are grija de aceste oua. Le ajuta sa eclozeze, apoi dreseaza tinerii hippogryphs. Rut'theran Village este un mic sat din Teldrassil, la sud."}},faq={{q="Ce se afla in lada de la Curgle Cranklehop?",a="Lada impachetata cu grija contine oua de hippogryph.",al={"ce se afla in lada","continutul lazii impachetate cu grija","ce car cu mine"}},{q="Unde trebuie dusa lada?",a="Lada ii este destinata druidului Erelas Ambersky, in micul sat Rut'theran din Teldrassil.",al={"unde duc lada","locatia lui Erelas Ambersky","unde se afla Rut'theran Village"}},{q="Cine este Erelas Ambersky?",a="Erelas Ambersky este un druid din Rut'theran Village. Are grija de ouale de hippogryph si ii antreneaza pe hippogryphii tineri dupa ce ies din ou.",al={"cine este erelas","ambersky poveste","cine primeste ouale"}}},fp="16,161,15.141.0,23.178.0,48.49.0,32.94.0,23.130.0"}
P.entries["quest:303"] = {n="The Dark Iron War",s="La marginea nordica a Wetlands, Motley Garmason organizeaza o aparare disperata pentru a recuceri Dun Modr de la Dark Iron clan. Dupa ce sabotorii inamici au sfaramat Thandol Span si au cucerit orasul, Ironforge Mountaineers au ramas sa tina o linie fragila, asteptand intariri care s-ar putea sa nu soseasca niciodata.",h="La marginea nordica a Wetlands, Motley Garmason organizeaza o aparare disperata pentru a recuceri Dun Modr de...",kw={"bronzebeard","fier intunecat","demolatori","dun modr","ironforge","motley garmason","sabotori","thandol span","wetlands"},ang={["faction:Alliance"]="Distrugerea Thandol Span si caderea Dun Modr intrerup accesul terestru dintre aliatii nordici ai Stormwind si regatele sudice.",["profession:Engineering"]="Precizia cu care sabotorii Dark Iron au folosit explozibili specializati pentru a sfarama vechile constructii de piatra ale dwarves dezvaluie o maiestrie infioratoare in demolarea structurilor.",["race:Dwarf"]="Pentru dwarves din Bronzebeard, pierderea lui Dun Modr este o umilinta amara si o amenintare directa la adresa suveranitatii Khaz Modan, care cere razbunare impotriva vechilor lor dusmani."},sec={{t="Un front la poarta de nord",b="Dun Modr era candva bastionul mandru al Ironforge, pazind capatul sudic al Thandol Span, podul colosal care uneste Khaz Modan de Lordaeron. Cand sabotorii si demolatorii Dark Iron au aruncat in aer arcada podului, au intrerupt circulatia Alliance si au coplesit rapid fortareata. Motley Garmason si cativa aparatori supravietuitori s-au retras suficient de departe pentru a infiinta o tabara de observatie, dar, fara contraatacuri imediate, intreaga poarta nordica risca sa ajunga pentru totdeauna sub stapanirea Dark Iron."},{t="Castigarea de timp pentru rezerve",b="Cu regimentele dwarven trimise pe campuri de lupta indepartate ale Alliance, mica unitate a lui Motley a fost lasata in mare parte sa se descurce singura. Cercetasii lui incearca sa ceara ajutorul Ironforge, dar comunicatiile s-au intrerupt, iar rezervele promise nu se vad nicaieri. Pentru a castiga timp si a perturba apararile inamice, Motley ordona lovituri tintite direct in ruinele din Dun Modr, ca sa rareasca randurile inginerilor, sapatorilor de tuneluri si soldatilor din prima linie Dark Iron, inainte ca acestia sa inainteze mai spre sud, in Wetlands."}},faq={{q="Cine este Motley Garmason?",a="Motley Garmason este un ofiter Mountaineer din Ironforge, care comanda ramasitele garnizoanei din Dun Modr. Stabilit chiar in afara orasului ocupat, el coordoneaza cercetarea terenului si atacurile de gherila impotriva fortelor Dark Iron de ocupatie.",al={"Motley Garmason","cine este Motley","comandantul din Dun Modr"}},{q="De ce este Dun Modr atat de important pentru Ironforge?",a="Dun Modr pazeste poalele sudice ale Thandol Span. Fiind singura sosea terestra care leaga Khaz Modan de Arathi Highlands si de nordul Lordaeronului, cine controleaza Dun Modr controleaza, de fapt, tot traficul terestru si aprovizionarea dintre aceste regiuni.",al={"de ce conteaza dun modr","importanta dun modr","istoria dun modr"}},{q="De ce se lupta piticii Dark Iron in Wetlands?",a="Dark Iron clan a cautat de multa vreme sa-si submineze verii Bronzebeard si sa slabeasca Alliance. Invadand Wetlands si distrugand Thandol Span, au intrerupt liniile de aprovizionare ale Ironforge spre nord si au deschis un al doilea front ostil in spatele granitelor Alliance.",al={"de ce sunt Dark Irons aici","Dark Iron in Wetlands","motivul Dark Iron War"}},{q="Ce s-a intamplat cu Thandol Span?",a="Minatorii si demolatorii Dark Iron au plasat explozibili concentrati in arcele de sustinere ale Thandol Span, avariind grav podul pentru a opri intaririle din Ironforge sa ajunga din Lordaeron, inainte sa cucereasca Dun Modr.",al={"Thandol Span distrus","cine a aruncat podul in aer","explozia de la Thandol Span"}},{q="Unde se afla fortele de rezerva din Ironforge?",a="Armata din Ironforge este puternic solicitata de mai multe campanii din strainatate si de apararea teritoriului propriu. Cercetasul lui Garmason, Roggo, s-a straduit sa stabileasca o legatura de incredere cu inaltul comandament, lasand avanpostul din Dun Modr sa tina linia cu orice aliati locali poate gasi.",al={"rezervele din ironforge","unde sunt intaririle","rezerva lui roggo"}},{q="Ce se intampla dupa respingerea Dark Irons din Dun Modr?",a="Eliminarea soldatilor de infanterie si a genistilor castiga timp pretios, dar informatiile lui Roggo dezvaluie ca Kam Deepfury, inchis in Stormwind Stockade, a ajutat la planuirea atacului asupra Thandol Span, iar Motley iti cere sa-i aduci capul lui Deepfury.",al={"urmatoarea misiune dupa Dark Iron War","misiunea Fury Runs Deep","ce urmeaza dupa Dark Iron War"}}},fx={["07a4003e"]={q="De ce vrea Motley Garmason ca acest lucru sa fie facut?",a="Motley este disperat sa recucereasca Dun Modr si sa opreasca inaintarea Dark Iron in Wetlands, inainte ca teritoriul Ironforge sa fie compromis cu totul. Dark Iron au aruncat deja in aer Thandol Span si au cucerit orasul, intrerupand legaturile esentiale cu nordul. Motley spera ca, punand imediat presiune ofensiva asupra liniilor lor, va putea mentine frontul suficient de mult pentru ca intaririle din Ironforge sa soseasca si sa-i alunge definitiv.",al={"motivul lui Motley Garmason","de ce sa luptam cu fierarii intunecati","de ce sa curatam Dun Modr"}},b2f42bee={q="De ce are Motley Garmason nevoie de ajutorul tau in loc sa-si foloseasca propriile trupe?",a="Armata permanenta din Ironforge este intinsa la limita, luptand departe de casa, pe taramuri straine, in numele Alliance. Dupa caderea Thandol Span si Dun Modr, Motley a ramas cu doar cativa aparatori si nu mai are soldati noi la dispozitie. Iscoadele sale nu reusesc sa mobilizeze rezervele, asa ca nu are de ales decat sa se bazeze pe calatori capabili ca tine, care sa duca lupta mai departe.",al={"de ce are Motley nevoie de mine","de ce nu se lupta gardienii","unde sunt trupele din Ironforge"}}},fp="17,310,28.523.0,28.515.0,23.229.0,42.247.0,51.264.0,34.223.0,39.269.0,59.235.1"}
P.entries["quest:304"] = {n="A Grim Task",s="Dupa atacul devastator al piticilor Dark Iron asupra localitatii Dun Modr si a podului Thandol Span, Longbraid the Grim cauta razbunare pentru rudele si soldatii cazuti. El le cere calatorilor curajosi sa-l gaseasca si sa-l ucida pe greu de prinsul warlock Dark Iron, Balgaras the Foul, si sa-i ia urechea drept dovada.",h="Dupa atacul devastator al piticilor Dark Iron asupra localitatii Dun Modr si a podului Thandol Span...",kw={"o sarcina sumbra","Balgaras the Foul","Dark Iron","Dun Modr","Longbraid the Grim","Roggo","Thandol Span","Wetlands"},ang={["class:Warlock"]="Balgaras the Foul foloseste magia fel malefica pentru a orchestra masacrarea aparatorilor din Dun Modr, aratand pana unde sunt dispusi sa mearga Dark Irons cu mestesugul lor periculos.",["faction:Alliance"]="Thandol Span este principala ruta terestra care leaga Khaz Modan de Lordaeron, astfel ca inlaturarea sabotorilor Dark Iron este o prioritate strategica esentiala pentru intreaga Alliance.",["race:Dwarf"]="Pentru dwarves din Ironforge, tradarea si violenta Dark Iron clan din Dun Modr reprezinta o jignire personala si o rana proaspata in indelungatul conflict civil dintre clanuri."},sec={{t="Ruinele din Dun Modr",b="Partea de nord a Wetlands a fost scena unor lupte aprige intre Mountaineers din Ironforge si infiltratii din Dark Iron clan. In timpul asediului, orasul Dun Modr a fost cucerit, iar podul vestic al Thandol Span a fost sfaramat. Longbraid the Grim nu a pierdut in asalt doar multi soldati loiali, ci si pe propriul frate, ceea ce l-a facut hotarat sa vada dusmanul platind cu aceeasi moneda."},{t="Un comandant las",b="Cercetarile cercetasilor precum Roggo au dezvaluit ca forta Dark Iron care ocupa Dun Modr este condusa de un vrajitor cunoscut drept Balgaras the Foul. In loc sa-si infrunte dusmanii fata in fata, Balgaras se ascunde, poruncindu-le soldatilor sa-i duca la indeplinire planurile intunecate. Longbraid spera ca uciderea lui Balgaras va frange coloana vertebrala a armatei Dark Iron, permitandu-le supravietuitorilor din Ironforge sa asigure trecatoarea vitala spre nord."}},faq={{q="Cine este Balgaras the Foul?",a="Balgaras the Foul este un vrajitor Dark Iron care comanda fortele ce ocupa Dun Modr, in nordul regiunii Wetlands. Longbraid the Grim il descrie drept un las; evita lupta directa si trimite multimi de soldati Dark Iron sa tina regiunea.",al={"Balgaras","cine este Balgaras","liderul Dark Iron din Dun Modr"}},{q="Cine este Longbraid the Grim?",a="Longbraid the Grim este un comandant pitic, aflat intr-o tabara de langa ruinele din Dun Modr. Si-a pierdut fratele si multi soldati cand fortele Dark Iron au cucerit asezarea si au distrus trecerea vestica de pe Thandol Span.",al={"longbraid","longbraid the grim","cel care da misiuni in dun modr"}},{q="De ce vrea Longbraid urechea lui Balgaras?",a="Deoarece Balgaras este o tinta greu de prins, care se ascunde deseori de lupta deschisa, Longbraid cere o dovada fizica a mortii warlockului, pentru a se asigura ca amenintarea a fost intr-adevar eliminata.",al={"de ce ear","Ear of Balgaras"}},{q="Ce s-a intamplat cu Thandol Span?",a="Podul vestic al Thandol Span a fost distrus de piticii Dark Iron in timpul ofensivei lor prin surprindere asupra Dun Modr, intrerupand o ruta esentiala intre Wetlands si Arathi Highlands.",al={"podul Thandol distrus","de ce este rupt Thandol Span"}},{q="Unde se ascunde Balgaras?",a="Balgaras pandeste printre fortificatiile cucerite si ruinele din jurul Dun Modr, ascunzandu-se in spatele soldatilor sai in loc sa iasa in mlastinile deschise.",al={"unde este balgaras","gaseste-l pe balgaras"}},{q="Ce se intampla dupa ce Balgaras este ucis?",a="Cu Balgaras mort, Longbraid crede ca trupele Dark Iron ramase, dezorganizate, vor fi mult mai usor de infrant inainte ca un alt comandant sa soseasca pentru a le intari randurile.",al={"dupa o sarcina grea","ce urmeaza in Dun Modr"}}},fx={["7a4e9943"]={q="De ce vrea Longbraid the Grim sa-l omoare pe Balgaras?",a="Longbraid a pierdut multi soldati in batalia de la Dun Modr, inclusiv pe propriul frate, care a pierit cand dwarves Dark Iron au distrus podul vestic al Thandol Span. Balgaras comanda fortele ostile Dark Iron din Wetlands, coordonand atacuri in timp ce se ascunde in siguranta in spatele subordonatilor sai. Ucigandu-l pe vrajitor, Longbraid cauta sa razbune rudele si soldatii cazuti, in speranta ca va destrama structura de comanda a cetei Dark Iron si le va aduce alinare supravietuitorilor.",al={"de ce sa-l ucizi pe Balgaras","motivul lui Longbraid","de ce vrea Longbraid ca acest lucru sa fie facut"}}},fp="11,288,21.409.0,20.441.0,25.240.0,26.217.0,39.180.0,34.200.0,25.155.0,37.171.0"}
P.entries["quest:305"] = {n="In Search of The Excavation Team",s="In Search of the Excavation Team incepe cu Tarrel Rockweaver, din Wetlands, care este coplesit de durere din cauza tacerii neasteptate a sotiei sale, Merrin. Repartizata la prestigiosul Whelgar Excavation Site, in est, ea nu i-a mai trimis scrisori de doua saptamani, iar el se teme ca expeditia a fost lovita de un dezastru. Calatorii trebuie sa se aventureze in mlastina, sa gaseasca situl de sapaturi si sa afle daca ea este in siguranta.",h="In Search of the Excavation Team incepe cu Tarrel Rockweaver, din Wetlands, care este coplesit de durere din...",kw={"breasla exploratorilor","in cautarea echipei de excavare","longbraid","merrin rockweaver","tarrel rockweaver","zone umede","excavatia Whelgar"},ang={["faction:Alliance"]="Mentinerea avanposturilor piticilor si a expeditiilor de cercetare prin mlastini este vitala pentru apararea Wetlands de pericolele salbaticiei care se apropie.",["race:Dwarf"]="Explorers' League este foarte mandra ca scoate la lumina istoria straveche, asa ca necazul rudelor lor de la excavarea Whelgar este o problema urgenta pentru orice dwarf ratacitor."},sec={{t="Groaza unui sot",b="In timp ce era stationat in intinderea mlastinoasa din Wetlands, Tarrel Rockweaver astepta cu nerabdare scrisorile regulate de la sotia sa, Merrin. Lucrand la sapaturile piticesti cunoscute drept Whelgar Excavation Site, Merrin trimitea saptamanal rapoarte despre munca lor. Cand au trecut doua saptamani intregi fara niciun cuvant, Tarrel s-a convins ca tabara fusese lovita de o nenorocire. Cu autoritatile piticilor oficiale suprasolicitate, el se bazeaza pe cercetasii aflati in trecere, care trebuie sa infrunte primejdiile mlastinilor pentru a vedea daca sapatorii mai sunt in viata."},{t="Sapaturile lui Whelgar",b="Whelgar Excavation Site este un exemplu tipic al eforturilor piticilor de a dezgropa relicve antice Titan si istoria faurita de Titan, ingropate in noroiul din Wetlands. Insa sapaturile in straturile preistorice ale tinuturilor salbatice ii expun adesea pe muncitori fiarelor neinblanzite si primejdiilor subterane ostile. Pentru a ajunge la sit, trebuie sa mergi spre est, in tinuturi indepartate de siguranta relativa a drumurilor principale, unde inca pandeste ceea ce a tulburat lucratorii sapaturilor si scrisorile lor."}},faq={{q="Cine este Tarrel Rockweaver?",a="Tarrel Rockweaver este un pitic ingrijorat, stationat in Wetlands. Ingrozit de intreruperea brusca a scrisorilor de la sotia sa Merrin, care lucreaza la situl arheologic din est, el ii confunda pe aventurierii aflati in trecere cu cercetasi oficiali trimisi sa afle de ce tabara a amutit.",al={"Tarrel Rockweaver","cel care da misiunea","cine da In Search of the Excavation Team"}},{q="Cine este Merrin Rockweaver?",a="Merrin Rockweaver este un arheolog pitic care lucreaza cu echipa de excavare a lui Whelgar, la est de Menethil Harbor, in Wetlands. Ii scria regulat sotului ei, pana cand o intorsatura neasteptata a evenimentelor i-a intrerupt brusc corespondenta.",al={"merrin rockweaver","sotia lui tarrel","cine este merrin"}},{q="Unde se afla Whelgar Excavation Site?",a="Whelgar Excavation Site se afla la est de Menethil Harbor si la sud-vest de Dun Modr, in Wetlands, cuibarit printre crestele stancoase, departe de drumul principal.",al={"locatia sitului de excavare","unde il gasesc pe Merrin","unde este excavarea lui Whelgar"}},{q="De ce a incetat Merrin sa trimita scrisori?",a="Linistea brusca de la locul sapaturilor a fost provocata de o amenintare aparuta acolo, care a izolat cercetatorii Dwarf de rutele obisnuite ale curierilor si de viata cotidiana a taberei.",al={"de ce au incetat scrisorile","ce s-a intamplat cu echipa de excavare","de ce nu mai vine posta"}},{q="Cine este 'Longbraid', mentionat de Tarrel?",a="Longbraid este o autoritate pitica ce a promis sa trimita cercetasi sa verifice echipa de excavare Whelgar daca se intrerupe comunicarea, ceea ce l-a facut pe Tarrel sa presupuna ca orice aventurier capabil sosit in ajutor fusese trimis la porunca lui Longbraid.",al={"cine este longbraid","cercetasul longbraid"}},{q="Este sigur sa te apropii de locul sapaturilor?",a="Nu. Situl se afla in tinutul salbatic si primejdios din Wetlands, iar orice a intrerupt expeditiile saptamanale ale echipei reprezinta o amenintare activa pentru oricine ajunge la sapaturi.",al={"este sapatura in siguranta","este whelgar periculos"}}},fx={d2e8931d={q="De ce are Tarrel Rockweaver nevoie de un aventurier care sa gaseasca echipa de excavare?",a="Tarrel este cuprins de griji in Menethil Harbor, dar nu este nici explorator inarmat, nici soldat capabil sa strabata singur mlastinile primejdioase. Dregatori locali precum Longbraid au promis ca vor trimite un cercetas cu experienta sa cerceteze tacerea de la situl arheologic. Cand sosesti, Tarrel te ia drept ajutorul capabil care i-a fost promis, ca sa infrunti salbaticia si sa afli ce s-a intamplat cu sotia lui.",al={"de ce ma trimite","de ce nu paznicii","de ce nu poate merge Tarrel"}}},fp="32,409,17.523.0,15.470.0,25.266.0,25.231.0,37.153.0,36.176.0,43.236.0,40.174.0"}
P.entries["quest:306"] = {n="In Search of The Excavation Team",s="Aceasta misiune transmite la Menethil Harbor vestea unui atac devastator al dinozaurilor asupra sitului de excavare al lui Whelgar. Merrin Rockweaver ii scrie in graba sotului ei ingrijorat, Tarrel, ca sa-l linisteasca, povestindu-i cum expeditia a fost coplesita.",h="Aceasta misiune transmite la Menethil Harbor vestea unui atac devastator al dinozaurilor asupra sitului de...",kw={"sapatura","menethil harbor","merrin rockweaver","raptori pestriti","ormer","tarrel rockweaver","wetlands","whelgar"},ang={["faction:Alliance"]="Drumurile de aprovizionare si proiectele de frontiera din Wetlands raman extrem de vulnerabile in fata fiarelor salbatice, impunand vigilenta constanta din partea calatorilor Alliance.",["race:Dwarf"]="Dezastrul de la situl de sapaturi loveste in plin ambitiile arheologice ale Dwarf si scoate in evidenta primejdiile cu care se confrunta exploratorii regelui Magni departe de siguranta din Ironforge."},sec={{t="Un mesaj din ruine",b="Dupa ce gaseste ramasitele echipei de sapaturi, ascunse langa creasta care domina locul, Merrin Rockweaver ofera un raport pripit. Dezgroparea unor artefacte rare alaturi de fosile preistorice uriase s-a dovedit fatala, cand haitele de rapitoare pestrite din zona s-au napustit asupra sapatorilor. Ferocitatea neasteptata i-a ucis pe cei mai multi membri ai echipei, iar supravietuitorii au ramas izolati de civilizatie."},{t="O usurare amara",b="Intoarcerea la Menethil Harbor ii aduce lui Tarrel Rockweaver o mangaiere sumbra. Gandul ca sotia lui si cel putin doi insotitori au supravietuit datorita curajului unui aparator pe nume Ormer il linisteste, desi macelul atator camarazi apasa greu asupra spiritului de frontiera al orasului."}},faq={{q="Ce s-a intamplat cu echipa de excavare din Wetlands?",a="In timp ce dezgropau artefacte rare si oase stravechi uriase, expeditia piticilor a fost luata prin surprindere si coplesita de raptoare pestrite, teritoriale. Majoritatea sapatorilor au fost ucisi, iar doar cativa supravietuitori au ramas prinsi pe povarnisurile de deasupra sitului arheologic.",al={"ce s-a intamplat cu situl arheologic","dezastrul sapaturilor din Wetlands","de ce au esuat sapaturile"}},{q="Cine l-a salvat pe Merrin Rockweaver?",a="Merrin spune ca un aparator curajos pe nume Ormer a alungat raptoarele si a escortat-o pe ea si pe Prospector spre siguranta relativa de pe creasta, in timp ce situl de jos se prabusea.",al={"cine l-a salvat pe Merrin","Ormer Rockweaver","cine este Ormer"}},{q="Cine este Tarrel Rockweaver?",a="Tarrel Rockweaver este sotul lui Merrin, stationat la Menethil Harbor. Ingrijorat de lipsa vestilor de la locul sapaturilor, a cautat calatori care sa-i investigheze disparitia.",al={"cine este tarrel","locatia lui tarrel rockweaver"}},{q="Unde se afla situl de excavare?",a="Santierul de excavare se afla in interiorul regiunii Wetlands, la est de Menethil Harbor si la sud-vest de Dun Modr.",al={"unde se afla excavatia","locatia excavatiei lui whelgar"}},{q="Ce cauta sapand expeditia?",a="Sub indrumarea prospectorilor dwarveni, echipa excava artefacte rare din subteran si fosile preistorice de mari dimensiuni, ingropate in mlastini.",al={"ce cautau in sapaturi","artefacte din excavatie"}},{q="Exista si alti supravietuitori in afara de Merrin?",a="Da, Merrin mentioneaza ca Ormer si seful Prospector au reusit sa scape de rapitori alaturi de ea, ridicand la trei numarul cunoscut al supravietuitorilor.",al={"cine a mai supravietuit","supravietuitori ai sapaturilor"}}},fx={["2f0bde8f"]={q="De ce vrea Merrin Rockweaver sa-i duci scrisoarea?",a="Merrin vrea sa-si linisteasca sotul, pe Tarrel, si sa-l asigure ca a supravietuit atacului salbatic asupra sitului de excavare. Raptoarele le-au invadat tabara si au macelarit multi dintre arheologi, lasandu-i pe Merrin, Prospector Whelgar si Ormer prinsi intr-un adapost improvizat. Neputand razbi singuri prin fiare, ea iti incredinteaza scrisoarea, ca Tarrel sa afle ca sunt in viata si sa inteleaga soarta crunta a expeditiei.",al={"de ce sa duc scrisoarea lui Merrin","motivul lui Merrin Rockweaver","de ce sa duc biletul la Tarrel"}},f4e86a28={q="De ce nu poate Merrin Rockweaver sa livreze ea insasi biletul?",a="Merrin si ceilalti supravietuitori sunt izolati si tinuti la pamant de raptoare patate, agresive. Parasirea adapostului i-ar expune fiarelor feroce care au sfasiat deja restul echipei de excavare. Fiind un calator in putere, capabil sa razbata prin mlastini si prin haitele de raptoare, poti duce in siguranta vestea la Menethil Harbor, lucru pe care ei nu-l pot face.",al={"de ce are merrin nevoie de mine","de ce nu poate merrin sa plece de la situl de excavare","de ce are merrin nevoie de ajutor"}}},fp="32,245,24.370.0,15.277.0,53.256.0,28.174.0,25.183.0,30.99.0,36.148.0,40.145.0"}
P.entries["quest:3062"] = {n="Dark Heart",s="Talo Thornhoof de la Camp Mojache vrea inima intunecata a Edanei Hatetalon, regina harpiilor din Northspring, care traieste in ruinele din vest. Talo o numeste intruchiparea raului.",h="Talo Thornhoof de la Camp Mojache vrea inima intunecata a Edanei Hatetalon, regina harpiilor din Northspring...",kw={"camp mojache","dark heart","edana hatetalon","feralas","harpy","hatetalon stones","northspring","talo thornhoof"},sec={{t="Regina Harpy",b="Edana Hatetalon este regina harpiilor si conduce hoarda Northspring din ruinele aflate la vest. Talo o numeste intruchiparea raului, fara alt sentiment in suflet decat ura fata de toti, si a auzit ca inima ei este facuta din cristal. Talo vrea sa o infrunti si sa-i aduci inapoi inima neagra, pentru ca ura pe care o raspandeste trebuie oprita."},{t="O chemare",b="Talo a auzit de un corn purtat de harpii. Se spune ca, daca este sunat langa pietrele Hatetalon, in partea de nord a ruinelor, o va atrage afara pe regina. Talo se bucura la gandul ca ai ei nu vor fi chemati sa raspunda; moartea ei va fi."},{t="La intoarcerea ta",b="Acum, Talo este sigur ca Edana a disparut pentru totdeauna si spune ca inima va fi pastrata in amintirea faptelor tale."}},faq={{q="Cine este Edana Hatetalon?",a="Ea conduce harpiile Northspring in ruinele vestice. Talo o numeste incarnarea raului si spune ca nu simte decat ura; a auzit si ca inima ei este de cristal.",al={"edana hatetalon","regina harpiilor din Feralas","cine este regina harpiilor"}},{q="Cum poate fi invocata Edana Hatetalon?",a="Talo a auzit ca harpiile poarta un corn si ca, daca il sufli langa pietrele Hatetalon de la capatul nordic al ruinelor, o vei chema pe regina.",al={"cum sa o invoc pe Edana","sufla in corn in Feralas","pietrele Hatetalon"}},{q="Cine da misiunea de vanatoare pentru Edana Hatetalon?",a="Talo Thornhoof, la Camp Mojache.",al={"cine ofera dark heart","talo thornhoof","unde gasesti dark heart"}},{q="De ce vrea Talo Thornhoof inima lui Edana?",a="Talo vrea sa puna capat urii pe care Edana o raspandeste peste tinut si iti cere inima ei intunecata.",al={"de ce inima intunecata","motivul lui talo thornhoof"}}},fp="10,170,15.315.0,9.230.0,14.107.1,23.148.0,36.142.0,39.32.0,43.89.0"}
P.entries["quest:3063"] = {n="Vengeance on the Northspring",s="Talo Thornhoof a fost candva un vanator incercat, caruia nu-i era teama de nicio creatura, pana cand harpiile l-au atacat prin surprindere in padure. Ura clocoteste in el de atunci, iar Talo iti cere sa te razbuni pe harpiile Northspring, aflate spre vest.",h="Talo Thornhoof a fost candva un vanator incercat, caruia nu-i era teama de nicio creatura, pana cand harpiile...",kw={"feralas","harpies","northspring","razbunare","roguefeather","slayer","talo thornhoof","windcaller"},sec={{t="O ranchiuna veche a unui Hunter",b="Talo isi aminteste ca era un Hunter incercat, care nu se temea de nicio creatura. Apoi, intr-o zi, in padure, in timp ce-si ascutea arma dupa o lupta grea, harpiile l-au inconjurat pe Talo. Abia a reusit sa se tarasca la adapost, iar si acum le aude tipetele rasunandu-i in minte. N-a mai fost niciodata la fel. Dupa atata timp, ura inca fierbe in el, iar Talo vrea sa se razbune."},{t="Harpile Northspring",b="Harpiile Northspring traiesc spre vest. Talo vrea sa omori cate patru Northspring Harpies, Roguefeathers, Windcallers si Slayers. Aripile lor sunt negre ca noaptea, te avertizeaza Talo, si se pot pierde din vedere in intuneric."},{t="Dupa vanatoare",b="Talo, vorbind ca un tauren batran, iti multumeste si spune ca ai linistit o minte tulburata."}},faq={{q="Cine este Talo Thornhoof?",a="Un vanator incercat in vremurile de odinioara, care nu se temea de nicio creatura pana cand harpiile l-au prins in ambuscada pe Talo, in padure. Dupa aceea, Talo n-a mai fost niciodata la fel.",al={"povestea lui talo thornhoof","cine da misiunea Vengeance on the Northspring","talo feralas"}},{q="Unde se afla Northspring harpies?",a="La vest de Talo Thornhoof.",al={"locatia lui northspring harpies","unde se afla northspring harpies","locatia harpiilor din feralas"}},{q="De ce vrea Talo sa se razbune pe harpii?",a="Harpiile l-au prins in ambuscada pe Talo in padure, l-au inconjurat in timp ce isi ascutea o arma dupa o lupta, iar Talo a scapat cu greu. N-a mai fost niciodata la fel, iar ura continua sa fiarba in el.",al={"de ce sa ucid harpiile Northspring","povestea lui Talo Thornhoof","de ce le uraste Talo pe harpii"}},{q="Ce harpii vrea Talo sa fie ucise?",a="Cate patru din fiecare dintre Northspring Harpies, Northspring Roguefeathers, Northspring Windcallers si Northspring Slayers.",al={"tinte pentru vengeance on the northspring","ce harpies sa ucid","tipuri de northspring harpy"}},{q="Cum arata Northspring harpies?",a="Talo spune ca aripile lor sunt negre ca noaptea si te avertizeaza ca se pot pierde in intuneric.",al={"infatisare de harpy","aripi de harpy din northspring"}}},fp="28,228,22.338.0,23.229.0,14.91.1,22.132.0,42.30.0,47.174.0,36.113.0,42.91.0"}
