P.entries["quest:3090"] = {s="Un mesager lasa un pergament marcat in timp ce esti plecat, iar profesorul tau Nartok vrea sa vorbeasca cu tine. Cuvintele sale provoaca domnia lui Thrall si avertizeaza asupra pericolului cu care se confrunta cei care detin puterea vrajitorilor.",h="Un mesager lasa un pergament marcat in timp ce esti plecat, iar profesorul tau Nartok vrea sa vorbeasca cu...",kw={"besudeltes pergament","den","nartok","orgrimmar","vraja","sclav","valea incercarilor","vrajitor"},ang={["class:Warlock"]="In calitate de vrajitor, avertismentul lui Nartok se refera la puterea pe care o detii si pericolul de a actiona nechibzuit."},sec={{t="Un mesaj asteapta",b="Se spune ca pergamentul vine de la Nartok, noul tau profesor. Vi se cere sa o cititi si sa vorbiti cu el in Barlogul din Valea Incercarilor. Nartok vorbeste despre orci ca despre un popor mandru si sustine ca Thrall se indeparteaza de puterea care ar putea face tara a lor."},{t="Un loc printre ei",b="Nartok spune ca v-ati alaturat randurilor lor, dar avertizeaza ca accesul la puterea vrajitorului nu va va face binevenit. Thrall permite vrajitorilor sa intre in Orgrimmar, deoarece raman orci; Nartok va avertizeaza ca imprudenta poate fi fatala. El ramane disponibil daca aveti nevoie de instructiuni in vraji."}},faq={{q="Cine a trimis pergamentul?",a="Se crede ca pergamentul provine de la Nartok, noul tau profesor.",al={"cine a trimis asta","pergament de la cine"}},{q="Unde pot vorbi cu Nartok?",a="Nartok este in Barlogul din Valea Incercarilor.",al={"unde este nartok","locatie nartok"}},{q="Ce parere are Nartok despre Thrall?",a="Nartok spune ca Thrall se indeparteaza de puterea care ar putea face pamantul al lor.",al={"opinie esclava","de ce critica thrall"}},{q="De ce Thrall permite vrajitorilor sa intre in Orgrimmar?",a="Nartok spune ca Thrall permite vrajitorilor sa intre in Orgrimmar pentru ca sunt inca orci.",al={"vrajitori in orgrimmar","de ce thrall permite vrajitorilor"}},{q="Ce avertisment da Nartok?",a="Nartok avertizeaza ca accesul la puterea vrajitorilor nu asigura acceptarea si ca imprudenta poate fi fatala.",al={"avertisment nartok","pericol de vrajitor"}},{q="Poate Nartok sa ma invete vraji?",a="Nartok spune ca il poti cauta din nou daca ai nevoie de instructiuni in vraji.",al={"lectii de vraji","antrenament de vrajitor"}}},fp="17,205,15.258.0,18.284.1,23.64.0,30.45.0,33.73.0,46.78.0,30.105.0,27.75.0"}
P.entries["quest:3091"] = {n="Simple Note",s="Simple Note este o scurta convocare scrisa, inmanata de un mesager local tinerilor razboinici tauren din Camp Narache. Scrisa de instructorul Harutt Thunderhorn, ii cheama pe tinerii luptatori sa se prezinte la datorie si le reaminteste rolul esential al razboinicilor, alaturi de druizi si shamani, in apararea granitelor tribale impotriva centaurilor.",h="Simple Note este o scurta convocare scrisa, inmanata de un mesager local tinerilor razboinici tauren din Camp...",kw={"Camp Narache","centaur","Harutt Thunderhorn","Mulgore","Red Cloud Mesa","nota simpla","Tauren","Warrior"},ang={["class:Warrior"]="Harutt Thunderhorn ii indruma pe razboinicii tauren incepatori, invatandu-i sa-si tempereze mandria martiala si sa poarte povara grea a apararii Camp Narache impotriva centaurilor pradalnici.",["race:Tauren"]="Pentru tinerii tauren care isi incep calatoria in Red Cloud Mesa, aceasta nota intareste ideea ca datoria razboinica de a proteja tribul sta alaturi de vocatii spirituale precum samanismul si druidismul."},sec={{t="O chemare la lupta",b="La sosirea in Camp Narache, tinerii razboinici primesc o scurta convocare adusa de un mesager al taberei. Scrisa de veteranul instructor Harutt Thunderhorn, Simple Note ii cere luptatorului in devenire sa se prezinte imediat pentru a-si incepe pregatirea practica in apararea tribului."},{t="Povara aparatorului",b="Desi Shu'halo isi venereaza profund conducatorii spirituali, Harutt le aminteste elevilor sai ca aparatorii fizici poarta o povara la fel de mare. Razboinicii sunt chemati sa patruleze granitele tribale, sa vaneze haite de centauri rapitori si sa-si apere rudele pasnice de agresiunile din afara. In ciuda gloriei dobandite in lupta, fiecare razboinic trebuie sa ramana umil si sa indeplineasca aceleasi rituri traditionale ca orice saman sau druid."}},faq={{q="Cine a scris Simple Note?",a="Biletul este trimis de Harutt Thunderhorn, instructorul de razboinici din Camp Narache, printr-un mesager care ii cauta pe tinerii tauren gata sa-si inceapa pregatirea martiala.",al={"cine a trimis biletul simplu","cine a scris biletul","expeditorul biletului simplu"}},{q="Cine este Harutt Thunderhorn?",a="Harutt Thunderhorn este un antrenor de razboinici tauren stationat in Camp Narache, in Mulgore. El ii pregateste pe razboinicii incepatori care cauta gloria luptei si vechile traditii ale razboiului tribal.",al={"cine este Harutt","Harutt Thunderhorn","unde este Harutt"}},{q="Care este scopul Simple Note?",a="Nota ii cheama pe razboinicii abia treziti sa-si intalneasca instructorul si le aminteste ca aparatorii din prima linie si vanatorii sunt la fel de importanti pentru trib ca druizii si samanilor.",al={"de ce este importanta nota","ce scrie in nota"}},{q="De ce li se cere razboinicilor sa vaneze centauri?",a="Taurenii din Mulgore se confrunta cu amenintari neincetate din partea cetei de centauri ostili de la granitele tinutului. Razboinicii precum Harutt au sarcina de a-i instrui pe aparatorii tribali sa-i vaneze si sa protejeze tabara.",al={"de ce sa luptam cu centaurii","conflictul dintre Tauren si centauri"}},{q="Unde se afla Camp Narache?",a="Camp Narache este tabara ancestrala de antrenament si asezarea de pornire pentru tinerii tauren din tribul Hawkwind, la marginea Red Cloud Mesa, in Mulgore.",al={"locatia camp narache","unde se afla camp narache"}},{q="Care sunt ritualurile tribale mentionate de Harutt?",a="Fiecare membru al tribului, fie ca este warrior, hunter, shaman sau druid, trebuie sa treaca prin ritualurile ancestrale comune ale tribului pentru a-si dovedi puterea, smerenia si devotamentul fata de poporul sau.",al={"riturile de trecere la maturitate ale taurenilor","ce rituri urmeaza taurenii"}}},fp="11,325,19.276.0,21.396.0,26.164.0,26.178.0,39.168.0,45.189.0,30.153.0,42.191.0"}
P.entries["quest:3092"] = {n="Etched Note",s="Etched Note este o convocare oficiala adresata tinerilor vanatori tauren promitatori din Camp Narache. Mesajul, transmis in numele instructorului Lanka Farshot, il cheama pe novice sa inceapa sa-si insuseasca artele practice si spirituale ale salbaticiei.",h="Etched Note este o convocare oficiala adresata tinerilor vanatori tauren promitatori din Camp Narache.",kw={"camp narache","nota gravata","Lanka Farshot","Mulgore","Red Cloud Mesa","vanator tauren"},ang={["class:Hunter"]="Aceasta chemare marcheaza primirea ta oficiala in traditia Hunter, pregatindu-te sa stapanesti arta tintasilor, supravietuirea in salbaticie si legatura cu animalele.",["race:Tauren"]="Pentru Shu'halo, vanatoarea este o datorie sacra, prin care cinstesc Earth Mother respectand fiarele ce sustin tribul prin campiile din Mulgore."},sec={{t="O chemare la vanatoare",b="In timpul antrenamentului printre falezele din Red Cloud Mesa, tinerilor tauren care dovedesc talent la tragerea cu arcul si la urmarirea prazii li se incredinteaza un mesaj gravat. Transmis de Grull Hawkwind, biletul le da de veste ca Lanka Farshot a remarcat obarsia si potentialul brut al tinerilor, indemnandu-i sa-si oficializeze studiile sub privirea lui atenta."},{t="Traditia campiilor",b="Pentru Shu'halo, un vanator este mult mai mult decat un simplu cercetas sau razboinic. Vanatorii sustin triburile prin vanarea prazii, protejeaza taberele nomade si traiesc in stransa armonie cu fiarele din Kalimdor. Chemarea novicei la instruire pune bazele deprinderii armelor, intelegerii creaturilor din Mulgore si, in cele din urma, insusirii stravechii arte de a imblanzi insotitori salbatici."}},faq={{q="La ce foloseste Etched Note?",a="Etched Note serveste drept prezentare oficiala, facand cunostinta unui novice Tauren cu Lanka Farshot, antrenorul local de clasa din Camp Narache.",al={"la ce foloseste biletul gravat","scopul biletului gravat","de ce am primit un bilet gravat"}},{q="Cine livreaza biletul?",a="Grull Hawkwind transmite biletul mai departe, explicand ca un mesager al instructorului de vanatoare l-a cautat pe tanarul vanator cu putin timp in urma.",al={"cine da nota gravata","cine ofera misiunea cu nota gravata","nota lui rohaku"}},{q="Unde se afla Lanka Farshot?",a="Lanka Farshot locuieste in Camp Narache, pe Red Cloud Mesa, langa terenurile de pregatire ale vanatorilor, gata sa-i instruiasca pe noii recruti.",al={"unde este Lanka Farshot","gaseste-l pe Lanka Farshot","locatia lui Lanka"}},{q="De ce sunt vanatorii atat de venerati printre taureni?",a="Hunterii joaca un rol esential in societatea Tauren: asigura hrana, descifreaza salbaticia neimblanzita si mentin armonia cu spiritele campiilor.",al={"povestea vanatorilor Tauren","de ce sunt importanti vanatorii Tauren"}},{q="Ce aptitudini te invata acest antrenament?",a="Lanka il initiaza pe novice in tehnicile de baza ale vanatorii, inclusiv folosirea armelor de distanta, intelegerea bestiilor salbatice si, in cele din urma, ritualurile necesare pentru a imblanzi tovarasi animale.",al={"ce te invata Lanka","notiuni de baza pentru Hunter Tauren"}},{q="Care este urmatorul pas dupa citirea biletului?",a="Prezentarea in fata lui Lanka Farshot incheie convocarea si il desemneaza drept instructorul tau; el te va invata sa tragi cu pusca, sa imblanzesti un animal de companie si multe altele pe masura ce progresezi.",al={"misiunea urmatoare dupa nota gravata","continuarea notei gravate"}}},fx={["69749d8d"]={q="De ce iti da Grull Hawkwind biletul gravat?",a="Grull Hawkwind doar iti transmite un mesaj din partea unui sol trimis prin Camp Narache. Lanka Farshot, instructorul de vanatori al taberei, l-a trimis pe sol anume sa te gaseasca, acum ca ai ajuns la varsta maturitatii. Grull se asigura doar ca primesti chemarea fara intarziere, ca sa-ti poti incepe pregatirea cuvenita alaturi de ai tai.",al={"de ce da Rohaku un bilet","motivul lui Rohaku Stonehoof","de ce mi-a dat Rohaku asta"}}},fp="11,247,21.346.0,23.398.0,39.152.0,22.132.0,31.134.0,44.152.0,41.189.0,45.148.0"}
P.entries["quest:3094"] = {n="Verdant Note",s="Verdant Note este o convocare oficiala adresata tinerilor tauren promitatori din Red Cloud Mesa. Incredintat de Grull Hawkwind, mesajul ii indeamna pe viitorii aparatori ai salbaticiei sa-l caute pe mentorul druidic Gart Mistrunner la Camp Narache.",h="Verdant Note este o convocare oficiala adresata tinerilor tauren promitatori din Red Cloud Mesa.",kw={"camp narache","druid","earthmother","gart mistrunner","grull hawkwind","mulgore","red cloud mesa","nota verdanta"},ang={["class:Druid"]="Aceasta invocatie marcheaza initierea timpurie a unui druid in canalizarea energiilor salbatice si a spiritelor neodihnite din Azeroth.",["faction:Horde"]="Druizii tauren reprezinta principala punte dintre Horde moderna si misterele naturii din Kalimdor, oferind echilibru spiritual fortei martiale brute a factiunii.",["race:Tauren"]="Pentru tauren, druidismul nu este doar o scoala de magie, ci un legamant sacru mostenit din veneratia mitica fata de Earthmother."},sec={{t="O chemare pe cale",b="Tinerii tauren care isi asuma responsabilitatile pe Red Cloud Mesa sunt remarcati repede pentru darurile lor firesti. Grull Hawkwind transmite acest mesaj in numele unui sol trimis de Gart Mistrunner. Biletul este o invitatie de a se alatura stravechii traditii a druidismului tauren, chemandu-l pe initiat sa lase in urma indatoririle obisnuite ale satului si sa asculte echilibrul soptit al campiilor."},{t="Vocile Mamei Pamant",b="Dupa ce raspunde chemarii, Gart Mistrunner il avertizeaza pe tanarul druid ca spiritele stramosilor si ale naturii au devenit nelinistite in tot Mulgore. Druizii tauren au sarcina de a fi intruchipari vii ale naturii si de a pastra armonia cu vointa lui Earthmother, indiferent de rivalitatile indepartate. Desi si elfii noptii practica artele druidice, Gart ii atrage atentia ca mandria ii impiedica sa vada legatura profunda a taurenilor cu lumea naturala."}},faq={{q="Ce este Verdant Note?",a="Este o invocare introductiva adresata tinerilor druizi tauren din Camp Narache. Le cere celor care o primesc sa-l caute pe instructorul local, Gart Mistrunner, pentru a incepe pregatirea organizata in artele druidice.",al={"Verdant Note","scrisoare de Druid","nota pentru misiunea Druid din Mulgore"}},{q="Cine ii livreaza biletul jucatorului?",a="Grull Hawkwind ii da biletul tanarului druid si mentioneaza ca un mesager trimis de Gart Mistrunner i-a cautat de curand.",al={"cine ofera biletul verdant","cel care incepe misiunea verdant note"}},{q="Unde poate fi gasit Gart Mistrunner?",a="Gart Mistrunner locuieste in Camp Narache, adapostit sub povarnisurile naturale ale taberei, unde supravegheaza instruirea druidilor tauren incepatori.",al={"Gart Mistrunner, locatie","unde este Gart"}},{q="De ce avertizeaza Gart Mistrunner impotriva Night Elves?",a="Desi ambele rase venereaza natura si practica druidismul prin Cenarion Circle, Gart observa ca aroganta elfilor noptii le influenteaza adesea felul in care privesc alte culturi. Isi indeamna elevul sa nu ia in seama asemenea atitudini si sa se concentreze doar asupra intelepciunii Mamei Pamant.",al={"taurenii si druizii night elf","mandria night elf a druizilor"}},{q="De ce sunt nelinistite spiritele din Mulgore?",a="Gart Mistrunner simte tulburari care agita spiritele stramosilor si ale naturii pe campiile din Mulgore, un semn timpuriu ca echilibrarea salbaticiei va fi responsabilitatea de-o viata a noului druid.",al={"spiritele din Mulgore sunt nelinistite","de ce sunt spiritele naturii furioase"}},{q="Ce abilitate te invata Gart dupa ce termini aceasta misiune?",a="Dupa ce-i dai raportul lui Gart Mistrunner, acesta devine antrenorul novicei si promite sa o invete darurile Earthmother pe masura ce capata intelepciune.",al={"ce urmeaza dupa nota verde","continuarea misiunii Druid"}}},fx={["92e5d696"]={q="De ce iti da Grull Hawkwind Verdant Note?",a="Un mesager te-a cautat anume in numele lui Gart Mistrunner, mentorul druid al taberei. Grull Hawkwind doar iti transmite mesajul urgent, ca sa nu intarzii inceperea pregatirii tale spirituale oficiale sub indrumarea lui Gart.",al={"de ce da Rohaku nota","motivul lui Rohaku Stonehoof","de ce vrea Rohaku sa se faca asta"}}},fp="12,237,21.383.0,25.433.0,25.201.0,36.134.0,35.150.0,54.278.0,40.202.0,62.137.0"}
P.entries["quest:3096"] = {n="Encrypted Scroll",s="Encrypted Scroll este o convocare discreta inmanata pungasilor Forsaken abia treziti la Deathknell. Transmisa de Shadow Priest Sarvis, scrierea cifrata il indruma pe recrut catre David Trias, un mentor pungas care isi desfasoara activitatea discret la hanul local.",h="Encrypted Scroll este o convocare discreta inmanata pungasilor Forsaken abia treziti la Deathknell.",kw={"David Trias","Deathknell","pergament criptat","rogue Forsaken","Shadow Priest Sarvis","Shadowstalkers","Tirisfal Glades"},ang={["class:Rogue"]="Aceasta scrisoare marcheaza inrolarea ta oficiala in reteaua clandestina a Forsaken, facand legatura dintre un cadavru abia inviat si un aspirant la rolul de agent sub acoperire.",["race:Undead"]="Pe masura ce Forsaken, abia intemeiati, isi apara Tirisfal Glades de Scourge si de ramasitele celor vii, cercetasii si agentii sub acoperire sunt esentiali pentru strategia de supravietuire a Dark Lady."},sec={{t="O chemare tacuta",b="In vreme ce Forsaken abia inviat lupta cu zombi lipsiti de minte in cimitir, conducatorii asezarii ii remarca pe cei cu o inclinatie deosebita spre furisare si viclesug. Shadow Priest Sarvis le inmaneaza acest pergament sigilat cercetasilor promitatori, dupa ce acestia isi dovedesc pregatirea de baza. Pecetluit cu sigiliul discret al lui David Trias, este o prima introducere in reteaua tainica ce opereaza in ierarhia Forsaken."},{t="Ochi in umbra",b="David Trias supravegheaza rascrucea de drumuri si hanul din Deathknell, cautand posibili candidati pentru viitoare operatiuni clandestine. In locul hotilor de rand sau al pungasilor nechibzuiti, Forsaken au nevoie de agenti clandestini disciplinati care sa slujeasca regatul abia intemeiat. Trias lasa sa se inteleaga ca talharii priceputi ar putea atrage intr-o zi atentia Shadowstalkers, o casta de elita din randul Forsaken, care pretuieste siretenia, precizia si loialitatea absoluta fata de Dark Lady."}},faq={{q="Care este scopul lui Encrypted Scroll?",a="Pergamentul este o invitatie privata pentru noii rogues Forsaken treziti. Shadow Priest Sarvis ti-l inmaneaza dupa ce dovedesti ca esti capabil, indrumandu-te sa te prezinti la David Trias pentru pregatire specializata.",al={"ce este pergamentul criptat","ce face pergamentul","de ce este pergamentul criptat"}},{q="Cine este David Trias?",a="David Trias este instructorul rogue din hanul din Deathknell. El evalueaza noii recruti si cauta potentiali agenti pentru operatiunile mai ample de informatii ale Forsaken.",al={"david trias","cine este trias","antrenorul rogue din deathknell"}},{q="Cine sunt Shadowstalkers mentionati de Trias?",a="Shadowstalkers sunt o organizatie de agenti si asasini Forsaken specializati in furisare. Trias ii avertizeaza pe noii hoti ca Shadowstalkers recruteaza doar agenti talentati si disciplinati, nu pungasi neindemanatici.",al={"cine sunt Shadowstalkers","Shadowstalkers Forsaken","Shadowstalkers"}},{q="De ce este criptat mesajul?",a="Nelegiuitii Forsaken pretuiesc secretul si siguranta operatiunilor. Transmiterea instructiunilor prin mesaje criptate asigura protejarea comunicarilor sensibile de ochii indiscreti intr-o asezare vulnerabila precum Deathknell.",al={"de ce e criptat","de ce cifru"}},{q="Unde il gasesti pe Shadow Priest Sarvis?",a="Shadow Priest Sarvis supravegheaza primirea noilor Forsaken in complexul central de cripte si capele din Deathknell, in Tirisfal Glades.",al={"unde este sarvis","locatia lui sarvis","gaseste-l pe Shadow Priest Sarvis"}},{q="Unde se afla David Trias?",a="David Trias se afla in cladirea avariata a hanului, putin mai jos pe poteca fata de capela centrala din Deathknell.",al={"unde se afla Trias","locatia lui David Trias","antrenorul din hanul Deathknell"}}},fp="16,243,15.433.0,19.443.0,44.200.0,19.169.0,46.205.0,29.217.0,39.142.0,29.108.0"}
P.entries["quest:3097"] = {n="Hallowed Scroll",s="Hallowed Scroll este o convocare de initiere adresata preotilor Forsaken abia treziti la Deathknell. Inmanat de Shadow Priest Sarvis, mesajul il cheama pe novice la Dark Cleric Duesten, in capela distrusa din sat, pentru a afla cum isi folosesc mortii-vii credinta dupa moarte.",h="Hallowed Scroll este o convocare de initiere adresata preotilor Forsaken abia treziti la Deathknell.",kw={"Dark Cleric Duesten","Deathknell","preot Forsaken","pergament sfant","misiune de Priest","Shadow Priest Sarvis","Tirisfal Glades"},ang={["class:Priest"]="Aceasta misiune marcheaza botezul tau filozofic in preotia Forsaken: renunti la evlavia traditionala si imbratisezi autonomia, suferinta si magia umbrelor.",["race:Undead"]="Pergamentul intruchipeaza viziunea Forsaken asupra lumii: desprinsi de vechea lor credinta omeneasca, supravietuiesc numai prin vointa de fier si necesitatea de a se sustine reciproc."},sec={{t="O chemare in Deathknell",b="Pe masura ce mortii-vii abia treziti se clatina iesind din mormintele din Deathknell, mintea lor este adesea tulburata de trauma plagii, a mortii si a eliberarii bruste de sub puterea Lich King. Pentru cei care in viata fusesera adepti devotati ai Holy Light, confuzia este neobisnuit de profunda. In timp ce mortii-vii abia treziti se lupta cu Scourge-ul fara minte care bantuie imprejurimile asezarii, Shadow Priest Sarvis intercepteaza mesajele primite. Purtand insemnul Dark Cleric Duesten, sulul sfintit le porunceste preotilor proaspat inviati sa renunte la pribegie si sa se prezinte la capela pangarita a orasului."},{t="Credinta redefinita",b="Dupa ce preda pergamentul, un novice descopera teologia aspra a preotimii Forsaken. Dark Cleric Duesten nu indulceste adevarul: Holy Light i-a parasit in moarte, spiritele stramosilor sunt basme goale, iar demonii planari nu sunt interesati de soarta lor. In schimb, preotii Forsaken ii invata ca doar vointa neclintita si increderea radicala in propriile puteri sunt surse reale de mantuire. Sub indrumarea lui Duesten, practicantii proaspat ridicati invata sa canalizeze atat disciplina divina, cat si umbra, manuind puterea nu din devotament fata de zei indepartati, ci din convingerea absoluta ca trebuie sa supravietuiasca."}},faq={{q="Ce este Hallowed Scroll?",a="Este un document sigilat, oferit de Shadow Priest Sarvis preotilor Forsaken abia inviati din Deathknell. Acesta le cere sa-l caute pe Dark Cleric Duesten in capela orasului, pentru a-si incepe pregatirea preoteasca oficiala.",al={"sul sfintit","obiect sul","sul de Priest"}},{q="Cine ii trimite pergamentul jucatorului?",a="Pergamentul poarta sigiliul personal al lui Dark Cleric Duesten, preotul Forsaken care indruma noii discipoli in capela din Deathknell, desi ti-l inmaneaza Shadow Priest Sarvis.",al={"cine a trimis sulul","sulul lui Duesten","scrisoarea lui Sarvis"}},{q="Mai pot Forsaken sa foloseasca Holy Light?",a="Dark Cleric Duesten le spune preotilor noi ca Holy Light nu-i mai priveste. Dupa cum explica el, venerarea traditionala a Luminii este abandonata in favoarea credintei in sine si a stapanirii Umbrei.",al={"strigoii folosesc lumina","Lumina Sfanta a Forsaken","pot strigoii sa foloseasca lumina"}},{q="Unde se afla Dark Cleric Duesten?",a="Se afla in biserica ruinata din centrul Deathknell, in vestul regiunii Tirisfal Glades, langa alti instructori Forsaken.",al={"gaseste-l pe duesten","locatia lui duesten","unde este clericul duesten"}},{q="De ce ii respinge Duesten pe stramosi si demoni?",a="Duesten vrea sa spulbere toate iluziile celor proaspat ridicati din morti. Le spune ca Light nu-i mai priveste, ca spiritele stramosilor lor sunt basme si ca fapturile din Nether nu-i doresc, predicand in schimb ca Forsaken au supravietuit numai prin vointa lor.",al={"discursul lui duesten","basme","nether nu te vrea"}},{q="Ce se intampla dupa ce citesti pergamentul?",a="Citesti pergamentul si te prezinti in fata lui Dark Cleric Duesten, in capela din Deathknell, deblocandu-ti primele abilitati de priest si stabilindu-l drept antrenorul tau pe durata sederii in zona de start.",al={"obiectivul pergamentului sfintit","predarea pergamentului"}}},fp="15,277,23.577.0,15.584.0,28.210.0,35.179.0,40.201.0,37.133.0,46.288.0,38.197.0"}
P.entries["quest:3098"] = {n="Glyphic Scroll",s="Glyphic Scroll este o convocare oficiala trimisa magilor Forsaken proaspat treziti la viata in Deathknell. Purtand sigiliul formatoarei de magi Isabella, pergamentul ii indeamna pe practicantii promitatori ai magiei arcane sa o caute in biserica profanata a satului, pentru a-si stapani puterile volatile.",h="Glyphic Scroll este o convocare oficiala trimisa magilor Forsaken proaspat treziti la viata in Deathknell.",kw={"arcane","Deathknell","Mage renegat","Glyphic Scroll","Isabella","antrenor de magi","Tirisfal Glades"},ang={["class:Mage"]="Acest pergament marcheaza initierea ta oficiala in randurile magilor Forsaken, legand direct arta ta magica de supravietuirea si renasterea poporului tau, proaspat eliberat.",["race:Undead"]="Mage-ii Forsaken folosesc magia arcana cu scopuri intunecate, tratand-o nu ca pe un joc academic din Dalaran, ci ca pe o arma indispensabila pentru a-si recuceri patria furata."},sec={{t="O chemare catre arcane",b="Cand un Forsaken abia ridicat din morti isi dovedeste inclinatia spre magia arcana in timp ce starpeste Scourge fara minte din jurul lui Deathknell, atrage repede atentia celor mai varstnici. Glyphic Scroll, adusa personal, poarta sigiliul arcane al Isabellei, instructoarea locala de magie. Pergamentul ii cere practicantului abia renascut sa se prezinte la postul ei din biserica in ruine, recunoscand ca aptitudinile magice necontrolate reprezinta un pericol la fel de mare pentru Forsaken ca si pentru dusmanii lor."},{t="Folosirea magiei in moartea vie",b="In capela in ruine din Deathknell, Isabella le explica incepatorilor ca moartea nu i-a scutit de primejdiile artelor arcane. Chiar daca si-au pierdut slabiciunile trupesti, atractia nestatornica si natura corupatoare a magiei au ramas la fel de puternice. Pentru Forsaken, urmarirea suprematiei arcane nu este doar un exercitiu intelectual, ci un instrument al supravietuirii si razbunarii - un mijloc de a-si revendica destinul si de a-i nimici pe toti cei care le contesta fragila recucerire a Lordaeronului."}},faq={{q="Ce este Glyphic Scroll?",a="Glyphic Scroll este un document cu instructiuni, purtand sigiliul personal al Isabellai, instructorul de magie Forsaken din Deathknell. Acesta le cere magilor abia treziti sa se prezinte la biserica in ruina pentru a-si aprofunda studiul magiei arcane.",al={"misiunea cu Glyphic Scroll","ce este acest pergament","pergamentul din Deathknell"}},{q="Cine iti trimite Glyphic Scroll?",a="Pergamentul este trimis de Isabella, instructorul mag din Deathknell, si iti este inmanat dupa ce iti dovedesti utilitatea ocupandu-te de Scourge fara minte din apropiere.",al={"cine a trimis pergamentul","cine a scris Glyphic Scroll","expeditorul lui Glyphic Scroll"}},{q="Unde se afla Isabella?",a="Isabella este postata in biserica in ruina din centrul satului Deathknell, alaturi de alti indrumatori de clasa care ii calauzesc pe Forsaken abia inviat.",al={"unde se afla isabella","gaseste-o pe isabella","locatia instructorului mage din deathknell"}},{q="De ce te avertizeaza Isabella cu privire la coruptia magica?",a="Isabella avertizeaza ca, desi Forsaken sunt strigoi, natura nestatornica a puterii arcane ramane neschimbata. Magia implica in continuare riscul constant al coruperii si dependentei, iar stapanirea ei fara a fi mistuit de aceasta cere disciplina si vointa.",al={"coruptia magiei undead","poveste despre coruptia arcana","de ce este magia periculoasa pentru undead"}},{q="De ce este magia arcana importanta pentru Forsaken din Deathknell?",a="Magii Forsaken considera puterea arcana un instrument vital pentru a recuceri Lordaeron si a-si asigura autonomia impotriva Scourge-ului fara minte, a muritorilor vii ostili si a Scarlet Crusade.",al={"de ce folosesc forsaken magia","povestea magilor undead"}},{q="Poate orice clasa Forsaken primi acest pergament?",a="Nu. Glyphic Scroll le este oferit exclusiv magilor Forsaken, ca o convocare de initiere la instructorul lor principal de clasa din Deathknell.",al={"Glyphic Scroll este doar pentru Mage","pot Warlock sa primeasca Glyphic Scroll","cine primeste Glyphic Scroll"}}},fp="14,286,23.482.0,25.502.0,27.226.0,36.169.0,26.165.0,52.239.0,60.174.0,43.134.0"}
P.entries["quest:3099"] = {n="Tainted Scroll",s="The Tainted Scroll este o misiune de inceput din Deathknell, care ii indruma pe warlockii Forsaken abia treziti catre instructorul lor, Maximillion. Prin acest mesaj, Maximillion il invita pe initiat sa imbratiseze puterea si servitutea intunecata, ca mijloace de a-si dobandi adevarata libertate.",h="The Tainted Scroll este o misiune de inceput din Deathknell, care ii indruma pe warlockii Forsaken abia...",kw={"Deathknell","Forsaken","Maximillion","Scourge","Sylvanas","Tainted Scroll","Tirisfal Glades","vrajitor"},ang={["class:Warlock"]="Maximillion ii initiaza pe proaspat trezitii warlock Forsaken in Deathknell, prezentand demonologia si subjugarea drept afirmarea suprema a stapanirii si libertatii.",["race:Undead"]="Vrajitorii Forsaken stabilesc o paralela intunecata intre eliberarea de Scourge si cautarea unor slujitori demonici pe care sa-i supuna vointei lor, pentru a supravietui."},sec={{t="O chemare intunecata",b="La scurt timp dupa ce Forsaken abia ridicati din morti incep sa curete ramasitele lipsite de minte ale Scourge din jurul Deathknell, soseste un mesaj sumbru purtand sigiliul lui Maximillion, instructorul local de warlock. Pergamentul il indeamna pe destinatar sa cumpaneasca natura supunerii si a autonomiei, inainte de a se intoarce in asezarea ruinata ca sa discute direct cu el."},{t="Filosofia controlului",b="Raspunzand chemarii, Maximillion isi dezvaluie filosofia despre putere si supunere. Dupa ce a scapat de stapanirea lipsita de minte a lui Lich King, sustine ca un sclav ramane sclav, indiferent cine-i este stapanul, pana cand pune mana pe o autoritate adevarata. In ochii lui, stapanirea slujitorilor demonici nu este o tradare a lui Sylvanas, ci urmarea fireasca a luptei Forsaken pentru autodeterminare si respect."}},faq={{q="Cine a trimis Tainted Scroll?",a="Pergamentul este livrat purtand sigiliul personal al lui Maximillion, antrenorul de warlock stabilit in Deathknell, care ii cauta pe cei abia treziti la practicarea artelor intunecate.",al={"cine trimite Tainted Scroll","cine mi-a dat Tainted Scroll","expeditorul lui Tainted Scroll"}},{q="Cine este Maximillion?",a="Maximillion este instructorul de vrajitorie din Deathknell, unde ii invata pe Forsaken proaspat inviati artele intunecate ale invocarii si controlului entitatilor demonice.",al={"cine este Maximillion","Maximillion din Deathknell","dresor de Warlock din Deathknell"}},{q="Ce scrie pe Tainted Scroll?",a="Pergamentul este o scrisoare trimisa warlocks abia treziti, care cugeta la libertate, putere si natura servitutii, indemnandu-l pe cititor sa-l viziteze pe Maximillion pentru instruire mai aprofundata.",al={"ce este Tainted Scroll","ce spune pergamentul","mesajul din pergament"}},{q="Este Maximillion un tradator al lui Lady Sylvanas?",a="Maximillion afirma clar ca nu este tradatorul Lady-ei Sylvanas. Sustine ca Banshee Queen i-ar aprecia perspectiva si argumenteaza ca propria ei cautare a autodeterminarii i-a rupt din lanturile Scourge.",al={"este maximillion un tradator","il tradeaza maximillion pe sylvanas","loialitatea lui maximillion"}},{q="Unde il gasesc pe Maximillion?",a="Maximillion locuieste in Deathknell, asezarea in ruine din Tirisfal Glades, unde Forsaken abia inviat ies pentru prima data din morminte.",al={"unde il gasesti pe Maximillion","locatia lui Maximillion"}},{q="Care este scopul acestei misiuni?",a="Misiunea este chemarea de inceput pentru warlockii Forsaken abia ridicati din morti: ii initiaza in pregatirea clasei si ii indruma catre mentorul local din Deathknell.",al={"de ce misiunea Warlock implica Tainted Scroll","scopul Tainted Scroll"}}},fp="14,258,14.340.0,25.413.1,28.171.0,19.148.0,38.178.0,42.202.0,29.134.0,34.176.0"}
P.entries["quest:31"] = {n="Aquatic Form",s="Aceasta misiune marcheaza ultima etapa din calatoria unui tanar druid al Horde spre stapanirea apelor. Dupa ce isi dovedeste vrednicia si se armonizeaza cu aspectul leului de mare in Moonglade, druidul se intoarce acasa, in Thunder Bluff, pentru a primi recunoasterea oficiala si a-si stapani forma acvatica.",h="Aceasta misiune marcheaza ultima etapa din calatoria unui tanar druid al Horde spre stapanirea apelor.",kw={"forma acvatica","Dendrite Starblaze","Druid","Moonglade","Pendant of the Sea Lion","leu de mare","Thunder Bluff","Turak Runetotem"},ang={["class:Druid"]="Dobandirea formei acvatice face legatura dintre uscat si mare, permitandu-ti sa strabati cu usurinta intinderile de apa si sa scapi de pradatorii din adancuri.",["faction:Horde"]="Druizii tauren intruchipeaza legatura spirituala dintre Horde si Cenarion Circle, calatorind intre sanctuare neutre stravechi si capitalele propriilor triburi.",["race:Tauren"]="Turak Runetotem iti aminteste ca stapanirea fiarelor marii iti onoreaza stramosii, consolidand renasterea sacra a taurenilor in traditia druidica."},sec={{t="Intoarcerea leului de mare",b="Dupa ce a infruntat incercarile din sanctuarul sacru al Moonglade, un aspirant tauren Druid este indrumat de Dendrite Starblaze inapoi spre Mulgore. Purtand Pendant of the Sea Lion, initiatul poarta dovada concreta a echilibrului si devotamentului sau peste apele Kalimdor. Acesta este o dovada palpabila ca a respectat traditiile stravechi necesare pentru a adopta o forma acvatica."},{t="Comuniunea cu apele",b="Dupa ce urca pe culmile din Thunder Bluff, calatorul ii prezinta pandantivul mentorului sau, Turak Runetotem. Incantat ca initiatul isi onoreaza stramosii si respecta echilibrul natural, Turak ii impartaseste taina formei acvatice. Datorita acestei invataturi, druidul dobandeste abilitatea innascuta de a se strecura pe sub rauri si oceane, respirand liber si strabatand adancurile ca o creatura marina."}},faq={{q="Care este scopul acestei misiuni?",a="Aceasta misiune incheie ritul de trecere pentru tinerii druizi Horde, permitandu-le sa predea in sfarsit in Thunder Bluff Pendant of the Sea Lion, castigat cu greu, si sa-si deblocheze forma schimbatoare Aquatic Form.",al={"de ce sa faci aceasta misiune","scopul formei acvatice","ce face aceasta misiune"}},{q="Cui trebuie sa-i duc Pendant of the Sea Lion?",a="Trebuie sa duci pandantivul la Turak Runetotem, antrenorul de druizi aflat pe inaltimile superioare din Thunder Bluff, in Mulgore.",al={"cine preda asta","unde predau forma acvatica","locatia lui Turak Runetotem"}},{q="Cine te trimite inapoi la Thunder Bluff?",a="Dendrite Starblaze, un druid night elf pazitor, aflat in sanctuarul neutru din Moonglade, te trimite inapoi dupa ce iti inchei incercarile acvatice.",al={"cine da misiunea pentru forma acvatica","misiunea lui Dendrite Starblaze"}},{q="Pot cei care nu sunt druizi sa indeplineasca aceasta misiune?",a="Nu. Acest sir de misiuni le este rezervat exclusiv druzilor, ca parte a evolutiei lor spirituale si magice, necesara pentru a debloca formele de animale.",al={"este doar pentru druid","pot si alte clase sa foloseasca forma acvatica"}},{q="De ce il ajuta un elf al noptii din Moonglade pe un druid din Horde?",a="Moonglade este un sanctuar neutru aflat sub supravegherea Cenarion Circle. Cand ii invata artele stravechi ale caii Cenarion, mentorii night elf ii indruma pe druizii tauren fara ostilitate politica, concentrandu-se exclusiv pe pastrarea echilibrului naturii.",al={"de ce ii ajuta dendrite pe cei din Hoarda","Moonglade, Hoarda si Alianta","neutralitatea druizilor"}},{q="Ce abilitate primesti la finalizarea acestei misiuni?",a="Dupa predarea misiunii lui Turak Runetotem, inveti Aquatic Form, care iti ofera viteza sporita de inot si respiratie sub apa cat timp esti transformat.",al={"ce forma primesc","vraja formei acvatice","forma acvatica"}}},fx={["269933c9"]={q="De ce te trimite Dendrite Starblaze inapoi la Thunder Bluff?",a="Dendrite Starblaze iti supravegheaza incercarile din Moonglade in numele Cenarion Circle, insa Moonglade este un sanctuar al invataturii, nu casa ta. Dupa ce ti-a pus la incercare rezistenta si respectul fata de apa, Dendrite si-a incheiat indatoririle. Te indruma inapoi la mentorul tau local, Turak Runetotem, de pe Elder Rise din Thunder Bluff, ca sa prezinti dovada ritualurilor tale si sa primesti binecuvantarea finala care iti ofera forma acvatica.",al={"de ce sunt trimis la turak","motivul lui dendrite starblaze","de ce return to thunder bluff"}}},fp="12,268,22.381.0,25.390.0,34.200.0,46.120.0,36.147.0,35.127.0,53.231.0,46.153.0"}
P.entries["quest:310"] = {n="Bitter Rivals"}
P.entries["quest:3100"] = {n="Simple Letter",s="Simple Letter este o directiva introductiva care ii indruma pe razboinicii incepatori catre instructorul Llane Beshere, la Northshire Abbey. Aceasta marcheaza inceputul pregatirii lor martiale oficiale si ii indeamna sa-i ajute pe locuitorii aflati la ananghie din vale.",h="Simple Letter este o directiva introductiva care ii indruma pe razboinicii incepatori catre instructorul...",kw={"elwynn forest","cavalerii silver hand","llane beshere","northshire abbey","northshire valley","scrisoare simpla","antrenor warrior"},ang={["class:Warrior"]="Llane Beshere este instructorul razboinic din Northshire Abbey, iar aceasta scrisoare simpla reprezinta prima chemare la disciplina martiala pentru luptatorii abia sositi.",["faction:Alliance"]="Chiar si in sanctuarul relativ protejat de Silver Hand, noii recruti sunt chemati imediat sa-i ajute pe cetatenii greu incercati ai Alliance.",["race:Human"]="Northshire Abbey este leaganul aventurierilor oameni care pornesc la drum prin Elwynn Forest, unde recruti locali primesc primele indrumari."},sec={{t="Un Call to Arms",b="Simple Letter este o prima scrisoare de prezentare pentru razboinicii aspiranti care sosesc in Northshire Valley. Adresata lui Llane Beshere, instructorul razboinic din Northshire Abbey, scrisoarea ii indeamna pe luptatorii nou-veniti sa-si contacteze instructorul, sa se familiarizeze cu imprejurimile si sa se pregateasca pentru rigorile vietii martiale."},{t="Asigurarea securitatii vaii",b="Desi Northshire Abbey se bucura de protectia vigilenta a Knights of the Silver Hand, aparenta linistita a vaii ascunde probleme mai profunde. Asa cum observa Beshere la primirea scrisorii, locuitorii din imprejurimi se confrunta cu numeroase necazuri, care au nevoie de protectori in putere, indemnandu-i pe recruti sa-si stapaneasca armele si sa se ridice in apararea regatului."}},faq={{q="Ce este Simple Letter?",a="Simple Letter este o scrisoare de prezentare inmanata razboinicilor din Northshire Valley dupa ce se intorc din taberele kobolzilor. Ii indruma sa se prezinte antrenorului local de razboinici, Llane Beshere, pentru a-si incepe pregatirea martiala oficiala.",al={"ce este Simple Letter","misiunea Simple Letter","scrisoare de inceput, razboinic uman"}},{q="Cine este Llane Beshere?",a="Llane Beshere este instructorul de razboinici aflat la Northshire Abbey. El ii invata tehnici de lupta pe razboinicii novici si ii primeste pe recruti atunci cand sosesc in vale cu ordine sau recomandari de a-l cauta.",al={"cine este Llane Besher","locatia lui Besher","unde este antrenorul de Warrior din Northshire"}},{q="Unde predau Simple Letter?",a="Scrisoarea ii este dusa direct lui Llane Beshere, care poate fi gasit in Northshire Abbey, in Northshire Valley, inconjurat de domeniile adapostite si ocrotite de ordinul sfant.",al={"unde predau Simple Letter","predarea scrisorii Simple Letter","locatia lui Llane Besher"}},{q="Ce rol au Knights of the Silver Hand in Northshire?",a="Knights of the Silver Hand ajuta la paza Northshire Valley, mentinand abatia si imprejurimile imediate relativ in siguranta, astfel incat recrutii, fermierii si clericii sa-si poata indeplini indatoririle in ciuda tensiunilor locale tot mai mari.",al={"ce fac paladinii in northshire","silver hand northshire abbey","paladinii din elwynn"}},{q="De ce au nevoie cetatenii de aici de ajutor?",a="Desi abatia este destul de bine aparata, locuitorii din imprejurimi se confrunta constant cu incursiuni si lipsuri. Beshere ii indeamna pe noii veniti sa cerceteze tinuturile din jur si sa-si puna forta martiala in slujba celor nevoiasi.",al={"de ce vrea beshere sa-i ajut pe cetateni","probleme din northshire","cine are nevoie de ajutor in northshire"}},{q="Cand ar trebui sa ma intorc la Llane Beshere dupa ce predau scrisoarea?",a="Llane Beshere este disponibil in abatie zi si noapte, gata sa-i instruiasca pe razboinici pe masura ce capata experienta in lupta si au nevoie de aptitudini martiale avansate.",al={"cand ar trebui sa ma intorc la llane beshere","mai mult antrenament pentru clasa Warrior in northshire","antrenament beshere"}}},fp="13,241,14.355.0,19.380.0,26.249.0,21.213.0,37.176.0,63.220.0,49.217.0,66.154.0"}
P.entries["quest:3101"] = {n="Consecrated Letter",s="Consecrated Letter este o convocare introductiva purtata de initiatii Holy Light care ajung in Northshire Valley. Ii cere purtatorului sa se prezinte la instructorul clasei sale din Northshire Abbey, pentru a-si incepe pregatirea si a-si imbratisa rolul de simbol vizibil al credintei.",h="Consecrated Letter este o convocare introductiva purtata de initiatii Holy Light care ajung in Northshire...",kw={"fratele sammuel","consecrated letter","elwynn forest","Lumina Sfanta","northshire","northshire abbey","paladin","antrenor"},ang={["class:Paladin"]="In calitate de purtatori ai Holy Light, paladinilor le revine sarcina de a-i intruchipa virtutile si de a fi faruri de speranta pentru aliatii lor din Northshire si de pretutindeni.",["faction:Alliance"]="Se asteapta ca reprezentantii Holy Light sa se poarte cu onoare, pastrand prestigiul moral si aparand Alliance.",["race:Human"]="Pentru oamenii care isi incep slujirea la Northshire Abbey, scrisoarea le subliniaza datoria de a fi simboluri onorabile intr-un regat tulburat de incercarile recente."},sec={{t="O chemare sacra",b="Consecrated Letter marcheaza inceputul oficial al calatoriei unui initiat in Northshire Valley. Adresat noilor veniti care manevreaza puterea Holy Light, documentul ii cere purtatorului sa-si caute instructorul la Northshire Abbey, pentru a-si oficializa pregatirea si a-si accepta responsabilitatile in cadrul Kingdom of Stormwind."},{t="Purtarea Luminii",b="Dupa prezentarea scrisorii, initiatului i se aminteste de responsabilitatea pe care o implica menirea sa. Holy Light straluceste vizibil in cei care o canalizeaza, facandu-i simboluri imediate ale sperantei pentru aliati si tinte clare pentru adversari. Instructorul subliniaza ca o asemenea putere cere purtare disciplinata si constientizarea exemplului oferit celorlalti."},{t="Indrumare si Discipline",b="Dincolo de obligatiile spirituale, scrisoarea stabileste o relatie de durata intre ucenic si mentor. Pe masura ce initiatul isi incearca puterile impotriva amenintarilor locale din Northshire, se asteapta sa revina cu regularitate pe domeniul manastirii pentru a descoperi taine mai profunde ale luptei si ale harului divin."}},faq={{q="Ce este Consecrated Letter?",a="Consecrated Letter este o scrisoare de chemare adresata unui initiat al Holy Light din Northshire Valley. Il indruma pe purtator catre instructorul clasei sale de la Northshire Abbey, pentru a-si incepe pregatirea si a-si aminti indatoririle sacre.",al={"ce este consecrated letter","misiunea consecrated letter"}},{q="De unde provine Consecrated Letter?",a="Dupa ce un paladin nou se intoarce din taberele koboldilor, cineva de la Northshire Abbey ii inmaneaza scrisoarea, pecetluita cu insemnul Brother Sammuel, prin care paladinului i se cere sa vina la el.",al={"cine da Consecrated Letter","cine trimite Consecrated Letter"}},{q="Cine primeste Consecrated Letter?",a="Scrisoarea ii este inmanata fratelui Sammuel, instructorul de paladini aflat langa intrarea in Northshire Abbey din Elwynn Forest.",al={"cine preda consecrated letter","cine citeste consecrated letter"}},{q="Ce rol are instructorul dupa ce citeste scrisoarea?",a="Instructorul este un indrumator in caile lui Holy Light, invatandu-l pe initiat tehnici martiale, binecuvantari defensive si vraji sacre, pe masura ce acesta castiga experienta practica in lupta prin vale.",al={"ce te invata antrenorul","de ce sa te antrenezi cu antrenorul"}},{q="De ce mentioneaza scrisoarea ca ar fi un simbol?",a="Cei care canalizeaza puterea Holy Light sunt vazuti drept exemple vii de credinta si virtute. Atat prietenii, cat si dusmanii recunosc puterea Light, ceea ce ii face pe cei care o folosesc figuri importante, al caror comportament se reflecta asupra credintei insesi.",al={"de ce sunt un simbol","simbolul Luminii Sacre"}},{q="Unde are loc aceasta instruire?",a="Northshire Abbey se afla in valea nordica linistita din Elwynn Forest, servind drept sanctuar al credintei si principal loc de recrutare pentru aparatorii Kingdom of Stormwind.",al={"unde este Northshire Abbey","unde duc scrisoarea"}}},fp="18,271,16.325.0,18.350.0,23.308.0,31.246.0,44.187.0,36.129.0,57.204.0,43.222.0,36.182.0"}
P.entries["quest:3102"] = {n="Encrypted Letter",s="Encrypted Letter este o convocare secreta trimisa potentialilor rogues de la Northshire Abbey, pecetluita cu insemnul lui Jorik Kerridan. Aceasta ii prezinta pe noii operativi antrenorului lor din grajdurile izolate si le ofera primele sfaturi despre cum sa supravietuiasca intereselor periculoase ale unor organizatii precum SI:7 si Defias Brotherhood.",h="Encrypted Letter este o convocare secreta trimisa potentialilor rogues de la Northshire Abbey, pecetluita cu...",kw={"Defias Brotherhood","scrisoare codificata","Jorik Kerridan","Northshire Abbey","Northshire Valley","instructor Rogue","SI:7"},ang={["class:Rogue"]="Aceasta depesa cifrata marcheaza initierea unui tanar hot in tainele lui Jorik Kerridan si ale lumii interlope, oferindu-i primele sfaturi despre cum sa navigheze printre factiuni precum SI:7 si Defias fara sa-si piarda independenta.",["faction:Alliance"]="Chiar si in spatele zidurilor pioase ale Northshire Abbey, agentii din umbra ai Kingdom of Stormwind recruteaza si instruiesc discret agenti promitatori pentru conflictele ce vor urma."},sec={{t="O convocare discreta",b="In spatele fatadei linistite si pioase a Northshire Abbey, talentele secrete sunt recrutate si slefuite in tacere. Encrypted Letter le este inmanata novicilor promitatori dupa ce se ocupa de parazitii kobold care se apropie, purtand sigiliul lui Jorik Kerridan. Scrisa cu discretie, pentru a tine chestiunea departe de privirile iscoditoare ale preotilor si paladinilor, scrisoarea isi indruma purtatorul spre o intalnire tainica in grajdurile din spatele Abatiei."},{t="Umbre in Northshire",b="Jorik Kerridan ramane in grajduri tocmai fiindca acolo e liniste si atrage putina atentie. Ii intampina pe nou-venitii care sosesc fara sa fie observati si nu pierde vremea explicandu-le realitatea cruda care ii asteapta pe hoti si cercetasi in lumea larga. Organizatii puternice - de la agentia regala de informatii a Stormwind, SI:7, pana la razvratita Defias Brotherhood - cauta neincetat agenti priceputi in furisare. Jorik propovaduieste autonomia personala mai presus de orice, avertizandu-i pe novici sa nu se lase niciodata calcati in picioare de sindicate puternice si amintindu-le ca un rogue istet tine toate cartile in mana."}},faq={{q="Cine a trimis Encrypted Letter?",a="Scrisoarea poarta sigiliul personal al lui Jorik Kerridan, antrenorul hotilor din Northshire Valley. Este inmanata novicilor promitatori care se intorc dupa ce au cercetat taberele kobold din apropiere.",al={"cine a trimis scrisoarea criptata","cine mi-a dat scrisoarea criptata","cine a scris scrisoarea criptata"}},{q="Unde se afla Jorik Kerridan?",a="Jorik Kerridan sta retras in grajdul linistit ascuns in spatele Northshire Abbey. Se tine intentionat departe de priviri, ca sa nu atraga atentia nedorita asupra activitatii sale sub acoperire.",al={"unde se afla Jorik","unde il gasesti pe Jorik Kerridan","locatia lui Jorik"}},{q="Care este scopul lui Encrypted Letter?",a="Scrisoarea este o invitatie discreta adresata hotilor in devenire, prin care sunt indemnati sa se prezinte instructorului local. Deoarece hotii isi desfasoara activitatea in secret, corespondenta este cifrata pentru ca detaliile sensibile despre instruire sa nu ajunga la urechile indiscrete din jurul manastirii.",al={"de ce scrisoarea este criptata","la ce foloseste scrisoarea criptata","de ce este criptata scrisoarea"}},{q="Ce organizatii incearca sa recruteze Rogues?",a="Potrivit lui Jorik Kerridan, diverse factiuni din Azeroth ravnesc la talentele hotilor iscusiti. Printre acestea se numara grupurile de aventurieri, serviciul secret SI:7 din Stormwind si chiar proscrisi precum Defias Brotherhood, care cauta spioni in Stormwind.",al={"cine ii vrea pe rogue","factiuni interesate de rogue","cine ravneste la abilitatile de rogue"}},{q="Ce sfat da Jorik Kerridan?",a="Jorik te indeamna sa-ti pastrezi individualitatea si sa nu lasi niciodata grupurile puternice sa te constranga sa actionezi impotriva vointei tale. Le aminteste hotilor ca ei detin cartile pana la sfarsitul jocului, subliniind importanta independentei si prudentei.",al={"sfatul lui Jorik","ce iti spune Jorik","sfatul lui Jorik pentru Rogue"}},{q="De ce ramane Jorik Kerridan in grajd?",a="Jorik prefera grajdurile izolate din spatele Northshire Abbey, fiindca locul este placut, linistit si atrage putina atentie. Instructorii si agentii secreti prefera sa se intalneasca fara sa fie observati de clericii sau de gardienii abatiei.",al={"de ce sa te ascunzi in grajduri","de ce e jorik in spatele abatiei","de ce e liniste in grajduri"}}},fp="16,322,18.428.0,21.552.0,30.202.0,32.183.0,44.245.0,50.252.0,37.219.0,43.225.0"}
P.entries["quest:3103"] = {n="Hallowed Letter",s="Hallowed Letter este o convocare oficiala data tinerilor preoti promitatori de Marshal McBride, in numele instructoarei din Northshire Abbey, Priestess Anetta. Marcheaza inceputul indrumarii oficiale a unui preot novice in principiile Holy Light, intr-o lume tulburata si vulnerabila.",h="Hallowed Letter este o convocare oficiala data tinerilor preoti promitatori de Marshal McBride, in numele...",kw={"elwynn","scrisoare sfintita","lumina sfanta","marshal mcbride","northshire abbey","priest","priestess anetta"},ang={["class:Priest"]="Aceasta misiune marcheaza primirea ta oficiala ca discipol al Holy Light sub indrumarea Priestess Anetta si infatiseaza magia divina drept o datorie vitala: vindecarea unei lumi sfasiate.",["race:Human"]="Northshire Abbey a fost multa vreme un sanctuar al credintei si al refacerii pentru Kingdom of Stormwind, pastrandu-si traditiile in ciuda tulburarilor care se apropie in Elwynn."},sec={{t="O chemare catre stofa",b="Dupa ce isi dovedesc valoarea in fata taberelor koboldilor din jurul Northshire, preotii novici primesc o scrisoare purtand sigiliul sacru al Priestess Anetta. Inmanata prin intermediul lui Marshal McBride, scrisoarea este o invitatie de a incepe studiul serios al Holy Light in linistea salilor manastirii."},{t="O lume aflata la nevoie",b="Cand i se inmaneaza scrisoarea, Priestess Anetta ii arata noului sau elev cat de sumbra este situatia din tinuturi. Amenintarile persistente ale Burning Legion arunca umbre lungi peste Azeroth, in vreme ce continentele inca se lupta cu rani noi si tulburari. In ochii ei, imbratisarea menirii de preot nu este doar o indeletnicire academica, ci o responsabilitate morala urgenta: sa aduca alinare si vindecare unei lumi suferinde."}},faq={{q="Ce este Hallowed Letter?",a="Este o scrisoare sigilata, purtand blazonul lui Priestess Anetta, inmanata preotilor Human nou-sositi de Marshal McBride, in Northshire Valley. Ii cere noviceului sa-si oficializeze pregatirea in Northshire Abbey.",al={"scrisoarea sfintita","misiunea de prezentare a Priest-ului din Northshire","scrisoarea Anettei"}},{q="Cine trimite Hallowed Letter?",a="Priestess Anetta, antrenoarea preotilor aflata in Northshire Abbey, scrie si sigileaza misiva, rugandu-l pe Marshal McBride sa o inmaneze cand initiatul se intoarce din cercetarea infestarii koboldilor.",al={"cine a scris scrisoarea sfintita","cine a trimis scrisoarea"}},{q="De ce ii cheama Priestess Anetta pe noii preoti?",a="Anetta recunoaste chemarea novicei catre Holy Light si doreste sa-i indrume pregatirea. Intr-o lume in care inca mai dainuie primejdii precum ramasitele Burning Legion, ea subliniaza ca e nevoie urgenta de vindecatori si indrumatori disciplinati.",al={"de ce ma vrea Anetta","scopul scrisorii"}},{q="Unde poate fi gasita Priestess Anetta?",a="Locuieste in sala principala a Northshire Abbey, pregatita sa-i invete pe preotii umani sa-si stapaneasca primele rugaciuni si ritualuri.",al={"unde se afla Anetta","locatia lui Priestess Anetta"}},{q="Ce se intampla dupa ce ii prezinti scrisoarea lui Priestess Anetta?",a="Dupa ce citeste scrisoarea si o saluta pe Anetta, aceasta il accepta pe jucator ca elev, ii impartaseste cunostinte de baza si il invita sa revina pentru mai multa instruire pe masura ce capata experienta.",al={"urmatoarea misiune dupa hallowed letter","ce urmeaza dupa hallowed letter"}},{q="De ce este mentionata Burning Legion in Northshire?",a="Desi Third War s-a incheiat, ramasitele demonice ale Legiunii inca bantuie Azeroth. Priestess Anetta mentioneaza aceasta amenintare globala pentru a sublinia pericolele mai ample care il asteapta pe orice aventurier ce paraseste valea.",al={"Burning Legion in Northshire","de ce vorbeste Anetta despre demoni"}}},fp="15,292,22.297.0,15.409.0,28.217.0,30.202.0,45.233.0,36.130.0,61.180.0,50.205.0"}
P.entries["quest:3104"] = {n="Glyphic Letter",s="O convocare sigilata ajunge la novicele human mages din Northshire Valley, trimisa de Marshal McBride. Khelden Bremen ii cheama pe vrajitorii promitatori la Northshire Abbey pentru a-si incepe pregatirea arcana.",h="O convocare sigilata ajunge la novicele human mages din Northshire Valley, trimisa de Marshal McBride.",kw={"arcane","elwynn forest","glyphic letter","khelden bremen","mage","marshal mcbride","northshire abbey"},ang={["class:Mage"]="Ca mage, iti incepi ucenicia recunoscuta in artele arcane din Stormwind sub indrumarea lui Khelden Bremen.",["race:Human"]="Ca human, porti mai departe mostenirea magiei arcane din Northshire, care isi are originile in vremea primilor arcanisti human din Dalaran si a Kirin Tor, si ajunge pana in Kingdom of Stormwind."},sec={{t="O chemare catre arcane",b="Marshal McBride ii da scrisoarea marcata cu rune unui ucenic aspirant care si-a dovedit priceperea ajutandu-l impotriva daunatorilor din zona. Khelden Bremen, instructorul Mage din Northshire, a scris-o. El urmareste recruti noi care sosesc la manastire si cauta semne de disciplina si talent magic."},{t="Greutatea vrajitoriei",b="Northshire Abbey a fost de multa vreme un sanctuar al Holy Light, dar primejdiile din Stormwind cer practicanti de toate disciplinele. Scrisoarea te duce la etaj, la Khelden Bremen. El nu te lauda cu usurinta. In schimb, te avertizeaza ca stapanirea puterii arcane inseamna sfidarea limitelor naturii si atrage atat respect profund, cat si teama puternica din partea oamenilor de rand."}},faq={{q="Cine livreaza Glyphic Letter?",a="Marshal McBride le da scrisoarea mage-ilor abia sositi, in afara Northshire Abbey, dupa ce acestia ajuta la starpirea koboldilor daunatori din apropiere.",al={"cine ofera glyphic letter","cel care da misiunea glyphic letter"}},{q="Cine a scris Glyphic Letter?",a="Khelden Bremen, instructorul de mage din camerele superioare ale Northshire Abbey, a scris si a sigilat scrisoarea.",al={"autorul lui Glyphic Letter","cine a trimis Glyphic Letter"}},{q="Unde il gasesc pe Khelden Bremen?",a="Intra in Northshire Abbey in urma lui Marshal McBride, ia-o pe coridorul din stanga, apoi urca scarile. Khelden te asteapta in camerele din spate pentru a te instrui.",al={"locatia lui khelden bremen","unde este khelden"}},{q="De ce se afla instructorul de magi intr-o manastire?",a="Northshire Abbey este un sanctuar sfant, dar Stormwind foloseste valea pentru a-i instrui pe aparatori in toate disciplinele. Acolo lucreaza profesori de magie arcana, clerici si maresali.",al={"de ce sunt magi la Northshire Abbey","antrenor de Mage in abatia sfanta"}},{q="Ce se intampla dupa ce predai scrisoarea?",a="Khelden Bremen te accepta ca elev, iti apreciaza hotararea de a stapani magia arcana in ciuda pericolelor ei si iti ofera acces direct la instruirea in vrajile de baza.",al={"ce urmeaza dupa Glyphic Letter","urmatoarea misiune dupa Glyphic Letter"}},{q="De ce avertizeaza Khelden ca Mage-ii vor fi temuti?",a="Magia arcana poate deforma realitatea si este instabila. Khelden avertizeaza ca urmarirea cunoasterii supreme trece dincolo de limite pe care oamenii obisnuiti le gasesc profund tulburatoare.",al={"de ce sunt temuti magii","dialogul lui Khelden Bremen"}}},fp="14,186,23.282.0,22.345.0,32.124.0,29.108.0,31.137.0,44.164.0,41.155.0,48.155.0"}
P.entries["quest:3105"] = {n="Tainted Letter",s="La Northshire, Tainted Letter ii cheama pe novicele warlock Human de langa strajerii abatiei la instruire in artele malefice. Drusilla La Salle ii incredinteaza scrisoarea lui Marshal McBride, care le-o duce recrutilor ei.",h="La Northshire, Tainted Letter ii cheama pe novicele warlock Human de langa strajerii abatiei la instruire in...",kw={"corupere","drusilla la salle","elwynn forest","marshal mcbride","northshire abbey","scrisoare patata","twisting nether","warlock"},ang={["class:Warlock"]="Ca Warlock, primesti instruire oficiala in Northshire, ferindu-te totodata de judecata garzilor si invatand sa stapanesti magia periculoasa a Abisului.",["race:Human"]="Ca human, traiesti intr-o cultura care venereaza Holy Light si magia arcana disciplinata a Kirin Tor. Warlocks practica invocarile in tacere, la marginea asezarilor precum Northshire."},sec={{t="O convocare discreta",b="Dupa ce se dovedesc impotriva amenintarii Kobold, novicele Warlock primesc o scrisoare de la Marshal McBride. In timp ce Priest si Paladin studiaza la vedere in Northshire Abbey, Warlock trebuie sa fie precauti. Insemnul lui Drusilla La Salle marcheaza scrisoarea, care il indruma pe fiecare vrajitor incepator spre postul ei izolat, din afara zidurilor principale ale abatiei, inainte de a prelua alte indatoriri."},{t="Tentatie si ambitie",b="Drusilla avertizeaza ca warlocks pasesc pe o cale primejdioasa sub privirile vigilente ale garzilor din Stormwind, pe care le numeste 'jalnici muritori de rand'. Atragerea puterii din Twisting Nether si comuniunea cu demonii implica intotdeauna riscul coruperii. Ea indeamna la rabdare, prudenta si autocontrol ferm cand sunt folosite acele energii intunecate, dar spune ca precautia nu trebuie sa stinga ambitia unui warlock."}},faq={{q="Cine trimite Tainted Letter?",a="Drusilla La Salle scrie si pecetluieste scrisoarea de la postul ei, chiar in afara Northshire Abbey. Ii cere lui Marshal McBride sa o livreze cand te intorci dupa ce cureti taberele kobold din apropiere.",al={"cine a scris Tainted Letter","autorul lui Tainted Letter","cine da Tainted Letter"}},{q="De ce livreaza Marshal McBride o scrisoare pentru un Warlock?",a="Marshal McBride le duce mesaje recrutilor promitatori din vale. Stie ca scrisoarea poarta sigiliul lui Drusilla si spune ca este prioritara, insa principala lui preocupare ramane apararea si administrarea Northshire, nu supravegherea practicilor magice ale aparatorilor.",al={"de ce il are mcbride","stie mcbride ce este scrisoarea","scrisoarea de warlock a lui mcbride"}},{q="Unde o pot gasi pe Drusilla La Salle?",a="Drusilla La Salle te asteapta in fata intrarii principale in Northshire Abbey, langa zidurile exterioare si corturi, departe de clericii dinauntru.",al={"locatia Drusillei","unde se afla Drusilla La Salle","gaseste-o pe Drusilla"}},{q="De ce sunt acceptati vracii in Northshire Abbey?",a="Warlock din teritoriile Alliance sunt priviti cu mare suspiciune si se straduiesc sa nu iasa in evidenta. Drusilla ii antreneaza pe recruti in aer liber, in Northshire, departe de sanctuar, pentru a evita o confruntare directa cu clericii si paladinii Holy Order of Northshire.",al={"warlock-ii din northshire","este legala magia fel in northshire","de ce sunt permisi warlock-ii"}},{q="Ce lectie preda Drusilla cand primeste scrisoarea?",a="Drusilla avertizeaza ca apelarea la Twisting Nether risca sa corupa orice practicant lipsit de disciplina. Ea indeamna la stapanire de sine si prudenta, insistand totodata ca teama de corupere nu trebuie sa inabuse ambitia unui warlock.",al={"sfatul Drusillei","ce spune Drusilla","lectie din scrisoarea contaminata"}},{q="Ce urmeaza dupa ce livrezi Tainted Letter?",a="Dupa ce vorbesti cu Drusilla, invocarea se incheie, iar ea devine maestra ta. Te invita sa revii pe masura ce devii mai puternic, ca sa afli mai multe despre arta warlock.",al={"misiunea urmatoare dupa Tainted Letter","continuarea lui Tainted Letter"}}},fp="14,200,18.368.0,23.372.0,29.184.0,50.258.0,35.127.0,45.235.0,58.217.0,47.161.0"}
