P.entries["quest:3121"] = {n="A Strange Request",s="Witch Doctor Uzer'i are nevoie de un elixir preparat de Neeru Fireblade in Orgrimmar. Uzer'i iti da un cap micsorat, promis lui Neeru in schimbul ierburilor, si te trimite sa-l livrezi in Cleft of Shadow, in Orgrimmar.",h="Witch Doctor Uzer'i are nevoie de un elixir preparat de Neeru Fireblade in Orgrimmar.",kw={"a strange request","cleft of shadow","feralas","neeru fireblade","orgrimmar","shrunken head","witch doctor uzer'i"},sec={{t="O plata promisa",b="Witch Doctor Uzer'i spune ca Neeru Fireblade din Orgrimmar are ceea ce-i trebuie pentru a incepe in Feralas: o potiune pentru ceva ce Uzer'i nu va dezvalui inca. Uzer'i iti da un cap micsorat, promis lui Neeru in schimbul ierburilor. Este capul unui biet Dwarf pe care Uzer'i l-a intalnit in padure. Neeru se afla in Cleft of Shadow."},{t="Plantele lui Neeru",b="Neeru Fireblade asteapta de ceva vreme ca Uzer'i sa faca aceasta livrare si iti da amestecul de ierburi pregatit pentru experimentele lui Uzer'i."}},faq={{q="Cine ofera A Strange Request?",a="Witch Doctor Uzer'i, care te trimite sa duci un cap micsorat la Orgrimmar.",al={"cine da a strange request","cine incepe aceasta","cel care da misiunea strange request"}},{q="Unde se afla Neeru Fireblade?",a="In Cleft of Shadow, in Orgrimmar.",al={"unde este neeru fireblade","incotro sa merg","locatia de predare a capului micsorat"}},{q="Al cui este capul micsorat?",a="Uzer'i spune ca este capul unui biet dwarf, gasit in padure.",al={"al cui este capul","identitatea capului micsorat","cine era dwarf-ul"}},{q="De ce trimite Uzer'i un cap micsorat lui Neeru?",a="Uzer'i i l-a promis lui Neeru in schimbul ierburilor si are nevoie de potiunea amestecata de Neeru.",al={"de ce vrea neeru capul","schimbul lui neeru fireblade"}},{q="Ce urmeaza dupa A Strange Request?",a="Lantul continua cu Return to Witch Doctor Uzer'i.",al={"ce urmeaza","urmatoarea misiune dupa Strange Request"}}},fp="17,230,18.343.0,13.133.1,28.67.0,25.37.0,32.71.0,46.99.0,31.53.0"}
P.entries["quest:3122"] = {n="Return to Witch Doctor Uzer'i",s="Dupa ce predai capul micsorat in A Strange Request, Neeru Fireblade iti da ierburile si iti cere sa le duci la Witch Doctor Uzer'i din Feralas, impreuna cu vestea ca Neeru este multumit de cap.",h="Dupa ce predai capul micsorat in A Strange Request, Neeru Fireblade iti da ierburile si iti cere sa le duci...",kw={"feralas","punga cu ierburi","vas Muisek","cap micsorat","witch doctor uzer'i"},sec={{t="Ierburile se intorc",b="Dupa A Strange Request, Neeru Fireblade iti da o punga cu ierburi pentru Witch Doctor Uzer'i. Ti se cere si sa-i spui lui Uzer'i ca Neeru este multumit de capul micsorat. Punga este destinata lui Uzer'i, in Feralas."},{t="Ritualul incepe",b="Uzer'i spune ca ierburile sunt exact ce trebuie pentru a pregati vasul muisek si spera ca ultimele sale incantatii vor fi la fel de puternice pe cat isi doreste. Iti cere sa astepti o clipa in timp ce face ritualul si foloseste ierburile."}},faq={{q="Cine ii da ierburile lui Witch Doctor Uzer'i?",a="Neeru Fireblade, cel caruia i-ai adus capul micsorat.",al={"unde incepe aceasta misiune","cine a dat ierburile"}},{q="Unde ajung ierburile?",a="La Witch Doctor Uzer'i, in Feralas.",al={"ce plante sunt acestea","unde duc saculetul cu plante"}},{q="A fost Neeru multumit de capul micsorat?",a="Da. Neeru este multumit de cap si iti cere sa-i spui asta lui Uzer'i.",al={"i-a placut lui neeru capul","schimbul cu capete micsorate al lui neeru"}}},fp="29,207,17.216.0,17.225.1,43.58.0,22.34.0,41.71.0"}
P.entries["quest:3123"] = {n="Testing the Vessel",s="Witch Doctor Uzer'i, dupa Return to Witch Doctor Uzer'i, numeste aceasta o incercare a ritualului infaptuit de Uzer'i si a propriilor tale aptitudini. Primesti un vas care poate micsora si captura o creatura, apoi esti trimis in Hinterlands sa prinzi zece wildkin cu el si sa le aduci inapoi lui Uzer'i, in Feralas.",h="Witch Doctor Uzer'i, dupa Return to Witch Doctor Uzer'i, numeste aceasta o incercare a ritualului infaptuit...",kw={"elune","feralas","hinterlands","muisek","owlbeast","uzer'i","vas","wildkin"},sec={{t="O corabie pentru Hinterlands",b="Witch Doctor Uzer'i numeste aceasta o incercare, atat a ritualului tocmai infaptuit, cat si a propriilor tale aptitudini. Vasul primit de tine poate micsora o creatura si o poate prinde inauntru. Pornesti spre Hinterlands in cautarea wildkin, care au fost candva animale de companie ale lui Elune, zeita night elves. Uzer'i iti indica drept prazi owlbeast-urile feroce, primitive si salbatice. Zece trebuie sa cada, fiecare fiind micsorat in vas inainte ca spiritul sa-i scape. Du-i pe cei zece si vasul inapoi la Uzer'i, in Feralas."},{t="Apoi",b="Uzer'i explica faptul ca, atunci cand o creatura moare violent, muisek-ul ei se poate elibera si poate cauta razbunare. Micsorarea celor cazuti, asa cum ai facut tu, impiedica muisek-ul sa scape, iar Uzer'i spune acum ca poate fi folosit dupa voie."}},faq={{q="Cine ofera Testing the Vessel?",a="Witch Doctor Uzer'i, care iti da recipientul.",al={"cel care ofera testing the vessel","cine da testing the vessel"}},{q="Unde se afla fapturile salbatice?",a="Uzer'i te trimite in Hinterlands sa-i cauti.",al={"unde gasesti wildkin","locatia wildkin"}},{q="Care creaturi sunt tintele?",a="Vicious, primitive sau salbatice owlbeasts, cunoscute drept wildkin. Sunt necesare zece.",al={"ce wildkin sa ucizi","tinte pentru Testing the Vessel"}},{q="Care este legatura dintre wildkin si Elune?",a="Uzer'i spune ca wildkin erau candva animalele de companie ale lui Elune, zeita night elf.",al={"wildkin elune lore","de ce wildkin"}},{q="Ce poate face vasul?",a="Iti permite sa micsorezi o creatura cazuta si s-o prinzi, astfel incat spiritul ei sa nu poata scapa.",al={"cum functioneaza vasul muisek","puterea vasului"}},{q="Ce urmeaza dupa Testing the Vessel?",a="Lantul continua cu Hippogryph Muisek.",al={"urmatoarea misiune dupa Testing the Vessel","ce urmeaza dupa Testing the Vessel"}}},fp="18,296,28.485.0,9.208.1,29.46.0,22.53.0,32.76.0,47.68.0,23.88.0,32.41.0"}
P.entries["quest:3124"] = {n="Hippogryph Muisek",s="Dupa incercarile tale cu vasul muisek, Witch Doctor Uzer'i iti cere sa te ocupi de o alta creatura. Hippogrifii Frayfeather din High Wilderness trebuie ucisi si micsorati imediat in vas, pentru ca muisek-ul lor sa fie pastrat.",h="Dupa incercarile tale cu vasul muisek, Witch Doctor Uzer'i iti cere sa te ocupi de o alta creatura.",kw={"feralas","frayfeather","high wilderness","hippogryph muisek","recipient pentru muisek","witch doctor uzer'i"},sec={{t="Tovarasi loiali",b="Witch Doctor Uzer'i te-a considerat demn de incredere si ti-a daruit vasul, iar acum vrea spiritul unei alte creaturi. Hippogryphs sunt vechi tovarasi ai night elves, iar spiritele lor sunt loiale si statornice. Trebuie ucisi zece hippogryphs Frayfeather de orice fel, fiecare micsorat si capturat repede cu vasul, pentru ca muisek-ul sau sa fie pastrat. Uzer'i ii plaseaza in High Wilderness, la sud de tabara."},{t="Avertismentul lui Uzer'i",b="Uzer'i spune ca, daca muisek-ul unui animal ucis este lasat sa scape, ar putea lua forma unei creaturi si mai mari, iar razbunarea ei nu ti-ar mai da pace. Uzer'i numeste treaba primejdioasa si spune ca ai indeplinit-o din nou cu bine."}},faq={{q="Cine te trimite sa capturezi hippogryphs?",a="Witch Doctor Uzer'i. Ajungi la acest pas dupa Testing the Vessel.",al={"cel care ofera misiunea Hippogryph Muisek","cine ofera Hippogryph Muisek","de unde obtii Hippogryph Muisek"}},{q="Unde se gasesc hippogryphs Frayfeather?",a="Se afla in High Wilderness, pe care Uzer'i il situeaza la sud de tabara.",al={"unde sunt frayfeather hippogryphs","locatia hippogryph in feralas","unde gasesti hippogryphs in feralas"}},{q="De ce vrea Witch Doctor Uzer'i spiritele hippogriffilor?",a="Uzer'i vorbeste despre hippogryphs ca despre vechi tovarasi ai night elves, cu suflete loiale si statornice. Scopul este pastrarea muisek-ului lor.",al={"de ce hipogrifii","de ce capturezi Hippogryph Muisek","motivul lui Uzeri pentru hipogrifi"}},{q="Cum este capturat muisek-ul?",a="Ucide un hippogryph Frayfeather, apoi micsoreaza-l rapid si prinde-l cu vasul muisek. Se cer zece, de orice tip.",al={"cum se foloseste recipientul muisek","cum obtii hippogryph muisek","capturarea muisek frayfeather"}},{q="Ce etapa din lant preceda aceasta?",a="Testing the Vessel, in care ti-ai dovedit increderea si capacitatea de a folosi vasul muisek.",al={"cerinta prealabila pentru hippogryph muisek","misiunea anterioara hippogryph muisek","cerinta pentru hippogryph muisek"}}},fp="17,234,16.426.0,16.241.1,37.68.0,44.78.0,53.145.0,27.118.0,41.92.0"}
P.entries["quest:3125"] = {n="Faerie Dragon Muisek",s="Dupa spiritele hippogryphs, Witch Doctor Uzer'i vrea acum spiritul unui faerie dragon. Esti trimis spre vest sa vanezi sprite darters si sprite dragons si sa capturezi ceea ce le da puterea.",h="Dupa spiritele hippogryphs, Witch Doctor Uzer'i vrea acum spiritul unui faerie dragon.",kw={"faerie dragon muisek","feralas","hippogryph muisek","horde","muisek vessel","sprite darter","sprite dragon","treant muisek","witch doctor uzer'i"},sec={{t="Infatisare firava, spirit puternic",b="Uzer'i remarca faptul ca dragonii zanelor par firavi, dar spiritul lor este adevarata recompensa. Au fost aliati ai night elves, iar Uzer'i vrea ca Horde sa impartaseasca aceasta putere. Uzer'i iti da un Muisek Vessel si te trimite spre vest sa ucizi opt sprite darters sau sprite dragons, apoi sa micsorezi si sa capturezi cu el fiecare dragon al zanelor cazut."},{t="Inapoi langa Uzer'i",b="Cand te intorci cu spiritele capturate, Uzer'i iti multumeste si spune ca puterea spirituala a dragonilor zanei este acum la dispozitia Horde. Uzer'i mai spera ca vei accepta inca o treaba."}},faq={{q="De ce vrea Witch Doctor Uzer'i spirite de dragon zanatic?",a="Uzer'i spune ca faerie dragons par firavi, dar au un spirit puternic si ca au fost aliati ai night elves. Uzer'i vrea ca si Horde sa beneficieze de aceasta putere.",al={"de ce faerie dragons","scopul lui faerie dragon muisek","de ce sa ucizi sprite darters"}},{q="Unde pot fi gasiti dragonii zanelor?",a="Uzer'i spune ca se afla la vest de locul in care sta Uzer'i.",al={"unde sunt dragonii-fae","locatia dragonului-fae","locatia dragonului zanelor din Feralas"}},{q="Ce creaturi furnizeaza acest muisek?",a="Sprite darters si sprite dragons. Opt dintre ei trebuie ucisi si capturati.",al={"ce creaturi pentru muisek","ce trebuie sa omor pentru faerie dragon muisek","tinte pentru faerie dragon muisek"}},{q="Ce trebuie facut cu creaturile cazute?",a="Muisek Vessel este folosit pe fiecare faerie dragon cazut pentru a-l micsora si a-i captura muisek-ul.",al={"cum obtin Faerie Dragon Muisek","cum functioneaza Muisek Vessel","capturarea lui Muisek"}},{q="Unde se incadreaza acest pas printre cererile lui Uzer'i?",a="Urmeaza dupa Hippogryph Muisek, iar Treant Muisek este etapa urmatoare.",al={"ce misiune preceda aceasta","ordinea misiunilor din lantul Muisek","ce urmeaza dupa Faerie Dragon Muisek"}}},fp="20,187,28.343.0,21.194.1,56.180.0,38.49.0,35.80.0,42.91.0,49.80.0"}
P.entries["quest:3126"] = {n="Treant Muisek",s="Urmatoarea tinta a lui Witch Doctor Uzer'i sunt umblatorii ratacitori ai padurii, treantii care strabat padurea incet. Dupa dragonii zanelor, esti trimis sa gasesti trei dintre ei.",h="Urmatoarea tinta a lui Witch Doctor Uzer'i sunt umblatorii ratacitori ai padurii, treantii care strabat...",kw={"feralas","recipient muisek","treant muisek","treants","uzer'i","wandering forest walker"},sec={{t="Protectori lenesi",b="Uzer'i spune ca night elves au recrutat treants ca aliati in lupta lor impotriva Horde. Se misca incet, dar Uzer'i considera incontestabila contributia lor ca protectori si planuieste sa foloseasca aceasta putere in beneficiul Horde."},{t="Trei calatori ai padurii",b="Uzer'i vrea sa gasesti si sa ucizi trei treant forestieri ratacitori, apoi sa micsorezi si sa capturezi fiecare treant cazut cu Muisek Vessel."},{t="Verdictul lui Uzer'i",b="La intoarcere, Uzer'i iti multumeste si remarca faptul ca colectia de muisek este aproape completa."}},faq={{q="Cine trimite aventurierii dupa treants?",a="Witch Doctor Uzer'i, care cere acest lucru imediat dupa dragonii faerie.",al={"cine ofera muisek pentru treant","muisek pentru treant, misiune data de","misiunea cu treant data de uzeri"}},{q="De ce vrea Witch Doctor Uzer'i muisek de treant?",a="Uzer'i spune ca night elves au recrutat treants ca aliati in lupta lor impotriva Horde si vrea sa puna puterea lor de protectie in slujba Horde.",al={"de ce sa ucizi forest walkers","de ce treant muisek","motivul lui uzeri treant"}},{q="Ce creaturi trebuie gasite pentru Treant Muisek?",a="Wandering forest walkers care ratacesc prin padure. Sunt necesari trei.",al={"ce treants sa ucizi","ratacitorii padurii","tinte pentru treant muisek"}},{q="Cum sunt capturati treantii?",a="Dupa ce un strajer al padurii ratacitor cade, recipientul Muisek este folosit pentru a-l micsora si captura.",al={"cum sa folosesti muisek vessel","capturarea forest walkers","micsoreaza treants"}},{q="Ce loc ocupa Treant Muisek printre cererile lui Uzer'i?",a="Urmeaza Faerie Dragon Muisek, iar dupa aceasta vine Mountain Giant Muisek.",al={"lantul Treant Muisek","ce urmeaza dupa Faerie Dragon Muisek","misiunea urmatoare dupa Treant Muisek"}}},fp="13,165,15.223.0,20.129.0,16.94.1,40.70.0,48.163.0,47.74.0,29.93.0,53.74.0"}
P.entries["quest:3127"] = {n="Mountain Giant Muisek",s="Witch Doctor Uzer'i numeste aceasta ultima treaba si te trimite spre nord-vest in cautarea ultimului dusman: mountain giants, a caror marime si putere Uzer'i este nerabdator sa le valorifice.",h="Witch Doctor Uzer'i numeste aceasta ultima treaba si te trimite spre nord-vest in cautarea ultimului dusman...",kw={"burning legion","cliff giant","feralas","land walker","mountain giant muisek","vas muisek","treant muisek","witch doctor uzer'i"},sec={{t="Gigantii tinutului stancos",b="Potrivit povestirii lui Uzer'i, uriasii muntilor au coborat din munti ca sa-i ajute pe night elves dupa sosirea Burning Legion in lume. Ii poti recunoaste usor dupa statura lor imensa si cutremurele care rasuna sub picioare pe terenul stancos. Uzer'i e nerabdator sa stapaneasca o asemenea putere. Vrea sa dobori sapte Land Walkers sau Cliff Giants, fiecare micsorat si capturat cu Muisek Vessel."},{t="Lauda lui Uzer'i",b="La intoarcerea ta, Uzer'i vorbeste despre posibilitatile oferite de ceea ce s-a adunat. Cu materialele pe care le-ai strans pe drum, Uzer'i sustine ca poate prinde pentru totdeauna spiritele acestor creaturi in orice doreste."}},faq={{q="Cine cere muisek-ul mountain giants?",a="Witch Doctor Uzer'i, care spune ca aceasta este ultima ta cerere.",al={"cel care da misiunea","cine ofera Mountain Giant Muisek","misiunea lui uzeri"}},{q="Unde se afla gigantii muntelui?",a="Uzer'i te trimite spre nord-vest sa-i gasesti pe teren stancos.",al={"locatia uriasului de munte","unde sunt land walkers","locatia uriasului de pe stanca"}},{q="De ce sunt uriasi ai muntelui aici?",a="Potrivit spuselor lui Uzer'i, au coborat din munti ca sa-i ajute pe Night Elves dupa sosirea Burning Legion in lume.",al={"de ce sunt aici gigantii","povestea gigantilor de munte Feralas"}},{q="Ce creaturi ofera muisek-ul necesar?",a="Land Walkers si Cliff Giants. Sunt necesari sapte, iar Muisek Vessel ii micsoreaza si ii captureaza pe fiecare dintre cei doborati.",al={"ce trebuie sa omor pentru muisek","care giganti se pun la socoteala"}},{q="Ce urmeaza inaintea acestui pas din sir?",a="Urmeaza dupa Treant Muisek, iar Weapons of Spirit este listata dupa aceasta.",al={"misiunea anterioara","ordinea misiunilor Muisek"}}},fp="21,161,26.395.0,14.235.1,41.58.0,38.67.0,29.124.0,44.108.0,39.67.0"}
P.entries["quest:3128"] = {n="Natural Materials",s="Witch Doctor Uzer'i din Camp Mojache are nevoie de materiale pentru a duce la bun sfarsit o lucrare, care trebuie adunate in paralel cu celelalte incercari: busteni despicati, minerale incrustate, tendoane rezistente si fragmente metalice, luate de la treants, mountain giants, dragoni zane, owlbeasts si hippogryphs.",h="Witch Doctor Uzer'i din Camp Mojache are nevoie de materiale pentru a duce la bun sfarsit o lucrare, care...",kw={"camp mojache","minerale incrustate","feralas","fragmente metalice","muisek","materiale naturale","tendoane rezistente","bustean aschiat","the hinterlands","witch doctor uzer'i"},sec={{t="Adunare pentru Witch Doctor",b="Dupa ce te intorci la Witch Doctor Uzer'i, te asteapta o alta lista de materiale, de adunat alaturi de celelalte obiecte pentru incercari. Sunt necesare doua trunchiuri despicate de la un treant din Feralas. Sase bucati de minerale incrustate se gasesc la mountain giants si faerie dragons, spre vest. Douazeci de bucati de tendoane rezistente provin de la owlbeasts din Hinterlands sau hippogryphs din Feralas. O cantitate mare de fragmente metalice, patruzeci in total, poate fi obtinuta de la oricare dintre aceste creaturi."},{t="Verdictul lui Uzer'i",b="Cand materialele sunt aduse inapoi, Uzer'i este multumit. Impreuna cu muisek, ar trebui sa dea exact rezultatele dorite."}},faq={{q="Cine cere aceste materiale naturale?",a="Witch Doctor Uzer'i, in Camp Mojache.",al={"cine da natural materials","cel care ofera misiunea natural materials","unde incepe natural materials"}},{q="Ce creaturi au bustenii aschiosi?",a="Un treant din Feralas; sunt necesare doua busteni despicate.",al={"unde gasesc busteni despicate","cine lasa busteni despicati","sursa bustenilor despicati"}},{q="Unde pot fi stranse minerale cu crusta?",a="Gigantii muntelui si dragonii zanelor, spre vest, le poarta; sunt necesare sase.",al={"cum obtin minerale incrustate","sursa mineralelor incrustate","cine lasa minerale incrustate"}},{q="Ce bestii furnizeaza tendoanele rezistente?",a="Owlbeast-ii din Hinterlands sau hippogryphs din Feralas; sunt necesare douazeci de bucati.",al={"unde cade resilient sinew","unde gasesti resilient sinew","cine are resilient sinew"}},{q="De unde provin fragmentele metalice?",a="Patruzeci provin de la oricare dintre creaturile numite: treants, mountain giants, faerie dragons, owlbeasts si hippogryphs.",al={"sursa fragmentelor metalice","cum obtin fragmente metalice","cine lasa fragmente metalice"}},{q="Ce a precedat aceasta cerere?",a="Aceasta cerere urmeaza dupa Return to Witch Doctor Uzer'i.",al={"cerinte prealabile pentru natural materials","misiunea anterioara natural materials","ce duce la natural materials"}}},fp="17,276,30.455.0,16.137.1,37.36.0,40.52.0,41.73.0,41.90.0,38.112.0,30.51.0"}
P.entries["quest:3129"] = {n="Weapons of Spirit",s="Witch Doctor Uzer'i are acum tot ce-i trebuie, inclusiv spiritele capturate de tine. Legarea lor in arme este o munca grea, asa ca Uzer'i iti cere sa astepti putin, pana sunt facute pregatirile.",h="Witch Doctor Uzer'i are acum tot ce-i trebuie, inclusiv spiritele capturate de tine.",kw={"feralas","Muisek","arme spirituale","arme ale spiritului","witch doctor uzer'i"},sec={{t="Un strop de rabdare",b="Uzer'i recunoaste ca insufletirea armelor cu muisek este o treaba anevoioasa. Acum ca are toate materialele necesare, precum si spiritele capturate de tine, Uzer'i se poate apuca de lucru si iti cere sa astepti cat timp sunt pregatite armele."},{t="Cand se termina asteptarea",b="Uzer'i se intoarce si te lasa sa alegi dintre arme, spunandu-ti ca spiritele creaturilor capturate sunt pecetluite pentru totdeauna in ele. Acum le poti folosi energia ca si cum ar fi a ta."}},faq={{q="Cine se afla in spatele Weapons of Spirit?",a="Witch Doctor Uzer'i, acelasi care te-a trimis dupa muisek, iar aceasta vine dupa Mountain Giant Muisek.",al={"cine ofera weapons of spirit","cine da misiunea weapons of spirit","misiunea lui uzeri"}},{q="Ce face Witch Doctor Uzer'i in aceasta etapa?",a="Uzer'i lucreaza la infuzarea armelor cu muisek capturat, un proces descris drept dificil, si iti cere sa astepti cat timp se fac pregatirile.",al={"ce se intampla in Weapons of Spirit","ce face uzeri"}},{q="De ce este nevoie inainte ca Uzer'i sa poata incepe?",a="Uzer'i spune ca materialele necesare au fost adunate si ca spiritele capturate sunt la indemana, asa ca munca poate incepe.",al={"cerinte pentru weapons of spirit","conditii prealabile pentru weapons of spirit"}}},fp="17,184,19.207.0,18.178.1,32.106.0,50.139.0,39.110.0"}
P.entries["quest:313"] = {n="The Grizzled Den"}
P.entries["quest:3130"] = {n="Against the Hatecrest",s="Dupa ce ai raportat, General Shandris Feathermoon te trimite mai departe la Latronicus Moonspear, adjunctul generalului, in Feathermoon Stronghold. Shandris ar dori sa trimita o armata intreaga impotriva naga, dar nu va lasa fortareata expusa in fata Horde sau, mai rau.",h="Dupa ce ai raportat, General Shandris Feathermoon te trimite mai departe la Latronicus Moonspear, adjunctul...",kw={"impotriva celor din Hatecrest","feathermoon stronghold","feralas","hatecrest","horde","latronicus moonspear","naga","shandris feathermoon"},sec={{t="Shandris cantareste riscurile",b="General Shandris Feathermoon te trimite la Latronicus Moonspear, adjunctul generalului, care a urmarit indeaproape fortele naga pana acum. Shandris va evalua situatia de ansamblu cu naga de aici. Chiar daca s-ar dori trimiterea tuturor fortelor impotriva lor, lasarea fortaretei deschise unui atac direct al Horde sau al unei amenintari si mai grave pare departe de a fi o idee buna. Latronicus te asteapta la Feathermoon Stronghold."},{t="Ce intentioneaza Latronicus",b="Latronicus Moonspear spune ca Generalul l-a insarcinat sa se ocupe direct de naga. Planul are doua parti: sa le reduca numarul si sa le slabeasca conducerea, apoi sa afle ce fac in ruine. Cu ajutorul tau, prezenta lor poate fi contracarata, iar fortareata va ramane in siguranta."}},faq={{q="De ce te trimite Shandris Feathermoon la Latronicus?",a="Shandris nu va angaja toate fortele impotriva naga daca asta ar lasa Feathermoon Stronghold expusa lui Horde sau unei amenintari si mai mari. In schimb, generalul te indruma la al doilea, Latronicus, care ii supravegheaza pe naga.",al={"de ce sa vorbesti cu latronicus","de ce latronicus moonspear","recomandare de la feathermoon"}},{q="Unde se afla Latronicus Moonspear?",a="In Feathermoon Stronghold, unde Shandris te trimite sa-i raportezi.",al={"locatia lui Latronicus","unde se afla Latronicus","gaseste Latronicus Moonspear"}},{q="Ce a avut loc inaintea acestei sarcini?",a="Return to Feathermoon Stronghold, dupa care Shandris te trimite mai departe la Latronicus.",al={"conditie prealabila pentru against the hatecrest","misiunea anterioara","inceputul lantului hatecrest"}}},fp="21,266,24.411.0,23.288.1,53.232.0,38.69.0,33.82.0"}
P.entries["quest:314"] = {n="Protecting the Herd"}
P.entries["quest:315"] = {n="The Perfect Stout",s="Rejold Barleybrew din Brewnall Village este hotarat sa prepare bere neagra piticeasca desavarsita, imbinand traditia berarilor din familie cu ingrediente locale exotice. Pentru a-si perfectiona reteta experimentala, cauta buruiana sclipitoare, o planta cu miros intepator, cultivata doar de trollii Frostmane ostili, pe Shimmer Ridge. Calatorii indrazneti sunt trimisi in tabara trollilor sa fure planta chiar din cosurile tribului.",h="Rejold Barleybrew din Brewnall Village este hotarat sa prepare bere neagra piticeasca desavarsita, imbinand...",kw={"Brewnall Village","Dun Morogh","bere pitica","Frostmane","bere neagra perfecta","Rejold Barleybrew","Shimmer Ridge","Shimmerweed"},ang={["profession:Herbalism"]="Desi nu este o planta obisnuita pentru mestesuguri, trasaturile botanice unice ale ierbii stralucitoare rezistente la ger o fac o curiozitate fascinanta printre crestele inghetate din Dun Morogh.",["race:Dwarf"]="Fabricarea berii este aproape sacra pentru Bronzebeard clan, iar gasirea unei plante salbatice exotice care sa intreaca tavernele rivale este considerata o indeletnicire nobila."},sec={{t="Ambitia unui berar",b="In Brewnall Village, fabricarea berii este mai mult decat o meserie - este un mod de viata, mai ales pentru familia Barleybrew. Rejold Barleybrew crede ca talentul de a face bere exceptionala ii curge prin sange, dar obtinerea legendarei 'perfect stout' cere inovatie neconventionala. In loc sa se bazeze doar pe hamei, malt si apa de izvor de munte obisnuite, Rejold cauta flora neimblanzita din Dun Morogh, care sa dea berii sale o tarie inconfundabila."},{t="Planta Troll din Shimmer Ridge",b="Ingredientul secret pe care-l ravneste Rejold este iarba stralucitoare, o planta rezistenta la frig, cultivata de trolii Frostmane pe Shimmer Ridge, la rasarit. In timp ce Frostmane o strang pentru ritualurile tribale si mistice, piticii au avut putine intrebuintari practice pentru ea, in afara de a-i remarca gustul intepator si distinct. Smulsa direct din cosurile de depozitare din satul trolilor, planta sta in centrul celui mai recent si indraznet experiment de fermentare al lui Rejold."}},faq={{q="Ce este iarba stralucitoare?",a="Shimmerweed este o planta aparte, cultivata si recoltata de trollii Frostmane pe Shimmer Ridge. Desi trollii o folosesc mai ales in ceremoniile si ritualurile tribale, Rejold Barleybrew vrea sa-i testeze aroma intensa si aparte, folosind-o ca ingredient neobisnuit pentru aromatizarea berii piticilor.",al={"povestea plantei shimmerweed","la ce foloseste shimmerweed","planta frostmane"}},{q="Unde se afla Shimmer Ridge?",a="Shimmer Ridge se afla pe inaltimile inzapezite din nordul Dun Morogh, la est de Brewnall Village. Este o tabara fortificata a trolilor Frostmane bastinasi, asa ca orice incursiune in cautare de ierburi acolo este o aventura primejdioasa pe teritoriu ostil.",al={"locatia Shimmer Ridge","unde se afla Shimmer Ridge","cum gasesti Shimmer Ridge"}},{q="De ce vrea Rejold sa fure de la trolii Frostmane?",a="Trollii Frostmane detin monopolul asupra cultivarii shimmerweed in Dun Morogh, iar tensiunile dintre dwarves si trolli fac imposibil comertul pasnic. Plantele au fost deja recoltate si stranse in cosuri tribale in tabara lor, asa ca Rejold nu are alta optiune decat sa se strecoare inauntru sau sa lupte pentru a pune mana pe ele.",al={"de ce sa furi de la troli","de ce cosurile trolilor","planul lui rejold cu trolii"}},{q="Cine este Rejold Barleybrew?",a="Rejold Barleybrew este un berar pitic ambitios care locuieste in Brewnall Village. Fidel numelui familiei sale, si-a dedicat mestesugul descoperirii retetei pentru berea neagra perfecta, experimentand intruna cu arome noi si ingrediente salbatice, puternice.",al={"cine este rejold","rejold barleybrew","familia barleybrew"}},{q="Este shimmerweed considerata o planta alchimica?",a="Nu. Shimmerweed nu este un reactiv alchimic cules din zacamanturi salbatice. Este un obiect de misiune depozitat in cosuri de rachita si ascunzatori raspandite prin asezarile Frostmane de pe Shimmer Ridge.",al={"pot culegatorii de plante sa adune Shimmerweed","Shimmerweed tine de ierbalism","culesul de Shimmerweed"}},{q="Ce se intampla cu iarba sclipitoare dupa ce este predata?",a="Rejold arunca iarba stralucitoare proaspat culeasa direct intr-un lot aflat deja la fermentat in Brewnall Village, sperand ca profilul sau unic va dezvalui, in sfarsit, reteta perfecta pe care o cauta.",al={"functioneaza berea tare","rezultatul berii lui rejold","bere cu shimmerweed"}}},fx={["3780a202"]={q="Cine sunt trollii Frostmane?",a="Frostmane este un trib bastinas de troll de gheata din piscurile inzapezite ale Dun Morogh. Alungati din vechile lor tinuturi de vanatoare de expansiunea Dwarf-ilor din Ironforge, ei nutresc o ostilitate profunda fata de vecinii lor Dwarf. Din asezari precum cea de pe Shimmer Ridge, cultiva buruiana stralucitoare pentru ritualurile tribului si isi apara cu inversunare taberele de orice intrus.",al={"trolls frostmane","cine sunt troll-ii de pe shimmer ridge","frostmane tribe"}}},fp="17,402,19.424.0,31.454.0,20.281.0,31.240.0,56.313.0,25.248.0,42.182.0,47.191.0"}
P.entries["quest:3161"] = {n="Gahz'ridian",s="Marvon Rivetseeker, om de stiinta si vanator de comori in sine, vrea treizeci de ornamente ramase in urma de la Troll care au trait candva in Tanaris. Marvon iti da un detector inventat de ei pentru a te ajuta sa le gasesti.",h="Marvon Rivetseeker, om de stiinta si vanator de comori in sine, vrea treizeci de ornamente ramase in urma de...",kw={"stalp rupt","detector","eastmoon ruins","gahz'ridian","gahz'rilla","marvon rivetseeker","southmoon ruins","tanaris","troll"},sec={{t="Relicvele zeului Hydra",b="Cu mult timp in urma, trolii au locuit acest tinut si au creat numeroase podoabe infatisandu-l pe Gahz'rilla, o hydra pe care o venerau ca pe un zeu. Marvon Rivetseeker numeste materialul din care au fost sculptate Gahz'ridian, dupa zeul hydra. Marvon a gasit cateva si ar dori sa mai aiba pentru studiu."},{t="Detectorul",b="Marvon a inventat un detector care usureaza gasirea de Gahz'ridian si ti-l da. Purtarea lui da startul cautarii. Ornamentele pot fi gasite aproape oriunde in Tanaris, dar se aduna mai ales langa Broken Pillar, Eastmoon Ruins si Southmoon Ruins."}},faq={{q="Cine este Marvon Rivetseeker?",a="Marvon Rivetseeker este un om de stiinta din Tanaris, dar in sufletul lui este si vanator de comori. Studiaza ornamentele facute de trollii din vechime.",al={"marvon rivetseeker","cine ofera gahzridian","cel care da misiunea"}},{q="Ce este Gahz'ridian?",a="Asa numeste Marvon Rivetseeker elementul din care au fost sculptate podoabele hidra ale troll, provenit de la zeul hidra.",al={"ce este gahzridian","mineralul gahzridian","materialul gahzridian"}},{q="Cine este Gahz'rilla?",a="Gahz'rilla este o hydra pe care vechii Troll o venerau ca pe un zeu. Ei isi confectionau podoabele dupa chipul sau.",al={"zeitatea gahzrilla","venerarea hidrei","cine este gahzrilla"}},{q="Unde se gasesc ornamentele Gahz'ridian?",a="Aproape oriunde in Tanaris, desi cele mai mari concentrari se gasesc in jurul Broken Pillar si al Eastmoon and Southmoon Ruins.",al={"unde gasesti gahzridian","cel mai bun loc pentru gahzridian","locatiile gahzridian"}},{q="Cum gasesti ornamentele?",a="Marvon a inventat un detector in acest scop. Purtarea lui incepe cautarea.",al={"cum sa identifici podoabele","detectorul gahzridian","gasirea gahzridian"}}},fp="11,207,23.285.0,12.263.0,26.130.0,20.119.0,18.102.0,38.125.0,30.77.0"}
P.entries["quest:317"] = {n="Stocking Jetsteam"}
P.entries["quest:318"] = {n="Evershine"}
P.entries["quest:3181"] = {n="The Horn of the Beast",s="Un corn urias, provenit de la Margol the Rager din Searing Gorge, este zgariat si crapat, iar in suprafata lui aspra este infipt un cap de topor rupt. Capul de topor poarta gravat numele proprietarului, Mountaineer Pebblebitty, si se sfarama in milioane de bucati cand incerci sa-l desprinzi. Cornul trebuie dus la Pebblebitty.",h="Un corn urias, provenit de la Margol the Rager din Searing Gorge, este zgariat si crapat, iar in suprafata...",kw={"corn gigantic","loch modan","margol the rager","pebblebitty","searing gorge","stonewrought pass"},sec={{t="Un indiciu distrus",b="Cornul lui Margol the Rager este acoperit de zgarieturi si crapaturi. In el este infipt un obiect metalic neobisnuit, un cap de secure rupt, gravat astfel incat sa arate ca i-a apartinut lui Mountaineer Pebblebitty. Cand incerci sa-l scoti, se sfarama in milioane de bucati."},{t="Poarta",b="Acest corn porneste lantul de misiuni care deschide Stonewrought Pass, trecatoarea dintre Loch Modan si Searing Gorge. Trebuie dus la Mountaineer Pebblebitty, care nu este dispus sa deschida poarta."},{t="La poarta",b="Pebblebitty spune ca cornul e in mod evident un fals. Dupa ce a dat nas in nas cu Margol, Pebblebitty spune ca al ei e mult mai mare, de cel putin opt ori cat al tau, si ca al tau probabil a fost luat de la un stormsnout din Barrens."}},faq={{q="De unde provine acest corn?",a="Provine de la Margol the Rager din Searing Gorge.",al={"unde gasesc cornul","locatia lui margol the rager","cine lasa cornul"}},{q="Cine este Mountaineer Pebblebitty?",a="Pebblebitty este alpinistul caruia trebuie sa-i duci cornul si cel care nu vrea sa deschida poarta.",al={"Pebblebitty","cine este Pebblebitty","mountaineer Pebblebitty"}},{q="Ce se intampla cu taisul toporului din corn?",a="Este gravat cu numele proprietarului, Mountaineer Pebblebitty, si se sfarama in un milion de bucati cand incerci sa-l desprinzi.",al={"de ce era toporul pebblebitty in corn","inscriptia de pe capul toporului"}},{q="Unde duce cornul?",a="Aceasta incepe lantul care deschide drumul prin Stonewrought Pass, legand Loch Modan de Searing Gorge.",al={"stonewrought pass","care este cheia spre searing gorge"}}},fp="21,316,16.250.0,8.188.0,11.233.1,31.48.0,31.112.0,41.123.0,27.103.1"}
P.entries["quest:319"] = {n="A Favor for Evershine"}
P.entries["quest:32"] = {n="Rise of the Silithid",s="Senior Surveyor Fizzledowser iti da raportul despre amenintarea insectelor si te indeamna sa-l duci la Orgrimmar, la un invatat troll pe nume Zilzibin Drumlore.",h="Senior Surveyor Fizzledowser iti da raportul despre amenintarea insectelor si te indeamna sa-l duci la...",kw={"drag","drumlore","fizzledowser","insecte","orgrimmar","silithid","tanaris","zilzibin"},sec={{t="Cineva care stie",b="Fizzledowser vrea ca raportul sa ajunga la cineva care cunoaste bine asemenea chestiuni. Zilzibin Drumlore este un invatat troll care a petrecut mult timp studiind formele de viata specifice ecosistemului din Azeroth si este, de asemenea, istoric. Fizzledowser spera ca Zilzibin va putea stabili care este cu adevarat pericolul si cum ar putea fi oprit si spune ca va fi nevoie de tot ajutorul disponibil. Zilzibin locuieste intr-o casa de la al doilea nivel din Drag, in Orgrimmar."},{t="Raspunsul lui Zilzibin",b="Zilzibin s-a mai confruntat cu aceste creaturi si crede ca Fizzledowser a facut bine sa trimita raportul si sa te trimita pe tine. Ele vor devora rapid desertul din Tanaris si se numara printre cele mai mari amenintari cu care se va confrunta cineva vreodata. Sunt silithid, instrumentele uneia dintre cele mai grave amenintari la adresa Horde si Alliance. Zilzibin deplange faptul ca nimeni n-a fost suficient de intelept ca sa-si dea seama mai devreme."}},faq={{q="Cine este Zilzibin Drumlore?",a="Un invatat Troll si istoric, care a petrecut mult timp studiind formele de viata unice ecosistemului din Azeroth.",al={"cine este Drumlore","povestea lui Zilzibin Drumlore","Troll carturar din Orgrimmar"}},{q="Cine te trimite la Zilzibin?",a="Senior Surveyor Fizzledowser, care iti da raportul si iti cere sa-l duci la Orgrimmar.",al={"inceputul Rise of the Silithid","cine da Rise of the Silithid"}},{q="Unde se afla Zilzibin Drumlore in Orgrimmar?",a="Intr-o casa de pe Drag, la al doilea nivel, in Orgrimmar.",al={"unde se afla Zilzibin","unde se afla casa Drumlore"}},{q="Ce precede direct acest pas?",a="Urmeaza Insect Part Analysis.",al={"misiunea anterioara rise of the silithid","ce a dus la rise of the silithid"}}},fp="20,153,17.452.0,17.367.1,25.115.0,26.93.0,48.60.0,37.32.0"}
P.entries["quest:320"] = {n="Return to Bellowfiz",s="Return to Bellowfiz este o scurta misiune de livrare din Dun Morogh, in care un aventurier ii duce un butoi cu Evershine local pilotului Bellowfiz, la Steelgrill's Depot. Misiunea incheie o favoare locala, rasplatindu-l pe soferul insetat cu o bautura binevenita.",h="Return to Bellowfiz este o scurta misiune de livrare din Dun Morogh, in care un aventurier ii duce un butoi...",kw={"butoi de evershine","dun morogh","evershine","kharanos","pilot bellowfiz","return to bellowfiz","steelgrill's depot"},ang={["faction:Alliance"]="A face comisioane intre vanatorii pitici si pilotii pitici ajuta la mentinerea moralului si a camaraderiei in randul fortelor Alliance stationate in Dun Morogh.",["race:Dwarf"]="O bere tare de dwarfi precum Evershine este mereu foarte cautata in Dun Morogh, asa ca livrarea ei in siguranta camarazilor insetati devine ceva firesc.",["race:Gnome"]="Pilot Bellowfiz este un conducator pitic de masini de asediu, stationat la Steelgrill's Depot, iar inginerii harnici, bine dispusi, mentin masinile in functiune."},sec={{t="Un butoi pentru depozit",b="Return to Bellowfiz este o sarcina de indeplinit prin tinuturile inzapezite din Dun Morogh. Dupa ce da o mana de ajutor la vanatoarea locala, un aventurier primeste un butoi de Evershine proaspat facut, cu instructiunea de a-l duce direct la Pilot Bellowfiz, la Steelgrill's Depot. Este o favoare simpla, care scoate in evidenta camaraderia neoficiala si sprijinul reciproc ce mentin viata la frontiera friguroasa."},{t="Aviatori insetati",b="Steelgrill's Depot este un centru aglomerat pentru testarea mecanismelor, intretinerea vehiculelor si mestesugul gnomilor, chiar langa Kharanos. Pentru pilotii stationati in bataia vanturilor inghetate, nimic nu e mai bun decat o halba de bautura locala tare. Pilot Bellowfiz nu pierde vremea dupa livrare: abia asteapta sa desfaca o sticla pe loc si sa se bucure de roadele muncii localnicilor."}},faq={{q="Ce este misiunea Return to Bellowfiz?",a="Return to Bellowfiz este o sarcina de livrare in Dun Morogh, in care un aventurier duce un butoi proaspat obtinut de Evershine direct la Pilot Bellowfiz, la Steelgrill's Depot.",al={"ce este return to bellowfiz","misiunea bellowfiz"}},{q="Cine este Pilot Bellowfiz?",a="Pilot Bellowfiz este un sofer pitic de motor de asediu, stationat la Steelgrill's Depot, chiar in afara Kharanosului, in Dun Morogh. Abia asteapta sa primeasca o noua livrare de Evershine, ca sa o guste.",al={"cine vrea Evershine","cine este Bellowfiz"}},{q="Ce este butoiul cu Evershine?",a="Evershine este o bautura locala tare, facuta in Dun Morogh, pastrata intr-un butoi rezistent si pretuita deopotriva de piloti si localnici insetati.",al={"ce este evershine","butoiul cu evershine"}},{q="Unde se livreaza butoiul?",a="Pilot Bellowfiz se afla la Steelgrill's Depot, un centru de inginerie si atelier situat chiar la est de Kharanos, in Dun Morogh.",al={"unde se afla Bellowfiz","locatia lui Bellowfiz"}},{q="De ce a fost trimisa Evershine lui Bellowfiz?",a="Dupa ce ajuta la sarcinile de vanatoare din regiune, un aventurier primeste in grija un butoi de Evershine, pe care trebuie sa-l duca la Pilot Bellowfiz, care abia asteapta sa-l guste.",al={"de ce sa livrezi evershine","motivul livrarii lui evershine"}},{q="Ce se intampla cand Bellowfiz primeste Evershine?",a="Dupa ce primeste butoiul, Pilot Bellowfiz este pe deplin multumit, declarand ca isi va face treaba foarte bine si trecand imediat sa desfaca o sticla pentru a gusta.",al={"ce face bellowfiz cu berea","reactia lui bellowfiz"}}},fp="19,233,20.367.0,16.361.0,38.167.0,23.182.0,30.127.0,30.127.0,40.177.0,51.160.0"}
P.entries["quest:321"] = {n="Lightforge Iron",s="Lightforge Iron este o misiune de recuperare a Alliance, oferita de Glorin Steelbrow in Menethil Harbor. Aventurierii sunt trimisi sa cerceteze ramasitele Flying Osprey, un distrugator elfic care transporta un metal sacru rar si care s-a pierdut impreuna cu Third Fleet of Kul Tiras in timpul Second War.",h="Lightforge Iron este o misiune de recuperare a Alliance, oferita de Glorin Steelbrow in Menethil Harbor.",kw={"Flying Osprey","Glorin Steelbrow","lingou","Kul Tiras","fier de Lightforge","Menethil Harbor","murloc","Third Fleet","cufar scufundat","zone umede"},ang={["class:Paladin"]="Armele faurite din fier Lightforge sunt profund legate de Holy Light, ceea ce face ca recuperarea chiar si a unui singur lingou pierdut sa aiba o mare insemnatate spirituala.",["faction:Alliance"]="Epavele scufundate din largul Menethil Harbor sunt memoriale sumbre ale Second War, unde marinari neinfricati din Kul Tiras si Lordaeron au cazut sub focul dragonilor.",["profession:Blacksmithing"]="Fierarii de toate specializarile venereaza fierul Lightforge ca pe un material ideal, renumit pentru binecuvantarile sale puternice si rezistenta structurala fara egal."},sec={{t="O incarcatura sacra",b="Desi majoritatea corabiilor scufundate care impanzesc coasta din Wetlands apartineau vestitului Third Fleet of Kul Tiras, una iesea in evidenta: un distrugator elf botezat Flying Osprey. Venind din Lordaeron, corabia cautase siguranta printre numeroasele nave ale flotei, transportand o incarcatura pretioasa de fier binecuvantat de Light. Din nefericire, alaturarea unei flotei de galere de razboi nu a putut-o salva cand dragonii rosii inrobiti de Dragonmaw clan au coborat din cer, dand foc flotei si tragand sub valuri atat soldatii, cat si metalul consacrat."},{t="Jefuiti de maree",b="La ramasitele sfaramate ale Flying Osprey, la sud de Menethil Harbor, se vede ca timpul si marea n-au fost singurele forte care au actionat. Cufarul imbibat cu apa, in care se afla incarcatura, a fost spart si scormonit cu ghearele. Murlocii de coasta, mereu dornici sa scotoceasca prin epave, au pradat cala si au imprastiat lingourile, lasand abia vreo urma din minereul pretios cautat de Glorin Steelbrow."}},faq={{q="Ce este Flying Osprey?",a="Flying Osprey era un distrugator elfilor care naviga din Lordaeron in timpul Second War. Transporta un transport de fier rar Lightforge si calatorea sub protectia Third Fleet of Kul Tiras, dar a fost ars si scufundat, impreuna cu restul flotei, de dragoni rosii inrobiti de orci.",al={"povestea lui flying osprey","distrugator elven din wetlands","ce nava avea fierul"}},{q="Cine este Glorin Steelbrow?",a="Glorin Steelbrow este un dwarf stationat in Menethil Harbor, in Wetlands. Este interesat sa recupereze relicve istorice si materiale valoroase de pe corabiile scufundate de-a lungul coastei, in special metale legendare precum fierul Lightforge.",al={"Glorin Steelbrow","piticul din Menethil","cine ofera fier Lightforge"}},{q="Ce este fierul Lightforge?",a="Fierul Lightforge este un metal sfintit, extrem de rar, folosit la faurirea armelor si armurilor consacrate. Este pretuit de fierari si campionii Holy Light pentru puritatea si proprietatile sale spirituale rezistente.",al={"metal Lightforge","ce este fierul Lightforge","lingouri Lightforge"}},{q="De ce au fost scufundate corabiile in Wetlands?",a="In timpul Second War, Dragonmaw clan din Horde a folosit Demon Soul pentru a inrobi Red Dragonflight. Calaretii pe dragoni au atacat Third Fleet din Kul Tiras in largul coastei din Wetlands, incendiind corabiile si trimitandu-le pe fundul oceanului.",al={"cine a scufundat third fleet","de ce sunt epavele navelor in wetlands","dragonii rosii wetlands fleet"}},{q="De ce este cufarul aproape gol?",a="Lada imbibata cu apa de pe Flying Osprey poarta urme proaspete de gheare lasate de murlocii de pe coasta. Creaturile au fortat-o si au jefuit incarcatura, luand majoritatea lingourilor si imprastiindu-le de-a lungul tarmului mlastinos.",al={"unde sunt lingourile","de ce sunt urme de gheare pe cufar","cine a furat fierul Lightforge"}},{q="Unde se afla epava Flying Osprey?",a="Epava se afla printre bancurile de nisip de langa coasta, chiar la sud de Menethil Harbor, de-a lungul tarmului vestic al Wetlands, imprastiata prin apele putin adanci din apropierea asezarilor locale de murloci.",al={"locatia Flying Osprey","unde se afla cufarul","locatia epavei din Wetlands"}}},fx={["915ea990"]={q="De ce vrea Glorin Steelbrow fier Lightforge?",a="Glorin Steelbrow este un preot care incearca sa recupereze metalul rar pentru a pregati o arma impotriva lui Morbent Fel. Incarcatura scufundata a navei Flying Osprey ofera o ocazie rara de a salva fierul Lightforge, o marfa elfica pretioasa, pierduta inca din Second War. Trimitandu-te sa-l recuperezi, spera sa adune suficient metal maleabil pentru a fauri arme demne de legenda sa nepieritoare.",al={"de ce vrea Glorin fier","motivul pentru care Glorin Steelbrow vrea Lightforge Iron","de ce trebuie gasit Lightforge Iron"}}},fp="15,276,14.542.0,22.407.1,26.291.0,24.241.0,24.206.0,40.234.0,30.223.0,51.170.0"}
P.entries["quest:322"] = {n="Blessed Arm",s="In Stormwind, Blessed Arm duce fier de forja luminoasa pentru arma menita sa-l infrunte pe Morbent Fel. Dupa ce recuperezi lingourile din epava lui Flying Osprey, in Wetlands, duci metalul pretios la maestrul fierar Dwarf Grimand Elmore, care il poate modela pentru lupta cu necromantul.",h="In Stormwind, Blessed Arm duce fier de forja luminoasa pentru arma menita sa-l infrunte pe Morbent Fel.",kw={"Blessed Arm","cartierul piticilor","Glorin Steelbrow","Grimand Elmore","fier Lightforge","Loch Modan","Morbent Fel","Stormwind"},ang={["class:Paladin"]="Ca paladin, sa duci fier sfintit pentru a fauri o arma impotriva unui necromant din Duskwood inseamna sa urmezi chemarea Silver Hand: sa infrunti magia intunecata cu vigilenta sfanta.",["faction:Alliance"]="Ca membru al Alliance, duci ajutoare intre regate, de la un priest dwarf din Menethil Harbor pana in Dwarven District din Stormwind, pentru locuitorii greu incercati din Duskwood.",["profession:Blacksmithing"]="Fierul Lightforge este rar si greu de prelucrat. Sa-l privesti pe fierarul Dwarf experimentat Grimand Elmore lucrand cu el demonstreaza priceperea necesara pentru a forja arme sfinte."},sec={{t="Se intoarce un metal rar",b="Glorin Steelbrow pregateste fierul recuperat de la lumina pentru Stormwind. Metalul este rar, iar puterea sa impotriva fiintelor ticaloase si necurate cere un fierar care stie sa-l prelucreze. Dupa ce transportul a fost scos din epava lui Flying Osprey, de pe coasta Wetlands, Glorin a stiut ca exista un singur mestesugar in regatele sudice potrivit pentru treaba: maestrul armurier Grimand Elmore."},{t="Forja din Dwarven District",b="In Dwarven District din Stormwind, Grimand Elmore pastreaza una dintre cele mai bune nicovale din oras. Au trecut ani de cand a batut ultima data fier lightforge, spune el, cand ii aduci transportul recuperat. Mesterul veteran este intrigat de sansa de a-l infrunta pe necromantul Morbent Fel si accepta sa-si puna ciocanul la treaba."}},faq={{q="Care este scopul acestei livrari?",a="Lada contine fier lightforge recuperat din epava Flying Osprey din Wetlands. Glorin Steelbrow il trimite lui Grimand Elmore, care poate fauri din metalul consacrat o arma impotriva necromantului Morbent Fel.",al={"de ce sa duci lingourile la stormwind","scopul lui blessed arm","la ce foloseste crate of lightforge ingots"}},{q="Cine este Grimand Elmore?",a="Grimand Elmore este un mester pitic respectat, specializat in arme, care lucreaza in Dwarven District din Stormwind. Putini artizani au pregatirea necesara pentru a fauri metale speciale precum lightforge iron.",al={"povestea lui Grimand Elmore","cine este fierarul din cartierul Dwarven"}},{q="De ce este atat de important fierul Lightforge impotriva lui Morbent Fel?",a="Fierul Lightforge este renumit pentru puterea sa impotriva fiintelor malefice si profane. Grimand Elmore poate modela metalul consacrat intr-o arma cu care sa-l infrunti pe necromantul Morbent Fel.",al={"de ce fier Lightforge","cum il raneste fierul Lightforge pe morbent fel"}},{q="Unde te trimite Glorin Steelbrow?",a="Glorin Steelbrow te trimite de la Menethil Harbor, din Wetlands, la forja lui Grimand Elmore din Stormwind City's Dwarven District.",al={"unde merg pentru Blessed Arm","unde se afla grimand elmore"}},{q="A mai lucrat Grimand Elmore cu fierul lightforge?",a="Da. Grimand spune ca au trecut ani de cand a lucrat ultima oara cu fier de forja luminoasa si se bucura de sansa de a modela din nou metalul legendar.",al={"a faurit Grimand Lightforge inainte","experienta lui Elmore in fierarie"}},{q="Ce trebuie sa se intample inainte ca arma sa poata fi terminata?",a="Grimand accepta sa faureasca Morbent's Bane din fierul lightforge recuperat. Cand termina, duci arma la Sven Yorgen, in Duskwood.",al={"ce urmeaza dupa blessed arm","este arma forjata imediat"}}},fx={["983cc211"]={q="De ce vrea Glorin Steelbrow sa fie facuta aceasta livrare?",a="Glorin stie ca otelul obisnuit nu poate strapunge protectiile intunecate care il apara pe Morbent Fel in Duskwood. Dupa ce a recuperat fierul de la forja luminii pe care l-ai obtinut din epava lui Flying Osprey din Wetlands, iti recunoaste campania impotriva necromantului si te indruma catre un fierar iscusit, capabil sa faureasca o arma care sa-l poata rani cu adevarat.",al={"motivul lui Glorin Steelbrow","de ce ajuta Glorin","de ce sa duci lingouri la Grimand"}}},fp="11,277,20.369.0,28.323.0,37.218.0,22.174.0,56.175.0,37.127.0,54.136.0,51.143.0"}
P.entries["quest:3221"] = {n="Speak with Renferrel",s="Speak with Renferrel este o scurta misiune in Sepulcher, in Silverpine Forest. High Executor Hadrec te trimite inapoi la cercetatorul local al Royal Apothecary Society pentru a discuta descoperirile privind inimile de lup contaminate.",h="Speak with Renferrel este o scurta misiune in Sepulcher, in Silverpine Forest.",kw={"hadrec","renferrel","Royal Apothecary Society","sepulcher","silverpine","inimi de lup"},ang={["faction:Horde"]="Pe masura ce Horde isi stabileste avanposturi in Lordaeron, intelegerea coruperii care afecteaza animalele locale este vitala pentru securizarea tinuturilor salbatice.",["race:Undead"]="Royal Apothecary Society colaboreaza indeaproape cu comandamentul militar de la Sepulcher, asigurandu-se ca fiecare anomalie biologica din Silverpine este studiata in folosul scopurilor Dark Lady."},sec={{t="Chemare din partea Societatii",b="Dupa ce ii ajuta pe Deathstalkers in Silverpine Forest, High Executor Hadrec transmite un mesaj urgent de la Apothecary Renferrel. Renferrel a petrecut ceva timp analizand inimile de lup decolorate, stranse de la vietatile din zona, si are nevoie de tine numaidecat."},{t="Curiozitati alchimice",b="Apothecary Renferrel slujeste Royal Apothecary Society din laboratorul sau aflat in cripta de la Sepulcher. Cercetarile sale in curs analizeaza felul in care magia neagra si bolile transforma fiarele din Silverpine, imbinand recunoasterea militara de pe linia intai cu cercetarea chimica."}},faq={{q="Unde se afla Apothecary Renferrel?",a="Apothecary Renferrel se afla in cripta Sepulcher-ului, in centrul regiunii Silverpine Forest, langa echipamentul sau de alchimie si la doar cativa pasi de High Executor Hadrec.",al={"locatia lui Renferrel","unde este Renferrel","gaseste-l pe Renferrel"}},{q="De ce vrea Apothecary Renferrel sa vorbeasca cu mine?",a="Renferrel a analizat inimile de lup decolorate, adunate de la lupii locali din Silverpine, si a descoperit particularitati ale coruperii lor care necesita investigatii suplimentare si comunicarea cu Undercity.",al={"de ce ma vrea Renferrel","inimile de lup pentru Renferrel"}},{q="Cine te trimite la Renferrel?",a="High Executor Hadrec, comandantul militar Forsaken de la Sepulcher, iti transmite chemarea lui Renferrel cand te intorci dupa ce i-ai ajutat Deathstalkers.",al={"cine ofera Speak with Renferrel","cel care da misiunea"}},{q="Ce urmeaza dupa aceasta conversatie?",a="Discutia cu Renferrel duce direct la sarcini care conecteaza cercetarile alchimice regionale din Sepulcher cu personalitati de rang inalt precum Apothecary Zinge din Undercity.",al={"misiunea urmatoare dupa speak with renferrel","continuarea pentru renferrel"}}},fx={["1f8d2902"]={q="De ce te trimite High Executor Hadrec la Renferrel?",a="High Executor Hadrec doar transmite o convocare oficiala in numele Royal Apothecary Society. In timp ce cercetai linia frontului din Silverpine pentru Deathstalkers, Apothecary Renferrel ti-a cerut sa te intorci pentru a discuta despre inimile de lup pe care le-ai adunat mai demult pentru cercetarile sale alchimice. Hadrec se asigura ca treburile importante dintre avanpostul militar si Societate se desfasoara fara probleme.",al={"motivul lui hadrec","de ce vrea hadrec sa speak with renferrel","de ce ma trimite la apothecary renferrel"}}},fp="20,221,24.273.0,22.261.0,38.169.0,52.211.0,27.159.0,31.172.0"}
P.entries["quest:323"] = {n="Proving Your Worth",s="Proving Your Worth este o etapa esentiala in campania de razbunare a lui Sven Yorgen in vestul Duskwood. Inainte de a-i ingadui unui aventurier sa-l infrunte direct pe necromantul Morbent Fel, pustnicul indurerat ii cere sa dovedeasca faptul ca poate invinge legiunile de strigoi care cotropesc Raven Hill Cemetery.",h="Proving Your Worth este o etapa esentiala in campania de razbunare a lui Sven Yorgen in vestul Duskwood.",kw={"calareti intunecati","Duskwood","Forlorn Rowe","Morbent Fel","sa-ti dovedesti valoarea","cimitirul Raven Hill","vindecator scheletic","jefuitor scheletic","strajer scheletic","Sven Yorgen"},ang={["class:Paladin"]="Purificarea Raven Hill Cemetery de mortii nelinistiti ai lui Morbent Fel este o lucrare sfanta, raspunzand strigatelor celor neingropati din Duskwood cu dreptatea Light.",["class:Priest"]="Profanarea mormintelor din Raven Hill prin ritualuri intunecate cere purificare spirituala, punand capat activitatii paznicilor si vindecatorilor care pervertesc viata si moartea.",["faction:Alliance"]="Vestul Duskwoodului a cazut in anarhie in lipsa patrulelor regulate din Stormwind, iar locuitori de la hotar, loviti de nenorociri precum Sven, trebuie sa se bazeze in intregime pe campionii calatori pentru a respinge flagelul strigoilor."},sec={{t="Incercarea unui sihastru amarat",b="Sven Yorgen se ascunde intr-o tabara izolata, la nord de padurea urlatoare, mistuit de durere si furie din pricina masacrarii familiei sale. A reusit sa afle ca Dark Riders, care i-au ras gospodaria de pe fata pamantului, erau aliati cu un necromant sinistru pe nume Morbent Fel. Desi Sven tanjeste dupa razbunare, nu este atat de nechibzuit incat sa-l arunce pe un recrut neincercat direct in mainile lui Fel. El cere o dovada de maiestrie absoluta in lupta impotriva fortelor scheletice care salasluiesc in Raven Hill Cemetery."},{t="Criptele din Raven Hill",b="Pentru a-i indeplini cererea lui Sven, aventurierii trebuie sa patrunda adanc in necropola din Raven Hill, la sud de Forlorn Rowe. Mausoleul si imprejurimile sunt pline de cadavre nelinistite, legate de magia spurcata a lui Fel: Skeletal Raiders inarmati cu sabii patruleaza printre pietrele funerare, in timp ce Skeletal Warders si Healers ingrijesc incaperile intunecate de sub pamant. Curatarea acestei forte din avanpost este o corvoada sangeroasa, mai ales cand groaza razbunatoare Mor'Ladim da tarcoale cararilor cimitirului."},{t="Drumul catre necromant",b="Supravietuirea in catacombele presarate cu oase il convinge pe Sven ca aliatul sau are mai mult decat curaj de parada. Totusi, infrangerea slujitorilor inferiori ai lui Fel este doar inceputul. Morbent Fel foloseste vraji intunecate de protectie care il fac aproape de neatins pentru armele obisnuite, obligandu-l pe Sven sa caute o intelepciune mai mare si relicve stravechi inainte de a incepe confruntarea finala."}},faq={{q="De ce ma pune Sven sa lupt cu scheleti inainte sa-l infrunt pe Morbent Fel?",a="Sven stie ca Morbent Fel este un necromant letal, aliat cu misteriosii Dark Riders. El refuza sa trimita un aliat la o moarte fara rost pana cand acesta nu dovedeste ca are rezistenta si pricepere tactica necesare pentru a strapunge intreaga avangarda de slujitori strigoi.",al={"de ce trebuie sa-ti dovedesti valoarea","de ce ma pune Sven sa ucid scheleti","incercarea lui Sven"}},{q="Unde se gasesc paznicii si vindecatorii scheletici?",a="In timp ce Skeletal Raiders cutreiera terenurile deschise ale cimitirului, la sud de Forlorn Rowe, Skeletal Healers si Warders se gasesc in principal in interiorul si in imediata apropiere a mausoleului mare si a tunelurilor criptei, la vest de centrul cimitirului.",al={"unde sunt paznicii","unde sunt vindecatorii scheletici","gaseste paznicii scheletici"}},{q="Cine este Mor'Ladim si de ce ar trebui sa ma feresc de el aici?",a="Mor'Ladim este un cavaler strigoi puternic si tragic, care cutreiera potecile din Raven Hill Cemetery. Este mult mai puternic decat scheletii obisnuiti din jurul criptelor si va dobori rapid aventurierii neprevazatori.",al={"pericolul Mor'Ladim","cine este Mor'Ladim","elita ratacitoare din Raven Hill"}},{q="Ce legatura are Morbent Fel cu Dark Riders?",a="Sven a descoperit ca Morbent Fel s-a aliat cu Dark Riders cu gluga, care i-au macelarit sotia si copiii. Calaretii au disparut inapoi in umbre, dar Fel a ramas in Duskwood si isi continua necromantia abjecta.",al={"legatura dintre Morbent Fel si calaretii intunecati","de ce calaretii intunecati si Fel","ucigasii familiei lui Sven"}},{q="Ce se intampla dupa finalizarea acestei misiuni?",a="Dupa ce iti dovedesti iscusinta in lupta, Sven iti recunoaste puterea, dar explica faptul ca Morbent Fel nu poate fi ucis doar prin forta bruta. Te indruma sa ceri sfatul lui Bishop Farthing, la Cathedral of Light din Stormwind, pentru a gasi o cale de a-l lipsi pe necromant de protectiile sale necurate.",al={"urmatoarea misiune dupa proving your worth","ce faci dupa schelete"}},{q="Unde este tabara lui Sven Yorgen?",a="Sven isi pastreaza o tabara ascunsa in dealurile de la marginea indepartata din nord-vestul Duskwood, ferita la nord de Raven Hill si la vest de drumul care duce spre Westfall.",al={"unde este sven","locatia taberei lui Sven"}}},fx={["865aa68b"]={q="Cine sunt servitorii scheletici de la Raven Hill?",a="Pradatorii scheletici, vindecatorii si paznicii care bantuie Raven Hill Cemetery sunt mortii readusi la viata de necromantul Morbent Fel. Ridicati din mormintele profanate din Duskwood, acesti morti nelinistiti formeaza acum un bastion profan care pazeste criptele cimitirului si indeplineste vointa intunecata a stapanului lor.",al={"jefuitori scheletici din Raven Hill","cine sunt scheletii din Raven Hill","acolitii lui Morbent Fel"}},fbdf818d={q="De ce are nevoie Sven Yorgen sa te lupti cu slujitorii lui Morbent Fel?",a="Sven Yorgen este un pustnic singuratic, care supravietuieste in tinuturile bantuite din Duskwood. Zdrobit de durere si mistuit de ura fata de Dark Riders, care i-au ucis familia, nu are puterea si resursele necesare sa atace singur armata de strigoi a lui Morbent Fel. De aceea, apeleaza la aventurieri capabili, gata sa infrunte Raven Hill Cemetery pentru a-l razbuna.",al={"de ce are nevoie Sven de ajutor","de ce nu lupta Sven","de ce imi cere Sven mie"}}},fp="18,282,22.482.0,21.463.0,27.362.1,64.250.0,49.239.0,57.200.0,48.220.0,41.288.1,36.171.0"}
P.entries["quest:324"] = {n="The Lost Ingots",s="Lost Ingots este o misiune a Alliance in Wetlands, ce presupune recuperarea metalului sfintit dintr-o epava. Dupa ce gasesc doar o singura bara intr-un cufar scufundat, calatorii trebuie sa-i vaneze pe murlocii Bluegill din zona, care au jefuit restul incarcaturii.",h="Lost Ingots este o misiune a Alliance in Wetlands, ce presupune recuperarea metalului sfintit dintr-o epava.",kw={"bluegill","flying osprey","glorin steelbrow","lingouri","fier lightforge","murloc","cufar plin cu apa","wetlands"},ang={["class:Paladin"]="Recuperarea fierului Lightforge de la murloci primitivi asigura pastrarea materialelor sfinte, necesare fauririi armelor consacrate, vrednice sa apere Light.",["profession:Blacksmithing"]="Orice prelucrator de metale cunoaste tragedia de a vedea un material superior precum fierul Lightforge ajungand podoaba intr-un cuib de murloci de pe tarm, in loc sa fie folosit la nicovala.",["race:Dwarf"]="Recuperarea minereului de maiestrie pierdut si inmanarea lui unui preot pitic precum Glorin Steelbrow onoreaza lunga traditie a mestesugului pitic si a celor care recupereaza aceste comori."},sec={{t="O epava jefuita",b="In largul tarmurilor cetoase din Wetlands se afla epava sfaramata a lui Flying Osprey. Cei trimisi sa recupereze fier Lightforge pretios pentru preotul dwarf Glorin Steelbrow au descoperit ca lada din cala, plina cu apa, era aproape goala. Voracii murloci Bluegill din zona jefuisera deja restul navei, luand pentru ei lingourile stralucitoare."},{t="Recuperarea metalului sacru",b="Fierul Lightforge nu este un minereu obisnuit, ci un metal rar, special, pregatit pentru mestesugul sacru al fierariei. Pentru un dwarf al Luminii, ar fi de neconceput sa-l lase sa se degradeze in taberele murlocilor. Vanandu-i pe jefuitorii Bluegill care misuna in apele putin adanci de langa epava rupta, aventurierii recupereaza lingourile imprastiate, pentru ca Glorin Steelbrow sa poata fauri din fier o arma."}},faq={{q="Ce nava a transportat fierul Lightforge?",a="Incarcatura a sosit la bordul lui Flying Osprey, o nava nefericita care si-a gasit sfarsitul in largul coastei din Wetlands. Epavele sale rupte se afla acum partial scufundate in apele putin adanci.",al={"ce corabie","flying osprey","numele epavei"}},{q="De ce nu se aflau lingourile in cufar?",a="In cufarul inundat mai ramasese incuiat un singur lingou. Murlocii Bluegill de pe coasta scotocisera deja printre ramasitele epavei scufundate si luasera restul incarcaturii, imprastiind-o printre piratii lor de pe litoral.",al={"unde sunt lingourile","de ce au murlocii fier","lada goala"}},{q="Cine este Glorin Steelbrow?",a="Glorin Steelbrow este un preot pitic al Church of the Holy Light, care se gaseste in Deepwater Tavern, in Menethil Harbor. Coleg cu Bishop Farthing, cauta fier Lightforge pentru a putea fi faurita o arma impotriva necromantului Morbent Fel.",al={"Glorin","cine este Glorin Steelbrow","cel care da misiunea"}},{q="Ce este special la fierul Lightforge?",a="Fierul Lightforge este un metal rar, sfintit, receptiv in mod unic la descantece sacre si la prelucrarea prin fierarie. Este foarte apreciat de mestesugarii care fauresc arme si armuri aflate in slujba Holy Light.",al={"istoria fierului Lightforge","ce este fierul Lightforge","de ce este fierul important"}},{q="Ce murloci au luat fierul?",a="Tribul Bluegill, mai exact jefuitorii murloc care dau tarcoale apelor putin adanci si plajelor din jurul epavei Flying Osprey, a pus mana pe lingourile disparute.",al={"cine a furat lingourile","care trib","praduitorii bluegill"}},{q="Ce urmeaza dupa ce returnezi lingourile?",a="Dupa ce Glorin Steelbrow primeste setul complet de lingouri, pune metalul sfintit intr-o lada si te trimite la armurierul Grimand Elmore din Stormwind ca sa-l prelucreze, continuand in Blessed Arm.",al={"misiunea urmatoare","ce face Glorin","misiunea Blessed Arm"}}},fp="15,236,21.371.0,27.370.0,38.180.0,37.216.0,24.239.0,38.170.0,28.154.0,43.204.1"}
P.entries["quest:325"] = {n="Armed and Ready"}
P.entries["quest:3261"] = {n="Jorn Skyseer"}
P.entries["quest:328"] = {n="The Hidden Key",s="Ascunsa in coperta registrelor lui Bookie Herod se afla o mica cheie de alama, alaturi de insemnari despre o caseta de valori bine pazita. Gasirea acestui recipient, adanc in complexul de pesteri din spatele Kurzen's Compound, ar putea dezvalui cum a fost tradat Private Thorsen.",h="Ascunsa in coperta registrelor lui Bookie Herod se afla o mica cheie de alama, alaturi de insemnari despre o...",kw={"bookie herod","cheie de alama","tabara lui Kurzen","private thorsen","rezerva","stranglethorn vale","cufar de valori"},sec={{t="Un secret in legaturi",b="Cautand prin registrele lui Bookie Herod, nu gasesti nicio mentiune directa despre Private Thorsen, dar descoperi altceva: o mica cheie de alama ascunsa in coperta unei carti. Printre hartii se strecoara cateva mentiuni despre o lada incuiata si sigura, ascunsa in Stockpile, complexul de pesteri din spatele lui Kurzen's Compound. Deschiderea ei ar putea dezvalui cum a fost deconspirat Thorsen."},{t="In adancul depozitului",b="Pentru a ajunge la lada de valori, trebuie sa explorezi sistemul de pesteri din spatele incintei. Greu, intarit cu bronz si construit solid, cufarul se afla printre lazile stivuite in pestera."}},faq={{q="De unde provine aceasta cheie de alama?",a="Cheita de alama era ascunsa in legatura uneia dintre cartile de contabilitate ale lui Bookie Herod si a fost descoperita in timp ce ii erau cercetate documentele.",al={"unde era cheia","cum am obtinut cheia","sursa cheii mici de alama"}},{q="Unde se afla lada de valori a lui Bookie Herod?",a="Cufarul incuiat se afla in Stockpile, complexul de pesteri aflat chiar in fundul Kurzen's Compound.",al={"locatia lazii de valori","unde se afla lada de valori","unde se afla cufarul"}},{q="De ce trebuie cautat cufarul lui Herod?",a="Hartiile ratacite ale lui Herod nu explica felul in care a fost compromisa prezenta lui Private Thorsen, dar mentioneaza o caseta de valori securizata care ar putea contine raspunsul.",al={"de ce sa gasesti lada de valori","ce se afla in lada","scopul lazii de valori"}},{q="Ce a fost inainte de acest pas?",a="Aceasta urmeaza investigatiei asupra lui Bookie Herod, cand s-a pornit pentru prima data in cautarea registrelor sale contabile si cercetarea lor.",al={"misiune anterioara","ce misiune vine prima"}}},fp="14,246,24.393.0,23.177.0,35.129.0,42.111.0,33.148.0,27.110.0"}
P.entries["quest:3281"] = {n="Stolen Silver"}
P.entries["quest:329"] = {n="The Spy Revealed!",s="In cufarul ferecat al lui Bookie Herod se afla o bucata umeda de pergament, care descrie rutina zilnica a lui Private Thorsen. Avand doar initiala M, aceasta corespondenta sugereaza ca un informator s-a infiltrat printre rebelii din nordul Stranglethorn Vale. Biletul plin de noroi este destinat lui Lieutenant Doren.",h="In cufarul ferecat al lui Bookie Herod se afla o bucata umeda de pergament, care descrie rutina zilnica a lui...",kw={"Doren","Herod","bilet mazgalit","Rebel Camp","spion","Stranglethorn","lada de valori","Thorsen","tradator"},ang={["faction:Alliance"]="Demascarea unui informator din Stranglethorn Vale protejeaza pozitia precara pe care rebelii din Alliance o mentin impotriva amenintarilor locale."},sec={{t="Un tradator printre randuri",b="In lada incuiata nu se gasesc doar obiecte de valoare, ci si un itinerar care urmareste deplasarile Private Thorsen. Scrisul abia lizibil ii descrie traseele de patrulare, insotitorii si activitatile zilnice din jurul Rebel Camp, fiind semnat doar cu -M. Observatiile atat de detaliate nu puteau proveni decat de la cineva care traieste alaturi de Thorsen, ceea ce indica existenta unui tradator in tabara rebelilor."},{t="Raportarea catre Doren",b="Ducand pergamentul umed inapoi la Rebel Camp, ii dezvalui adevarul lui Lieutenant Doren. Cu biletul semnat cu initiale in mana, comandantul are acum dovezile necesare pentru a-l cauta pe infiltratul care actioneaza chiar in perimetrul lor."}},faq={{q="Ce scrie pe biletul plin de noroi?",a="Biletul contine itinerarul activitatilor zilnice ale soldatului Thorsen. Prezinta locurile in care patruleaza, oamenii cu care vorbeste si modul in care isi petrece orele in tabara, incheindu-se cu o singura litera -M.",al={"textul biletului murdar","ce scrie pe bilet","detaliile biletului spionului"}},{q="De unde provine acest bilet?",a="Biletul este descoperit in cufarul incuiat al lui Bookie Herod, printre celelalte lucruri din lada.",al={"unde gasesc muddy note","inceperea misiunii spy revealed","cum incep spy revealed"}},{q="Cine primeste biletul?",a="Biletul trebuie dus la Lieutenant Doren, in Rebel Camp, in nordul Stranglethorn Vale.",al={"cui predau muddy note","unde duc nota","predare lieutenant doren"}},{q="Ce urmeaza dupa predarea biletului?",a="Dupa acest raport, ancheta Lieutenant Doren continua cu Patrol Schedules.",al={"ce misiune urmeaza","urmatorul pas dupa ce spionul a fost demascat","dupa ce spionul a fost demascat"}}},fp="17,300,22.373.0,18.227.1,34.205.0,30.116.0,22.96.0,41.88.0"}
P.entries["quest:33"] = {n="Wolves Across the Border",s="Eagan Peltskinner iti cere sa vanezi lupii care dau tarcoale prin Northshire Valley si sa-i aduci carnea lor. Te asteapta in afara Northshire Abbey, unde nevoile vaii continua sa fie importante, desi garzile se concentreaza asupra banditilor Defias.",h="Eagan Peltskinner iti cere sa vanezi lupii care dau tarcoale prin Northshire Valley si sa-i aduci carnea lor.",kw={"abatie","eagan","elwynn","carne","northshire","jupuitor","lup de padure","lupi"},ang={["profession:Cooking"]="Ca bucatar, inveti un adevar al tinuturilor de la pofta lui Eagan pentru friptura de lup: vanatul poate fi adesea gatit si mancat.",["race:Human"]="Ca recruta human in Northshire, aceasta este una dintre primele modalitati concrete prin care poti contribui la securizarea granitelor din apropierea Stormwind."},sec={{t="O cerere pragmatica",b="Eagan Peltskinner asteapta langa zidurile Northshire Abbey, cu o ranchiuna impotriva lupilor de padure din zona. Marshal McBride si garzile Stormwind au forte limitate pentru a apara abatia de banditii Defias, in timp ce mestesugarii au in continuare nevoi zilnice. Eagan iti cere sa raresti lupii si sa-i aduci carnea lor tare pentru gatit."},{t="Salbaticia din Northshire",b="Lupii se apropie tot mai mult de Northshire Abbey, pe masura ce patrulele slabesc. Kingdom of Stormwind are prea putine trupe si sufera din cauza lipsei conducerii. Lupii tineri si cei de padure dau acum tarcoale cararilor si livezilor abatiei. Vanarea lor umple camara lui Eagan si face potecile din apropiere mai sigure pentru novici, muncitori si aparatorii nou-sositi."}},faq={{q="Cine este Eagan Peltskinner?",a="Eagan Peltskinner este un vanator si negustor aflat langa intrarea in Northshire Abbey. Nu-i plac lupii de padure din zona si se bucura sa le gateasca si sa le manance carnea.",al={"cine este Eagan","jupuitorul","Eagan Peltskinner"}},{q="De ce vrea Eagan carne de lup?",a="Eagan se bucura sa manance fripturi de lup. Le ofera echipament de inceput util si bani recrutilor care ii aduc carne proaspata.",al={"de ce carne de lup","eagan e flamand","ce face eagan cu carnea"}},{q="Unde se afla lupii?",a="Lupi de padure si lupi tineri cutreiera campurile, dealurile si malurile raurilor din Northshire Valley, mai ales la sud si est de abatie.",al={"unde sunt lupii","locatiile lupilor","gaseste lupii"}},{q="De ce sunt lupii o problema in Northshire?",a="Patrulele reduse si banditii Defias au lasat drumurile si fermele din Northshire expuse fiarelor salbatice, facand calatoriile fara escorta periculoase pentru clerici si lucratori.",al={"de ce ataca lupii","problema lupilor din Northshire"}},{q="Trebuie sa vorbesc cu cineva inainte de a accepta aceasta misiune?",a="Nu. Deputy Willem ii poate trimite pe nou-veniti la Eagan pentru o treaba de initiere, dar Eagan le ofera vanatoarea direct tuturor celor care il abordeaza in afara manastirii.",al={"cerinte preliminare ale misiunii","cerinte preliminare","cine ofera aceasta misiune"}},{q="Se foloseste carnea tare de lup in retete culinare?",a="Eagan planuieste sa gateasca el insusi carnea. Bucatarii incepatori afla adesea ca, in Elwynn Forest, carnea de lup este un ingredient de baza pentru gatitul in aer liber.",al={"gatirea carnii tari de lup","pot jucatorii sa gateasca carne de lup"}}},fx={["12d6ae41"]={q="La ce serveste Tough Wolf Meat?",a="Eagan Peltskinner vrea sa-l gateasca si sa faca fripturi de lup pentru el insusi. Desi detesta bestiile care bantuie prin vale, a ajuns sa le aprecieze carnea si schimba cu placere echipamente folositoare cu oricine este dispus sa-i aprovizioneze masa.",al={"la ce foloseste carnea tare de lup","de ce carne tare de lup","utilizarea carnii tari de lup"}},acd05579={q="De ce dau tarcoale lupii prin Northshire?",a="Lupii tineri si lupii de padure pandesc in mod firesc la marginile impadurite si pe pajistile deschise din Northshire Valley. Totusi, cum garzile locale din Stormwind sunt preocupate de amenintarea tot mai mare a Defias Brotherhood, pradatorii se apropie nestingheriti de terenurile manastirii.",al={"de ce sunt lupi aici","lupii Timber din Northshire","lupi in Northshire"}}},fp="24,212,19.339.0,19.339.0,25.159.0,30.109.0,29.128.0,39.155.0,53.160.0,44.149.0"}
P.entries["quest:330"] = {n="Patrol Schedules",s="Dupa descoperirea unui mesaj incriminator semnat doar cu o initiala, Lieutenant Doren incearca sa-l identifice pe tradatorul din Rebel Camp. Comparand listele de serviciu, registrele pot dezvalui cine a impartit traseele de patrulare cu Private Thorsen in saptamana precedenta.",h="Dupa descoperirea unui mesaj incriminator semnat doar cu o initiala, Lieutenant Doren incearca sa-l...",kw={"corporal sethman","kurzen","lieutenant doren","programe de patrulare","private thorsen","rebel camp","stranglethorn vale"},sec={{t="Un indiciu in registre",b="Nota recuperata poarta doar initiala M, care nu prea ajuta la identificarea conspiratorului ce sprijina fortele lui Kurzen. Autorul mentioneaza insa ca, in saptamana precedenta, a impartit in mod regulat traseele de serviciu cu Private Thorsen. Lieutenant Doren iti cere sa traversezi Rebel Camp si sa vorbesti cu Corporal Sethman, soldatul care tine evidenta serviciilor, pentru a afla cine a patrulat alaturi de Thorsen."},{t="Ce dezvaluie documentele",b="Verificarea registrelor oficiale confirma ca Private Merle a fost repartizat exact la aceleasi ore si pe aceleasi trasee ca Thorsen pe tot parcursul saptamanii precedente. Descoperirea il demasca pe Merle drept informatorul care le furnizeaza informatii oamenilor lui Kurzen. Odata identificat, tradatorul fuge din tabara spre granita nordica cu Duskwood."}},faq={{q="De ce te trimite Lieutenant Doren la Corporal Sethman?",a="Corporal Sethman se ocupa de registrele de serviciu si de programarile de la Rebel Camp. Intrucat biletul recuperat mentioneaza patrule regulate facute impreuna cu Private Thorsen, registrele lui Sethman pot dezvalui cine era desemnat sa patruleze alaturi de el.",al={"de ce sa vorbesti cu Sethman","rolul lui corporal Sethman","orarul patrulelor lui Sethman"}},{q="Ce indiciu se gaseste in biletul recuperat?",a="Mesajul este semnat cu o singura litera, M, si mentioneaza explicit ca autorul sau a urmat aceleasi trasee de serviciu ca Private Thorsen in saptamana anterioara.",al={"indiciu din bilet","indiciu din scrisoare","cine a semnat biletul"}},{q="Unde are loc aceasta investigatie?",a="Aceasta investigatie se desfasoara in intregime in Rebel Camp, in nordul Stranglethorn Vale, facand naveta intre Lieutenant Doren si Corporal Sethman.",al={"unde se afla programele patrulelor","locatia programelor patrulelor"}},{q="Ce eveniment a precedat aceasta investigatie?",a="In The Spy Revealed! i-ai adus locotenentului Doren biletul plin de noroi, gasit printre lucrurile de valoare ale lui Bookie Herod, semnat doar cu o initiala.",al={"misiunea anterioara","ce a dus la programul patrulelor"}}},fp="16,279,21.417.0,21.337.1,55.225.0,41.158.0,35.148.0,33.131.0"}
P.entries["quest:3301"] = {n="Mura Runetotem"}
P.entries["quest:331"] = {n="Report to Doren",s="Dupa ce obtine informatiile despre patrula, Corporal Sethman te trimite inapoi la Lieutenant Doren. Predarea acestor informatii aduce informatii militare cruciale direct comandantului rebelilor din nordul Stranglethorn Vale.",h="Dupa ce obtine informatiile despre patrula, Corporal Sethman te trimite inapoi la Lieutenant Doren.",kw={"doren","kurzen","programele patrulelor","sethman","stranglethorn"},sec={{t="Predarea informatiilor",b="Corporal Sethman iti aminteste ca Lieutenant Doren vrea un raport direct despre informatiile privind patrula. Trebuie sa-i duci lui Doren ce ai aflat."},{t="Un tradator demascat",b="Informatiile despre patrule dezvaluie ca Merle a fost cel care a tradat tabara. Lieutenant Doren deplange pierderea unui soldat pe care il credea candva curajos si loial, dar simte si o usurare imensa ca l-a demascat pe tradator inainte ca Colonel Kurzen sa poata profita de situatie."}},faq={{q="Cine te trimite la Lieutenant Doren?",a="Corporal Sethman iti cere sa te prezinti la Lieutenant Doren dupa ce parcurgeti impreuna programul patrulelor.",al={"cine incepe report to doren","cine ma trimite la doren","cine da misiunea report to doren"}},{q="Ce a precedat acest raport?",a="Urmeaza dupa Patrol Schedules, unde Corporal Sethman trece in revista programele patrulelor pentru tine.",al={"misiunea anterioara","ce urmeaza inainte de Report to Doren","programele de patrulare"}},{q="Unde este predat acest raport?",a="Predai raportul direct locotenentului Doren, la Rebel Camp, in nordul Stranglethorn Vale.",al={"unde se afla Lieutenant Doren","locatia lui Doren","unde ma duc"}}},fp="15,223,27.146.0,18.265.1,34.111.0,29.96.0,31.101.0"}
P.entries["quest:332"] = {n="Wine Shop Advert",s="In Stormwind, Renato Gallina ii atrage pe trecatori la pravalia de vinuri a familiei sale. Ofera un bon pentru o sticla gratuita de vin vechi de la magazinul lor de pe canal, un mic semn al comertului din capitala reconstruita.",h="In Stormwind, Renato Gallina ii atrage pe trecatori la pravalia de vinuri a familiei sale.",kw={"canale","gallina winery","pinot noir","renato gallina","suzetta gallina","cartierul comercial","wine shop advert","tichet pentru vin"},ang={["faction:Alliance"]="Chiar si in vremuri tulburi, cu regi disparuti si razboi in desfasurare, Trade District din Stormwind pastreaza o piata animata pentru bunuri de lux locale si marfuri importate.",["profession:Cooking"]="Pinot noir-ul familiei Gallina merge bine cu mesele consistente pregatite in tavernele din Eastern Kingdoms.",["race:Human"]="Ca Human care isi reface viata in Stormwind, s-ar putea sa gasesti reconfortant semnul renasterii orasului reprezentat de cramele de familie de-a lungul canalelor."},sec={{t="Gustul canalelor",b="Viata de zi cu zi din Stormwind se invarte in jurul comertului intens. Renato Gallina strabate strazile pavate din Trade District, facand reclama la Gallina Winery, micul magazin pe care il conduce impreuna cu sora lui, Suzetta. Imparte fluturasi calatorilor insetati si localnicilor, fiecare oferind o degustare gratuita."},{t="Recolta de Pinot Noir",b="Familia Gallina iti ofera o sticla din faimosul sau pinot noir. Urmeaza tichetul pana la intrarea in crama, langa canale, unde Suzetta Gallina iti da sticla. Familia spera ca gustul vinului ei reprezentativ sa-i faca pe nou-veniti sa revina."}},faq={{q="Unde se afla Gallina Winery?",a="Gallina Winery se afla in Trade District din Stormwind City, de-a lungul canalelor, aproape de traseul lui Renato Gallina.",al={"unde se afla Gallina Winery","locatia lui Suzetta Gallina","unde se preda Wine Shop Advert"}},{q="Cine sunt Renato si Suzetta Gallina?",a="Renato si Suzetta Gallina sunt frati si surori care conduc un magazin de vinuri in Stormwind. Renato il promoveaza cu fluturasi, in timp ce Suzetta se ocupa de magazin si serveste vinul.",al={"cine sunt Gallina","Renato Gallina","povestea lui Suzetta Gallina"}},{q="Ce vin obtii cu biletul?",a="Biletul iti aduce o sticla din celebrul pinot noir al familiei Gallina, vinul rosu emblematic al acesteia.",al={"vin pinot noir","ce vin primesti","pinot noir stormwind"}},{q="De ce imparte Renato bilete gratuite la vin?",a="Renato ofera bilete gratuite la vin pentru a atrage clientii in magazinul de langa canal si a-i incuraja sa revina.",al={"de ce vin gratuit","scopul tichetului de la magazinul de vinuri"}},{q="Presupune aceasta treaba vreun pericol sau vreo lupta?",a="Nu. Iei un tichet promotional de la Renato si strabati o distanta scurta pe strazile sigure din Trade District pana la magazinul lui Suzetta.",al={"este Wine Shop Advert periculos","lupte in misiunea cu vinul"}},{q="Vinde Gallina Winery si alte marfuri?",a="Suzetta vinde vinuri obisnuite si alte bauturi alcoolice pentru calatori, garzi aflate in pauza si furnizorii tavernelor locale.",al={"ce mai vinde suzetta","bauturi de la gallina winery"}}},fp="16,211,21.271.0,22.241.0,36.99.0,35.155.0,31.87.0,43.107.0,46.148.0,41.116.0"}
P.entries["quest:333"] = {n="Harlan Needs a Resupply",s="Harlan Bagley, un negustor din Stormwind, nu reuseste sa tina pe stoc haine si armuri rezistente. Pe masura ce cererea creste brusc, trimite o comanda urgenta de panza catre Rema Schneider, de la Canal Tailor and Fit Shop, fara sa stie de conflictele care se pregatesc dincolo de zidurile orasului.",h="Harlan Bagley, un negustor din Stormwind, nu reuseste sa tina pe stoc haine si armuri rezistente.",kw={"bagley","canal","stofa","harlan","rema","reaprovizionare","croitor","stormwind"},ang={["faction:Alliance"]="Cumparatorii din Stormwind devin tot mai nelinistiti in inima Alliance, in absenta regelui Varian Wrynn.",["profession:Tailoring"]="Atelierele de pe canalele din Stormwind aprovizioneaza magazinele mai mari, dezvaluind mersul de zi cu zi al comertului cu textile din oras.",["race:Human"]="Mestesugarii care lucreaza in Stormwind nu au incredere in conducatorii lor si banuiesc ca nobilimea tine oamenii de rand in necunostinta de cauza in privinta pericolelor care se apropie."},sec={{t="Cerere mare de haine rezistente",b="Prin tot Stormwind City, rafturile lui Harlan Bagley se golesc repede. Cetatenii si aventurierii ratacitori cumpara tunici intarite, haine de calatorie si armuri gata de lupta. Harlan se intreaba daca oamenii se pregatesc pentru un anotimp aspru sau pentru iarna, dar graba a lasat magazinul sau fara suficiente tesaturi finisate."},{t="Intrebari despre Canals",b="Pentru a-si umple din nou rafturile, Bagley trimite un alergator peste canalele orasului la Rema Schneider, croitoreasa care conduce Canal Tailor and Fit Shop. Desi Rema este recunoscatoare pentru comenzile continue, navala brusca pe echipamentul de protectie i se pare nelinistitoare. In regat circula zvonuri despre tensiuni, iar croitoreasa nu se poate abtine sa nu se intrebe daca House of Nobles, care conduce Stormwind, le ascunde oamenilor de rand zvonurile despre un razboi deschis."}},faq={{q="Cine este Harlan Bagley?",a="Harlan Bagley este croitor si negustor in Stormwind City. Croitorii locali ii furnizeaza articolele tricotate si hainele potrivite pentru calatorii pe care le vinde.",al={"Harlan Bagley","cine este Harlan","Bagley din Stormwind"}},{q="Cine este Rema Schneider?",a="Rema Schneider este croitoreasa si confectionera profesionista la Canal Tailor and Fit Shop din Stormwind. Impreuna cu sotul ei, Corbett, furnizeaza negustorilor din oras tesaturi si haine proaspat cusute.",al={"rema schneider","croitoreasa Rema","Canal Tailor"}},{q="De ce ramane Harlan fara haine?",a="Cetatenii si calatorii cumpara armuri si haine rezistente in numar neobisnuit de mare. Harlan glumeste ca par sa se astepte la o iarna grea, desi adevarata cauza este tulburarea si pericolul tot mai mare de-a lungul granitelor regatului.",al={"de ce nu mai este stofa","de ce se cumpara armuri","afacerea lui harlan prospera"}},{q="De ce ii suspecteaza Rema Schneider pe nobili?",a="Rema considera ciudat faptul ca oamenii de rand se pregatesc brusc de lupta fara o declaratie oficiala de razboi. House of Nobles controleaza treburile regale in absenta regelui Varian Wrynn, iar ea se teme ca nobilii ascund publicului un razboi iminent.",al={"nobili Rema","nobilii din Stormwind ascund razboiul","de ce sunt nobilii suspecti"}},{q="Unde se afla Canal Tailor and Fit Shop?",a="Canal Tailor and Fit Shop se afla de-a lungul canalelor care strabat Stormwind City, intre principalele cartiere ale orasului, pentru livrari convenabile catre negustori.",al={"locatia Canal Tailor","unde este Rema Schneider","unde este croitorul Canal Tailor"}},{q="Ce se intampla dupa ce este livrata cererea de panza?",a="Dupa ce Rema primeste comanda, isi roaga sotul, Corbett Schneider, sa duca o alta incarcatura de tricotaje prin oras, pana la Harlan, la Lionheart Armory. In drum spre magazin, Corbett se opreste la Trias' Cheese pentru o gustare.",al={"plimbarea lui Corbett Schneider","cu ce se ocupa Corbett","sotul Remei"}}},fp="23,240,23.298.0,23.341.0,21.135.0,22.205.0,38.221.0,43.273.0,47.154.0,50.232.0"}
P.entries["quest:334"] = {n="Package for Thurman",s="In Stormwind City, Rema Schneider are nevoie de materialele de croitorie ale fiului ei Thurman, aflate la Larson Clothiers din Mage Quarter. El a plecat de acasa fara foarfeca si ace, iar Rema te roaga sa i le duci la atelier.",h="In Stormwind City, Rema Schneider are nevoie de materialele de croitorie ale fiului ei Thurman, aflate la...",kw={"ucenic","croitori","larson","Mage Quarter","rema","schneider","trusa de cusut","Stormwind","thurman"},ang={["faction:Alliance"]="Cetatenii si mesterii de rand din Stormwind se ingrijesc ca in capitala sa existe haine, hrana si bunuri necesare, cate o treaba pe rand.",["profession:Tailoring"]="Orice croitor de seama incepe de jos, cosand cusaturi si tinand ace. La Larson Clothiers, chiar si un ucenic poate dori sa scape de treburi."},sec={{t="O insarcinare de la o mama",b="Rema Schneider se teme ca Thurman va ramane in urma cu lucrul la croitorie fara foarfeca si acele sale. El a plecat de acasa in graba, iar mama lui te roaga sa duci uneltele peste canalele din Stormwind pana la atelierul lui."},{t="Un ucenic reticent",b="Larson Clothiers se afla in Mage Quarter, langa Mage Tower. Cand Thurman isi primeste uneltele, recunoaste ca le-a lasat intentionat in urma ca sa scape de treburile zilnice si sa se distreze. Interventia lui Rema ii incheie dupa-amiaza libera, iar el se intoarce la cusut."}},faq={{q="Cine da startul misiunii Package for Thurman?",a="Rema Schneider iti cere sa duci o trusa de cusut fiului ei, care lucreaza in Mage Quarter.",al={"cine ofera misiunea","misiunea lui Rema Schneider","cel care ofera misiunea"}},{q="Unde poate fi gasit Thurman Schneider?",a="Thurman Schneider lucreaza in Larson Clothiers din Mage Quarter al Stormwind, aproape de drumul spre Mage Tower.",al={"locatia lui Thurman","unde este Thurman","gaseste-l pe Thurman"}},{q="Chiar si-a uitat Thurman uneltele din greseala?",a="Rema crede ca Thurman a plecat in graba fara echipamentul sau si iti cere sa i-l duci.",al={"a uitat Thurman","de ce a lasat Thurman uneltele","leneveala lui Thurman"}},{q="La ce magazin isi face Thurman ucenicia?",a="Thurman este ucenic croitor la Larson Clothiers, un magazin de haine din Mage Quarter al Stormwind, administrat de familia Larson.",al={"unde lucreaza thurman","larson clothiers","pentru cine lucreaza thurman"}},{q="De ce ii cere Rema Schneider ajutor unui aventurier?",a="Rema crede ca ucenicia lui Thurman este in pericol fara trusa lui. Neputand sa-si abandoneze propriile indatoriri, le cere ajutorul calatorilor care se indreapta spre Mage Quarter.",al={"de ce sa intrebi jucatorul","ajutor pentru rema"}},{q="Ce se intampla dupa ce predai trusa de cusut?",a="Thurman isi ia trusa si se intoarce sa-i ajute pe Larsoni cu cusutul.",al={"recompensa misiunii","dupa Package for Thurman","reactia lui thurman"}}},fx={["3c7bea70"]={q="De ce vrea Rema Schneider ca aceasta treaba sa fie facuta?",a="Rema se gandeste la viitorul fiului ei, Thurman. Acesta a obtinut un loc de ucenic la Larson Clothiers, in Mage Quarter, dar a plecat in graba fara foarfece si ace. Fara unelte, Thurman nu-si poate indeplini indatoririle si nici invata meseria, riscandu-si pozitia in fata patronilor. Crezand ca a fost un accident sincer, Rema vrea ca trusa lui sa-i fie adusa de indata, pentru ca pregatirea sa nu aiba de suferit.",al={"de ce trebuie livrat setul de cusut pentru rema","motivul rema schneider","de ce trebuie duse uneltele la thurman"}}},fp="19,213,17.218.0,22.263.1,41.88.0,37.111.0,50.82.1,38.123.0,51.169.0,46.75.1"}
P.entries["quest:335"] = {n="A Noble Brew",s="Zardeth of the Black Claw comploteaza impotriva nobililor din Stormwind din ascunzatoarea de sub Slaughtered Lamb. Cererea lui Lord Wishock de a deschide o investigatie pune in pericol covenul ascuns de Warlock.",h="Zardeth of the Black Claw comploteaza impotriva nobililor din Stormwind din ascunzatoarea de sub Slaughtered...",kw={"darkshire","house of nobles","bizam","slaughtered lamb","stonewrought dam","tilloa","wishock","zardeth"},ang={["class:Warlock"]="Ca Warlock, criptele de sub Slaughtered Lamb sunt refugiul tau sigur din Stormwind. Ajutandu-l pe Zardeth, iti aperi fratii si surorile in artele intunecate de a fi descoperiti de nobilimea pioasa a regatului.",["faction:Alliance"]="Cat timp regele Varian Wrynn ramane disparut, manevrele politice din House of Nobles au atins un nivel fara precedent. Din acest motiv, scandalurile din oras reprezinta un pericol deosebit pentru stabilitatea sa.",["profession:Herbalism"]="Ca herbalist, stii ca Tear of Tilloa si Musquash Root sunt plante rare, care cresc doar in regiuni marcate de o istorie crunta sau de torente cu ape pure."},sec={{t="Amenintarea nobilimii",b="Sub strazile din Mage Quarter, warlock-ii se aduna la Slaughtered Lamb si isi tin ascunsa adunarea. Lord Wishock, membru al House of Nobles, a aflat de magia neagra de sub oras. Isi indeamna semenii sa lanseze o ancheta amanuntita, ceea ce ar putea atrage asupra adunarii garzile orasului si atentia regelui."},{t="O licoare in umbra",b="Pentru a evita o confruntare deschisa cu clasa conducatoare din Stormwind, Zardeth of the Black Claw cauta o solutie discreta care sa-l tina ocupat pe Lord Wishock. Licoarea necesita plante rare din tinuturi indepartate ale Eastern Kingdoms: palida Tear of Tilloa din Duskwood si o Musquash Root culeasa sub apa, sub Stonewrought Dam."}},faq={{q="Cine este Lord Wishock?",a="Lord Wishock este un nobil din House of Nobles, in Stormwind. Dupa ce a auzit aluzii la activitati de warlock sub Mage Quarter, a inceput sa faca presiuni asupra consiliului pentru deschiderea unei anchete oficiale.",al={"wishock","lord wishock","cine este wishock"}},{q="Cine este Zardeth of the Black Claw?",a="Zardeth este un warlock de rang inalt in criptele de sub Slaughtered Lamb din Stormwind. El incearca sa ascunda de autoritati cabala warlockilor din oras, pentru a o feri de descoperire si epurare.",al={"Zardeth","Zardeth Black Claw","cine este Zardeth"}},{q="De unde provine Tear of Tilloa?",a="Tear of Tilloa este o floare alba delicata, care creste in Gradina napadita de vegetatie a lui Stalvan, la marginea Darkshire, in Duskwood.",al={"locatia Tear of Tilloa","Tear of Tilloa","unde se afla Tear of Tilloa"}},{q="Unde se gaseste Musquash Root?",a="Musquash Root creste doar in zonele umede de la baza cascadelor uriase de sub Stonewrought Dam, in Wetlands.",al={"locatia Musquash Root","Musquash Root","de unde obtii Musquash Root"}},{q="De ce guvernul din Stormwind nu stie deja despre warlocki?",a="Warlockii sunt priviti cu profunda neincredere in Stormwind, asa ca templul lor de sub Slaughtered Lamb isi ascunde practicile in subteran, departe de garzile si nobilii orasului. Lord Wishock abia a aflat de existenta lui.",al={"secretul Warlock din Stormwind","de ce se ascund Warlock","sunt Warlock ilegali"}},{q="Ce intentioneaza Zardeth sa prepare cu acesti reactivi?",a="Zardeth sustine ca licoarea il va tine pe Lord Wishock 'ocupat', astfel incat ancheta sa se impotmoleasca. Ce anume are de gand cu nobilul devine limpede abia dupa ce licoarea este gata.",al={"ce este bautura","scopul bauturii nobile","de ce se prepara bautura"}}},fx={e620a973={q="De ce vrea Zardeth of the Black Claw ca acest lucru sa fie facut?",a="Lord Wishock a descoperit covenul clandestin de Warlock care activeaza sub Slaughtered Lamb, in Mage Quarter din Stormwind. In timp ce Wishock mobilizeaza activ House of Nobles pentru a lansa o ancheta oficiala asupra prezentei lor, Zardeth are nevoie de o licoare care sa-l tina ocupat pe nobilul bagacios, inainte ca autoritatile orasului sa reprime practicile lor intunecate.",al={"de ce sa-l ajut pe zardeth","motivul lui zardeth","de ce vrea zardeth o bautura nobila"}},["9e466bd7"]={q="La ce foloseste Tear of Tilloa?",a="Tear of Tilloa este o floare alba si delicata, culeasa din Garden of Stalvan, langa Darkshire. Zardeth are nevoie de ea ca ingredient principal pentru o potiune speciala, menita sa zadarniceasca lupta politica a lui Lord Wishock impotriva covenului.",al={"la ce foloseste Tear of Tilloa","scopul lui Tear of Tilloa","de ce ai nevoie de Tear of Tilloa"}},["84ab02b5"]={q="La ce foloseste Musquash Root?",a="Musquash Root creste la baza cascadelor invaluita in ceata, sub Stonewrought Dam, in Wetlands. Zardeth ii foloseste proprietatile puternice, impreuna cu Tear of Tilloa, pentru a prepara o licoare destul de tare incat sa-l distraga pe lordul Wishock.",al={"la ce foloseste Musquash Root","scopul lui Musquash Root","de ce e nevoie de Musquash Root"}},["256dc9f2"]={q="De ce are Zardeth nevoie de un aventurier in loc sa-si procure singur ingredientele?",a="Zardeth si ceilalti warlocki trebuie sa ramana ascunsi sub Slaughtered Lamb. Daca isi parasesc sanctuarul, risca sa atraga imediat atentia garzii orasului si a House of Nobles, mai ales cat timp Lord Wishock cere in mod activ o investigatie.",al={"de ce eu pentru o bautura nobila","de ce are zardeth nevoie de mine","de ce nu poate zardeth sa obtina reactivii"}}},fp="12,175,24.319.0,27.315.1,20.186.0,33.170.0,40.130.0,33.133.0,67.202.0,53.158.1"}
P.entries["quest:336"] = {n="A Noble Brew",s="In Stormwind, un curier ii duce Black Claw Stout lui Lord Baurles K. Wishock, in Royal Keep. Zardeth of the Black Claw a aranjat livrarea din pivnita de sub Slaughtered Lamb.",h="In Stormwind, un curier ii duce Black Claw Stout lui Lord Baurles K.",kw={"baurles wishock","black claw stout","hall of petitioners","bere nobila","slaughtered lamb","stormwind keep","zardeth"},sec={{t="Un nobil ipocrit",b="Lord Baurles K. Wishock isi petrece timpul in Hall of Petitioners din Stormwind Keep, vorbind despre propria importanta si viitorul regatului. Clientii de la Slaughtered Lamb cunosc o alta latura a sa. Noaptea, bea in salile de sus ale hanului si lasa note mari neplatite. Ziua, cere inchiderea hanului."},{t="Un toast fatal",b="Zardeth of the Black Claw prepara Black Claw Stout sub Slaughtered Lamb, ca sa stinga definitiv datoria lui Wishock. Spune ca bautura are ceva tarie. In Hall of Petitioners, Wishock il ia pe curier drept servitor si-i arunca o moneda de arama. Bea cu lacomie stout-ul, apoi se prabuseste mort pe culoarele fortaretei."}},faq={{q="Cine este Zardeth of the Black Claw?",a="Zardeth of the Black Claw este un warlock care are o cabala secreta in catacombele de sub Slaughtered Lamb, in Mage Quarter din Stormwind. Desfasoara operatiuni primejdioase si clandestine, ferite de privirile garzii orasului.",al={"cine este Zardeth","Zardeth of the Black Claw","cine ofera misiunea"}},{q="De ce il vizeaza Zardeth pe Lord Wishock?",a="Wishock bea noaptea la etajele superioare ale Slaughtered Lamb fara sa-si achite consumatia, apoi isi petrece zilele in Hall of Petitioners, cerandu-le autoritatilor sa inchida hanul.",al={"de ce sa-l omori pe Wishock","motivul lui Wishock","de ce a fost otravit"}},{q="Unde poate fi gasit Lord Wishock?",a="Lord Baurles K. Wishock se afla in Hall of Petitioners, o anticamera din Stormwind Keep unde nobilii si cetatenii se aduna pentru a face petitii regentei tinutului.",al={"locatia lordului wishock","unde se afla wishock","wishock din hall of petitioners"}},{q="Cum primeste Lord Wishock bautura?",a="Wishock il ia pe curier drept servitor, bea berea bruna racoritoare si il expediaza cu o moneda de cupru.",al={"moare Wishock","moartea lui Wishock","ce face berea tare"}},{q="Atrage livrarea berii atentia garzilor?",a="Livrarea pare sa fie facuta de un slujitor obisnuit care aduce o bautura, iar curierul isi poate continua drumul fara sa se confrunte cu garzile.",al={"ataca garzile","sunt cautat in Stormwind","consecintele otravirii"}},{q="Ce misiune urmeaza dupa aceasta livrare?",a="Dupa livrare urmeaza 'You Have Served Us Well', care te trimite inapoi la Zardeth, sub Slaughtered Lamb.",al={"ce urmeaza","dupa A Noble Brew","misiunea urmatoare"}}},fx={["46bddf0f"]={q="Cine este Lord Wishock si de ce este tinta?",a="Lord Baurles K. Wishock este un nobil din Stormwind plin de sine, care zaboveste in Hall of Petitioners pentru a adresa petitii curtii regale. Desi se considera esential pentru viitorul regatului, isi petrece noptile band la etaj in Slaughtered Lamb, acumuland note de plata uriase pe care refuza sa le achite, in timp ce face campanie activa pentru inchiderea localului. Zardeth il ia in vizor pentru a-i opri amestecul si a-si recupera datoriile neplatite.",al={"cine este lord wishock","de ce sa-l omori pe wishock","cine este wishock","lord wishock"}},c4eeba5d={q="De ce are nevoie Zardeth sa livrezi berea bruna in loc sa o duca el?",a="Zardeth si ceilalti vrajitori ai sai isi desfasoara activitatea in secret, in criptele de sub Slaughtered Lamb, in inima orasului Stormwind. Daca s-ar infatisa in persoana inaintea nobililor si a garzilor orasului, in Stormwind Keep, ar atrage imediat atentia si ar fi arestati, mai ales ca Lord Wishock stie deja de stabilimentul lui Zardeth. Trimitand un aventurier care nu atrage atentia, livrarea pare sa fie doar a unui servitor obisnuit care aduce racoritoare, tinand planul lui Zardeth ascuns.",al={"de ce are zardeth nevoie de mine","de ce sa duc bautura","de ce nu i-o poate da zardeth"}}},fp="12,192,17.330.0,14.332.1,33.208.0,37.185.1,28.158.0,39.121.1,56.131.1,33.116.1"}
P.entries["quest:3361"] = {n="A Refugee's Quandary",s="Dupa caderea dezastruoasa a Gnomeregan in mainile troggilor si ale radiatiilor, gnomii stramutati au fugit in tinuturile salbatice, inzapezite, din Dun Morogh. In afara Anvilmar, un inginer pe nume Felix Whindlebolt si-a pierdut lucrurile si uneltele esentiale, furate de scotocitorii troli Frostmane in timpul evacuarii precipitate.",h="Dupa caderea dezastruoasa a Gnomeregan in mainile troggilor si ale radiatiilor, gnomii stramutati au fugit in...",kw={"Anvilmar","galeata cu suruburi","Coldridge","Felix Whindlebolt","Frostmane","Gnomeregan","radiatii"},ang={["profession:Engineering"]="Niciun mestesugar care se respecta nu poate sta deoparte cand scotocitorii fura suruburi de precizie, sublere si truse de scule, lucruri a caror asamblare a durat o viata.",["race:Dwarf"]="Muntii Coldridge ti-au adapostit neamul vreme de secole; ajutandu-i pe refugiatii gnomi sa se stabileasca in Anvilmar, cinstesti alianta straveche dintre Ironforge si Gnomeregan.",["race:Gnome"]="Aceasta misiune intruchipeaza tragedia amara care iti loveste poporul: dupa ce si-a pierdut minunatul camin din cauza otravii si a tradarii, pana si mestesugarii de rand trebuie acum sa roage straini sa le recupereze uneltele de baza de la troli primitivi."},sec={{t="Fuga din Gnomeregan",b="Cand troggii subterani au cotropit orasul ultratehnologizat Gnomeregan, Marele Mester Gelbin Mekkatorque si sfetnicii sai au autorizat eliberarea unui gaz radioactiv, intr-o incercare disperata de a-i nimici pe invadatori. Planul a esuat catastrofal: mii de nevinovati au fost ucisi, supravietuitorii s-au transformat in gnomi leprosi lipsiti de minte, iar populatia ramasa a fost silita sa fuga in graba prin Dun Morogh."},{t="Necrofagi in zapada",b="Inginerii si mesterii care fugeau au luat cu ei uneltele si schitele pe care le puteau salva. Insa trecatorile montane inghetate dintre Gnomeregan si Coldridge Valley sunt strabatute de trolii Frostmane bastinasi. In timp ce Felix Whindlebolt se grabea spre adapostul din Anvilmar, jefuitorii Frostmane i-au furat lada cu unelte, cutia incuiata si galeata cu suruburi, ducandu-le in taberele lor de la sud-vest de oras."}},faq={{q="Cine este Felix Whindlebolt?",a="Felix Whindlebolt este un inginer gnom care a scapat ca prin minune de distrugerea radioactiva a Gnomereganului. Neavand indemanarea de lupta necesara pentru a infrunta pericolele din Dun Morogh, se adaposteste langa Anvilmar in timp ce incearca sa-si recupereze echipamentul furat.",al={"Felix Whindlebolt","cine este Felix","Felix Anvilmar"}},{q="De ce este Gnomeregan iradiat?",a="In timpul unei invazii neasteptate de trogg, autoritatile gnome au eliberat un gaz radioactiv volatil, menit sa nimiceasca monstrii. In schimb, gazul a contaminat sistemele de ventilatie ale orasului, ucigand sau transformand majoritatea locuitorilor si facand capitala de nelocuit.",al={"ce s-a intamplat cu Gnomeregan","radiatia din Gnomeregan","prabusirea Gnomereganului"}},{q="Cine a furat bunurile lui Felix?",a="Trollii Frostmane i-au luat cufarul, lada si galeata cu suruburi. Acesti trolli bastinasi ataca prin surprindere calatorii de-a lungul potecilor montane din Dun Morogh si duc inapoi in taberele lor primitive, aflate la sud-vest de Anvilmar, fier vechi si echipamente furate.",al={"cine a furat bolturile","cine are lucrurile lui felix","trolii frostmane"}},{q="Unde s-au refugiat gnomii stramutati?",a="Multi gnomi au fugit peste Dun Morogh spre regatul piticilor, Ironforge, in timp ce altii au cautat adapost temporar in asezari mai mici precum Anvilmar si Kharanos, tot in Dun Morogh.",al={"unde locuiesc gnomii","refugiati gnomi","asezare de gnomi"}},{q="De ce este atat de importanta o galeata de suruburi?",a="Pentru un gnom mester exilat, uneltele, suruburile speciale si bolturile prelucrate reprezinta intregul sau mijloc de trai. Fara echipamentul potrivit, inginerii refugiati nu-si pot practica meseria, nu pot construi apararea si nici nu-si pot recladi viata in exil.",al={"de ce suruburi","galeata de suruburi a lui felix"}},{q="Ce amenintare reprezinta trolii Frostmane pentru Coldridge Valley?",a="Frostmane tribe traieste de multa vreme pe piscurile aspre din Dun Morogh. Odata cu recentele izbucniri ale troggilor si haosul evacuarii Gnomeregan, trolls au devenit mai indrazneti, atacand liniile de aprovizionare si intinzand ambuscade calatorilor.",al={"trolls in Dun Morogh","amenintarea Frostmane","tabara Frostmane"}}},fx={["0b2d3aab"]={q="De ce vrea Felix Whindlebolt sa-si recupereze lucrurile?",a="Dupa ce a fugit din Gnomeregan, unde radiatiile otraveau totul, cu abia hainele de pe el, Felix si-a pierdut ultimele ramasite ale mijloacelor de trai si ale meseriei. Fara cufarul personal, lada si uneltele sale, este complet izolat in Anvilmar, fara vreo cale de a-si recladi viata ori de a-si practica meseria ca refugiat.",al={"motivul lui felix","de ce are felix nevoie de asta","lucrurile lui felix whindlebolt"}},["48f90e68"]={q="De ce nu-si poate recupera Felix singur lucrurile?",a="Felix este un mester in ale mecanismelor si un refugiat stramutat obisnuit, nu un aventurier sau soldat. Ingrozit de tinutul salbatic ostil si lipsit de orice sansa impotriva trolilor Frostmane care i-au luat echipamentul, el nu-si poate risca viata intr-o incursiune solitara in taberele lor.",al={"de ce nu-si ia Felix lucrurile","de ce are Felix nevoie de mine","Felix, de ce eu"}},["6a13a14f"]={q="Ce se afla in Felix's Box and Chest?",a="Lada si cufarul lui Felix contin bunurile personale si uneltele specializate pe care a reusit sa le impacheteze cand a fugit din calea dezastrului din Gnomeregan. Pentru un mestesugar stramutat, departe de casa, aceste recipiente adapostesc tot ce ii trebuie pentru a o lua de la capat.",al={"felix's box","cufarul lui Felix","ce se afla in cufarul lui Felix"}}},fp="20,283,26.396.0,22.399.0,25.243.0,29.266.0,29.221.0,43.182.0,42.237.0,61.221.0"}
P.entries["quest:3362"] = {n="Thistleshrub Valley",s="Tran'rek din Gadgetzan vrea sa intre in Thistleshrub Valley, dar fiarele ciudate de acolo il tin departe. Curata o parte dintre thistleshrubs, iar Tran'rek s-ar putea gandi sa se intoarca.",h="Tran'rek din Gadgetzan vrea sa intre in Thistleshrub Valley, dar fiarele ciudate de acolo il tin departe.",kw={"cactus","gadgetzan","gnarled thistleshrub","rootshaper","tanaris","thistleshrub","tran'rek","thistleshrub valley"},sec={{t="O vale primejdioasa",b="Thistleshrub Valley se afla la sud-vest de Gadgetzan, iar Tran'rek o numeste un loc extrem de periculos. Nu au incredere in fiarele ciudate de acolo, thistleshrub-urile noduroase si thistleshrub rootshaper-ii, si, fiindca sunt atat de multe, nu se vor mai intoarce."},{t="Rarirea Thistleshrub-urilor",b="Tran'rek vrea sa cureti zona de opt tufe de scai noduroase si de opt modelatoare de radacini de scai. Exista o conditie: Tran'rek vrea sa cerceteze de aproape cactusul din vale, asa ca o parte din el trebuie lasata intreaga."}},faq={{q="Cine cere ajutor pentru Thistleshrub Valley?",a="Tran'rek, care se afla in Gadgetzan.",al={"cel care ofera misiunea","locatia lui tran'rek","cine ofera thistleshrub valley"}},{q="Unde se afla Thistleshrub Valley?",a="Se afla la sud-vest de Gadgetzan.",al={"locatia Thistleshrub Valley","unde este valea","gaseste valea din tanaris"}},{q="De care creaturi trebuie sa scapi?",a="Opt thistleshrubs nodurosi si opt thistleshrub rootshapers.",al={"tinte","ce sa omori","care thistleshrubs"}},{q="De ce vrea Tran'rek ca o parte din cactus sa ramana intreaga?",a="Tran'rek vrea sa examineze mai indeaproape cactusul din vale, asa ca ar trebui sa lasi o parte din el intreaga.",al={"motivul lui tranrek","de ce sa mergi in vale","interesul fata de cactusi"}}},fp="19,185,18.240.0,26.213.0,43.30.0,29.32.0,34.63.0,60.108.0"}
P.entries["quest:3364"] = {n="Scalding Mornbrew Delivery"}
P.entries["quest:3365"] = {n="Bring Back the Mug"}
P.entries["quest:3367"] = {n="Suntara Stones",s="Dorius Stonetender este grav ranit in Searing Gorge, ametit, cu lumea invartindu-se si sangerand pe dinauntru. Spune ca trebuie sa se intoarca la Ironforge si te implora sa-l ajuti sa ajunga acolo.",h="Dorius Stonetender este grav ranit in Searing Gorge, ametit, cu lumea invartindu-se si sangerand pe dinauntru.",kw={"Dorius Stonetender","Ironforge","Searing Gorge","scrisoare arsa","Stonewrought Pass","pietrele Suntara"},sec={{t="Un apel dupa ajutor",b="Dorius geme, spunand ca este grav ranit. Simte ca ameteste, lumea se invarteste si are o hemoragie interna. Singura lui dorinta este sa se intoarca la Ironforge, iar el iti cere ajutorul pentru a face drumul."},{t="Drumul spre trecatoare",b="Drumul se termina chiar inainte de Stonewrought Pass. Acolo, Dorius este impuscat si moare, iar scrisoarea pe care o purta cade la pamant, parjolita."}},faq={{q="Cine este Dorius Stonetender?",a="Dorius Stonetender este grav ranit in Searing Gorge si are nevoie de ajutor pentru a se intoarce la Ironforge.",al={"cine este dorius","dorius stonetender","dwarf ranit din searing gorge"}},{q="Unde incearca sa ajunga Dorius?",a="Vrea sa se intoarca in Ironforge.",al={"destinatia lui Dorius","unde merge Dorius","locatia escortei lui Dorius"}},{q="In ce stare se afla Dorius?",a="Este grav ranit, ametit si are hemoragie interna; lumea se invarte in jurul lui.",al={"starea lui dorius","este dorius ranit","de ce are dorius nevoie de ajutor"}}},fp="14,188,15.204.0,20.135.1,26.94.0,29.34.0,28.95.0"}
P.entries["quest:3368"] = {n="Suntara Stones",s="O scrisoare parlita, scapata din mana lui Dorius, ii este adresata fratelui sau. Vorbeste despre pietrele Suntara, care exista cu adevarat si se afla in mainile Dark Irons, al caror conducator, Lathoric the Black, le foloseste puterea pentru a inrobi echipa de excavare a lui Dorius. Scrisoarea ii este destinata lui Thorius, de la Hall of Explorers din Ironforge, iar tu trebuie sa i-o duci.",h="O scrisoare parlita, scapata din mana lui Dorius, ii este adresata fratelui sau.",kw={"cazan","dorius","hall of explorers","ironforge","lathoric the black","obsidion","searing gorge","scrisoare parjolita","pietrele suntara","thorius"},sec={{t="Scrisoarea mortului",b="In scrisoare, Dorius ii scrie fratelui sau ca, daca o citeste, inseamna ca el a murit. Pietrele exista, iar Dark Irons le au. Conducatorul lor, Lathoric the Black, le foloseste puterea pentru a inrobi echipa de sapaturi a lui Dorius. Echipa a fost dusa la cazan, iar mintile membrilor sai sunt sucite in timp ce trudesc zi si noapte sa termine ceva numit Obsidion. Dorius isi implora fratele sa-i ajute, aceasta fiind ultima lui dorinta, si cere ca cei care aduc scrisoarea sa fie rasplatiti."},{t="Thorius afla vestea",b="Thorius suspina cand i se aduce scrisoarea. Apoi isi sterge fata si jura in numele Light ca dorinta lui Dorius va fi indeplinita."}},faq={{q="Cine a scris scrisoarea parlita?",a="Dorius i-a scris fratelui sau, ca un mesaj care sa fie citit dupa moartea lui.",al={"cine a scris scrisoarea","autorul scrisorii arse","scrisoarea lui dorius"}},{q="Unde locuieste Thorius?",a="Curator Thorius poate fi gasit in Hall of Explorers din Ironforge.",al={"unde este Thorius","locatia curatorului Thorius","Thorius in Hall of Explorers"}},{q="Ce s-a intamplat cu echipa de excavare a lui Dorius?",a="Scrisoarea spune ca Lathoric the Black si Dark Irons ii folosesc pietrele pentru a-i inrobi. Au fost dusi la cazan.",al={"ce s-a intamplat cu echipa de excavare","echipa de excavare a lui Dorius","mineri inrobiti, cazan"}},{q="La ce lucreaza echipa inrobita?",a="Scrisoarea spune ca mintile lor sunt pervertite si ca trudesc zi si noapte la ceva numit Obsidion.",al={"ce este obsidion","proiectul de excavare al cazanului","proiectul dark iron obsidion"}},{q="Cine este Lathoric the Black?",a="Scrisoarea il numeste drept conducatorul celor Dark Irons, care stapanesc pietrele Suntara si le folosesc puterea pentru a inrobi echipa lui Dorius.",al={"cine este Lathoric","Lathoric the Black","conducator Dark Iron din Searing Gorge"}},{q="Cum se leaga aceasta de misiunea anterioara Suntara Stones?",a="Aceasta duce la primele Suntara Stones, unde Dorius a fost impuscat, iar scrisoarea i-a cazut lui Dorius. Scrisoarea trebuie dusa la Ironforge.",al={"misiunea anterioara Suntara Stones","lantul Suntara Stones"}}},fp="14,334,21.458.0,22.134.1,28.72.0,26.67.0,42.124.0,37.104.0,26.127.0,48.133.0"}
P.entries["quest:3369"] = {n="In Nightmares",s="In Nightmares este o misiune a Hordei in care un aventurier trebuie sa duca o relicva tulburatoare, Nightmare Shard, la Arch Druid Hamuul Runetotem, in varful Elder Rise din Thunder Bluff. Recuperata initial ca un fragment stralucitor din Wailing Caverns, relicva dezvaluie o coruptie profund tulburatoare care patrunde in Emerald Dream.",h="In Nightmares este o misiune a Hordei in care un aventurier trebuie sa duca o relicva tulburatoare, Nightmare...",kw={"elder rise","emerald dream","falla sagewind","glowing shard","hamuul runetotem","in nightmares","nightmare shard","thunder bluff","wailing caverns"},ang={["class:Druid"]="Pentru druids, aschia este o dovada profund ingrijoratoare ca sanctitatea nepatata a Emerald Dream a fost compromisa, confirmand zvonurile despre coruptia care se strecoara prin cercurile Cenarion.",["faction:Horde"]="Livrarea ciobului ocroteste bunastarea spirituala a centrului Kalimdorului si demonstreaza ca Horde joaca un rol esential in stavilirea coruptiei fungice si nascute din vis, care se revarsa din Barrens.",["race:Tauren"]="Intoarcerea la Arch Druid Hamuul Runetotem subliniaza importanta tot mai mare a druidilor tauren in Cenarion Circle, in timp ce acestia infrunta amenintari cosmologice stravechi alaturi de profesorii lor elfi de noapte."},sec={{t="O descoperire tulburatoare",b="Dupa ce examineaza cristalul ciudat recuperat din adancurile Wailing Caverns, Falla Sagewind isi da seama ca este alcatuit din esenta pura a Emerald Dream. Viziunea care salasluieste insa in interiorul lui este intunecata si haotica, semnaland nu un somn linistit, ci un cosmar din care cineva se trezeste. Nevoind sa vorbeasca deschis despre astfel de prevestiri alarmante, iti incredinteaza fragmentul si te indeamna sa-l cauti pe cel mai venerat druid batran din Thunder Bluff, Arch Druid Hamuul Runetotem."},{t="Un secret din vis",b="Cand Hamuul Runetotem priveste in Nightmare Shard, prezentat pe Elder Rise, calmul sau obisnuit se clatina. Infruntand dovada palpabila ca Emerald Dream se destrama si devine un cosmar, arhidruidul isi alege cu grija cuvintele. El recomanda cu tarie discretia, avertizand ca aceste chestiuni delicate depasesc cu mult intelegerea calatorilor de rand, si hotaraste in tacere sa cerceteze suferinta nevazuta care ameninta taramul adormit."}},faq={{q="Ce este Nightmare Shard?",a="Nightmare Shard este fragmentul stralucitor recuperat din Wailing Caverns, pe care Falla Sagewind ti-l incredinteaza dupa ce il examineaza. Desi este faurit din esenta spirituala pura a Emerald Dream, poarta o viziune sinistra si deformata, semn ca ceva a mers cumplit de prost in Dream.",al={"ce este Nightmare Shard","fragment luminos de cosmar","ce a gasit Falla"}},{q="Cine este Falla Sagewind?",a="Falla Sagewind este o druid tauren priceputa, aflata pe versantul muntelui cu vedere spre Wailing Caverns, in Barrens. Ea studiaza fenomenele anormale care se manifesta in cavernele oazei corupte si trimite soli Horde la Hamuul Runetotem cand sunt descoperite relicve periculoase.",al={"falla sagewind","cine mi-a dat aceasta misiune","cel care da misiunea"}},{q="Unde il gasesc pe Arch Druid Hamuul Runetotem?",a="Arhidruidul Hamuul Runetotem locuieste in Elder Rise, una dintre mesele inalte din Thunder Bluff. Poate fi gasit in cercul druidic, alaturi de ceilalti practicanti ai Cenarion Circle.",al={"unde este Hamuul","locatia lui Hamuul Runetotem","Hamuul la Elder Rise"}},{q="De ce vrea Hamuul sa pastreze secretul despre fragment?",a="Emerald Dream este sanctuarul sacru al naturii si al druidilor adormiti. Dovezile concrete ca este transformat intr-un cosmar ar putea provoca panica pe scara larga in randul Cenarion Circle si ar submina eforturile fragile de refacere spirituala din Kalimdor, determinandu-l pe Hamuul sa ceara tacere.",al={"de ce sa pastrezi tacerea","secretul lui Hamuul","de ce ascunde Hamuul fragmentul"}},{q="Are Alliance o versiune a acestei misiuni?",a="Da. In timp ce campionii Hordei duc Nightmare Shard la arhidruidul Hamuul Runetotem din Thunder Bluff, jucatorii din Alliance care cerceteaza Wailing Caverns sunt indrumati sa duca fragmentul peste mare, la Darnassus, si sa i-l prezinte druidului Mathrengyl Bearwalker din Cenarion Circle.",al={"versiunea Aliantei","In Nightmares pentru Alianta","poate Alianta face asta"}},{q="Ce legatura are asta cu Wailing Caverns?",a="Fragmentul provine din Wailing Caverns, unde druidul Naralex a intrat intr-o transa adanca pentru a canaliza izvoarele subterane spre Barrens. In loc sa vindece pamantul, somnul lui Naralex s-a prefacut intr-un cosmar trait cu ochii deschisi, mutand fauna pesterii si infiltrandu-se in fragmente de cristal precum acesta.",al={"legatura cu wailing caverns","legatura cu naralex","ce legatura are asta cu naralex"}}},fx={d74ecb00={q="De ce vrea Falla Sagewind ca Nightmare Shard sa-i fie livrat lui Hamuul Runetotem?",a="Cand examineaza fragmentul, Falla Sagewind recunoaste esenta pura a Emerald Dream, dar intinata de viziuni ale unui cosmar care prinde viata. Tulburata de ceea ce vede, isi da seama ca descoperirea este mult prea periculoasa si importanta pentru a se ocupa singura de ea. Refuza sa mai vorbeasca despre aceasta si insista sa-l duci imediat la Arch Druid Hamuul Runetotem din Thunder Bluff, avand incredere ca numai unul dintre cei mai intelepti druizi, cu rangul cel mai inalt in Cenarion Circle, poate intelege si gestiona un asemenea semn de rau augur.",al={"de ce sa duci fragmentul la Hamuul","de ce vrea Falla sa se faca asta","motivul lui Falla Sagewind"}}},fp="13,325,22.482.0,21.463.1,28.297.0,22.283.0,45.197.0,48.296.0,47.288.0,44.297.0"}
P.entries["quest:337"] = {n="An Old History Book",s="In Stormwind, o cronica pierduta se intoarce la Royal Library. Intitulata The History of Stormwind, cartea zdrentuita poarta sigiliul bibliotecii si a disparut inainte ca regatul sa fie reconstruit dupa First War. Intoarcerea ei ii ofera bibliotecarului-sef Milton Sheaf sansa de a pastra istoria tinuturilor sudice ale human.",h="In Stormwind, o cronica pierduta se intoarce la Royal Library.",kw={"an old history book","duskwood","milton sheaf","pastrarea cunostintelor","southshore","stormwind keep","stormwind library","the history of stormwind"},ang={["class:Mage"]="Ca mage, stii ca bibliotecile stravechi adapostesc cunostinte care se pot pierde sau pot fi neglijate daca sunt lasate in salbaticie.",["faction:Alliance"]="Ca un calator Alliance, contribui la restaurarea fragmentelor mostenirii din Stormwind care au supravietuit distrugerilor provocate de First War.",["race:Human"]="Ca Human din sud, ajuti la recuperarea documentelor scrise din salbaticie si la reconstruirea unei culturi sfasiate de Old Horde."},sec={{t="O relicva din First War",b="Cei Undead si ogrii din Duskwood cutreiera ruinele in care a fost gasit acest volum acoperit de noroi. Cartea este o relicva rara, datand de dinaintea distrugerii Stormwind. Pe prima pagina se afla sigiliul oficial al bibliotecii regatului. Cineva a imprumutat-o cu zeci de ani in urma, inainte ca Horde sa distruga prin foc capitala, iar cartea a fost considerata pierduta odata cu prabusirea tinuturilor sudice."},{t="Restaurarea cronicilor uitate",b="Milton Sheaf recunoaste cartea cand aceasta ajunge la el, in Royal Library din Stormwind Keep. Bibliotecarul-sef intentioneaza s-o aseze in arhiva de carti rare, desi paginile i-au fost grav deteriorate de anii petrecuti in salbaticia bantuita. Descoperirea il impulsioneaza pe Sheaf sa caute si alte cunostinte pierdute. Isi indreapta privirea spre nord, catre Southshore, orasul cel mai apropiat de regatul ruinat Alterac si de bibliotecile sale abandonate."}},faq={{q="Unde se gaseste aceasta carte?",a="Gasesti cartea printre creaturile ostile care ratacesc prin Duskwood, cel mai adesea printre Undead din cimitire si de pe campuri sau printre ogrii din dealurile sudice.",al={"unde gasesti vechea carte de istorie","locatia obiectului lasat la prada","cartea de istorie din Duskwood"}},{q="Cui trebuie sa-i duc cartea?",a="Du volumul la Milton Sheaf, bibliotecarul-sef din Royal Library, in interiorul Stormwind Keep.",al={"locatia predarii","unde predau acest obiect","locatia lui Milton Sheaf"}},{q="De ce este cartea intr-o stare atat de proasta?",a="Cartea a fost imprumutata inainte de First War si de jefuirea Stormwind. A petrecut zeci de ani in salbaticia din Duskwood, expusa murdariei si putreziciunii si manuita de gunoieri ratacitori si monstri.",al={"de ce e noroios","de ce e deteriorat"}},{q="Duce returnarea acestei carti la alte sarcini?",a="Da. Milton Sheaf te trimite spre nord, la Southshore, in Hillsbrad Foothills, sa vorbesti cu Loremaster Dibbs, care te poate indruma catre carti din Ruins of Alterac.",al={"ce urmeaza","misiune de continuare","lantul de misiuni al cartii"}},{q="De ce ii pasa atat de mult lui Milton Sheaf de acest anumit volum?",a="Au supravietuit putine documente originale dupa ce regatul a fost ras de pe fata pamantului, iar Stormwind a ars in timpul First War. Textele autentice dinaintea razboiului ii ajuta pe cercetatori sa reconstituie trecutul regatului.",al={"de ce este importanta cartea","importanta istoriei Stormwind"}},{q="Pot jucatorii Horde sa indeplineasca aceasta misiune?",a="Nu. Cartea apartine Royal Library din Stormwind, iar numai bibliotecarii Alliance din Stormwind Keep o pot accepta.",al={"varianta Horde","este doar pentru Alliance"}}},fp="19,306,24.342.0,26.386.0,25.148.0,27.92.0,39.188.0,45.159.0,60.174.0,38.114.0"}
P.entries["quest:3370"] = {n="In Nightmares"}
P.entries["quest:3372"] = {n="Release Them",s="Un arheolog pe moarte din Searing Gorge te indeamna sa-i eliberezi pe cei pe care puterea lui Suntara ii sileste in continuare sa munceasca, desi trupurile le-au cedat. Totul depinde de altarul lui Suntara, iar o relicva pazita de Twilight's Hammer trebuie asezata pe el.",h="Un arheolog pe moarte din Searing Gorge te indeamna sa-i eliberezi pe cei pe care puterea lui Suntara ii...",kw={"altarul lui Suntara","arheolog muribund","artefact misterios","elibereaza-i","Searing Gorge","groapa de zgura","Twilight's Hammer"},sec={{t="O rugaminte pe moarte",b="Inainte sa se prabuseasca, arheologul te implora sa-l eliberezi. Trupul i-a cedat, dar puterea lui Suntara il impinge sa-si continue munca. Cheia, spune arheologul, este altarul lui Suntara."},{t="Altarul lui Suntara",b="Mergi spre nord-vest, catre dealurile de deasupra pesterii. Idolatrii din Twilight's Hammer pazesc acolo o relicva numita Mysterious Artifact. Ia-o de la ei si du-o la Slag Pit, ca s-o asezi pe altarul lui Suntara."}},faq={{q="Cine cere ajutor pentru Release Them?",a="Un arheolog pe moarte din Searing Gorge, care se prabuseste dupa ce te implora.",al={"cel care ofera misiunea","cine da misiunea Release Them","arheolog pe moarte"}},{q="Unde se afla artefactul misterios?",a="Adoratorii Twilight's Hammer il pazesc in cadranul de nord-vest al Searing Gorge, pe dealurile de deasupra pesterii.",al={"locatia artefactului misterios","unde este relicva","adoratorii Twilight's Hammer"}},{q="Unde trebuie dus artefactul?",a="Este dus la Slag Pit si asezat pe altarul lui Suntara.",al={"locatia Altar of Suntara","unde este altarul","unde duc artefactul"}},{q="De ce nu se pot odihni victimele?",a="Arheologul spune ca puterea lui Suntara ii indeamna sa-si continue munca, desi trupurile le-au cedat.",al={"de ce sa-i eliberezi","ce li se intampla","puterea lui suntara"}}},fp="12,276,12.212.0,20.212.0,36.69.0,41.109.0,37.62.0,35.114.0"}
P.entries["quest:3374"] = {n="The Essence of Eranikus",s="Intri in legatura cu Oathstone of Ysera's Dragonflight, iar Itharius iti vorbeste direct in minte. Acceptarea acestei sarcini inseamna sa o ajuti pe Ysera's Dragonflight sa rascumpere sufletul corupt al lui Eranikus; primul sacrificiu este sa-i dai lui Itharius nestemata care inlantuie partea din mintea lui Eranikus ce a ramas inca libera. Itharius te asteapta in Swamp of Sorrows.",h="Intri in legatura cu Oathstone of Ysera's Dragonflight, iar Itharius iti vorbeste direct in minte.",kw={"esenta inlantuita","eranikus","flightul dragonilor verzi","itharius","oathstone","swamp of sorrows","ysera"},sec={{t="O voce prin piatra",b="Prin Oathstone, Itharius iti spune ca acceptarea acestei misiuni inseamna sa ajuti Ysera's Dragonflight sa rascumpere sufletul corupt al lui Eranikus. Itharius asteapta multe sacrificii de la voi doi, iar primul este sa-i predai nestemata care a legat orice parte a mintii lui Eranikus care si-a pastrat vointa libera. Oathstone si Chained Essence of Eranikus trebuie duse la Itharius din Swamp of Sorrows, iar acolo alegi daca vei ajuta dragonflight."},{t="O alegere facuta",b="Itharius te intampina la inca o rascruce si te intreaba ce alegi. Dupa ce alegerea e facuta, Itharius spune ca deciziile tale de pana acum au fost cele corecte si ca faptele tale de acum inainte vor hotari daca asa va fi si pe viitor."}},faq={{q="Cine este Itharius?",a="Itharius iti vorbeste in minte prin Oathstone pentru Ysera's Dragonflight si te asteapta in Swamp of Sorrows, incercand sa rascumpere sufletul corupt al lui Eranikus.",al={"cine este itharius","rolul lui itharius","cine trimite mesajul"}},{q="Ce este Chained Essence of Eranikus?",a="Este gema care tine in lant partea din mintea lui Eranikus ce a ramas libera. Itharius iti cere sa renunti la ea drept prima jertfa.",al={"chained essence of eranikus","ce este nestemata inlantuita","esenta lui eranikus"}},{q="Ce a precedat aceasta misiune?",a="Urmeaza dupa primul pas din The Essence of Eranikus, cu acelasi nume.",al={"misiune necesara","etapa anterioara"}},{q="Unde duci Oathstone si esenta?",a="Lui Itharius, in Swamp of Sorrows, unde alegi daca sa ajuti dragonflight.",al={"unde sa duci oathstone","unde se afla itharius","locatia de predare"}}},fp="23,340,25.453.0,13.226.1,16.163.0,40.128.0,28.74.0,48.87.0"}
P.entries["quest:3376"] = {n="Break Sharptusk!",s="Break Sharptusk! este un rit de trecere hotarator, impus de Brave Windfeather pe Red Cloud Mesa. Pentru a apara tinuturile tauren de raidurile neincetate, tinerii campioni sunt trimisi spre est, in Brambleblade Ravine, sa-l ucida pe Chief Sharptusk Thornmantle. Eliminarea conducatorului Bristleback da o lovitura grea quilboarilor care invadeaza Mulgore.",h="Break Sharptusk!",kw={"brambleblade","bristleback","mulgore","narache","quilboar","red cloud mesa","sharptusk","thornmantle","windfeather"},ang={["class:Hunter"]="Pentru vanatori, aceasta misiune este incercarea suprema de inceput: sa vaneze o prada inzestrata cu viclenie, arme si intentia de a te vana la randul ei.",["faction:Horde"]="Executandu-l pe Chief Sharptusk, aliatii Horde isi demonstreaza angajamentul fata de stabilizarea Mulgore si asigurarea unor tinuturi pasnice pentru noii lor frati tauren.",["race:Tauren"]="Uciderea lui Sharptusk Thornmantle este una dintre ultimele incercari pe care le infrunta un tanar tauren inainte de a parasi Camp Narache, dovedind astfel ca are hotararea necesara pentru a apara triburile de vecinii ostili."},sec={{t="Un camin castigat cu sange",b="Inaltimile inierbate din Red Cloud Mesa au fost de multa vreme un sanctuar pasnic, unde tinerii tauren invata traditiile vanatorii si comuniunea cu Earth Mother. Totusi, aceasta pace este contestata fara incetare. La est se afla Brambleblade Ravine, un defileu napadit de spini, revendicat de tribul ostil de quilboari Bristleback. Quilboarii ii considera pe tauren invadatori care le fura pamantul sacru si lanseaza incaierari necontenite impotriva triburilor ce incearca sa-si cladeasca o viata statornica in Mulgore."},{t="Ameninarea lui Thornmantle",b="Atacurile neincetate asupra platoului nu sunt o izbucnire fara tinta; ele sunt coordonate sub conducerea brutala a sefului Sharptusk Thornmantle. Aflat intr-un sat improvizat si fortificat, adanc in ravina, Sharptusk isi indreapta razboinicii si geomantii impotriva Shu'halo. Dandu-si seama ca Bristleback nu-si vor opri raidurile cat timp seful lor mai respira, Brave Windfeather ii porunceste unui erou in devenire sa patrunda in ravina, sa-l doboare pe Thornmantle si sa se intoarca cu capul sau retezat drept dovada."},{t="Lectiile vanatorii",b="Pentru tinerii Tauren si aliatii lor, vanarea lui Sharptusk este mai mult decat o simpla executie - este o initiere in realitatea dura a supravietuirii. Asa cum ii invata Brave Windfeather, vanatoarea de bestii deprinde rabdarea, dar urmarirea unui dusman suficient de viclean incat sa vaneze la randul lui pune la incercare curajul, vigilenta si disciplina martiala. Doborarea lui Sharptusk face dreptate rudelor cazute si dovedeste ca vanatorul este pregatit sa strabata campiile intinse din Mulgore."}},faq={{q="Cine este Chief Sharptusk Thornmantle?",a="Chief Sharptusk Thornmantle este liderul nemilos al quilboarilor Bristleback care locuiesc in Brambleblade Ravine. Sub conducerea sa, tribul organizeaza raiduri si lupte neintrerupte impotriva asezarii tauren de pe Red Cloud Mesa.",al={"cine este Sharptusk","povestea lui Sharptusk Thornmantle","cine este seful quilboar"}},{q="Unde poate fi gasit Chief Sharptusk Thornmantle?",a="Sharptusk se afla in adancul Brambleblade Ravine, la marginea estica a Red Cloud Mesa. Isi supravegheaza tribul din satul improvizat, cuib din canionul acoperit de spini.",al={"unde se afla Sharptusk","locatia lui Sharptusk","cum il gasesc pe Sharptusk"}},{q="Cine ofera misiunea Break Sharptusk!?",a="Misiunea este oferita de Brave Windfeather, o razboinica tauren cu experienta, care pazeste Camp Narache, pe Red Cloud Mesa. Ea le cere noilor veniti promitatori sa-si dovedeasca vitejia inlaturand amenintarea Bristleback.",al={"cine da misiunea Break Sharptusk","cine porneste misiunea Break Sharptusk","locatia lui Brave Windfeather"}},{q="De ce urasc quilboar-ii Bristleback poporul Tauren?",a="Quilboar il venereaza pe semizeul lor, Agamaggan, si isi apara cu inversunare tinuturile pe care le revendica. Ei ii considera pe taurenii care intemeiaza asezari in Mulgore intrusi ce le incalca stravechile terenuri de vanatoare.",al={"de ce ataca quilboarii","conflictul dintre Tauren si quilboari","de ce sunt ostili quilboarii"}},{q="Ce dovezi cere Brave Windfeather?",a="Brave Windfeather cere capul retezat al capeteniei Sharptusk Thornmantle. Aducerea capului dovedeste fara urma de indoiala ca liderul a cazut si serveste drept avertisment sever pentru orice Bristlebacks ramasi.",al={"ce trebuie sa-i aduc lui Windfeather","dovada Sharptusk","obiectivul misiunii Sharptusk"}},{q="Care este semnificatia culturala a acestei vanatori pentru tinerii tauren?",a="In cultura taurenilor, maturitatea adevarata vine din intelegerea echilibrului dintre vanator si prada. Windfeather subliniaza ca urmarirea unui adversar inteligent si viclean precum Sharptusk ii invata pe tinerii razboinici gravitatea luptei pe viata si pe moarte si responsabilitatea de a-si apara tribul.",al={"de ce sa omori Sharptusk, din punct de vedere al lore-ului","rit de initiere Tauren si Sharptusk","semnificatia vanatorii"}}},fx={d0ec7fec={q="De ce vrea Brave Windfeather sa fie ucis Chief Sharptusk?",a="Quilboarii Bristleback duc o campanie neobosita impotriva taurenilor din Red Cloud Mesa, punand in pericol siguranta noii lor asezari. Chief Sharptusk Thornmantle conduce aceste raiduri din apropiata Brambleblade Ravine. Brave Windfeather vrea sa dea o lovitura decisiva conducerii lor, pentru a opri varsarea de sange si a-i avertiza ferm pe cei care ar contesta prezenta taurenilor pe mesa.",al={"motivul lui windfeather","de ce sa-l ucizi pe sharptusk","de ce sa-l rapui pe sharptusk"}},["8bbc47fc"]={q="De ce te trimite Brave Windfeather in loc sa se ocupe ea insasi de Sharptusk?",a="Alti aparatori cu experienta au incercat deja sa-l alunge pe capetenia quilboar si au esuat, in timp ce razboinicii ramasi trebuie sa stea in urma pentru a pazi Camp Narache si a-i proteja pe tineri de amenintarile ratacitoare. Auzind zvonuri despre potentialul tau tot mai mare ca vanator, Windfeather te considera un talent nedovedit, dar redutabil, capabil sa invinga un adversar viclean si sa inteleaga adevarata greutate a vanatorii.",al={"de ce ma trimiti","de ce nu trimiti bravii","de ce nu Brave Windfeather"}}},fp="16,345,19.488.0,25.507.0,23.453.0,35.229.0,47.190.0,37.205.0,48.191.0,41.200.0,64.277.0"}
P.entries["quest:3377"] = {n="Prayer to Elune",s="Un spirit tinut intr-o cusca din Searing Gorge, Zamael Lunthistle, te intreaba daca il vei ajuta. Nu a mai primit vizitatori de multi ani si, mai intai, vrea sa-i asculti povestea.",h="Un spirit tinut intr-o cusca din Searing Gorge, Zamael Lunthistle, te intreaba daca il vei ajuta.",kw={"darkshore","elune","lunthistle","rugaciune","pocainta","searing gorge","tablite","twilight's hammer","zamael"},sec={{t="Un spirit intr-o cusca",b="Zamael Lunthistle te intampina cu o lauda adresata lui Elune si spune ca au trecut multi ani de cand l-a vizitat cineva. Te intreaba daca il vei ajuta si incepe prin a-ti cere sa-i asculti povestea."},{t="Povestea lui Zamael",b="Zamael era un night elf tanar din Darkshore cand a intrat in randurile Twilight's Hammer, care s-a imprietenit cu el si l-a indepartat de Elune. O viziune de la Elune l-a trezit din apatia provocata de venerarea vechilor zei, iar, in semn de pocainta, si-a sapat durerea intr-o tablita din aur pur, ca rugaciune catre Elune. Twilight's Hammer a gasit tablita, l-a declarat blasfemator si l-a executat, lasandu-i rugaciunea neterminata. Acum este legat de lume ca spirit si tinut in cusca, drept avertisment pentru toti cei care ar trada credinta Twilight's Hammer. Zamael si-a acceptat soarta, dar spune ca rugaciunea trebuie gasita."}},faq={{q="Cine este Zamael Lunthistle?",a="Zamael Lunthistle este un spirit inchis intr-o cusca din Searing Gorge. Iti cere sa-i asculti povestea.",al={"cine este Zamael","povestea lui Zamael Lunthistle","cine este fantoma din cusca"}},{q="Ce iti cere Zamael?",a="Te intreaba daca il vei ajuta si mai intai sa-i asculti povestea.",al={"ce vrea zamael","cererea lui zamael"}},{q="Ce urmeaza dupa ce auzi povestea lui Zamael?",a="Urmeaza o a doua parte din Prayer to Elune, din nou alaturi de Zamael.",al={"urmatoarea etapa rugaciunea catre elune","lantul rugaciunii catre elune"}}},fp="15,164,18.190.0,13.599.1,25.92.0,28.65.0,39.60.0"}
P.entries["quest:3378"] = {n="Prayer to Elune",s="Zamael Lunthistle iti cere sa-i gasesti rugaciunea catre Elune, inscrisa pe o tabla de aur. Unul dintre ticalosii inchinatori la idoli trebuie sa o aiba asupra lui, iar Zamael vrea sa o duci la Astarii Starseeker in Darnassus.",h="Zamael Lunthistle iti cere sa-i gasesti rugaciunea catre Elune, inscrisa pe o tabla de aur.",kw={"astarii starseeker","darnassus","tavla de aur","rugaciune catre elune","searing gorge","temple of the moon","zamael lunthistle"},sec={{t="Rugaciunea pierduta",b="Credinta lui Zamael s-a reaprins, dar spune ca asta conteaza prea putin dupa nenumaratele fapte ticaloase pe care le-a savarsit impotriva lumii si a locuitorilor ei. Nu se asteapta la iertare. Tot ce cere este ca rugaciunea sa-i fie auzita, asa ca te trimite sa recuperezi tablita de aur de la adoratorii idolilor si sa o duci la Astarii Starseeker in Darnassus."},{t="La Temple of the Moon",b="La Temple of the Moon, Astarii Starseeker iti spune ca Elune iti zambeste in aceasta seara, fiindca un suflet ratacit i-a fost inapoiat de mana ta. Iti este oferita recunostinta pentru fapta."}},faq={{q="Cine este Zamael Lunthistle?",a="Zamael Lunthistle iti cere sa-i gasesti rugaciunea catre Elune. Credinta i s-a reaprins dupa nenumaratele fapte rele pe care le-a savarsit impotriva lumii.",al={"povestea lui zamael lunthistle","cine ofera prayer to elune","zamael"}},{q="Pe ce este inscriptionata rugaciunea?",a="Rugaciunea lui Zamael a fost gravata pe o tablita de aur, iar el crede ca unul dintre ticalosii care venereaza idolii o poarta asupra sa.",al={"obiectul Prayer to Elune","tableta aurie","ce este rugaciunea"}},{q="Cui trebuie sa-i fie data rugaciunea?",a="Lui Astarii Starseeker, in Darnassus, care se gaseste la Temple of the Moon.",al={"cine primeste Prayer to Elune","astarii starseeker","unde duc rugaciunea"}},{q="Se asteapta Zamael sa fie iertat pentru trecutul sau?",a="Nu. Spune ca iertarea este ultimul lucru la care se asteapta, dar rugaciunea lui trebuie ascultata.",al={"vrea zamael iertare","absolutia lui zamael"}}},fp="15,201,15.349.0,25.186.1,25.161.0,32.110.0,39.75.0,44.82.0"}
P.entries["quest:338"] = {n="The Green Hills of Stranglethorn",s="Lui Barnil Stonepot i s-a incredintat corectura manuscrisului romanului lui Hemet Nesingwary, dar o rafala puternica a imprastiat paginile libere prin jungla. Pentru a-l scuti de mania maestrului sau, ti se cere sa cauti prin tinuturile salbatice, sa asamblezi paginile lipsa in patru capitole complete si sa aduci inapoi lucrarea terminata.",h="Lui Barnil Stonepot i s-a incredintat corectura manuscrisului romanului lui Hemet Nesingwary, dar o rafala...",kw={"barnil stonepot","capitole","green hills of stranglethorn","hemet nesingwary","manuscris","pagini","stranglethorn vale"},sec={{t="Un manuscris imprastiat",b="Dupa sosirea ta in tabara expeditiei, in urma misiunii Welcome to the Jungle, Barnil Stonepot se confrunta cu un dezastru. In timp ce revizuia schita romanului lui Hemet Nesingwary, The Green Hills of Stranglethorn, o rafala neasteptata a smuls foile imprastiate si le-a purtat in salbaticie. Desi a reusit sa recupereze o buna parte din lucrare, multe pagini s-au pierdut prin tufisuri. Pentru ca maestrul sau sa nu afle de patanie, are nevoie sa gasesti toate paginile ratacite si sa le aduni in Chapter I, Chapter II, Chapter III si Chapter IV."},{t="Pastrarea povestii Hunter",b="Aducerea celor patru sectiuni complete inapoi il scuteste pe Barnil de o confruntare neplacuta cu Nesingwary. Cu capitolele adunate si in siguranta, spera ca lucrarea restaurata va ajunge curand in biblioteci din toata lumea."}},faq={{q="Cine a scris The Green Hills of Stranglethorn?",a="Romanul a fost scris de conducatorul expeditiei, Hemet Nesingwary, care i-a incredintat manuscrisul lui Barnil Stonepot pentru corectura.",al={"autorul cartii Green Hills of Stranglethorn","cine a scris cartea","cartea lui Nesingwary"}},{q="Cum s-au pierdut paginile?",a="O rafala puternica de vant a trecut chiar prin tabara de vanatoare in timp ce Barnil recitea manuscrisul, imprastiind foile libere prin jungla.",al={"de ce sunt paginile imprastiate","ce s-a intamplat cu paginile","cum au fost luate paginile de vant"}},{q="De ce este nevoie pentru a termina manuscrisul?",a="Trebuie sa aduni paginile imprastiate si sa le asamblezi in patru parti distincte: Chapter I, Chapter II, Chapter III si Chapter IV, apoi sa-i inmanezi setul complet lui Barnil.",al={"ce capitole sunt necesare","cum completez Green Hills","cerinte pentru manuscris"}},{q="De unde a venit aceasta misiune?",a="Barnil ofera aceasta slujba in tabara expeditiei din Stranglethorn Vale, dupa ce termini Welcome to the Jungle.",al={"conditie prealabila pentru Green Hills","misiunea dinaintea Green Hills","cum primesc aceasta misiune"}},{q="Ce intentioneaza Barnil sa faca cu romanul restaurat?",a="Pe langa faptul ca se salveaza de mania lui Nesingwary, Barnil se asteapta ca manuscrisul terminat sa fie distribuit, in cele din urma, in biblioteci din intreaga lume.",al={"de ce sa aduni paginile","ce se intampla cu cartea","unde va ajunge cartea"}}},fp="32,309,22.536.0,28.231.0,43.128.0,24.152.0,40.166.0,36.109.0,54.148.0"}
P.entries["quest:339"] = {n="Chapter I",s="Barnil Stonepot incearca sa restaureze partea de inceput a manuscrisului de vanatoare imprastiat al lui Hemet Nesingwary, The Green Hills of Stranglethorn. Are nevoie de patru file lipsa, adunate din toata jungla, pentru a recompune sectiunea introductiva.",h="Barnil Stonepot incearca sa restaureze partea de inceput a manuscrisului de vanatoare imprastiat al lui Hemet...",kw={"barnil stonepot","chapter i","green hills of stranglethorn","hemet nesingwary","stranglethorn vale"},sec={{t="Introducerea lipsa",b="Dupa discutia voastra despre The Green Hills of Stranglethorn, Barnil Stonepot isi propune sa restaureze pasajul de inceput al cartii. Potrivit dwarf-ului, aceasta prima parte pregateste scena pentru povestea de ansamblu si descrie grupul de vanatori al lui Nesingwary, numarandu-l chiar pe Barnil printre insotitori. Din pacate, filele manuscrisului sunt inca pierdute in salbaticie, iar paginile unu, patru, sase si opt lipsesc din colectie."},{t="Legarea primei sectiuni",b="Dupa ce aduci inapoi cele patru pagini lipsa, Barnil poate sa reuneasca prima sectiune din textul vanatorului-maestru intr-o parte unitara si coerenta a cartii."}},faq={{q="Cine cere aceste pagini?",a="Barnil Stonepot, un tovaras al lui Hemet Nesingwary aflat in tabara lor din Stranglethorn Vale, are nevoie de pagini ca sa reuneasca memoriile imprastiate despre vanatoare.",al={"cine da capitolul 1","barnil stonepot","cel care da misiunea"}},{q="De ce pagini este nevoie pentru aceasta parte a manuscrisului?",a="Barnil are nevoie de paginile unu, patru, sase si opt pentru a reasambla cu succes sectiunea de inceput a lucrarii.",al={"ce pagini sunt necesare","pagini lipsa","care pagini"}},{q="Ce este descris in aceasta parte a manuscrisului?",a="Potrivit lui Barnil Stonepot, aceasta ofera fundalul povestii si ii prezinta pe tovarasii de vanatoare ai lui Nesingwary, inclusiv pe Barnil insusi.",al={"despre ce este capitolul 1","continutul manuscrisului"}},{q="Ce a dus la acest pas?",a="Aceasta urmeaza efortului mai amplu de recuperare a The Green Hills of Stranglethorn, in care Barnil iti spune prima data despre paginile lipsa.",al={"conditie prealabila","misiunea anterioara"}}},fp="9,251,24.431.0,25.163.0,30.154.0,55.104.0,49.140.0,25.129.0"}
P.entries["quest:34"] = {n="An Unwelcome Guest",s="An Unwelcome Guest este o misiune locala din Lakeshire, in care Martie Jainrose cauta sa se razbune pe Bellygrub, un mistret salbatic distrugator. Fiara i-a devastat gradina si i-a calcat in picioare narcisele de sezon, asa ca ea a pus o recompensa pe coltii creaturii.",h="An Unwelcome Guest este o misiune locala din Lakeshire, in care Martie Jainrose cauta sa se razbune pe...",kw={"an unwelcome guest","bellygrub","mistret","narcise","lakeshire","marshal marris","martie jainrose","redridge","redridge mountains"},ang={["class:Hunter"]="Bellygrub este o bestie faimoasa, cu nume, care cutreiera tinuturile de la sud-vest de Lakeshire, fiind o provocare de seama pentru urmarire si vanatoare pentru orice tragator de elita care trece prin Redridge Mountains.",["faction:Alliance"]="Ajutand-o pe Martie Jainrose sa-si apere casa si gradina, aduci o mica masura de ordine si alinare in orasul greu incercat Lakeshire, ai carui locuitori sunt deja coplesiti de amenintari mai mari din Redridge.",["profession:Herbalism"]="Mandria lui Martie Jainrose era rondul ei de flori, ingrijit cu migala, iar navalirea distrugatoare a lui Bellygrub i-a nimicit narcisele de sezon, lovind in plin firava viata domestica a plantelor din Redridge."},sec={{t="Necazuri in gradina",b="In oraselul de pe malul lacului Lakeshire, Martie Jainrose se ocupa de gospodaria ei, in vreme ce umbrele se aduna deasupra Redridge Mountains. Rutina ei linistita este tulburata de o teroare locala persistenta: un mistret salbatic, vestit pentru agresivitate, care i-a invadat gradina in repetate randuri. Dupa ce i-a distrus fara putinta de refacere pentru acest sezon peticul pretios de narcise, locuitoarea indurerata apeleaza la calatori priceputi ca sa puna capat animalului dezlantuit."},{t="Ameninarea reprezentata de Bellygrub",b="Localnicii cunosc fiara vinovata drept Bellygrub, nume potrivit nascocit de Marshal Marris, comandantul garzii orasului Lakeshire. Bellygrub isi petrece cea mai mare parte a timpului scormonind si cautand hrana prin tufisurile campurilor de la sud-vest de oras. Totusi, apetitul sau vorace si indrazneala il aduc adesea periculos de aproape de locuintele civilizate, iar straturile de flori ale lui Martie au fost complet distruse, facand necesara indepartarea lui definitiva."}},faq={{q="Cine ofera misiunea An Unwelcome Guest?",a="Martie Jainrose ofera misiunea in oraselul de pe malul lacului Lakeshire, din Redridge Mountains. Tulburata de distrugerea constanta a gradinii sale cu flori, le cere aventurierilor care trec pe acolo sa dea de urma faptasului.",al={"cine ofera an unwelcome guest","unde pot lua an unwelcome guest","misiunea lui martie jainrose"}},{q="Cine sau ce este Bellygrub?",a="Bellygrub este un mistret agresiv si distructiv, cunoscut pentru ca terorizeaza imprejurimile din jurul Lakeshire. Marshal Marris, comandantul garzii locale a orasului, i-a dat initial aceasta porecla.",al={"cine este Bellygrub","ce este Bellygrub","de ce i se spune Bellygrub"}},{q="Unde poate fi gasit Bellygrub?",a="Bellygrub isi petrece cea mai mare parte a timpului cautand hrana pe campurile deschise de la sud-vest de Lakeshire, desi rataceste adesea mai aproape de marginile orasului si prin gradinile localnicilor.",al={"locatia lui Bellygrub","unde este Bellygrub","gaseste-l pe Bellygrub","unde apare Bellygrub"}},{q="De ce vrea Martie Jainrose sa-l ucida pe Bellygrub?",a="Bellygrub a calcat in picioare si a pradat in repetate randuri gradina ingrijita cu migala de Martie Jainrose, distrugandu-i complet narcisele, astfel incat niciuna nu mai poate fi replantata pana in sezonul urmator. Satula de stricaciunile repetate, ea vrea sa-l elimine.",al={"de ce vrea Martie sa-l omoare pe Bellygrub","de ce sa-l omori pe Bellygrub","ce a facut Bellygrub"}},{q="Ce dovada este necesara pentru a incheia misiunea?",a="Martie Jainrose cere coltul lui Bellygrub drept dovada ca fiara amenintatoare a fost in sfarsit invinsa, inainte sa-ti ofere recompensa.",al={"dovada Bellygrub","predare Unwelcome Guest","ce sa-i aduc lui Martie Jainrose"}},{q="Cine este Marshal Marris si ce legatura are cu bestia?",a="Marshal Marris este maresalul din Lakeshire. In timp ce Martie Jainrose cauta sa se razbune pentru narcisele distruse, Marris este cel care a dat numele Bellygrub vierului buclucas.",al={"cine este Marshal Marris","Marshal Marris Bellygrub"}}},fp="18,262,21.442.0,23.435.0,39.213.0,25.194.0,29.164.0,47.225.0,43.135.0,62.189.0"}
P.entries["quest:340"] = {n="Chapter II",s="Barnil Stonepot are nevoie de ajutor pentru a aduna frunzele lipsa din a doua parte a manuscrisului de vanatoare imprastiat al lui Hemet Nesingwary. Dupa ce a adunat singur cea mai mare parte a pergamentului, se bazeaza pe calatorii din Stranglethorn Vale ca sa recupereze relatarile ramase despre vanatoarea de pantere si tigri.",h="Barnil Stonepot are nevoie de ajutor pentru a aduna frunzele lipsa din a doua parte a manuscrisului de...",kw={"barnil stonepot","chapter ii","green hills of stranglethorn","nesingwary","pagini","pantera","stranglethorn vale","tigru"},sec={{t="Vanatorile pisicilor din jungla",b="Dupa ce manuscrisul lui Hemet Nesingwary s-a imprastiat prin Stranglethorn Vale, Barnil Stonepot a reusit sa recupereze singur multe pagini. Al doilea capitol cuprinde povestiri palpitante despre urmarirea panterelor si tigrilor prin salbaticie. Patru pagini anume - numerele 10, 11, 14 si 16 - au ramas pierdute in vant si printre vietuitoarele junglei, lasand neterminata aceasta parte din cronica expeditiei."}},faq={{q="Cine cere aceste pagini de manuscris?",a="Barnil Stonepot, care ajuta expeditia Nesingwary in Stranglethorn Vale, iti cere sa-l ajuti sa adune filele lipsa.",al={"cine da capitolul 2","cel care da misiunea Chapter II","barnil stonepot"}},{q="De ce pagini este nevoie pentru al doilea capitol?",a="Barnil are nevoie de paginile 10, 11, 14 si 16 pentru a termina asamblarea celui de-al doilea capitol.",al={"ce pagini sunt necesare","pagini pentru capitolul 2","paginile din Chapter II"}},{q="Ce povesti sunt consemnate in al doilea capitol?",a="Al doilea capitol consemneaza povesti despre pandirea si vanarea panterelor si tigrilor care dau tarcoale prin Stranglethorn Vale.",al={"despre ce este capitolul 2","povestea Chapter II","continutul capitolului 2 Green Hills"}},{q="Ce precede aceasta cerere?",a="Aceasta cerere urmeaza dupa apelul initial al lui Barnil pentru ajutor privind manuscrisul pierdut, cunoscut sub numele de The Green Hills of Stranglethorn.",al={"misiune anterioara","capitolul 2, conditie prealabila","lantul Green Hills"}}},fp="10,301,24.424.0,41.126.0,46.78.0,48.113.0,31.124.0"}
P.entries["quest:341"] = {n="Chapter III",s="Barnil Stonepot incearca sa reconstituie al treilea capitol din manuscrisul de vanatoare al lui Hemet Nesingwary, in Stranglethorn Vale. Sectiunea povesteste despre prima prada doborata cu o pusca dwarven de Sir Erlgadin si Lady Rouack, insa patru file anume au fost imprastiate prin jungla.",h="Barnil Stonepot incearca sa reconstituie al treilea capitol din manuscrisul de vanatoare al lui Hemet...",kw={"barnil stonepot","chapter iii","erlgadin","green hills of stranglethorn","hemet nesingwary","pagina 18","pagina 20","pagina 21","pagina 24","rouack","stranglethorn vale"},sec={{t="O vanatoare consemnata",b="Barnil Stonepot considera aceasta parte din The Green Hills of Stranglethorn preferata lui. Textul relateaza primele ispravi ale lui Sir Erlgadin si Lady Rouack, descriind in amanunt prima lor ucidere, cu ajutorul unei pusti piticesti. Capitolul se incheie cu un suspans puternic."},{t="File lipsa",b="Pentru a recompune povestea, Barnil are nevoie de paginile 18, 20, 21 si 24. Aceste fragmente lipsa s-au risipit in tinuturile salbatice, purtate departe prin Stranglethorn Vale, la fel ca restul manuscrisului."}},faq={{q="Cine cauta Chapter III?",a="Barnil Stonepot, care a corectat manuscrisul lui Hemet Nesingwary in tabara expeditiei din nordul Stranglethorn Vale, reuneste paginile lipsa.",al={"cine ofera chapter 3","cel care ofera misiunea chapter 3","barnil stonepot chapter iii"}},{q="Ce se intampla in Chapter III din carte?",a="Capitolul povesteste despre prima vanatoare la care au pornit Sir Erlgadin si Lady Rouack cu o pusca de Dwarf, incheindu-se intr-un moment de suspans fara rezolutie.",al={"despre ce este chapter 3","povestea din chapter iii","erlgadin si rouack"}},{q="De ce pagini este nevoie pentru a incheia Chapter III?",a="Barnil are nevoie de paginile 18, 20, 21 si 24 pentru a uni Chapter III intr-un singur volum.",al={"ce pagini chapter 3","paginile necesare pentru chapter iii","pagini pentru chapter 3"}},{q="Ce a precedat aceasta misiune?",a="Aceasta misiune urmeaza demersului initial cunoscut drept The Green Hills of Stranglethorn, in care Barnil explica prima data pierderea manuscrisului lui Hemet Nesingwary.",al={"cerinte preliminare pentru Chapter 3","ce duce la Chapter III"}}},fp="11,272,15.263.0,14.205.0,31.154.0,40.138.0,45.77.0,28.157.0"}
P.entries["quest:342"] = {n="Chapter IV",s="Barnil Stonepot incearca sa reconstituie emotionantul final al celebrului manuscris al lui Hemet Nesingwary. Recuperarea ultimelor trei file va reface deznodamantul culminant al povestii salbatice despre vanatoare.",h="Barnil Stonepot incearca sa reconstituie emotionantul final al celebrului manuscris al lui Hemet Nesingwary.",kw={"barnil stonepot","capitolul 4","chapter iv","green hills of stranglethorn","hemet nesingwary","pagina 25","pagina 26","pagina 27","stranglethorn vale"},sec={{t="Marele final",b="Barnil Stonepot considera aceasta sectiune punctul culminant al intregului volum de vanatoare. Pentru a alcatui al patrulea capitol, are nevoie de cineva care sa gaseasca si sa-i aduca paginile douazeci si cinci, douazeci si sase si douazeci si sapte. Odata ce aceste trei file pierdute vor fi adunate din jungla, finalul captivant al manuscrisului va putea fi, in sfarsit, reconstituit."}},faq={{q="Cine vrea sa fie restaurat Chapter IV?",a="Barnil Stonepot iti cere ajutorul ca sa aduni foile imprastiate si sa poata reconstitui finalul cartii de vanatoare a lui Hemet Nesingwary.",al={"cine ofera chapter iv","cel care da misiunea chapter iv","cine are nevoie de capitolul 4"}},{q="Ce pagini sunt necesare pentru a incheia Chapter IV?",a="Ai nevoie de paginile douazeci si cinci, douazeci si sase si douazeci si sapte din The Green Hills of Stranglethorn pentru a completa al patrulea capitol.",al={"paginile chapter 4","ce pagini trebuie pentru chapter iv","de ce pagini am nevoie"}},{q="Ce precede aceasta cerere?",a="Aceasta cerere urmeaza dupa primul apel al lui Barnil Stonepot de a aduna frunzele risipite ale lui The Green Hills of Stranglethorn.",al={"cerinte preliminare pentru Chapter IV","misiunea anterioara pentru Chapter 4"}}},fp="10,200,16.337.0,30.133.0,46.124.0,31.119.0"}
P.entries["quest:343"] = {n="Speaking of Fortitude",s="Brother Kristoff pregateste o predica in Cathedral of Light din Stormwind City. Pentru mesajul sau despre Taria Spiritului, cauta o carte in Royal Library din Stormwind Keep.",h="Brother Kristoff pregateste o predica in Cathedral of Light din Stormwind City.",kw={"Brother Kristoff","Cathedral of Light","metalurgie","Milton Sheaf","Royal Library","Speaking of Fortitude","Stormwind Keep","Stresses of Iron"},ang={["class:Priest"]="Ca priest, poti vedea cum clericii din Stormwind imbina mestesugurile de zi cu zi cu devotamentul fata de Light atunci cand predau taria spirituala.",["faction:Alliance"]="Ca membru Alliance, poti vedea legatura dintre preotimea din Cathedral Square si Royal Library din Stormwind Keep, parte a vietii civice si academice a capitalei.",["profession:Blacksmithing"]="Ca fierar, cunosti greutatile muncii la forja. Brother Kristoff intentioneaza sa foloseasca \"Stresses of Iron\" pentru a explica rezistenta sub presiune."},sec={{t="O metafora in metal",b="Brother Kristoff, un Priest din Cathedral of Light din Stormwind, pregateste o predica despre Fortitudinea Spiritului. Vrea sa se inspire din mestesugul prelucrarii metalului, alaturi de scripturi. Pentru a-si sustine ideea, are nevoie de un tratat numit \"The Stresses of Iron.\" Lectiile sale despre rezistenta la presiune i-ar putea ajuta enoriasii sa inteleaga puterea credintei."},{t="Stivele regale",b="Royal Library adaposteste istoriile din Stormwind, scrierile civice si alte lucrari in Stormwind Keep. Rafturile sale contin secole de scrieri, asa ca Brother Kristoff trimite soli la bibliotecarul-sef Milton Sheaf. Sheaf cunoaste arhiva pe de rost si ii poate indruma catre lucrari rare despre mestesuguri."}},faq={{q="Cine este Brother Kristoff?",a="Brother Kristoff este un Priest care slujeste in Church of the Holy Light, in Cathedral Square, Stormwind City. Le cere adesea vizitatorilor sa caute materiale si referinte pentru invataturile si predicile sale.",al={"kristoff","cine da speaking of fortitude","brother kristoff"}},{q="Ce carte cauta Brother Kristoff?",a="Brother Kristoff cauta \"The Stresses of Iron\", un text tehnic despre prelucrarea metalelor pe care intentioneaza sa-l citeze ca metafora a rezistentei spirituale.",al={"ce carte","Stresses of Iron","cartea lui Kristoff"}},{q="Cine este Milton Sheaf?",a="Milton Sheaf este bibliotecarul-sef al Royal Library din Stormwind Keep. El supravegheaza cartile, pergamentele si documentele publice ale regatului si cunoaste bine colectia.",al={"milton sheaf","bibliotecarul din stormwind","bibliotecar-sef"}},{q="Unde se afla Royal Library?",a="Royal Library se afla in aripa de nord-est a Stormwind Keep, la care se ajunge prin sala principala a palatului regal.",al={"locatia bibliotecii din Stormwind","unde este Royal Library","biblioteca din Stormwind Keep"}},{q="De ce are nevoie un Priest de o carte de metalurgie?",a="Brother Kristoff pregateste o predica intitulata \"Fortitude of the Spirit.\" Planuieste sa compare tensiunea la care este supus fierul in timpul fauririi cu felul in care incercarile intaresc spiritul uman.",al={"de ce metalurgia","de ce cartea despre fier","predica despre tarie"}},{q="Are Milton Sheaf cartea gata imediat?",a="Milton Sheaf spune ca biblioteca adaposteste carti despre prelucrarea metalelor, dar trebuie sa verifice titlul exact si sa caute cartea lui Kristoff.",al={"are Sheaf cartea","preda Speaking of Fortitude"}}},fp="21,173,19.344.0,16.292.0,24.189.0,42.140.0,20.170.0,35.110.0,41.170.0,49.142.0"}
P.entries["quest:344"] = {n="Brother Paxton",s="In arhivele regale din Stormwind, Milton Sheaf te trimite la Northshire Abbey dupa un tratat Dwarf disparut. Cartea fusese imprumutata cu luni in urma pentru a fi copiata, dar nu s-a intors pe rafturile orasului.",h="In arhivele regale din Stormwind, Milton Sheaf te trimite la Northshire Abbey dupa un tratat Dwarf disparut.",kw={"brother paxton","margulf blaggon","milton sheaf","northshire abbey","biblioteca Stormwind","the stresses of iron","transcriere"},ang={["class:Priest"]="La Northshire Abbey poti vedea munca erudita a clericilor: copierea cartilor de mana pentru a pastra cunostintele ordinului.",["faction:Alliance"]="Poti vedea legaturile dintre Stormwind si Ironforge in studiul si pastrarea, in bibliotecile Human, a textelor fundamentale ale Dwarves.",["profession:Mining"]="Cartea lui Margulf Blaggon, 'The Stresses of Iron', pastreaza zeci de ani de cunostinte miniere ale Dwarves, adunate din muntii Khaz Modan.",["race:Dwarf"]="Cartea cautata este o lucrare de mestesugarit a Dwarves, scrisa de minerul Margulf Blaggon, iar scribii din Stormwind o pretuiesc indeajuns incat sa caute copii."},sec={{t="Un volum imprumutat",b="Bibliotecarul-sef din Stormwind, Milton Sheaf, are de-a face cu o carte disparuta. 'The Stresses of Iron', un tratat despre tehnici metalurgice scris de prospectorul Dwarf Margulf Blaggon, lipseste de pe rafturile capitalei. Cartea a fost imprumutata cu cateva luni in urma clericilor din Northshire Abbey, ca sa faca o copie. Nu a fost ratacita in Stormwind."},{t="Scribul din Northshire",b="La Northshire Abbey, Brother Paxton ingrijeste biblioteca si cartile ei. Ordinul sacru al clericilor din Northshire pretuieste cunoasterea, dar copierea de mana a unui manuscris tehnic lung cere timp. Paxton recunoaste ca nu a terminat de transcris lucrarea lui Blaggon, asa ca originalul nu s-a intors inca la Stormwind."}},faq={{q="De ce te trimite Milton Sheaf la Northshire Abbey?",a="Milton Sheaf i-a imprumutat lui Brother Paxton, cu cateva luni in urma, exemplarul din 'The Stresses of Iron' al celor din Stormwind, pentru ca abatia sa poata face o copie. Cum nu a primit niciun raspuns si nici cartea inapoi, Sheaf te trimite sa intrebi cum merge copierea.",al={"de ce Brother Paxton","unde este cartea","comisionul lui Milton Sheaf"}},{q="Cine este Brother Paxton?",a="Brother Paxton este un cleric care se ocupa de biblioteca de la Northshire Abbey. El catalogheaza si copiaza de mana carti de pret pentru colectia abatiei.",al={"cine este paxton","povestea lui brother paxton","paxton din northshire"}},{q="Ce este 'Stresses of Iron'?",a="'The Stresses of Iron' este un manual tehnic scris cu zeci de ani in urma de minerul pitic Margulf Blaggon. Acesta consemneaza cunostintele sale despre extragerea minereului si tensiunile metalurgice din adancurile muntilor Khaz Modan.",al={"ce este Stresses of Iron","cartea Stresses of Iron","cartea lui Margulf Blaggon"}},{q="De ce nu a returnat Paxton cartea inca?",a="Brother Paxton inca transcrie manuscrisul de mana pentru rafturile abatiei. Munca indelungata necesita timp si materiale, iar el ezita sa renunte la original inainte sa termine.",al={"de ce a intarziat","de ce dureaza atat de mult Paxton","intarzierea lui Paxton"}},{q="Unde poate fi gasit Brother Paxton?",a="Brother Paxton locuieste in Northshire Abbey, caminul Ordinului Sacru al Clericilor din Northshire, in Northshire Valley, in nordul tinutului Elwynn Forest.",al={"locatia lui paxton","unde se afla brother paxton"}},{q="Ce se intampla dupa ce-l infrunti pe Brother Paxton?",a="Paxton recunoaste ca are cartea si spune ca are nevoie de mai multe materiale de scris ca sa termine de copiat. Te trimite sa aduni cerneala si alte provizii.",al={"urmatoarea misiune dupa Paxton","de ce are nevoie Paxton"}}},fx={["4a96b020"]={q="De ce are Milton Sheaf nevoie de un aventurier care sa-l gaseasca pe Brother Paxton?",a="Milton Sheaf este bibliotecarul-sef din Stormwind, obligat de datorie sa supravegheze Royal Library din Stormwind Keep. Nu-si poate parasi pur si simplu postul ca sa mearga pana in Northshire Valley dupa o carte asteptata de multa vreme. Cand sosesti cerand 'The Stresses of Iron', ii oferi un mesager potrivit, care este deja in calatorie si dispus sa-l caute pe Brother Paxton.",al={"de ce eu, Brother Paxton","de ce are nevoie Milton Sheaf de mine","de ce nu poate Milton sa ia singur cartea"}}},fp="14,191,17.336.0,19.297.0,51.212.0,22.147.0,31.203.0,40.183.0,34.139.0,47.128.1"}
P.entries["quest:3441"] = {n="Divine Retribution",s="Kalaran Windblade iti cere sa-i asculti povestea in Searing Gorge. Tatal sau a fost ucis de ceea ce pandeste in cazan, iar magistratul din Stormwind n-a vrut sa-l asculte. Kalaran cauta razbunare si vrea ca un aventurier sa actioneze in locul sau.",h="Kalaran Windblade iti cere sa-i asculti povestea in Searing Gorge.",kw={"cazan","Dark Iron","Kalaran Windblade","Ragnaros","pedeapsa","Stormwind","razbunare","Windblade"},sec={{t="Un tata ucis",b="Kalaran spune ca mizeria din cazan i-a ucis tatal. A cerut ajutor magistratului din Stormwind, dar rugamintile lui au ramas fara raspuns. Stormwind, spune el, ar prefera sa nu recunoasca nici macar existenta acestei parti a lumii, cu atat mai putin sa trimita soldati pentru a infaptui dreptatea aici."},{t="Un apel la razbunare",b="Kalaran vrea razbunare, pur si simplu. Este singur, in afara de un scutier masiv si greoi, iar Dark Iron dwarves, impreuna cu bestiile lui Ragnaros, l-ar zdrobi fara ajutor. Are incredere ca un aventurier curajos s-ar putea ocupa de locuitorii cazanului si promite bogatii nemaivazute oricui il ajuta."}},faq={{q="Cine este Kalaran Windblade?",a="Kalaran Windblade este un barbat din Searing Gorge al carui tata a fost ucis si care cauta razbunare. Este insotit de un scutier.",al={"cine este kalaran","povestea lui kalaran","lore despre kalaran"}},{q="De ce cauta Kalaran razbunare?",a="Kalaran da vina pe mizeria care traieste in cazan pentru moartea tatalui sau si vrea razbunare.",al={"de ce razbunarea divina","razbunarea lui Kalaran","ce s-a intamplat cu tatal lui Kalaran"}},{q="De ce nu l-a ajutat Stormwind pe Kalaran?",a="Kalaran spune ca magistratul din Stormwind i-a ignorat rugamintile. Potrivit lui, Stormwind nu vrea sa recunoasca existenta acestei parti a lumii, cu atat mai putin sa trimita soldati ca sa infaptuiasca dreptatea.",al={"refuzul Stormwind","de ce nu va ajuta Stormwind","magistratul din Stormwind"}},{q="Ce amenintari mentioneaza Kalaran?",a="Ii numeste pe Dark Iron dwarves si bestiile lui Ragnaros si spune ca oricare dintre ele l-ar coplesi de unul singur.",al={"cine se afla in cazan","dusmanii din cazan","dusmanii lui kalaran"}},{q="Ce promite Kalaran in schimbul ajutorului?",a="Ii promite bogatii si averi dincolo de cele mai indraznete vise oricui il ajuta cu curaj.",al={"oferta lui kalaran","ce ofera kalaran"}}},fp="18,235,14.265.0,20.330.0,25.118.0,35.95.0,34.180.0,34.96.0,47.97.0"}
P.entries["quest:3442"] = {n="The Flawless Flame",s="Kalaran Windblade spune ca ai facut alegerea potrivita si ca lovitura trebuie sa cada acolo unde provoaca cele mai mari pagube: asupra celor patru turnuri de straja. Odata ce toate patru ard, ofensiva poate incepe inainte ca cineva sa aiba timp sa reactioneze. Pentru a le aprinde, Kalaran trebuie sa faureasca torta flacarii fara cusur.",h="Kalaran Windblade spune ca ai facut alegerea potrivita si ca lovitura trebuie sa cada acolo unde provoaca...",kw={"ulei de golem","inima flacarii","kalaran windblade","searing gorge","turnuri de straja","torta flacarii impecabile"},sec={{t="Pregatirea tortiei",b="Dupa Divine Retribution, Kalaran iti spune planul: ardeti cele patru turnuri de straja, ca atacul sa poata incepe inainte ca cineva sa aiba timp sa reactioneze. Pentru a le aprinde e nevoie de unealta potrivita, iar unealta necesita materiale. Kalaran va fauri torta flacarii fara cusur daca ii aduci patru inimi de foc si patru globuri de ulei de golem, si te trimite mai intai la golemii si elementalii acestor tinuturi."}},faq={{q="Care este scopul colectarii acestor materiale?",a="Kalaran Windblade are nevoie de patru inimi de flacara si patru globuri de ulei de golem pentru a fauri torta care va incendia cele patru turnuri de paza.",al={"de ce sa aduni flacara si ulei","scopul flacarii impecabile","motivul pentru torta flacarii impecabile"}},{q="Unde se gasesc componentele necesare?",a="Kalaran te indruma catre golemii si elementalii din Searing Gorge.",al={"unde gasesc ulei de golem","unde gasesc inima flacarilor","locatia materialelor pentru Flawless Flame"}},{q="Ce urmeaza inaintea acestui pas?",a="Urmeaza Divine Retribution, in care ai auzit povestea lui Kalaran Windblade.",al={"conditia prealabila pentru Flawless Flame","misiunea anterioara Flawless Flame"}},{q="De ce sa fie arse turnurile de straja?",a="Kalaran spune ca acolo se pot provoca cele mai mari pagube si ca, odata ce cele patru turnuri vor arde, se poate lansa un atac inainte ca cineva sa aiba timp sa reactioneze.",al={"de ce turnuri de straja","planul turnurilor de straja"}}},fp="18,276,19.396.0,50.136.0,42.65.0,28.75.0,27.143.0"}
P.entries["quest:3443"] = {n="Forging the Shaft",s="Dupa The Flawless Flame, Kalaran Windblade spune ca pentru a tine flacara perfecta sunt necesare atat o tija, cat si o carcasa, iar tija trebuie facuta prima. Sclavii si supraveghetorii Dark Iron din cazan folosesc arme de thorium vrajite, iar opt pumnale placate cu thorium pot fi refacute intr-o tija.",h="Dupa The Flawless Flame, Kalaran Windblade spune ca pentru a tine flacara perfecta sunt necesare atat o tija...",kw={"caldare","sclavagist dark iron","supraveghetor dark iron","flacara fara cusur","kalaran windblade","searing gorge","pumnal placat cu thoriu"},sec={{t="Un aliaj fermecat",b="Kalaran spune ca sunt necesare atat o tija, cat si o teaca pentru a sustine flacara fara cusur. Sclavii si supraveghetorii Dark Irons din cazan lupta cu thorium fermecat, un metal foarte rezistent. Kalaran poate desface cele opt pumnale placate cu thorium ale acestora si poate reface aliajul intr-o tija."},{t="O limba ascutita",b="Cand ii sunt livrate pumnalele, Kalaran nu-ti multumeste, ci doar te ia in ras. Esti numit un muncitor exceptional si esti intrebat daca te-ai gandit vreodata la o alta ocupatie: detectiv, cautator de vechituri sau unul dintre acei Gnome caraghiosi care rascolesc plajele din Azeroth cu dispozitive de detectare a metalelor, in cautarea comorilor pierdute."}},faq={{q="De ce are Kalaran nevoie de pumnale placate cu thorium?",a="Kalaran Windblade le poate descompune aliajul si il poate reforja intr-o tija care sa sustina flacara perfecta.",al={"de ce pumnale","scopul pumnalelor placate cu thorium","de ce pumnale de thorium"}},{q="Cine poarta pumnalele necesare?",a="Sclavii si supraveghetorii Dark Iron din cazan lupta cu arme din thorium vrajit.",al={"cine lasa pumnalele","unde sunt pumnalele","cine are pumnale de thorium"}},{q="Unde se incadreaza acest pas in lantul de misiuni?",a="Urmeaza dupa The Flawless Flame, in care ai adunat materiale pentru torta Flawless Flame.",al={"ce misiune vine inainte de Forging the Shaft","pozitia in lantul de misiuni"}},{q="Cate pumnale sunt necesare?",a="Kalaran cere opt pumnale placate cu thorium.",al={"cate pumnale","numarul pumnalelor","cate pumnale de toriu"}}},fp="17,292,15.297.0,14.320.1,45.105.0,33.90.0,40.95.0,30.46.0"}
P.entries["quest:3444"] = {n="The Stone Circle",s="Marvon Rivetseeker a intrat candva in Sunken Temple si a scapat la limita. O piatra rotunda cu simbolul unui sarpe, aflata acum in atelierul lui Marvon din Ratchet, i-ar putea permite lui Marvon sa-ti spuna mai multe, iar tie ti se cere s-o aduci.",h="Marvon Rivetseeker a intrat candva in Sunken Temple si a scapat la limita.",kw={"marvon rivetseeker","ratchet","statuie-serpente","sunken temple","tanaris","cerc de piatra"},sec={{t="Amintirea lui Marvon",b="Marvon Rivetseeker vorbeste despre raul din Sunken Temple, care se raspandeste asupra tuturor celor ce-i strabat incaperile. Evadarea a fost o lupta prin masa gelatinoasa intinsa acum pe podele, iar ceea ce i-a ramas in minte este o incapere mare si rotunda, plina de statui cu serpi."},{t="Piatra din Ratchet",b="Intre timp, Marvon a dat peste o piatra rotunda care pare sa poarte acelasi simbol al sarpelui. A pus-o intr-o lada si a trimis-o la atelierul din Ratchet. Adu-o acolo, iar Marvon s-ar putea sa aiba mai multe de impartasit."},{t="Cand se intoarce piatra",b="Vazand piatra, Marvon confirma ca este cea potrivita si spune ca isi aminteste totul."}},faq={{q="Cine este Marvon Rivetseeker?",a="Marvon Rivetseeker este cel care te trimite dupa piatra. Marvon a intrat candva in Sunken Temple si abia a reusit sa iasa.",al={"marvon rivetseeker","cine da misiunea stone circle","cel care da misiuni in tanaris"}},{q="Unde se afla cercul de piatra?",a="A fost ambalat intr-o lada si trimis mai departe la atelierul lui Marvon din Ratchet.",al={"unde este cercul de piatra","atelierul cercului de piatra","locatia cercului de piatra"}},{q="De ce vrea Marvon cercul de piatra?",a="Piatra poarta un simbol de sarpe, asemenea statuilor pe care Marvon si le aminteste dintr-o sala rotunda din Sunken Temple. Cu ea in mana, Marvon ar putea spune mai multe.",al={"de ce sa gasesti cercul de piatra","scopul cercului de piatra"}},{q="Ce i s-a intamplat lui Marvon in Sunken Temple?",a="Marvon abia a gasit drumul spre iesire, croindu-si calea prin namolul raspandit pe podele. Tot ce-si aminteste Marvon este ca s-a impiedicat printr-o incapere mare si rotunda, plina de statui de serpi.",al={"marvon si templul scufundat","povestea lui marvon"}}},fp="16,219,15.259.0,20.191.0,22.85.1,26.116.0,26.58.0,38.155.0,45.173.0"}
P.entries["quest:3445"] = {n="The Sunken Temple",s="Angelas Moonbreeze iti povesteste despre Sunken Temple, un loc ingropat adanc sub pamant de forte mai puternice decat orice a vazut Angelas. Ca sa afli mai multe, esti indrumat la un goblin pe nume Marvon Rivetseeker, despre care se stie ca se afla in Tanaris.",h="Angelas Moonbreeze iti povesteste despre Sunken Temple, un loc ingropat adanc sub pamant de forte mai...",kw={"angelas moonbreeze","feralas","marvon rivetseeker","ratchet","sunken temple","tanaris","ruine Troll"},sec={{t="Un loc surghiunit in adancuri",b="Angelas Moonbreeze vorbeste despre un loc scufundat adanc sub suprafata pamantului de forte mai puternice decat oricare vazute de Angelas: Sunken Temple. Pentru mai multe informatii, cauta-l pe goblinul Marvon Rivetseeker, care, la fel ca Angelas si Troyas, a studiat siturile stravechi din intreaga lume. Marvon si-a parasit casa din Ratchet ca sa cerceteze ruinele troll din Tanaris, dar de ceva vreme nu s-a mai auzit nimic despre el."},{t="Ce spune Marvon",b="Cand il gasesti pe Marvon Rivetseeker, spune ca a vazut Sunken Temple cu propriii ochi si te intreaba daca vrei sa afli mai multe. Te crede o fire aventuroasa si spune ca stie lucruri care te-ar putea intriga."}},faq={{q="Cine incepe cautarea pentru Sunken Temple?",a="Angelas Moonbreeze vorbeste despre un loc afundat mult sub pamant, Sunken Temple, asezat acolo de forte mai puternice decat orice a vazut Angelas.",al={"cine da misiunea Sunken Temple","cine ofera misiunea Sunken Temple","Angelas Moonbreeze"}},{q="Cine este Marvon Rivetseeker?",a="Un goblin care, asemenea lui Angelas si Troyas, a studiat situri antice din intreaga lume.",al={"marvon rivetseeker","unde se afla marvon rivetseeker","cine este marvon"}},{q="Unde a plecat Marvon Rivetseeker?",a="Ultimele vesti spun ca a plecat din Ratchet, casa lui, spre Tanaris si ruinele sale troll. Nimeni nu a mai primit vesti de la el de ceva vreme.",al={"locatia lui marvon","unde il gasesc pe marvon","marvon in tanaris"}}},fp="17,231,22.397.0,16.221.1,44.143.0,26.90.0,32.117.0"}
P.entries["quest:345"] = {n="Ink Supplies",s="Ink Supplies este o misiune a Alliance in numele lui Brother Paxton, un copist monah care locuieste in Northshire Abbey. Avand nevoie de un ingredient mineral special pentru a-si prepara cerneala care se usuca repede, Paxton trimite un aventurier spre est, in asezarea asediata Lakeshire, ca sa obtina minereu Rethban de la Foreman Oslow.",h="Ink Supplies este o misiune a Alliance in numele lui Brother Paxton, un copist monah care locuieste in...",kw={"brother paxton","foreman oslow","rechizite pentru cerneala","lakeshire","northshire abbey","redridge mountains","minereu rethban","the stresses of iron"},ang={["class:Priest"]="Ca Priest, poti ajuta clerul cu munca sa de cercetare. Sarcina lui Brother Paxton urmeaza predica lui Brother Kristoff despre Taria Spiritului.",["faction:Alliance"]="Ca drumet din Alliance, vezi contrastul dintre izolarea linistita a Northshire Abbey si violenta care ameninta Lakeshire.",["profession:Mining"]="Ca miner, poti cauta minereu de fier Rethban, gasit sus, in povarnisurile abrupte din Redridge."},sec={{t="Formula unui scrib",b="Brother Paxton este mandru de mestesugul sau si foloseste o cerneala speciala pentru scrieri importante, precum The Stresses of Iron. Reteta sa se usuca repede si nu se intinde, dar cerneala se poate usca in vas daca este lasata prea mult. Pentru a prepara mai multa, are nevoie de minereu brut de fier Rethban, extras din stancii Redridge Mountains."},{t="Un oras sub asediu",b="Lakeshire nu prea are timp pentru cererea unui scrib aflat departe. Foreman Oslow ii supravegheaza pe muncitorii ocupati cu intarirea baricadelor, reconstruirea cladirilor ruinate si apararea orasului de raidurile continue ale Orc Blackrock. Neavand muncitori disponibili pentru minerit, calatorii trebuie sa caute singuri minereul in primejdioasele Rethban Caverns."}},faq={{q="De ce are nevoie Brother Paxton de minereu de fier pentru cerneala?",a="Brother Paxton are nevoie de minereu de fier din Rethban pentru a-si prepara cerneala speciala. Minereul macinat furnizeaza pigmentul mineral si proprietatile de intarire care dau cernelii o scriere cu uscare rapida si rezistenta la intindere.",al={"de ce fier pentru cerneala","minereul lui paxton pentru cerneala","reteta de cerneala a Brother Paxton"}},{q="Cine este Foreman Oslow?",a="Foreman Oslow supravegheaza constructiile si reparatiile publice din Lakeshire. In timp ce orcii Blackrock ameninta orasul, el ii coordoneaza reconstructia si fortificarea.",al={"Foreman Oslow","Oslow din Lakeshire","cine este Oslow"}},{q="Unde te trimite Brother Paxton?",a="Paxton te trimite spre est, din Elwynn Forest la Lakeshire, in Redridge Mountains, ca sa-l gasesti pe Foreman Oslow.",al={"destinatia proviziilor de cerneala","unde se afla oslow","unde merg pentru provizii de cerneala"}},{q="De ce nu-ti da pur si simplu minereul Foreman Oslow?",a="Atacurile orcilor din Blackrock mentin Lakeshire sub presiune. Muncitorii lui Oslow sunt ocupati cu repararea cladirilor avariate si fortificarea orasului, asa ca nu mai are cine sa mineze.",al={"de ce nu exista minereu","Oslow refuza minereul","de ce este Oslow furios"}},{q="Ce carte incearca Brother Paxton sa copieze?",a="Brother Paxton copiaza Stresses of Iron. Munca sa s-a oprit cand precedentul sau amestec de cerneala cu uscare rapida s-a solidificat in recipient.",al={"cartea lui paxton","ce copiaza paxton","The Stresses of Iron"}},{q="Ce se intampla dupa ce vorbesti cu Foreman Oslow?",a="Foreman Oslow iti spune sa aduni singur minereu de fier Rethban din periculoasele Rethban Caverns, la nord de Lake Everstill.",al={"urmatoarea misiune dupa proviziile de cerneala","ce urmeaza dupa oslow","continuarea misiunii proviziile de cerneala"}}},fx={["3b01bf84"]={q="De ce vrea Brother Paxton sa aduci minereu Rethban?",a="Brother Paxton se dedica copierii tratatului savant The Stresses of Iron pentru biblioteca Northshire Abbey. Insista sa-si prepare singur cerneala speciala, care se bazeaza pe minereu de fier Rethban macinat, pentru a se usca repede si a nu se intinde. Din pacate, ultimul lui lot s-a uscat complet inainte sa termine transcrierea, lasandu-i proiectul in impas pana la sosirea unor minerale proaspete.",al={"de ce are Brother Paxton nevoie de minereu","motivul lui Brother Paxton","de ce are nevoie de provizii de cerneala"}},c7dba9bc={q="De ce te trimite Brother Paxton in loc sa mearga el insusi dupa minereu?",a="Brother Paxton este un copist devotat, a carui datorie il tine intre zidurile izolate ale Northshire Abbey. Calatoria pana la Lakeshire, in Redridge Mountains, depaseste cu mult rutina sa monahala linistita, mai ales ca drumurile devin tot mai primejdioase. Fiind deja un aventurier capabil, aflat in calatorie prin tinut, poti duce cu usurinta un mesaj persoanei cu care ia de obicei legatura.",al={"de ce nu poate paxton obtine minereul","de ce sa trimita un aventurier","de ce eu sa aduc provizii de cerneala"}}},fp="12,176,18.295.0,18.318.0,46.180.0,21.151.0,35.104.0,46.164.0,47.137.0,47.118.0"}
P.entries["quest:3452"] = {n="The Flame's Casing",s="Dupa Forging the Shaft, Kalaran Windblade spune ca mai e nevoie de o ultima piesa pentru torta. La nord-vest se afla o tabara mare a Twilight's Hammer, unde se zvoneste ca exista simboluri si idoli in cinstea zeului sau, iar Kalaran vrea un singur Symbol of Ragnaros.",h="Dupa Forging the Shaft, Kalaran Windblade spune ca mai e nevoie de o ultima piesa pentru torta.",kw={"teaca flacarii","kalaran windblade","searing gorge","symbol of ragnaros","torch of retribution","twilight's hammer"},sec={{t="O piesa pentru carcasa",b="Kalaran spune ca aceasta este ultima piesa de care are nevoie torta. Se zvoneste ca, in munti, spre nord-vest, o tabara mare a Twilight's Hammer adaposteste simboluri si idoli in cinstea zeului lor, care ar putea avea suficienta vraja pentru o carcasa magica. Kalaran cere un Symbol of Ragnaros si va incerca sa extraga magia din el. Torch of Retribution are nevoie de un singur lucru: o sursa potrivita de energie arcana."},{t="Simbolul cercetat",b="Simbolul emana o magie respingatoare, pe care Kalaran o considera ideala pentru aceasta treaba."}},faq={{q="De ce este nevoie pentru a crea invelisul flacarii?",a="Kalaran Windblade cere un singur Symbol of Ragnaros, din care se poate extrage magia necesara pentru a forma invelisul.",al={"obiectul flames casing","de ce are nevoie kalaran","simbolul necesar"}},{q="Unde se afla tabara Twilight's Hammer?",a="Kalaran spune ca in munti, la nord-vest, se afla o tabara mare a Twilight's Hammer.",al={"locatia Twilight's Hammer","unde este tabara cultului","cultul din muntii nord-vestici"}},{q="De ce vrea Kalaran un Symbol of Ragnaros?",a="Simbolurile si idolii lui Twilight's Hammer ar putea avea suficienta vrajitorie pentru a alcatui o carcasa magica, iar Kalaran spera sa extraga acea magie dintr-unul dintre ei.",al={"de ce symbol of ragnaros","scopul simbolului lui ragnaros","ce face simbolul"}},{q="Ce precede aceasta etapa din lant?",a="Aceasta urmeaza dupa Forging the Shaft, in care Kalaran a cerut pumnale placate cu thorium pentru a le reforja intr-o tija.",al={"misiunea anterioara","ce misiune preceda flames casing"}}},fp="18,247,22.399.0,19.74.1,44.105.0,42.89.0,43.148.0,41.104.0"}
P.entries["quest:3453"] = {n="The Torch of Retribution",s="Dupa The Flame's Casing, Kalaran Windblade iti cere sa astepti pana cand piesele sunt imbinate si torta este fermecata. Lucrarea presupune canalizarea energiei si nu trebuie intrerupta.",h="Dupa The Flame's Casing, Kalaran Windblade iti cere sa astepti pana cand piesele sunt imbinate si torta este...",kw={"canalizare","vraja","kalaran windblade","searing gorge","torch of retribution"},sec={{t="Legarea fragmentelor",b="Dupa ce aduni piesele, Kalaran are nevoie de un moment ca sa le uneasca si sa puna descantecele necesare pe torta. Lucrarea presupune canalizarea unei vraji care nu trebuie intrerupta, asa ca astepti cat timp Kalaran o rosteste."},{t="Cand se termina asteptarea",b="Dupa o vreme, torta apare in fata lui Kalaran, care spune ca este gata. Kalaran adauga ca mai ramane un ultim lucru de care trebuie sa te ocupi."}},faq={{q="Cine confectioneaza torta?",a="Kalaran Windblade imbina piesele si aplica vrajile, canalizand magia pentru a termina torta.",al={"mesterul facliilor","cine face faclia","rolul lui kalaran windblade"}},{q="Ce a avut loc chiar inaintea acestui pas?",a="The Flame's Casing, in care ai gasit un Symbol of Ragnaros pe care Kalaran sa-l transforme in invelis.",al={"misiunea anterioara","conditie preliminara","ce am facut tocmai acum"}},{q="De ce nu trebuie sa-l intrerupi pe Kalaran?",a="Kalaran canalizeaza energia si te avertizeaza sa nu intrerupi procesul in timp ce piesele sunt imbinate.",al={"nu intrerupe","procesul de canalizare"}}},fp="24,169,18.195.0,18.137.1,21.105.0,33.96.0,35.96.0"}
P.entries["quest:3454"] = {n="The Torch of Retribution",s="Dupa ce faceti torta, Kalaran Windblade spune ca acum trebuie sa aiba un stapan de care sa fie legata si va spune sa o ridicati.",h="Dupa ce faceti torta, Kalaran Windblade spune ca acum trebuie sa aiba un stapan de care sa fie legata si va...",kw={"legare","kalaran windblade","searing gorge","torch of retribution"},sec={{t="Legarea flacarii",b="Kalaran spune ca torta trebuie legata de proprietarul ei. Pentru asta, ti se spune sa o iei tu."},{t="Torta in mana",b="Apuci torta cu ambele maini, iar ura si furia te strabat in valuri."}},faq={{q="Cine iti spune sa iei torta?",a="Kalaran Windblade, care spune ca trebuie legat de proprietarul sau.",al={"cine ofera torta","cel care da misiunea cu torta","torta lui kalaran"}},{q="De ce trebuie sa ridici torta?",a="Kalaran spune ca torta trebuie legata de stapanul ei si iti spune sa o ridici.",al={"de ce sa ridici torta","legarea cu ajutorul tortei"}},{q="Unde se incadreaza acest pas in lantul de misiuni?",a="Urmeaza dupa pasul Torch of Retribution, in care ai asteptat cat timp Kalaran a asamblat bucatile si le-a vrajit.",al={"lant de misiuni cu torta","misiunea anterioara"}}},fp="24,110,17.103.0,17.82.1,32.62.0,31.79.0,40.123.0"}
P.entries["quest:346"] = {n="Return to Kristoff",s="Brother Kristoff asteapta la Stormwind sa-i fie inapoiata o carte imprumutata. Dupa o cautare indelungata si o intarziere in Northshire, duci The Stresses of Iron inapoi la Cathedral of Light.",h="Brother Kristoff asteapta la Stormwind sa-i fie inapoiata o carte imprumutata.",kw={"brother kristoff","brother paxton","cathedral square","milton sheaf","northshire abbey","return to kristoff","stormwind","the stresses of iron"},ang={["class:Priest"]="Ca Priest, vezi cum Church of the Holy Light pastreaza si raspandeste cunostinte importante in tot regatul.",["faction:Alliance"]="Ca membru al Alliance, te bazezi pe drumuri sigure care leaga Stormwind Keep, Northshire si Redridge Mountains, aflate sub asediu."},sec={{t="O intoarcere mult intarziata",b="Brother Kristoff asteapta in Cathedral Square The Stresses of Iron, o carte despre metalurgie. Firul ei a dus de la Royal Library din Stormwind Keep la Northshire Abbey, unde Brother Paxton copia textul de mana. Paxton a ramas fara minereu Rethban pentru cerneala scribului, asa ca lucrarea s-a oprit. Dupa ce minereul a fost recuperat si copia terminata, aduci cartea originala inapoi la Stormwind."},{t="Munca scribilor",b="Copistii din Northshire pastreaza cu rabdare cunostintele civice si spirituale. Brother Paxton iti cere sa-ti ceri scuze de la bibliotecarul Milton Sheaf, semn ca resursele manastirii au ajuns la limita. Scribii trebuie sa copieze cu atentie, trasatura cu trasatura, cartile pretioase, folosind cerneala bogata in minerale, inainte de a le inapoia in grija Stormwind. Astfel, o cerere de carte devine o indatorire indelungata."}},faq={{q="Despre ce este cartea The Stresses of Iron?",a="Stresses of Iron este un tratat despre metalurgie si prelucrarea metalelor. Brother Kristoff l-a cautat pentru studiu in Cathedral Square, iar scribii din Northshire Abbey aveau nevoie de o copie pentru a-i pastra cunostintele.",al={"ce este Stresses of Iron","cartea Stresses of Iron","ce carte cauta Kristoff"}},{q="De ce se afla cartea la Northshire Abbey?",a="Royal Library i-a imprumutat The Stresses of Iron lui Brother Paxton, ca sa faca o copie ilustrata pentru arhivele din Northshire Abbey. Lucrul sau a stagnat cand a ramas fara minereu Rethban, necesar pentru cerneala speciala.",al={"de ce tinea Paxton cartea","de ce era in Northshire"}},{q="Cine este Brother Kristoff?",a="Brother Kristoff face parte din Clergy of the Holy Light si este trimis in Cathedral Square, in fata Cathedral of Light din Stormwind. A cerut cartea si ofera binecuvantari spirituale in semn de recunostinta.",al={"cine este kristoff","kristoff Stormwind"}},{q="Cine este Milton?",a="Milton Sheaf este bibliotecarul-sef al Royal Library din Stormwind Keep. A permis imprumutul volumului The Stresses of Iron si a devenit nerabdator din cauza intarzierii indelungate a returnarii lui.",al={"cine este bibliotecarul Milton","Milton Sheaf"}},{q="Unde incepe acest lant de misiuni?",a="Sirul incepe in Cathedral Square din Stormwind, unde Brother Kristoff ofera Speaking of Fortitude. De acolo, duce la Librarian Milton Sheaf, apoi la Northshire Abbey si Redridge Mountains, inainte de a te aduce inapoi la Kristoff.",al={"cum incepi Speaking of Fortitude","inceputul lantului de misiuni"}},{q="Aceasta misiune are vreo continuare?",a="Return to Kristoff incheie seria Speaking of Fortitude. Cand predai The Stresses of Iron, Brother Kristoff iti multumeste si iti ofera o binecuvantare a Light.",al={"ce urmeaza dupa Return to Kristoff","exista o misiune urmatoare"}}},fx={["46830297"]={q="De ce vrea Brother Paxton ca volumul sa-i fie inapoiat lui Brother Kristoff?",a="Brother Paxton a imprumutat The Stresses of Iron doar ca sa-i copieze continutul la Northshire Abbey. Acum ca a terminat transcrierea, nu mai are niciun drept asupra rarului volum si trebuie sa-l inapoieze in siguranta la Cathedral of Light din Stormwind, sperand sa repare orice neplacere provocata de intarzierea sa indelungata.",al={"de ce sa returnezi Stresses of Iron","motivul lui Brother Paxton","de ce sa-i trimiti cartea inapoi lui Kristoff"}}},fp="18,181,21.385.0,20.350.0,44.198.0,37.202.0,24.205.0,14.169.0,34.222.0,36.159.0"}
P.entries["quest:3462"] = {n="Squire Maltrake",s="Dupa The Torch of Retribution, Kalaran Windblade te trimite mai departe la Squire Maltrake, un emisar de-al lor. Maltrake iti va spune cum trebuie folosita torta.",h="Dupa The Torch of Retribution, Kalaran Windblade te trimite mai departe la Squire Maltrake, un emisar de-al...",kw={"emisar","kalaran windblade","searing gorge","squire maltrake","torch of retribution"},sec={{t="O discutie cu emisarul",b="Kalaran Windblade te trimite la Squire Maltrake, un emisar. Maltrake iti va explica felul in care trebuie folosita Torch of Retribution."}},faq={{q="Cine te trimite la Squire Maltrake?",a="Kalaran Windblade, care il numeste pe Maltrake emisar si iti spune sa mergi sa-i asculti instructiunile.",al={"cine ofera squire maltrake","cel care da misiunea squire maltrake","cine incepe squire maltrake"}},{q="Care este rolul lui Squire Maltrake?",a="Maltrake este trimisul numit de Kalaran Windblade si te va invata cum trebuie folosit Torch of Retribution.",al={"ce face Squire Maltrake","cine este Maltrake","de ce sa vorbesti cu Maltrake"}},{q="Ce urmeaza inainte de a vorbi cu Squire Maltrake?",a="Torch of Retribution, pasul anterior din acelasi lant.",al={"cerinta prealabila pentru squire maltrake","ce misiune preceda squire maltrake","misiunea anterioara maltrake"}}},fp="15,154,21.143.0,33.95.0,31.115.0,46.63.0"}
P.entries["quest:3463"] = {n="Set Them Ablaze!",s="Squire Maltrake iti spune ca cele patru turnuri din Searing Gorge nu pot fi distruse niciodata, dar Torch of Retribution le poate tine in flacari foarte mult timp. Cat timp ard, niciun paznic sau strajer nu poate ramane la posturile de observatie, iar Dark Irons isi pierd prima linie de aparare.",h="Squire Maltrake iti spune ca cele patru turnuri din Searing Gorge nu pot fi distruse niciodata, dar Torch of...",kw={"dark iron","searing gorge","turnuri de straja","da-le foc","squire maltrake","torch of retribution"},sec={{t="Un foc pe care nicio forta nu-l poate potoli",b="Flacarile aprinse de torta nu pot fi stinse de niciun element sau de vreo forta. Maltrake te trimite in fiecare dintre cele patru turnuri de straja, North, South, East si West, pentru a folosi torta intre zidurile lor. Dark Iron au pus strajeri in turnuri, iar Maltrake te avertizeaza sa te feresti de ei."},{t="Dupa ultima flacara",b="Dupa ce ultimul turn arde, te intorci la Maltrake si il auzi strigand triumfator catre un stapan. Velarok the Deceiver ii raspunde si se arata in forma unui drake din black dragonflight. Planul lui, se lauda el, a mers perfect, fiindca n-ai fi ajutat niciodata legiunea Blackrock daca ti-ar fi cerut-o pur si simplu. Cand Maltrake se intreaba ce sa faca acum cu tine, Velarok il reduce la tacere: vei trai ca sa privesti invazia legiunii Blackrock in defileu. Il pune pe Maltrake sa-ti dea maruntisuri, vorbeste despre naparlire si isi ia zborul spre defileu."}},faq={{q="Cine te trimite sa dai foc turnurilor?",a="Squire Maltrake o face si iti pune la dispozitie Torch of Retribution pentru aceasta treaba.",al={"cine ofera set them ablaze","cine da misiunea set them ablaze","misiunea lui maltrake"}},{q="Ce turnuri trebuie aprinse?",a="Cele patru turnuri de veghe: nord, sud, est si vest. Trebuie sa intri in fiecare si sa folosesti torta inauntru.",al={"care turnuri","locatiile turnurilor de paza","incendiaza turnurile"}},{q="De ce sa folosesti Torch of Retribution in loc sa darami turnurile?",a="Turnurile nu pot fi distruse niciodata. In schimb, torta le face sa arda veacuri intregi, cu flacari pe care niciun element sau forta nu le poate potoli.",al={"de ce torta","distruge turnurile de paza"}},{q="Care a fost pasul anterior acestuia?",a="Dupa ce vorbesti cu Squire Maltrake, acesta iti da insarcinarea.",al={"da-le foc, conditie prealabila","misiunea anterioara"}}},fp="16,269,26.287.0,20.520.1,39.75.0,29.101.0,68.125.0,43.67.0"}
P.entries["quest:347"] = {n="Rethban Ore",s="Foreman Oslow te trimite in Rethban Caverns din Redridge sa cauti un mineral intunecat de care au nevoie scribii de la Northshire Abbey pentru cerneala. Este prea moale pentru arme sau armuri rezistente, dar culoarea il face folositor pentru munca lor.",h="Foreman Oslow te trimite in Rethban Caverns din Redridge sa cauti un mineral intunecat de care au nevoie...",kw={"bart rethban","brother paxton","foreman oslow","northshire abbey","redridge drudgers","rethban caverns","rethban ore","stresses of iron"},ang={["faction:Alliance"]="Ca un calator Alliance, poti vedea cat de intinse sunt liniile de aprovizionare ale Kingdom of Stormwind: scribii manastirii se bazeaza pe calatori pentru a aduce materiale de scris din zonele de razboi.",["profession:Mining"]="Ca miner, poti scoate Rethban Ore din filoanele pesterilor cu un tarnacop, in loc sa aduni bucati brute de la gnoll drudgers.",["race:Human"]="Ca human din Stormwind, impartasesti cu invatatii din Stormwind datoria de a pastra manuscrisele de la Northshire Abbey si de a readuce la lumina cunostintele pierdute in timpul First War si Second War."},sec={{t="Un mineral neobisnuit",b="Scribii de la Northshire Abbey apreciaza Rethban Ore pentru culoarea sa inchisa si plata. Bart Rethban a descoperit minereul, dar acesta este putin folositor la nicovala unui armurier. Metalul topit din minereu nu are rezistenta necesara pentru arme trainice sau armuri de placi. Culoarea bruta il face insa o baza pretuita pentru vopselele de manuscris."},{t="Pesteri disputate",b="Zacamintele principale se afla in muntii nordici din Redridge, in Rethban Caverns. Pietrarii din Lakeshire au parasit pestera, alungati de o haita feroce de gnoll-i din Redridge. Gnoll-ii ii pun pe truditori sa scoata minereu din filoanele stancoase, pentru propriile lor scopuri rudimentare."},{t="Pastrarea cuvantului",b="Brother Paxton, un calugar de la Northshire Abbey, are nevoie de pigment pentru a copia texte istorice. Munca sa la The Stresses of Iron s-a oprit in lipsa vopselei potrivite. Acum, mesageri si aventurieri strabat tinuturile stapanite de gnolli pentru a-i aduce piatra bruta."}},faq={{q="La ce se foloseste Rethban Ore?",a="Rethban Ore topit este prea slab pentru arme sau armuri rezistente, dar culoarea sa intunecata si mata il face o baza folositoare pentru cerneluri si vopsele. Brother Paxton si alti scribi de la Northshire Abbey il folosesc pentru a copia manuscrise istorice.",al={"de ce avem nevoie de minereul Rethban","la ce foloseste minereul Rethban","pentru ce este minereul Rethban"}},{q="Cine a fost Bart Rethban?",a="Bart Rethban a fost exploratorul si prospectorul care a descoperit filoanele de minereu intunecat din muntii nordici ai Redridge. Mineralul si Rethban Caverns isi trag numele de la el.",al={"cine a descoperit minereul din Rethban","povestea lui Bart si a Rethbanului"}},{q="De ce nu a mai extras Lakeshire minereul in ultima vreme?",a="Foreman Oslow si muncitorii din Lakeshire sunt ocupati cu apararea orasului impotriva incursiunilor orcilor Blackrock. Gnollii din Redridge au ocupat, de asemenea, Rethban Caverns si i-au alungat pe minerii civili.",al={"de ce nu extrage Oslow minereul","de ce sunt minele abandonate"}},{q="Ce carte copiaza Brother Paxton?",a="Brother Paxton copiaza The Stresses of Iron. Are nevoie de vopseaua inchisa la culoare obtinuta din Rethban Ore pentru a termina textul destinat bibliotecii abatiei.",al={"ce carte scrie Paxton","manuscrisul lui Paxton"}},{q="De ce vor gnoll-ii minereul?",a="Gnolls din Redridge ii pun pe sapatorii lor sa sape prin toate cavernele. S-ar putea sa doreasca minereul pentru unelte grosolane, pentru comert sau ca sa-si fortifice vizuinile din munti impotriva intrusilor.",al={"de ce mineaza gnolii","hamalii gnolli din Rethban"}},{q="Unde duce mai departe acest lant de misiuni?",a="Dupa ce Brother Paxton primeste minereul si isi pregateste cernelurile, te trimite inapoi in Stormwind ca sa-i raportezi lui Kristoff succesul, ducand la capat treaba scribilor din Northshire.",al={"ce misiune urmeaza dupa minereul Rethban","urmatoarea misiune Return to Kristoff"}}},fx={["86e7e5db"]={q="De ce vrea Foreman Oslow ca acest lucru sa fie facut?",a="Foreman Oslow nu cauta minereu pentru el sau pentru constructorii din Lakeshire. Brother Paxton de la Northshire Abbey te-a trimis la Oslow sa faci rost de minereu Rethban pentru cerneala folosita la legarea cartilor. Oslow doar indeplineste cererea indrumandu-te spre locul de unde se poate obtine, fiindca rezervele orasului s-au epuizat, iar muncitorii sai nu au timp sa-l sape.",al={"motivul lui Foreman Oslow","de ce are Oslow nevoie de minereu","de ce il ajuta Oslow pe Paxton"}},fa5d21e9={q="Cine ocupa Rethban Caverns?",a="Gnolii din Redridge au invadat Rethban Caverns, la nord de Lakeshire. In loc sa le lase nefolosite, gnolii mineri au inceput sa sape dupa filoanele de minereu intunecat, pentru propriile scopuri, alungand cu forta orice miner local care incearca sa se apropie.",al={"dusmani din Rethban Caverns","cine se afla in Rethban Caverns","gnollii din pesterile Redridge"}}},fp="11,211,17.300.0,17.277.0,19.246.0,29.215.0,21.179.0,44.191.0,36.137.0,27.170.0,38.177.1"}
P.entries["quest:348"] = {n="Stranglethorn Fever",s="In Booty Bay, Fin Fizracket zace bolnav de Stranglethorn Fever, un virus mortal. Spune ca singurul leac este inima lui Mokk the Savage, o fiara alba greu de gasit, si ca e pe moarte.",h="In Booty Bay, Fin Fizracket zace bolnav de Stranglethorn Fever, un virus mortal.",kw={"Booty Bay","Fin Fizracket","Heart of Mokk","Mokk the Savage","Stranglethorn Fever","Stranglethorn Vale","Witch Doctor Unbagwa"},sec={{t="Un leac disperat",b="Fin Fizracket vorbeste balbait si abia mai poate sta in picioare, convins ca a contractat Stranglethorn Fever. Spune ca singurul leac este sa manance inima lui Mokk the Savage, o bestie alba greu de gasit. Numai Witch Doctor Unbagwa poate chema creatura, iar Fin te trimite sa-l gasesti pe Unbagwa intr-o pestera ascunsa de pe capul sudic, Spirit Den."},{t="Inapoi langa Fin",b="Odata ce inima lui Mokk ajunge in mainile lui Fin, puterile lui incep sa revina. Se trezeste nedumerit, nestiind unde se afla, iar cand afla ca este in Booty Bay, povesteste despre un vis straniu. Inca mai persista o parte din slabiciune."}},faq={{q="De ce boala sufera Fin Fizracket?",a="Fin spune ca are Stranglethorn Fever, un virus mortal. Il lasa cuprins de frig si delir, iar el crede ca moare.",al={"ce boala are Fin","boala Stranglethorn Fever","Fin Fizracket este bolnav"}},{q="De ce este nevoie pentru a vindeca febra?",a="Fin spune ca singurul leac este sa mananci inima lui Mokk the Savage, o bestie alba greu de gasit.",al={"cum se vindeca Stranglethorn Fever","leac pentru Fin Fizracket","leac pentru inima lui Mokk"}},{q="Cine este Witch Doctor Unbagwa?",a="Fin spune ca Witch Doctor Unbagwa este singurul care il poate invoca pe Mokk the Savage. Acesta se afla intr-o pestera ascunsa pe capul sudic, Spirit Den din Stranglethorn Vale.",al={"unde se afla unbagwa","cine il poate invoca pe mokk","rolul vrajitorului voodoo unbagwa"}},{q="Unde poate fi gasit Fin Fizracket?",a="Fin Fizracket se afla in Booty Bay.",al={"locatia lui fin fizracket","unde este fin fizracket","omul cu febra din booty bay"}}},fp="19,180,16.325.0,18.210.1,45.115.0,35.86.0,28.166.0,33.30.0"}
P.entries["quest:3481"] = {n="Trinkets...",s="Dupa Set Them Ablaze!, te asteapta un cufar numit Hoard of the Black Dragonflight in Searing Gorge. Pare incuiat.",h="Dupa Set Them Ablaze!, te asteapta un cufar numit Hoard of the Black Dragonflight in Searing Gorge.",kw={"prada Black Dragonflight","Searing Gorge","dati-le foc","obiecte de podoaba"},sec={{t="Un cufar incuiat",b="Hoard of the Black Dragonflight pare sa fie incuiata, iar deschiderea ei iti revine tie. Cufarul apare dupa ce turnurile din Searing Gorge sunt cuprinse de flacari."},{t="La atingerea ta",b="Cufarul se deschide la atingerea ta, fara sa fie nevoie de cheie. Inauntru se afla o naparlire de dragon negru. Un gand trecator se intreaba cata branza ar putea incapea acolo, iar singura cale de a afla este sa te uiti."}},faq={{q="Ce este Hoard of the Black Dragonflight?",a="Un cufar din Searing Gorge, care apare dupa Set Them Ablaze!. Pare sa fie incuiat.",al={"ce este Hoard of the Black Dragonflight","cine detine cufarul","locatia cufarului cu obiecte de podoaba"}},{q="Ce trebuie sa preceada cufarul?",a="Set Them Ablaze!, incendierea turnurilor din Searing Gorge.",al={"cerinta prealabila pentru trinkets","misiunea anterioara","ce duce la trinkets"}},{q="Ce ti se cere sa faci cu cufarul?",a="Deschide-l. Cufarul pare incuiat, dar ti se cere doar sa-l deschizi.",al={"este incuiat cufarul","cum deschid cufarul","ce fac cu cufarul"}}},fp="11,123,14.153.0,13.192.1,44.84.0,28.71.0,40.76.0"}
P.entries["quest:349"] = {n="Stranglethorn Fever",s="In adancul Stranglethorn Vale, Witch Doctor Unbagwa sustine ca stie cum sa scoata la iveala bestia numita Mokk the Savage. Inainte sa inceapa comuniunea cu spiritele, witch doctor-ul cere zece colti de gorila drept ofranda. Cand incepe ritualul, este nevoie sa-l aperi pe troll de fiarele agitate ale junglei, ca sa atragi creatura afara.",h="In adancul Stranglethorn Vale, Witch Doctor Unbagwa sustine ca stie cum sa scoata la iveala bestia numita...",kw={"colt de gorila","Mokk the Savage","Stranglethorn Fever","Stranglethorn Vale","Unbagwa","Witch Doctor"},sec={{t="Un ritual pentru salbatic",b="Witch Doctor Unbagwa cunoaste ritualul necesar pentru a-l invoca pe Mokk the Savage din jungla inconjuratoare. Pentru a incepe incantatia, witch doctor-ul cere zece colti de gorila. Comuniunea cu spiritele presupune un risc major, caci cantarea ritualica atrage atentia gorilelor din apropiere, asa ca este nevoie de protectie cat timp magia isi face efectul."}},faq={{q="Cine este Witch Doctor Unbagwa?",a="Witch Doctor Unbagwa este un practicant troll din Stranglethorn Vale care sustine ca vorbeste cu spiritele pentru a-l atrage pe marele Mokk the Savage.",al={"Unbagwa","cine este Unbagwa","Witch Doctor Unbagwa"}},{q="De ce are nevoie Witch Doctor Unbagwa pentru a incepe?",a="Doctorul vrajitor cere zece colti de gorila inainte sa accepte sa vorbeasca cu spiritele.",al={"misiune cu colti de gorila","ce obiect trebuie sa-i aduci lui unbagwa","cerintele lui unbagwa"}},{q="De ce trebuie aparat witch doctor-ul?",a="Vorbirea cu spiritele atrage celelalte bestii gorilla din apropiere. Unbagwa nu poate incheia comuniunea pentru a-l invoca pe Mokk daca este coplesit de aceste bestii.",al={"de ce sa-l aperi pe unbagwa","aparati-l pe vrajitorul voodoo unbagwa","ritualul bestiilor gorilla"}},{q="Cine este Mokk the Savage?",a="Mokk the Savage este o gorila impunatoare care bantuie Stranglethorn Vale si pe care Witch Doctor Unbagwa stie cum s-o invoce.",al={"mokk","cine este mokk","mokk the savage"}}},fp="19,340,23.367.0,28.142.0,48.86.0,38.150.0,23.120.0"}
P.entries["quest:35"] = {n="Further Concerns",s="Marshal Dughan trimite un curier al Alliance spre est, plecand din Goldshire, pentru a verifica vestile despre pericol. Traversezi Elwynn Forest ca sa vorbesti cu Guard Thomas, care pazeste trecerea peste rau spre Redridge.",h="Marshal Dughan trimite un curier al Alliance spre est, plecand din Goldshire, pentru a verifica vestile...",kw={"podul estic","elwynn forest","further concerns","goldshire","guard thomas","marshal dughan","murloc"},ang={["faction:Alliance"]="Pentru Alliance, apararea slaba din apropierea capitalei dezvaluie fisuri tot mai mari in capacitatea de operare a Kingdom of Stormwind.",["race:Human"]="Ca Human din Elwynn, te confrunti cu murlocii a caror raspandire ameninta fermele-granare si rutele comerciale care leaga Goldshire de Lakeshire."},sec={{t="Cu ochii pe trecatoarea estica",b="Zvonurile vorbesc despre creaturi acvatice ostile care se furiseaza pe malurile raurilor din Elwynn. Marshal Dughan conduce garnizoana din Goldshire, unde banditismul si daunatorii pun deja probleme in centrul padurii. Nu respinge relatarile, dar nu poate lipsi orasul de garzi. In schimb, te trimite spre est sa-l consulti pe Guard Thomas, santinela de la podul peste raul care duce spre Redridge."},{t="O frontiera intinsa la limita",b="Guard Thomas pazeste avanpostul de la pod de mai bine de o saptamana si a vazut ce doar se temeau conducatorii din Goldshire. Murloci ostili, seminteligenti, si-au facut tabere de-a lungul cailor navigabile din estul Elwynn. Armata Stormwind lipseste, iar garnizoanele locale apara zidurile oraselor si liniile de aprovizionare. Astfel, posturile rurale de la pod, precum cel al lui Thomas, sunt izolate in fata pericolului tot mai mare."}},faq={{q="De ce ma trimite Marshal Dughan la Guard Thomas?",a="Marshal Dughan te trimite la Guard Thomas, deoarece rapoartele spun ca murloc se strecoara in caile navigabile din est. Thomas este stationat de o saptamana la podul estic din Elwynn, asa ca Dughan are incredere ca el va confirma amenintarea.",al={"de ce Guard Thomas","scopul lui Dughan","vorbeste cu Thomas"}},{q="Unde este stationat Guard Thomas?",a="Guard Thomas pazeste podul de lemn peste rau, in indepartatul est al Elwynn Forest, pe drumul spre Redridge Mountains.",al={"locatia lui Guard Thomas","unde se afla Thomas","garda de la podul de est"}},{q="Ce amenintare confirma Guard Thomas?",a="Guard Thomas confirma ca murloci ostili, semiinteligenti, s-au stabilit de-a lungul paraielor si cursurilor de apa din estul Elwynn, amenintand calatorii si fermele din apropiere.",al={"amenintarea murlocilor","ce a descoperit thomas","amenintarea de pe raul de est"}},{q="Cum ajung la Guard Thomas?",a="Urmeaza drumul spre est din Goldshire, traversand Elwynn Forest pana la podul de peste raul estic, unde Guard Thomas sta de veghe.",al={"calatorie rapida la thomas","plimbare calare cu dughan","calare pana la pod"}},{q="De ce nu trimite Stormwind o armata sa ajute estul Elwynn?",a="Fortele din Stormwind sunt raspandite pe fronturi, in timp ce King Varian Wrynn este disparut, iar resursele au fost redirectionate dinspre zonele rurale. Santinele precum Guard Thomas sunt nevoite sa se bazeze in mare masura pe aventurierii aflati in trecere.",al={"unde sunt garzile din Stormwind","de ce Elwynn nu este aparat","ajutor militar din partea Stormwind"}},{q="Ce se intampla dupa ce raportezi la Guard Thomas?",a="Dupa ce confirma prezenta murlocilor, Guard Thomas iti cere sa cercetezi ce s-a intamplat cu ceilalti strajeri care patrulau pe malul raului si nu s-au mai intors.",al={"urmatoarea misiune dupa Further Concerns","continuarea pentru Thomas","misiunea cu gardienii disparuti"}}},fx={["01d891f6"]={q="De ce il trimite Marshal Dughan pe un aventurier in loc sa-si foloseasca propriii gardieni?",a="Marshal Dughan este coplesit de sarcina de a mentine Goldshire in siguranta in fata banditilor Defias si a gnollilor. Cum Stormwind refuza sa trimita trupe si resurse suplimentare, garnizoana locala nu poate trimite soldati in misiuni obisnuite de curierat sau cercetare la distanta. Pentru ca i-ai adus avertismentul initial si ti-ai aratat grija fata de siguranta din Elwynn, iti incredinteaza misiunea de a merge spre est pentru a discuta cu Guard Thomas, la podul estic.",al={"de ce ma trimite","de ce sa nu folosim garzile","de ce are nevoie dughan de mine"}}},fp="16,188,28.372.0,25.369.0,48.220.0,32.126.0,38.164.0,30.124.0,58.192.0,45.158.0"}
P.entries["quest:350"] = {n="Look to an Old Friend",s="Master Mathias Shaw te trimite sa cauti un contact neobisnuit in Trade District din Stormwind. Coruptia nobililor ii fereste pe tradatori de justitia obisnuita, asa ca Shaw apeleaza la cel mai iscusit negustor de branza din oras si la reteaua sa de informatori.",h="Master Mathias Shaw te trimite sa cauti un contact neobisnuit in Trade District din Stormwind.",kw={"Defias","Elling Trias","Lescovar","Marzon","Mathias Shaw","Stormwind","cartierul comercial","branza Trias"},ang={["class:Rogue"]="Ca Rogue, poti vedea rivalitatea plina de neincredere dintre Mathias Shaw si Elling Trias. Informatorii de pe strazi pot avea mai multa influenta decat divizia oficiala de informatii a coroanei.",["faction:Alliance"]="Ca membru al Alliance, vezi cum coruptia din House of Nobles submineaza securitatea interna a Stormwind, in timp ce King Varian Wrynn ramane disparut."},sec={{t="Mai presus de lege",b="Lord Gregor Lescovar si Marzon the Silent Blade au legaturi directe cu Defias Brotherhood, dar Master Mathias Shaw a ajuns intr-un impas al investigatiei. Edwin VanCleef e mort in Deadmines, iar Bazil Thredd a fost eliminat in Stockade. Nu mai exista lideri banditi in viata care sa depuna marturie. Rangul nobiliar si legaturile politice ale lui Lescovar il lasa, de asemenea, in afara razei de actiune a justitiei obisnuite a Garzii Regale si a mandatelor oficiale SI:7."},{t="Urechea negustorului de branzeturi",b="Master Mathias Shaw te trimite la Elling Trias, proprietarul Trias' Cheese din Trade District. In tot Stormwind, Trias este cunoscut drept un negustor irascibil, care vinde bucati si roti de branza din import. El conduce si o retea independenta de informatori care rivalizeaza cu SI:7. Shaw detesta sa apeleze la fostul sau coleg, dar demascarea tradarii din Stormwind Keep cere metode care depasesc canalele regale oficiale."}},faq={{q="De ce te trimite Mathias Shaw la un negustor de branzeturi?",a="Elling Trias este mai mult decat un negustor de branza. El conduce Trias' Cheese, langa intrarea in Trade District, si intretine o retea independenta de informatii, cu o raza larga de actiune. Shaw uraste sa-i ceara ajutorul, dar SI:7 are nevoie de mijloace neobisnuite pentru a actiona impotriva unui nobil aflat in afara razei de actiune a fortelor de ordine obisnuite.",al={"de ce Elling Trias","de ce sa vorbesc cu Trias","de ce magazinul de branzeturi"}},{q="De ce nu-l poate aresta pur si simplu Mathias Shaw pe Lord Lescovar?",a="Lord Lescovar este un nobil de rang inalt din Stormwind, cu legaturi stranse in House of Nobles. Shaw nu are marturia necesara pentru ca probele sa poata fi sustinute in fata unui aristocrat.",al={"de ce sa nu-l arestam pe Lescovar","de ce nu-l poate aresta Shaw pe Lescovar","de ce este Lescovar de neatins"}},{q="Cine este Marzon the Silent Blade?",a="Marzon the Silent Blade este un agent letal care lucreaza indeaproape cu conspiratia Defias. Acesta comunica in secret cu Lord Lescovar in curtea din Stormwind.",al={"cine este marzon","rolul lui marzon, lama tacuta"}},{q="De ce il mentioneaza Trias pe Deathwing cand ii vorbesti?",a="Cand afla de conspiratia Defias Brotherhood, Trias raspunde cu sarcasm amar. Isi bate joc de ideea ca, in pasul urmator, i se va spune ca Deathwing, Black Dragon Aspect disparut de mult, este in viata si ataca regatul.",al={"de ce spune Trias Deathwing","replica lui Trias despre Deathwing","Deathwing ataca Stormwind"}},{q="Ce se intampla dupa intalnirea cu Elling Trias?",a="Dupa ce afla intreaga poveste a conspiratiei, Trias incepe sa planifice o infiltrare discreta in Stormwind Keep, pentru a-l incolti pe Lord Lescovar fara sa alerteze restul curtii nobiliare.",al={"urmatoarea misiune dupa Trias","unde merg dupa Look to an Old Friend"}},{q="Unde se afla Elling Trias?",a="Elling Trias se afla in Trias' Cheese, in Trade District din Stormwind, chiar langa drumul principal care porneste de la portile orasului.",al={"locatia Trias","unde se gaseste branza Trias"}}},fx={["9cbff8f4"]={q="De ce te trimite Mathias Shaw in loc sa se ocupe de asta prin SI:7?",a="Lord Gregor Lescovar este un nobil puternic, cu relatii influente, practic situat deasupra legii obisnuite din Stormwind. Shaw nu are marturiile necesare pentru a dovedi oficial cazul impotriva lui in instanta. O interventie oficiala din partea SI:7 sau a garzii orasului ar provoca indignarea politica a nobilimii, in lipsa unor dovezi incontestabile. Tu, insa, actionezi neoficial, ca agent independent, ceea ce ii permite lui Shaw sa recurga la cai neobisnuite si discrete, fara sa atraga prematur atentia aliatilor lui Lescovar din House of Nobles.",al={"de ce ma trimit","de ce nu SI7","de ce are nevoie Shaw de mine"}}},fp="21,222,13.424.1,22.397.1,52.294.0,51.171.0,31.159.0,55.204.0,45.180.1,30.111.0"}
P.entries["quest:351"] = {n="Find OOX-17/TN!",s="Un dispozitiv metalic ciudat, in forma de ou, pe care l-ai descoperit, prinde viata cand ii invarti butonul, iar o voce din interior se prezinta drept Oglethorpe. Robotul de reperare al lui Oglethorpe a disparut, iar ti se cere sa duci baliza la el.",h="Un dispozitiv metalic ciudat, in forma de ou, pe care l-ai descoperit, prinde viata cand ii invarti butonul...",kw={"baliza de urgenta","prapastia cascata","robot de localizare","pui mecanic","oglethorpe","oox-17/tn","tanaris"},sec={{t="O voce din ou",b="Rotirea unui buton de pe oul ciudat il deschide, dezvaluind un mecanism robotic gnomish, iar o voce prinde viata cu un fasait din interior. Cel care vorbeste se prezinta drept Oglethorpe si spune ca un robot de localizare a disparut. Oglethorpe a calculat acum locul in care s-a prabusit, langa Gaping Chasm din Tanaris, si iti cere sa duci baliza la robot."},{t="La locul prabusirii",b="La locul prabusirii, robotul de orientare se dovedeste a fi un pui de gaina robotic. Oglethorpe spune ca trebuie pornit cu un impuls electric inainte sa poata zbura acasa, la Booty Bay, pentru reparatii, iar baliza se introduce in el. Se aud zumzete si bazaituri in timp ce robotul incearca sa se ridice, iar acum vocea lui Oglethorpe vine chiar din robot. Functioneaza, dar are nevoie de reparatii majore si este mult prea greu ca sa-l poti ridica."}},faq={{q="Cine te contacteaza prin dispozitiv?",a="O voce din interiorul oului rosteste numele Oglethorpe si spune ca robotul de localizare a disparut.",al={"cine este oglethorpe","cine vorbeste prin ou"}},{q="Unde s-a prabusit robotul de localizare?",a="Coordonatele calculate de Oglethorpe indica un loc in apropiere de Gaping Chasm, in Tanaris.",al={"unde este robotul","unde este OOX-17/TN","unde duc semnalizatorul","locatia robotului din prapastia adanca"}},{q="La ce foloseste farul?",a="Oglethorpe iti cere sa duci farul la robotul de reperare disparut.",al={"ce face felinarul","ce este oul","de ce sa porti felinarul"}}},fp="15,245,20.337.0,17.382.1,41.97.0,33.74.0,23.68.0"}
P.entries["quest:3512"] = {n="In Eranikus' Own Words",s="Itharius vrea sa gaseasca o cale de a vorbi cu Eranikus prin intermediul nestematei. Eranikus se afla undeva intre somn si moarte, prins intr-o tesatura de cosmaruri, iar esenta pe care i-ai dat-o este puternic intinata, dar mai exista o sansa. Itharius te trimite departe, in partea de est a Winterspring.",h="Itharius vrea sa gaseasca o cale de a vorbi cu Eranikus prin intermediul nestematei.",kw={"eranikus","itharius","cosmar","spiritspeaker","swamp of sorrows","umbranse","winterspring"},sec={{t="O voce dincolo de cosmar",b="Itharius explica faptul ca Eranikus se afla intre somn si moarte, rasucit intr-o tesatura de cosmaruri. Esenta pe care i-ai dat-o este puternic intinata, dar mai exista o sansa de a ajunge la el. Pentru a deschide o conversatie prin gema, Itharius te trimite in estul Winterspring, un tinut de gheata, sa cauti unul dintre aliatii lor muritori."},{t="Vorbitorul spiritelor",b="Aliatul este Umbranse the Spiritspeaker, un om care actioneaza ca medium pentru cei morti. Eranikus nu este cu adevarat mort, dar Itharius crede ca Umbranse ar putea ajuta oricum."},{t="Starea lui Umbranse",b="Umbranse spune ca Itharius a fost intelept sa te trimita si ca Eranikus iti va oferi in curand sfaturi chiar prin propriile cuvinte. Deocamdata, Umbranse nu te poate ajuta direct. Iti va impartasi priceperea in vorbirea cu mortii, dar mai intai are nevoie de ajutorul cuiva pe care slabiciunile varstei nu-l tin pe loc, fiindca cel mai puternic instrument de augur din grija lui Umbranse a fost luat impotriva vointei sale, iar fara el nu-l poate ajuta pe Eranikus."}},faq={{q="Cine te trimite in aceasta calatorie?",a="Itharius din Swamp of Sorrows, dupa ce primeste de la tine esenta corupta a lui Eranikus.",al={"cine ofera In Eranikus' Own Words","cel care da misiunea lui eranikus"}},{q="Cine este Umbranse the Spiritspeaker?",a="Un Human care slujeste drept medium pentru cei morti si unul dintre aliatii muritori ai lui Itharius. Poate fi gasit in estul Winterspring.",al={"cine este umbranse","povestea lui umbranse spiritspeaker"}},{q="Este Eranikus considerat mort?",a="Nu este cu adevarat mort. Eranikus zace undeva intre somn si moarte, prins intr-o tesatura de cosmaruri.",al={"este eranikus mort","starea lui eranikus"}},{q="Unde se incadreaza acest pas in firul narativ?",a="Urmeaza dupa al doilea pas din The Essence of Eranikus, in care i-ai dat lui Itharius nestemata ce continea ce mai ramasese din vointa libera a lui Eranikus.",al={"ordinea lantului de misiuni Eranikus","ce s-a intamplat inainte, in cuvintele lui Eranikus"}}},fp="22,271,28.312.0,17.164.0,20.402.1,30.88.0,34.115.0,28.97.0,42.135.0"}
