P.entries["quest:3521"] = {n="Iverron's Antidote",s="Iverron's Antidote este o misiune urgenta in Shadowglen, menita sa salveze un cercetas night elf otravit. Adunand ciuperci salbatice, crini si venin de paianjen, aventurierii o ajuta pe Dirania Silvershine sa prepare un leac inainte ca veninul sa-si faca pe deplin efectul.",h="Iverron's Antidote este o misiune urgenta in Shadowglen, menita sa salveze un cercetas night elf otravit.",kw={"Aldrassil","antidot","Dirania Silvershine","ciuperca zambila","Iverron","Moonpetal Lily","Shadowglen","Shadowthread Cave","ichor de paianjen din padure"},ang={["class:Druid"]="Prepararea leacurilor din plantele locale si neutralizarea otravurilor naturale reflecta echilibrul fundamental pe care druizii se straduiesc sa-l mentina in salbaticie.",["profession:Herbalism"]="Culegerea crinilor Moonpetal si a ciupercilor Hyacinth demonstreaza ca plantele salbatice din Teldrassil au proprietati medicinale puternice daca sunt manevrate cu grija.",["race:NightElf"]="Sa ai grija de rudele cazute este o datorie sacra in Shadowglen, unde fiecare aparator este necesar pentru a proteja World Tree, care abia incepe sa inmugureasca."},sec={{t="O cursa contra veninului",b="In timp ce cerceta ramurile din Shadowglen, tanarul Iverron a cazut victima coltilor veninosi ai paianjenilor Webwood din tinut. Prabusit si pe moarte, supravietuirea lui depinde in intregime de cunostintele despre plante medicinale ale Diraniei Silvershine din Aldrassil. Pe masura ce tanarul se stinge repede, ea trebuie sa pregateasca numaidecat o potiune speciala care sa neutralizeze veninul agresiv ce-i strabate sangele."},{t="Reactivi din Shadowglen",b="Reteta Diraniei se bazeaza pe plantele tamaduitoare din Teldrassil, echilibrate cu veninul insusi. Ciupercile hyacinth, indragite de grell hoti din sud, ofera o baza pamantie, in timp ce crinii delicati Moonpetal, culesi din ochiurile linistite de apa ale padurii, au proprietati purificatoare. Pentru a desavarsi potiunea, trebuie extras un esantion de ichor Webwood direct de la paianjenii care pandesc langa Shadowthread Cave, astfel incat leacul sa fie adaptat otravii lor specifice."}},faq={{q="Cine este Iverron?",a="Iverron este un tanar elf al noptii din Shadowglen, care s-a aventurat prea aproape de paianjenii ostili Webwood si a fost rapus de veninul lor letal.",al={"iverron","cine este iverron","cine a otravit"}},{q="Cine ofera misiunea Iverron's Antidote?",a="Dirania Silvershine, o slujitoare aflata in afara marilor ramuri ale lui Aldrassil din Shadowglen, ofera misiunea si prepara leacul.",al={"cel care ofera misiunea","dirania","dirania silvershine"}},{q="De ce are antidotul nevoie de ichor de paianjen?",a="In remediile traditionale din plante, adaugarea unei componente din fluidele corporale sau veninul creaturii ajuta la contracararea toxinelor specifice care afecteaza victima.",al={"de ce ichor de paianjen","la ce foloseste Webwood Ichor","leac pentru veninul de paianjen"}},{q="Unde se gasesc Hyacinth Mushrooms?",a="Ciupercile zambile cresc la baza copacilor mari din Shadowglen si pot fi smulse si din ghearele grell-urilor care le aduna la sud.",al={"unde gasesc ciuperci de zambile","locatia ciupercilor de zambile"}},{q="Unde cresc Moonpetal Lilies?",a="Crinii Moonpetal infloresc de-a lungul marginilor ochiurilor de apa dulce si linistite, ascunse in partea de nord-vest a Aldrassilului.",al={"locatia Moonpetal Lily","unde sunt crinii"}},{q="Unde se gasesc paianjenii Webwood?",a="Paianjenii Webwood traiesc in padurile nordice din Shadowglen, mai ales in jurul intrarii intunecate din Shadowthread Cave.",al={"locatia paianjenului Webwood","locatia paianjenului in Shadowglen"}}},fx={["77bb41e6"]={q="De ce vrea Dirania Silvershine sa se faca acest lucru?",a="Dirania stie sa prepare un leac care poate neutraliza otrava mortala ce strabate trupul lui Iverron. Fara interventie rapida, starea lui se va inrautati, iar ea se bazeaza pe promptitudinea ta pentru a aduna ingredientele necesare din padure, inainte sa fie prea tarziu pentru a-l salva.",al={"motivul lui Dirania Silvershine","de ce sa-l ajuti pe Iverron","de ce sa prepari antidotul"}},d7eaa833={q="La ce se foloseste Hyacinth Mushroom?",a="Ciupercile zambila sunt fungi autohtoni care cresc sub ramurile uriase din Shadowglen. Dirania le foloseste ca ingredient principal in prepararea antidotului, echilibrand veninurile mai puternice si neutralizand toxina care patrunde in trupul lui Iverron.",al={"la ce foloseste ciuperca hyacinth","de ce ciuperca hyacinth","povestea ciupercii hyacinth"}},ece05283={q="La ce este folosita Moonpetal Lily?",a="Crinii Moonpetal sunt flori acvatice delicate, care se dezvolta in ochiurile linistite de apa din padurile Shadowglen. Dirania ii amesteca in leacul ei pentru a le folosi proprietatile naturale calmante si a contracara veninul puternic al paianjenilor.",al={"scopul Moonpetal Lily","de ce Moonpetal Lily","povestea Moonpetal Lily"}}},fp="18,226,20.372.0,22.448.0,15.139.0,39.140.0,40.160.0,35.151.0,31.121.0,38.116.0"}
