P.entries["quest:353"] = {n="Stormpike's Delivery",s="Grimand Elmore trimite calatori spre nord cu un topor pentru Mountaineer Gringer Stormpike. Drumul porneste din Dwarven District al Stormwindului si duce la un avanpost din Ironforge, in Loch Modan.",h="Grimand Elmore trimite calatori spre nord cu un topor pentru Mountaineer Gringer Stormpike.",kw={"topor","elmore","grimand","gringer","turn de paza","loch modan","mountaineer","stormpike"},ang={["faction:Alliance"]="Ca membru al Alliance, ajuti la transportul proviziilor militare intre Stormwind si avanposturile montane, unde oamenii si piticii se bazeaza unii pe altii.",["profession:Blacksmithing"]="Ca fierar, poti recunoaste maiestria lucrarii lui Grimand Elmore. Garzile montane apreciaza atat de mult prelucrarea metalului in stil piticesc, incat o comanda din alte regate.",["race:Dwarf"]="Ca Dwarf, stii ca Stormpike sunt cinstiti de ai tai. Sa ajuti un muntean de acelasi neam la hotarele salbatice din Loch Modan intareste legaturile dintre clanuri."},sec={{t="O arma pentru nord",b="I s-a cerut lui Grimand Elmore sa faca o arma pentru Mountaineer Gringer Stormpike. Clanul Stormpike este respectat in Ironforge pentru gustul sau rafinat si mandria martiala. Elmore apeleaza la calatori de incredere sa duca securea spre nord, traversand distanta dintre Stormwind si tinuturile de granita ale dwarves."},{t="De garda in Loch Modan",b="La turnul de garda nordic din Loch Modan, Mountaineer Stormpike supravegheaza tinuturile tulburate de troggs ratacitori si koboldii care sapa galerii. Regatele Human din sud se confrunta cu zvonuri de tulburari si banditism, in timp ce frontiera dwarf are propriile primejdii. Stormpike are nevoie de o lama noua care sa ajute la paza trecatorilor montane."}},faq={{q="Cine este Mountaineer Stormpike?",a="Gringer Stormpike este un Mountaineer din Ironforge, membru al respectatului clan Stormpike. Este stationat in turnul de paza nordic din Loch Modan, aparand drumul vaii de troggs si de amenintarile locale.",al={"gringer stormpike","cine este stormpike","mountaineer gringer stormpike"}},{q="Ce se afla in pachet?",a="Pachetul contine un topor dwarf facut la comanda si faurit de Grimand Elmore in Stormwind. Mountaineer Stormpike l-a comandat pentru a fi folosit impotriva troggs si kobolds din Loch Modan.",al={"ce livrez","continutul coletului Stormpike","arma lui Grimand Elmore"}},{q="Unde trebuie sa livrez pachetul?",a="Du pachetul la Mountaineer Stormpike, la turnul de paza din nordul Loch Modan, pe drumul care strabate dealurile spre granitele nordice ale muntilor.",al={"unde se afla stormpike","cum il gasesc pe mountaineer stormpike","locatia turnului de garda din loch modan"}},{q="De ce cumpara un pitic din Loch Modan arme din Stormwind?",a="Grimand Elmore este un fierar priceput de arme Dwarf in Dwarven District din Stormwind. Clanul Stormpike pretuieste lucratura fina in metal, iar Gringer i-a comandat lui Elmore sa-i faca securea, in ciuda distantei.",al={"de ce sa cumperi de la stormwind","de ce elmore","dwarf comanda de la un oras al oamenilor"}},{q="Ce legatura are aceasta cu Elmore's Task?",a="Aceasta livrare face parte din Elmore's Task. Grimand Elmore le cere calatorilor sa duca o alta favoare intre Stormwind si Khaz Modan.",al={"firul de misiuni al lui Elmore","misiunea dinaintea livrarii lui Stormpike","cum incep aceasta misiune"}},{q="Cum ajung calatorii din Stormwind in Loch Modan?",a="Ia Deeprun Tram din Dwarven District, Stormwind, pana la Ironforge. De la Great Gates, urmeaza soseaua estica prin trecatorile inzapezite din Dun Morogh si North Gate Pass, pana in Loch Modan.",al={"cum ajungi in Loch Modan","calatorie spre Khaz Modan","Deeprun Tram spre Loch Modan"}}},fp="20,171,22.299.0,22.314.0,29.189.0,27.168.0,31.158.0,58.192.0,39.123.0,49.189.0"}
P.entries["quest:354"] = {n="Deaths in the Family",s="Coleman Farthing, fost muncitor la moara, care locuieste acum in Brill, cauta razbunare personala impotriva aristocraticei familii Agamand. Convinsi sa ramana si sa-si apere domeniile de Scourge in timpul Third War, Farthing si ceilalti muncitori au pierit alaturi de stapanii lor incapatanati, doar ca Agamands sa se ridice din nou, devenind sclavi fara minte ai Lich King.",h="Coleman Farthing, fost muncitor la moara, care locuieste acum in Brill, cauta razbunare personala impotriva...",kw={"agamand","agamand mills","brill","coleman farthing","deaths in the family","gregor agamand","nissa agamand","scourge","thurman agamand","tirisfal glades"},ang={["faction:Horde"]="Inlaturarea conducerii Agamand elimina comandantii periculosi ai Scourge care pandesc nepermis de aproape de Brill si de caile de acces nordice spre Undercity.",["race:Undead"]="Aceasta sarcina reflecta resentimentele personale profunde pe care multi Forsaken le pastreaza din vietile lor muritoare, ilustrand trauma persistenta a caderii Lordaeron si amaraciunea fata de cei care i-au dus la pieire."},sec={{t="O mostenire a mandriei",b="Inainte ca Third War sa devasteze Lordaeron, familia Agamand era cea mai bogata si mai influenta dinastie agrara din Tirisfal Glades. Morile lor intinse si pasunile fertile produceau recolte bogate, iar zeci de fermieri arendasi si morari munceau pentru ei. Cand Plague of Undeath s-a raspandit in regat, Agamands au refuzat sa fuga sau sa-si abandoneze pamanturile mostenite, convinsi ca zidurile de piatra si lucratorii loiali puteau tine piept ororilor care inaintau dinspre rasarit."},{t="Pretul loialitatii",b="Avand incredere in asigurarile stapanilor lor, angajati loiali precum Coleman Farthing au ramas pe pozitii pentru a apara mosia. Apararea s-a dovedit zadarnica in fata atacului neintrerupt al Scourge. Agamands si lucratorii lor au fost macelariti, iar trupurile le-au putrezit acolo unde au cazut, inainte de a fi readuse la viata ca morti-vii. Desi Farthing a reusit in cele din urma sa se elibereze datorita izbavirii aduse de Sylvanas Windrunner, patriarhii si mostenitorii familiei Agamand au ramas prinsi sub controlul mental al Lich King, ratacind prin morile in ruina ca strajeri lipsiti de minte ai Scourge."},{t="Razbunare amara",b="Acum locuieste in Brill, iar Coleman Farthing nutreste o ura profunda fata de fostii stapani, a caror trufie l-a costat viata de muritor. In cautarea unei impacari si a razbunarii, el trimite campioni Forsaken la Agamand Mills sa-i distruga pe Gregor, Nissa si Thurman Agamand. Farthing spera deschis ca, dincolo de chipurile lor putrezite, fostii sai stapani si-au pastrat destula constiinta cat sa simta groaza in timp ce existenta lor de strigoi era curmata cu brutalitate."}},faq={{q="Cine a fost familia Agamand?",a="Agamands erau cea mai bogata si prospera familie de mari proprietari funciari din Tirisfal Glades inainte de caderea Lordaeron. Ei detineau si administrau vastele Agamand Mills, angajand numerosi fermieri si morari din zona.",al={"cine sunt agamands","povestea agamand","istoria morilor agamand"}},{q="De ce este Coleman Farthing atat de furios pe ei?",a="Farthing a lucrat la morile lor cat a fost in viata. Cand a sosit Scourge, Agamands i-au convins pe muncitori sa ramana si sa intareasca domeniul, in loc sa fuga. Farthing considera ca mandria lor aristocratica este motivul direct pentru care el si semenii sai au murit si au devenit strigoi.",al={"ranchiuna lui coleman farthing","de ce ii uraste farthing pe agamands","motivul lui farthing"}},{q="S-au alaturat Agamands celor Forsaken?",a="Nu. Spre deosebire de Coleman Farthing si de ceilalti Forsaken cu vointa proprie, Agamands nu s-au eliberat niciodata de sub controlul Lich King. Au ramas slujitori fara minte ai Scourge, bantuind morile familiei ruinate.",al={"sunt Agamands Forsaken","de ce sunt Agamands Scourge","cine ii controleaza pe Agamands"}},{q="Care membri ai familiei Agamand trebuie nimiciti?",a="Misiunea iti cere sa-i vanezi pe Gregor Agamand, Nissa Agamand si Thurman Agamand si sa le aduni ramasitele de pe mosia familiei, pentru a le confirma pieirea.",al={"pe cine ucizi","tinte agamand","care agamands"}},{q="Unde se afla Agamand Mills?",a="Agamand Mills se afla in tinuturile nordice din Tirisfal Glades, la nord-vest de Brill. Domeniul candva roditor este alcatuit din mai multe mori de vant si ferme in ruina, napadite de Scourge.",al={"unde se afla morile agamand","locatia lui agamand"}},{q="Ce face Coleman Farthing cu ramasitele lor?",a="Coleman le cere ramasitele doar pentru a confirma ca au fost distrusi. Trofeul simbolizeaza incheierea vechilor sale ranchiune de muritor si dovedeste ca mandrii lorzi care l-au condamnat au fost nimiciti definitiv.",al={"de ce sa aduni ramasite","ramasitele lui Farthing"}}},fx={["5fad58e7"]={q="Pe cine esti trimis sa distrugi la mori?",a="Ti se cere sa distrugi ramasitele strigoilor din familia Agamand: Gregor, Nissa si Thurman. Cand erau in viata, acestia stapaneau intinsele Agamand Mills si si-au convins lucratorii sa ramana si sa apere mosia de Scourge. Incercarea lor a esuat, iar membrii familiei au fost inviatI ca slujitori lipsiti de minte ai Lich King-ului, bantuind locurile unde au pierit lucratorii lor.",al={"cine sunt tintele","cine sunt Agamands","tintele Agamand"}}},fp="20,357,17.490.0,20.524.0,18.434.0,27.213.0,41.261.0,35.194.0,47.167.0,32.181.0,49.205.0"}
P.entries["quest:355"] = {n="Speak with Sevren",s="Dupa ce socotelile personale ale lui Coleman Farthing au fost lamurite la Agamand Mills, Magistrate Sevren il cheama pe aventurier la Brill. Morile adapostesc mult mai mult decat fantomele amare ale unei familii: ele reprezinta o amenintare activa din partea Scourge la granita nordica a asezarii.",h="Dupa ce socotelile personale ale lui Coleman Farthing au fost lamurite la Agamand Mills, Magistrate Sevren il...",kw={"agamand mills","brill","coleman farthing","magistrat sevren","sevren","cripta familiei","the haunted mills","tirisfal glades"},ang={["faction:Horde"]="Brill reprezinta prima linie de aparare a Undercity; securizarea terenurilor agricole din imprejurimi impotriva Scourge este vitala pentru mentinerea controlului Horde asupra nordului Lordaeron.",["race:Undead"]="Dovedindu-ti priceperea impotriva Scourge fara minte, castigi rapid recunoastere in Brill si treci de la treburi ocazionale la apararea directa a comunitatii sub comanda lui Magistrate Sevren."},sec={{t="De la razbunare la indatorirea civica",b="Coleman Farthing cauta sa se razbune personal pe fostii sai vecini, Agamands, trimitand calatori spre nord sa-i nimiceasca pe mortii vii care bantuiau prin preajma morilor de faina. Dupa ce ramasitele au fost aduse, Coleman si-a dat seama ca ranchiuna personala se intersecta cu o problema tactica mai ampla: intreaga mosie Agamand este plina de slujitori ai Scourge, agresivi si lipsiti de minte, chiar la portile Brill."},{t="Chemarea magistratului",b="Magistrate Sevren supravegheaza siguranta civila si militara din Brill in numele Dark Lady. Impresionat de rapoartele despre un aventurier capabil sa supravietuiasca incursiunilor adanci in fermele bantuite, Sevren intervine pentru a-i indruma pe cei capabili spre sursa infestarii - cripta straveche a familiei Agamand."}},faq={{q="De ce ma trimite Coleman Farthing la Magistrate Sevren?",a="Coleman si-a razbunat propria suferinta pe familia Agamand inviata, dar stie ca prezenta strigoilor la mori ameninta intregul Brill. Ti-a raportat iscusinta in lupta lui Magistrate Sevren, care organizeaza apararea locala.",al={"de ce sa merg la Sevren","recomandarea lui Coleman Farthing","cine este magistratul Sevren"}},{q="Unde poate fi gasit Magistrate Sevren?",a="Magistrate Sevren se afla in Brill, in Tirisfal Glades, in cladirea Brill Town Hall, unde coordoneaza treburile locale pentru Forsaken.",al={"locatia lui Sevren","unde este magistratul Sevren","gaseste-l pe Sevren"}},{q="Ce amenintare reprezinta Agamand Mills?",a="Morile se afla chiar la nord de Brill si sunt in continuare pline de Scourge fara minte. Daca nu sunt opriti, mortii umblatori si spiritele nelinistite care ratacesc pe campuri ar putea cotropi cu usurinta orasul.",al={"pericolul morilor agamand","de ce sunt morile o amenintare"}},{q="Ce se intampla dupa ce vorbesti cu Magistrate Sevren?",a="Sevren te trimite intr-o lovitura directa in Agamand Family Crypt, pentru a elimina amenintarea Scourge din adancuri, care ii tine pe mortii-vii legati de mori.",al={"urmatoarea misiune dupa Sevren","ce vrea Sevren"}},{q="Trebuie sa te intorci imediat la mori pentru aceasta misiune?",a="Aceasta scurta insarcinare este doar o etapa de legatura. Raporteaza-te lui Sevren in Brill pentru a incheia indiciul lui Coleman inainte de a accepta urmatoarea misiune in cripta.",al={"trebuie sa ma intorc la mori","este doar o misiune de discutie"}},{q="De ce ii pasa lui Brill de familia Agamand?",a="In viata, familia Agamands era formata din instariti proprietari de mori din regiune si vecini de seama in Tirisfal. Dupa moarte, mosia lor profanata serveste drept baza fortificata pentru Scourge fara minte.",al={"importanta agamand","cine sunt agamands pentru brill"}}},fp="17,256,28.404.0,21.309.0,55.228.0,37.132.0,38.191.0,51.142.0,59.149.0,45.185.0"}
P.entries["quest:356"] = {n="Rear Guard Patrol",s="Rear Guard Patrol este o misiune de recunoastere militara, incredintata de Deathguard Linnea pentru a proteja apararea Forsaken de-a lungul granitei estice a Tirisfal. Operativii trebuie sa starpeasca oroarea ratacita a Scourge si spiritele ratacitoare care bantuie Balnir Farmstead, inainte ca acestea sa puna in pericol liniile de aprovizionare care sustin Bulwark.",h="Rear Guard Patrol este o misiune de recunoastere militara, incredintata de Deathguard Linnea pentru a proteja...",kw={"Balnir","groaza sangeranda","bastion","Linnea","Scourge","Tirisfal","spirit ratacitor","Zygand"},ang={["faction:Horde"]="Mentinerea perimetrului estic al Tirisfal asigura ca Horde isi pastreaza fragila pozitie in nordul Eastern Kingdoms, in fata legiunilor de strigoi.",["race:Undead"]="Pentru Forsaken, apararea flancului din spate al Bulwark tine pur si simplu de supravietuire; alungarea Scourge din Balnir Farmstead impiedica intoarcerea stapanirii Lich King asupra tinuturilor lor natale."},sec={{t="Asigurarea flancului fortificatiei",b="Bulwark este principala reduta care impiedica molima si armatele din Western Plaguelands sa se reverse in Tirisfal Glades. Deathguard Linnea supravegheaza securitatea din spatele liniilor de-a lungul acestei frontiere. Cum linia nu-si poate permite sa-si imparta fortele pentru a respinge ambuscadele din spate, orice strigoi care trece de punctul de strangulare trebuie nimicit inainte sa poata taia liniile de aprovizionare care sustin frontul."},{t="Ruinele de la Balnir Farmstead",b="Odinioara o ferma activa din estul Tirisfal, Balnir Farmstead a ajuns o ruina in timpul Third War. Acum complet pangarite, campurile napadite de buruieni si grajdurile care se naruie le ofera adapost intrusilor Bleeding Horrors si nelinistitelor Wandering Spirits. Curatarea locului il lipseste pe Lich King de o baza de atac chiar in Tirisfal si pastreaza drumul sigur pentru intaririle Horde."}},faq={{q="De ce este importanta aceasta patrula pentru Bulwark?",a="Bulwark pazeste trecatoarea ingusta de la granita cu Western Plaguelands. Daca Scourge ratacitori ar ocoli fortificatia sau s-ar aseza in spatele ei, aparatorii ar fi prinsi intr-o lupta pe doua fronturi si si-ar pierde liniile de aprovizionare care ii leaga de Brill si Undercity.",al={"de ce sa fac rear guard patrol","importanta bastionului","de ce sa securizez balnir"}},{q="Cine da ordinul acestei misiuni?",a="Deathguard Linnea, ofiter stationat langa drumul care duce spre est, catre Plaguelands, iti incredinteaza patrula si ii trimite lui Executor Zygand rapoarte despre reusita.",al={"cine da Rear Guard Patrol","Deathguard Linnea"}},{q="Ce creaturi bantuie Balnir Farmstead?",a="Ferma blestemata e plina de Bleeding Horrors - cadavre reanimate, cusute laolalta prin necromantie - si de Wandering Spirits, fostii locuitori care au murit in timpul cuceririi initiale de catre Scourge.",al={"creaturi de la Balnir Farmstead","ce monstri sunt la Balnir","groaza sangeranda"}},{q="Cine este Executor Zygand?",a="Executor Zygand este un comandant Deathguard Forsaken cu rang inalt, aflat in Brill, si superiorul lui Deathguard Linnea.",al={"povestea executor zygand","cine este zygand"}},{q="De ce nu abandoneaza pur si simplu Forsaken granita estica?",a="Abandonarea Bulwark ar lasa toate Tirisfal Glades si portile Undercity la cheremul hoardelor nesfarsite ale Scourge, care marsaluiesc din Plaguelands.",al={"de ce sa aperi meterezul","de ce sa lupti la granita"}}},fx={a47e493a={q="De ce are Deathguard Linnea nevoie de un aventurier, in loc sa se ocupe ea insasi de patrula?",a="Aparatorii stationati la Bulwark sunt intinsi la maximum, tinand frontiera estica impotriva atacurilor neincetate din partea Plaguelands. Linnea si garnizoana nu-si pot permite sa-si abandoneze pozitiile fortificate pentru a curata spatele fara sa slabeasca linia principala. Apeland la calatori capabili, Forsaken pot elimina infiltratii din spatele lor, mentinand in acelasi timp un zid neintrerupt de aparare impotriva Scourge.",al={"de ce eu, linnea","de ce trimite un aventurier la rear guard patrol","de ce nu o face linnea"}}},fp="17,315,28.410.0,29.371.0,45.261.0,24.159.0,42.198.0,23.111.0,55.164.0"}
P.entries["quest:3566"] = {n="Rise, Obsidion!",s="Dupa misiunea Release Them, un arheolog pe moarte isi da ultima suflare spunand ca totul a fost o capcana si te roaga sa-l ucizi pe tradator, in numele lui si al lui Thorius. Trebuie sa moara atat Lathoric the Black, cat si Obsidion, iar Curator Thorius din Ironforge vrea dovezi.",h="Dupa misiunea Release Them, un arheolog pe moarte isi da ultima suflare spunand ca totul a fost o capcana si...",kw={"curator thorius","arheolog muribund","Ironforge","Lathoric the Black","Obsidion","Ragnaros","ridica Obsidion","Searing Gorge"},sec={{t="O rugaminte pe moarte",b="Arheologul abia poate vorbi. Spune ca totul a fost o capcana, cere iertare si te roaga sa-l ucizi pe tradator in numele sau si al lui Thorius. Lathoric the Black si Obsidion trebuie sa piara amandoi, iar Curator Thorius din Ironforge vrea capul unuia si inima celuilalt."},{t="Un glas raspunde",b="Dorius apare si te ia drept un prost. Profitand de sentimentele slabe ale fratelui sau, a trimis salvatori ca sa ia ultima piatra Suntara de la Twilight's Hammer. A dat peste pietrele Suntara la Grimesilt Digsite, iar puterea lui Ragnaros a navalit prin el, dandu-i un scop. La porunca lui Ragnaros a fost construit Obsidion, pentru a-i distruge pe orcs Blackrock din Blackrock Spire. Renascut ca adept al focului, si-a luat numele de Lathoric the Black. In Ironforge, Thorius paleste in fata dovezii: propriul sau frate a pus totul la cale si l-a tradat pe el si Ironforge. Thorius se teme ca Old Gods inca isi pastreaza puternica influenta aici si ca, daca un om atat de onorabil a putut fi intors atat de usor in slujba lui Ragnaros, nimeni nu este in siguranta."}},faq={{q="Cine ofera aceasta misiune?",a="Un arheolog pe moarte, care te roaga sa-i razbuni pe ei si pe Thorius.",al={"cel care da misiunea","cine incepe rise obsidion","arheologul muribund"}},{q="Ce misiune preceda aceasta?",a="Urmeaza Release Them.",al={"misiune anterioara","cerinta prealabila","seria dinainte de Rise of Obsidion"}},{q="Cui ii prezinti dovada?",a="Curator Thorius din Ironforge, care vrea dovezi sub forma unui cap si a unei inimi.",al={"unde ma intorc","la cine ma intorc","unde se afla Thorius"}},{q="Pe cine esti trimis sa ucizi?",a="Doi dusmani: cel numit Lathoric the Black si Obsidion.",al={"cine este obsidion","cine este lathoric","tinte"}}},fp="15,229,12.287.0,15.719.1,21.63.0,29.33.0,30.80.0,25.57.0"}
P.entries["quest:3567"] = {n="To the Top",s="Marli Wishrunner te poate duce sa admiri privelistea de pe unul dintre twin colossals din Feralas, cu un avertisment: drumul are doar dus.",h="Marli Wishrunner te poate duce sa admiri privelistea de pe unul dintre twin colossals din Feralas, cu un...",kw={"colosi","feralas","Marli Wishrunner","varf","spre varf","Twin Colossals"},sec={{t="O singura cale in sus",b="Marli Wishrunner te intreaba daca vrei sa vezi privelistea din varful unuia dintre twin colossals si te poate trimite acolo. Marli adauga un cuvant de precautie: gandeste-te cum vei cobori, pentru ca aceasta este o calatorie fara intoarcere."}},faq={{q="Cine te poate trimite in varful unui colossal?",a="Marli Wishrunner te poate trimite sus, de unde poti admira privelistea de la unul dintre twin colossals.",al={"cine da","cine ofera misiunea To the Top","marli wishrunner"}},{q="Unde duce aceasta calatorie?",a="In varful unuia dintre Twin Colossals.",al={"unde te trimite marli","destinatia","locatia din varf"}},{q="Iti ofera Marli o cale de coborare?",a="Nu. Marli te avertizeaza ca drumul este fara intoarcere, asa ca ar trebui sa te gandesti cum vei cobori.",al={"cum cobor","exista cale de intoarcere","calea de coborare de la twin colossals"}}},fp="10,146,10.224.0,42.74.0,29.40.0,35.91.0"}
P.entries["quest:357"] = {n="The Lich's Identity",s="Lich's Identity este o misiune din Undercity, oferita de Bethor Iceshard in Magic Quarter. Dorind sa afle identitatea unui lich retras, care traieste pe Brightwater Lake, Bethor trimite un emisar sa-i fure cartea de vraji, pentru a-i evalua puterea si loialitatea.",h="Lich's Identity este o misiune din Undercity, oferita de Bethor Iceshard in Magic Quarter.",kw={"Bethor Iceshard","Brightwater Lake","Forsaken","Magic Quarter","necromant","Sylvanas","cartea de vraji a regelui-lich","Undercity"},ang={["class:Mage"]="Magii care il viziteaza pe Bethor Iceshard in Magic Quarter vad cum traditiile magice ramase din Lordaeron si Dalaran sunt transformate in mijloace de supravietuire pentru Forsaken.",["faction:Horde"]="Recrutarea unor necromanti puternici intareste frontiera nordica a Horde impotriva atacurilor neincetate ale Scarlet Crusade si Scourge.",["race:Undead"]="Pentru Forsaken, eliberarea unor strigoi independenti dovedeste ca desprinderea de Lich King nu a fost un miracol izolat si asigura totodata putere necromantica esentiala pentru curtea lui Sylvanas."},sec={{t="Un pustnic pe lac",b="La nord de Undercity, in apele invaluite in ceata ale lacului Brightwater Lake, un lich singuratic traieste in exil pe o insula mica, din proprie vointa. Spre deosebire de pionii lipsiti de minte ai Lich King, acest necromant isi pastreaza liberul-arbitru, dar traieste cuprins de o paranoia profunda. Convins ca orice strigoi care se apropie de el sunt slujitori ai Scourge, trimisi sa-l tarasca inapoi in robie, isi dezlantuie servitorii invocati impotriva oricui pune piciorul pe tarmurile sale."},{t="Un bun valoros",b="Vestea despre lichul renegat a ajuns in cele din urma la Bethor Iceshard, arhimagul care ii supravegheaza pe magii din Undercity. Bethor a inteles importanta strategica a unei asemenea fiinte: Lady Sylvanas Windrunner cauta orice farama de maiestrie magica si orice vointa capabila sa-i intareasca pe Forsaken impotriva numeroaselor lor dusmani. Pentru a evalua daca pustnicul poate fi recrutat, Bethor cere dovezi despre identitatea si priceperea lui in necromantie."},{t="Un vechi prieten regasit",b="Dupa ce cartea de vraji furata este dusa in Magic Quarter, Bethor ii cerceteaza scrierea arcana si descopera adevarata identitate a licheului: Gunther Arcanus. In viata, Gunther fusese un necromant talentat si un apropiat al lui Bethor, inainte ca molima sa devasteze Lordaeron. Descoperirea confirma ca Gunther nu este doar un suflet independent, ci si un vechi aliat ale carui puteri necromantice sporite ar putea fi de mare folos tinutului Dark Lady."}},faq={{q="Cine te trimite in aceasta misiune?",a="Bethor Iceshard, un mag Forsaken puternic si cu rang inalt, stationat in Magic Quarter of the Undercity, ofera misiunea.",al={"cel care ofera misiunea","locatia lui Bethor Iceshard","cine ofera misiunea The Lich's Identity"}},{q="De ce ataca lichul pe oricine se apropie de el?",a="Lichul s-a eliberat de sub controlul Lich King prin propria vointa, dar crede in mod eronat ca toti ceilalti morti-vii din Lordaeron raman slujitori ai Scourge controlati mental. Drept urmare, isi ordona slugilor sa-i atace pe toti cei care se apropie de insula lui, pentru a-si apara libertatea.",al={"de ce este Gunther ostil","de ce ataca lichul","lichul din Brightwater este ostil"}},{q="Unde se afla tabara lichului?",a="Locuieste pe o insula din mijlocul Brightwater Lake, in Tirisfal Glades, chiar la nord de Ruins of Lordaeron si Undercity.",al={"unde se afla lichul","insula din brightwater lake","locatia lui gunther arcanus"}},{q="De ce vrea Lady Sylvanas ca el sa fie primit in randurile Forsaken?",a="Strigoii independenti cu aptitudini magice deosebite sunt extrem de rari. Un necromant cu vointa proprie, capabil sa stapaneasca o magie a mortii puternica, le-ar oferi Forsaken o forta cruciala impotriva Scourge si a Scarlet Crusade.",al={"de ce sa recrutez lichul","interesul lui Forsaken pentru Gunther","lichul Sylvanas"}},{q="Cine se dovedeste a fi lichul?",a="Bethor dezvaluie ca lich-ul este Gunther Arcanus, fost mag din Dalaran si necromant priceput, care a fost un camarad apropiat al lui Bethor inainte de Third War.",al={"identitatea lichului","cine este lichul"}},{q="Ce se intampla dupa ce predai cartea de vraji?",a="Dupa ce Bethor confirma identitatea lui Gunther, te trimite inapoi la Brightwater Lake cu cartea de vraji, ca sa-l convingi pe Gunther ca Forsaken sunt cu adevarat liberi si vor sa-l primeasca printre ei.",al={"ce urmeaza","misiunea Return the Book","dupa identitatea lichului"}}},fx={["2f6ced1e"]={q="De ce vrea Bethor Iceshard cartea de vraji a lichului?",a="Bethor Iceshard cauta, in numele lui Dark Lady, sa-l atraga pe magul strigoi si retras de lume de partea Forsaken. Cum lichul ii alunga cu violenta pe toti cei care se apropie, Bethor nu poate pur si simplu sa stea de vorba cu el. Trebuie sa cerceteze cartea de vraji, sa-i descopere adevarata identitate, sa-i evalueze puterea necromantica si sa afle daca talentele sale pot sluji cu adevarat cauza Forsaken.",al={"motivul lui Bethor","de ce vrea Bethor cartea","de ce sa furi cartea de vraji a lichului"}},f276cf7d={q="La ce foloseste Lich's Spellbook?",a="Cartea de vraji ii apartine lichului retras care traieste langa Brightwater Lake. Aceasta contine tainele sale necromantice si semnaturile sale magice personale. Bethor Iceshard o foloseste pentru a-l identifica pe pustnic si a-i evalua priceperea necromantica, fara a fi nevoit sa intre in vorba cu el.",al={"cartea de vraji a lichului","scopul cartii de vraji a lichului","la ce foloseste cartea de vraji"}},e5299862={q="Cine este lichele de la Brightwater Lake?",a="Tinta este un mag strigoi puternic si cu liber-arbitru, care traieste pe o insula din Brightwater Lake, la nord. Nu are incredere in nimeni si crede ca toti ceilalti strigoi sunt inca sclavi fara minte ai Scourge. Prin urmare, s-a inconjurat de slujitori invocati si ii respinge cu violenta pe toti cei care se apropie.",al={"cine este lichul","lichul din brightwater lake","de la cine trebuie sa fur cartea"}}},fp="19,260,21.418.0,16.420.0,19.434.1,30.125.0,51.261.0,33.139.0,58.221.0,33.156.1,45.175.1"}
P.entries["quest:358"] = {n="Graverobbers",s="Magistrate Sevren din Brill le cere aventurierilor sa starpeasca gnollii Rot Hide din Mass Grave, la sud-vest de Garren's Haunt. Aceste bestii strigoi au fost trimise de Scourge sa dezgroape cadavrele primelor victime ale molimei si sa le sporeasca randurile. Uciderea lor si recuperarea ichorului folosit la imbalsamare ii protejeaza pe cei cazuti si ajuta cercetarile Royal Apothecary Society.",h="Magistrate Sevren din Brill le cere aventurierilor sa starpeasca gnollii Rot Hide din Mass Grave, la sud-vest...",kw={"Brill","ichor de imbalsamare","Garren's Haunt","jefuitori de morminte","Magistrate Sevren","groapa comuna","Rot Hide","Tirisfal Glades"},ang={["faction:Horde"]="Oprirea eforturilor Scourge de a-si reaproviziona trupele asigura nordul Lordaeronului, intarind pozitia Horde impotriva fortelor ramase ale Lich King.",["race:Undead"]="Pentru Forsaken, impiedicarea Scourge sa ridice cetatenii de odinioara ai Tirisfal ii scuteste pe compatriotii cazuti de soarta cumplita a robiei lipsite de minte."},sec={{t="Pangarirea mormintelor comune",b="Cand Plague of Undeath a cuprins pentru prima data Tirisfal Glades, mortii se adunau mai repede decat puteau fi ingropati dupa randuiala. In nord au fost sapate gropi comune uriase pentru a cuprinde numarul uluitor de pierderi. Pana de curand, ramasitele ingropate au scapat de inviere. Acum, insa, Scourge a dezlantuit gnollii Rot Hide asupra santurilor funerare de la sud-vest de Garren's Haunt, trimitandu-i sa dezgroape ramasitele descompuse si sa intareasca ostile Lich King."},{t="Intoarcerea alchimiei Scourge impotriva lor",b="Rot Hides sunt sustinuti de ichorul folosit la imbalsamare, o potiune alchimica ce le conserva si le anima trupurile putrezite. Poruncindu-le cercetasilor sa-i ucida pe jefuitorii de morminte si sa extraga acest lichid, Magistrate Sevren loveste de doua ori dintr-o singura miscare: opreste Scourge sa mai adune trupuri proaspete si le trimite direct apotecarilor din Brill specimene biologice valoroase, care cauta sa intoarca impotriva lui propria arta a Lich King-ului."}},faq={{q="De ce dezgroapa Scourge Mass Grave?",a="Groapa comuna adaposteste nenumarate victime ale sosirii initiale a Molimei in Tirisfal. Scourge intentioneaza sa dezgroape aceste trupuri pastrate pentru a ridica noi soldati si a-si spori armatele impotriva Forsaken.",al={"de ce sap gnolii dupa cadavre","ce vrea scourge de la trupuri","scopul gropii comune"}},{q="Ce sunt gnoll-ii Rot Hide?",a="Sunt gnolli strigoi inrobiti de Scourge. Animati si conservati cu ajutorul unui lichid alchimic pentru imbalsamare, ei slujesc drept scormonitori si trupe de soc in jurul Garren's Haunt si al cimitirelor invecinate.",al={"povestea celor cu piele putreda","gnolli strigoi din tirisfal","ce sunt cei cu piele putreda"}},{q="Unde se afla Groapa Comuna?",a="Groapa Comuna se afla la sud-vest de Garren's Haunt, in dealurile nordice din Tirisfal Glades, chiar la nord de Brill.",al={"unde sunt jefuitorii de morminte","locatia gropii comune","groapa comuna din Garren's Haunt"}},{q="Ce vor Forsaken de la Embalming Ichor?",a="Magistrate Sevren le preda ichorul adunat apotecarilor Forsaken, pentru ca acestia sa studieze cum invie si mentine Scourge servitorii sai inferiori, cautandu-le punctele slabe pe care le-ar putea exploata in razboiul aflat in desfasurare.",al={"de ce sa colectezi ichor pentru imbalsamare","la ce foloseste ichorul","povestea ichorului"}},{q="Cine ordona moartea Graverobbers?",a="Magistrate Sevren, supraveghetorul Forsaken din Brill, ofera recompensa pentru apararea granitelor din Tirisfal si procurarea reactivilor folositori pentru Apothecaries.",al={"cine da Graverobbers","rolul magistratului Sevren"}},{q="De ce le pasa Forsaken daca victimele moarte ale plagii sunt readuse la viata?",a="Fiecare cadavru revendicat si inviat de Scourge devine un soldat inamic care marsaluieste la porunca Lich King, amenintand direct regatul Forsaken, proaspat eliberat.",al={"de ce protejeaza forsaken mormintele","de ce le pasa de cadavre"}}},fx={["9e6ccf32"]={q="Impotriva cui esti trimis la Mass Grave?",a="Esti trimis sa distrugi gnolii Rot Hide - mai exact jefuitorii de morminte si corcituri - care bantuie Garren's Haunt si groapa comuna din apropiere. Aceste bestii strigoi sunt slugi josnice ale Scourge, insarcinate sa dezgroape nenumaratele victime ale ciumei initiale si sa ingroase randurile armatelor Lich King chiar la portile Brill.",al={"cine sunt dusmanii","ce fac rot hide","tinta jefuitorilor de morminte"}}},fp="12,355,30.448.0,30.421.0,45.211.0,29.196.0,32.111.0,51.197.0,41.146.0,59.167.0"}
P.entries["quest:359"] = {n="Forsaken Duties",s="Forsaken Duties este o misiune de cercetare atribuita de Magistrate Sevren din Brill, menita sa evalueze activitatea Scourge de-a lungul perimetrului estic din Tirisfal Glades. Ea scoate in evidenta amenintarea permanenta reprezentata de Scourge, care se strecoara pe langa The Bulwark si pune in pericol asezarile locale.",h="Forsaken Duties este o misiune de cercetare atribuita de Magistrate Sevren din Brill, menita sa evalueze...",kw={"Balnir Farmstead","Brill","Deathguard Linnea","Forsaken Duties","Magistrate Sevren","Scourge","The Bulwark","Tirisfal Glades"},ang={["faction:Horde"]="Asigurarea apararii Tirisfal Glades impotriva incursiunilor Scourge garanteaza ca Horde isi mentine un punct de sprijin sigur in nordul Lordaeron.",["race:Undead"]="Pentru Forsaken, este vital sa ramana vigilenti impotriva Scourge, deoarece orice bresa de-a lungul granitei ameninta direct Brill si Undercity, recucerit de curand."},sec={{t="Vigilenta la granita",b="Magistrate Sevren supravegheaza securitatea din Brill si din tinuturile invecinate, tinand sub observatie, nelinistit, granitele estice ale Tirisfal Glades. Cum Scourge se revarsa peste Western Plaguelands, Sevren are nevoie de recunoastere constanta din partea santinelelor de pe linia frontului, pentru a se asigura ca ororile strigoilor nu trec neobservate de perimetru. Calatorii dispusi sa ajute sunt trimisi spre sud si est, de-a lungul drumului principal, pentru a obtine o evaluare tactica urgenta de la Deathguard Linnea."},{t="Rapoarte de pe front",b="Stationata la un avanpost din est, de-a lungul drumului, Deathguard Linnea observa direct tinutul de frontiera. Descoperirile ei confirma temerile magistratilor: desi pozitia fortificata de la The Bulwark tine cu succes piept ostii principale a Scourge, grupuri mici de strigoi reusesc uneori sa ocoleasca apararea. Aceste forte ratacite au inceput sa se adune in jurul fermei Balnir Farmstead din apropiere, reprezentand o amenintare locala, dar periculoasa, pentru Tirisfal Glades."}},faq={{q="Cine ofera misiunea Forsaken Duties?",a="Magistrate Sevren, aflat in Brill, le incredinteaza calatorilor sarcina de a recupera un raport de recunoastere actualizat de la avanpostul Deathguard din est.",al={"cine ofera Forsaken Duties","cine incepe Forsaken Duties","misiunea lui Sevren"}},{q="Cine este Deathguard Linnea?",a="Deathguard Linnea este stationata la postul Deathguard de la est de Brill, unde supravegheaza miscarile de-a lungul drumului si pazeste caile de acces spre Plaguelands.",al={"cine este Linnea","locatia lui Deathguard Linnea","unde este Linnea"}},{q="Ce este The Bulwark?",a="Bulwark este avanpostul fortificat de la granita dintre Tirisfal Glades si Western Plaguelands, aparat pentru a impiedica Scourge sa cotropeasca tinuturile Forsaken.",al={"ce este Bulwark","apararea Bulwark","de ce este Bulwark important"}},{q="Pe unde se strecoara Scourge peste granita?",a="In timp ce aparatorii de la The Bulwark tin la distanta grosul armatei de strigoi, forte razlete ale Scourge se strecoara si se aduna in jurul fermei Balnir Farmstead, la est de punctul de popas.",al={"scourge in tirisfal","scourge la balnir farmstead","pe unde se strecoara scourge"}},{q="De ce vrea Magistrate Sevren un raport de situatie?",a="Magistrate Sevren trebuie sa se asigure ca Scourge nu-si poate instapani o pozitie puternica in Tirisfal Glades, lucru care impune vigilenta necontenita din partea Deathguard.",al={"de ce are Sevren nevoie de un raport","ingrijorarea lui Sevren"}},{q="Cum ajungi la postul lui Deathguard Linnea?",a="Pentru a ajunge la statia de popas din Brill, calatorii urmeaza drumul spre sud, apoi o iau spre est la bifurcatie, catre tinuturile estice din Tirisfal Glades.",al={"unde este statia de popas","cum ajungi la linnea"}}},fp="15,274,23.484.0,22.437.0,36.140.0,25.162.0,20.163.0,43.166.0,48.159.0,43.140.0"}
P.entries["quest:36"] = {n="Westfall Stew",s="In Westfall, o alta familie isi paraseste ferma, alungata de pe pamanturile sale de banditism. Inainte de plecare, Verna Furlbrow ii incredinteaza Salmei Saldean reteta locala pe care o pretuieste.",h="In Westfall, o alta familie isi paraseste ferma, alungata de pe pamanturile sale de banditism.",kw={"cooking","farmer furlbrow","reteta","saldean's farm","salma saldean","tocana","verna furlbrow","westfall"},ang={["profession:Cooking"]="Westfall Stew este hrana de la granita pentru colonistii Human, preparata din vanat de preerie recuperat si legume radacinoase rezistente.",["race:Human"]="Ca human, vezi cum cetatenii rurali ai regatului sunt alungati de pe fermele stramosesti si impinsi in exil urban, pe masura ce granita Stormwind se prabuseste."},sec={{t="O reteta transmisa mai departe",b="Hotii Defias si masinile salbatice de secerat au alungat-o pe Verna si pe Farmer Furlbrow de pe pamanturile familiei. Isi incarca caruta si se pregatesc sa caute adapost in spatele zidurilor Stormwind. Inainte sa plece, Verna ii da reteta pentru Westfall Stew vecinei sale Salma Saldean, sperand ca traditia culinara a fermei va dainui."},{t="Solidaritate la gospodarie",b="Salma Saldean si sotul ei, Farmer Saldean, isi pastreaza in continuare gospodaria, chiar mai jos pe drum. Reteta Vernei marcheaza pierderea inca unui vecin din cauza tulburarilor, dar mentine vie o traditie locala de la ferma. Salma porneste sa adune ingredientele necesare pentru a-i hrani pe cei care inca se lupta sa razbata la frontiera."}},faq={{q="De ce parasesc Furlbrows ferma?",a="Hotii si banditii Defias au facut campurile Furlbrows prea periculoase pentru a fi lucrate. Verna si Farmer Furlbrow isi pregatesc caruta pentru a fugi la Stormwind City.",al={"de ce pleaca furlough","furlbrows parasesc westfall","de ce isi face verna bagajele"}},{q="Cine este Salma Saldean?",a="Salma Saldean este o fermiera din Westfall care locuieste cu familia ei la Saldean's Farm, imediat dupa bifurcatia de drum de la ferma familiei Furlbrow. Ei continua sa-si lucreze pamantul in ciuda faradelegii din jur.",al={"cine este salma","lore despre salma saldean"}},{q="Ce este Westfall Stew?",a="Westfall Stew este un preparat regional traditional, facut din ingrediente intalnite pe campiile din Westfall si impartit intre gospodariile fermierilor locali.",al={"ce este Westfall Stew","reteta de Westfall Stew"}},{q="Unde planuiesc sa mearga Furlbrows?",a="Furlbrows se indreapta spre nord, catre Stormwind City, pentru siguranta; prietenii Vernei cred ca ea se va integra de minune acolo.",al={"unde merg Furlbrows","destinatia lui Furlbrow"}},{q="Unde se afla Saldean's Farm?",a="Saldean's Farm se afla chiar dincolo de intersectia de pe drumul principal, la sud de peticul de dovleci Furlbrow din Westfall.",al={"locatia fermei Saldean","unde este Salma Saldean"}},{q="Ofera aceasta misiune reteta de gatit propriu-zisa?",a="Sa-i duci instructiunile scrise Salmei este doar primul pas. Pentru a pregati tocana, ea iti cere ajutorul la adunarea ingredientelor.",al={"recompensa cu reteta","primesc reteta de westfall stew"}}},fx={["6757b659"]={q="De ce vrea Verna Furlbrow ca reteta ei de tocana sa fie livrata Salmei Saldean?",a="Cu gospodaria napadita de hoti si banditi, Verna Furlbrow fuge definitiv din Westfall. Inainte ca ea si sotul ei sa paraseasca tinuturile rurale pentru siguranta din Stormwind, vrea sa se asigure ca indragita ei reteta de tocana consistenta din Westfall ramane in mainile vecinei dragi si colegei sale fermiere, Salma Saldean.",al={"de ce sa predai reteta de tocanita din Westfall","motivul Vernei Furlbrow","de ce sa-i dai reteta Salmei"}},["5964e98d"]={q="De ce nu poate Verna Furlbrow sa livreze ea insasi reteta?",a="Drumurile sunt pline de proscrisi Defias, asa ca orice calatorie prin campii este primejdioasa. Mai urgent, Verna si sotul ei sunt blocati pe marginea drumului, asteptandu-l pe Farmer Furlbrow sa le repare caruta stricata, ca sa poata fugi spre Stormwind; ea nu poate ajunge singura la ferma lui Saldean.",al={"de ce are verna nevoie de mine","de ce nu poate verna sa o livreze","de ce eu sa livrez pentru verna"}}},fp="13,183,18.329.0,20.294.0,41.158.0,21.210.0,22.139.0,39.114.0,32.107.0,49.134.0"}
P.entries["quest:360"] = {n="Return to the Magistrate",s="Return to the Magistrate incheie o misiune urgenta de cercetare intre granita estica a Tirisfal Glades si orasul Brill. Dupa ce le raporteaza vestile lui Deathguard Linnea la avanpostul ei de la est de Brill, aventurierii sunt trimisi inapoi sa-i duca direct Magistrate Sevren vestile tulburatoare. Mesajul confirma ca slujitorii lipsiti de minte ai lui Lich King continua sa puna la incercare granitele tinerei natiuni Forsaken.",h="Return to the Magistrate incheie o misiune urgenta de cercetare intre granita estica a Tirisfal Glades si...",kw={"brill","bastion","Forsaken Duties","linnea","flagelatii","sevren","Tirisfal"},ang={["faction:Horde"]="Capul de pod al Horde in Eastern Kingdoms depinde de stabilitatea din Tirisfal Glades, ceea ce face ca apararea Bulwark sa fie cruciala impotriva ororilor strigoilor din Plaguelands.",["race:Undead"]="Sa duci informatii de la Bulwark te face sa intelegi cat de fragila este libertatea Forsaken: stapanul de care ai scapat inca isi intinde ghearele spre pragul noului tau camin."},sec={{t="Rapoarte de frontiera",b="Drumul estic care iese din Tirisfal Glades duce direct in ruinele napadite de molima din Western Plaguelands, unde Scourge domneste cu o putere devastatoare. Pentru a impiedica hoardele de strigoi sa navaleasca in patria nou cucerita, Forsaken au intemeiat Bulwark - un punct de control fortificat, supravegheat dintr-o statie de popas aflata in spatele liniei de aparare de santinele sumbre precum Deathguard Linnea. Dupa ce aduna rapoarte despre ce ameninta poarta estica, Linnea trimite mesageri in goana spre vest, de-a lungul King's Road, catre Brill, inainte ca infiltratorii inamici sa profite de orice brese."},{t="Juramantul lui Sevren",b="Cand Magistrate Sevren primeste mesajul in Brill, acesta ii confirma cele mai negre temeri: cercetasii Scourge gasesc cai de ocolire sau de strapungere a liniei de aparare din prima linie. Pentru Forsaken, fiecare ghoul care se taraste si fiecare schelet lipsit de minte nu sunt doar o neplacere militara, ci si o amintire a inrobirii de care au scapat odata cu caderea Lordaeronului. Sevren sustine cu tarie ca, oricat de neincetata ar deveni ofensiva Lich King, mortii liberi nu-si vor ceda niciodata autonomia nou-dobandita."}},faq={{q="De unde provine acest raport?",a="Raportul vine de la Deathguard Linnea, stabilita la un avanpost Deathguard la est de Brill, pe drumul spre Bulwark. Ea strange informatii de la baricadele care separa Tirisfal de Western Plaguelands, napadita de Scourge.",al={"originea misiunii","cine a trimis acest raport","unde este linnea"}},{q="De ce este Magistrate Sevren ingrijorat de aceasta veste?",a="Mesajul il informeaza pe Sevren ca fortele Scourge au reusit sa se strecoare dincolo de fortificatiile Bulwark-ului. Pentru Forsaken din Brill, incursiunile inamice ameninta asezarile lor inca fragede si le amintesc constant de eforturile Lich King-ului de a-i recuceri.",al={"de ce e ingrijorat Sevren","ce spune raportul","amenintarea Scourge"}},{q="Cine este Magistrate Sevren?",a="Magistrate Sevren este administratorul civil al Brill. Isi desfasoara activitatea din primaria orasului si supravegheaza apararea locala, infrastructura si mobilizarea cetatenilor Forsaken nou-recrutati din centrul Tirisfal Glades.",al={"povestea lui sevren","cine este magistratul"}},{q="Ce este bastionul?",a="Bulwark este un avanpost fortificat construit de-a lungul drumului principal dintre Tirisfal Glades si Western Plaguelands. Acesta serveste drept principala bariera care impiedica incursiunile Scourge in tinuturile Forsaken.",al={"povestea bastionului","granita estica din Tirisfal"}},{q="De ce ii urasc Forsaken atat de mult pe Scourge?",a="Forsaken au fost candva slujitori fara vointa ai Scourge, ucisi in viata si readusi la viata in moarte pentru a-si macelari propriile rude. Dupa ce si-au recastigat liberul arbitru, ei il detesta pe Lich King si se tem sa nu-si piarda din nou mintile sub controlul acestuia.",al={"forsaken vs scourge","de ce il urasc pe lich king"}},{q="Pe ce ruta calatoreste acest mesaj?",a="Mesagerii calatoresc spre vest pe drumul principal de la statia de popas a lui Deathguard Linnea, traversand centrul Tirisfal Glades pana ajung in centrul orasului Brill.",al={"drumul de la Bulwark la Brill","drumul spre Brill"}}},fx={["8343d5ab"]={q="De ce vrea Deathguard Linnea ca acest lucru sa fie facut?",a="Deathguard Linnea este stationata la un post al Deathguard, la est de Brill, pe drumul spre Bulwark. Cand fortele Scourge strapung aceste aparari estice si se infiltreaza in Tirisfal Glades, conducerea din Brill trebuie sa afle numaidecat. Linnea trebuie sa-l instiinteze fara intarziere pe Magistrate Sevren, pentru ca autoritatile locale sa se poata pregati de incursiuni si sa mobilizeze aparatorii impotriva slujitorilor neobositi ai Lich King.",al={"de ce raportul lui Linnea","de ce sa trimiti raportul lui Sevren","motivul Deathguard Linnea"}},["0dd03a94"]={q="De ce are Deathguard Linnea nevoie de tine pentru a duce mesajul?",a="Linnea si Deathguards alaturi de care slujeste vegheaza intr-un punct de popas la est de Brill, urmarind activitatea Scourge care trece de Bulwark. Ii cere unui aventurier aflat in trecere sa-i duca raportul lui Magistrate Sevren, pentru ca orasul sa se poata pregati, in timp ce postul de popas isi continua supravegherea.",al={"de ce sa nu trimita un deathguard","de ce are nevoie Linnea de mine","de ce sa-i duc mesajul lui Sevren"}}},fp="24,413,16.569.0,12.492.0,33.229.0,51.255.0,25.217.0,20.211.0,45.238.0,35.160.0"}
